def _yf_symbol(w):
    code = w.get("code", "")
    market = w.get("market", "JP")
    if market == "US":
        return code
    if market == "IDX":
        return IDX_YF_OVERRIDE.get(code, code)
    return code + ".T"  # 日本株


STOCK_QUOTES_CHUNK = 80  # 一括ダウンロード1回あたりの銘柄数（多すぎる一括取得も失敗しやすいため分割する）


def _download_chunk(symbols):
    """yf.downloadで複数銘柄をまとめて取得する。個別Ticker().history()を数百件連続で呼ぶと
    Yahoo側のレート制限に引っかかり、後半の銘柄ほど失敗しやすくなるため、まとめて取得することで
    速度・成功率の両方を改善する（実測：個別逐次は285件で数分＋失敗多発、一括は80件で約3秒・成功率100%）。
    group_by="ticker"指定時は銘柄が1件でも同じ階層構造（MultiIndex）で返るため、後続処理を共通化できる。"""
    try:
        return yf.download(symbols, period="7d", group_by="ticker", threads=True,
                            progress=False, auto_adjust=False)
    except Exception as e:
        print("  一括取得失敗", symbols[:3], "…", len(symbols), "件", e)
        return None


def _parse_stock_quote_frame(h):
    """yf.downloadが返す1銘柄分のDataFrameから、get_stock_quotesの戻り値1件分を作る
    （キャッシュ有無に関わらず共通で使うパース処理を切り出しただけ、ロジックは変更なし）。
    データが無ければNoneを返す。"""
    closes = h["Close"].dropna()
    if len(closes) == 0:
        return None
    t = round(float(closes.iloc[-1]), 2)
    p = round(float(closes.iloc[-2]), 2) if len(closes) >= 2 else None
    highs = h["High"].dropna()
    lows = h["Low"].dropna()
    opens = h["Open"].dropna()  # 2026-09-07新規（ポジション・リアルタイム売却判断）：当日始値。
    volumes = h["Volume"].dropna()
    turnover = float(t) * float(volumes.iloc[-1]) if len(volumes) and t is not None else None
    spark = [round(float(x), 2) for x in closes.tolist()[-20:]]  # 10-1章：カードUIのミニスパークライン用
    return {
        "t": t, "p": p,
        "open": round(float(opens.iloc[-1]), 2) if len(opens) else None,
        "high": round(float(highs.iloc[-1]), 2) if len(highs) else None,
        "low": round(float(lows.iloc[-1]), 2) if len(lows) else None,
        "volume": float(volumes.iloc[-1]) if len(volumes) else None,
        "turnover": turnover,
        "spark": spark,
    }


def get_stock_quotes(watchlist, cache_ttl=0, status_out=None):
    """登録銘柄それぞれの現在値(t)・前日終値(p)・当日高値(high)・当日安値(low)・売買代金(turnover)を返す。
    売買代金は 終値×出来高 で概算（セクターの並び替え用。4章の時価総額ソートから変更）。
    価格履歴と同じ history() の出来高列から計算するため、追加のAPI呼び出しは不要。
    2026-09-10新規（レート制限耐性）：cache_ttl>0を指定した呼び出し元（Market Intelligence
    Timeline・Morning Check）だけ、銘柄単位のキャッシュ+バッチ全滅時のリトライ+stale
    fallbackが有効になる。既存呼び出し元（メインダッシュボードの/api/stock-quotes等）は
    cache_ttl省略＝0のままなので、常に無条件で最新値を取りに行く既存動作を完全維持する
    （指示書「既存機能を壊さない」）。status_outを渡すとcode→cache_status（"ok"|
    "stale_cache"|"rate_limited"|"failed"）を書き込む（呼び出し側のdata_quality集計用）。"""
    out = {}
    if yf is None:
        return out
    items = [(w.get("code", ""), _yf_symbol(w)) for w in watchlist if w.get("code")]
    if not items:
        return out

    to_fetch = items
    if cache_ttl > 0:
        to_fetch = []
        for code, sym in items:
            entry = _cache_get(f"stockquote:{sym}")
            if _cache_fresh(entry, cache_ttl):
                out[code] = entry["value"]
                if status_out is not None:
                    status_out[code] = "ok"
            else:
                to_fetch.append((code, sym))

    newly_fetched_codes = set()
    if to_fetch:
        symbols = [sym for _, sym in to_fetch]

        def _download_all():
            frames = {}
            for i in range(0, len(symbols), STOCK_QUOTES_CHUNK):
                chunk = symbols[i:i + STOCK_QUOTES_CHUNK]
                data = _download_chunk(chunk)
                if data is None:
                    raise RuntimeError("stock quotes chunk download failed")
                for sym in chunk:
                    try:
                        sub = data[sym]
                        if sub is not None and not sub.empty:
                            frames[sym] = sub
                    except Exception:
                        pass  # このシンボルだけ結果に含まれなかった（上場廃止・シンボル誤り等）
            return frames

        if cache_ttl > 0:
            frames, exc = _retry_on_rate_limit(_download_all)
            frames = frames or {}
        else:
            # 既存動作を完全維持：リトライせず1回だけ（失敗時は握りつぶして空扱い、従来通り）
            try:
                frames = _download_all()
            except Exception as e:
                print("  一括取得失敗（リトライ無効経路）", e)
                frames = {}
            exc = None

        for code, sym in to_fetch:
            h = frames.get(sym)
            quote = None
            if h is not None:
                try:
                    quote = _parse_stock_quote_frame(h)
                except Exception as e:
                    print("  個別銘柄失敗", code, sym, e)
            if quote is not None:
                out[code] = quote
                newly_fetched_codes.add(code)
                if status_out is not None:
                    status_out[code] = "ok"
            elif cache_ttl > 0 and exc is not None:
                # バッチ取得自体が例外で全滅した場合のみキャッシュへフォールバックする。
                # 個別銘柄がデータ無し（上場廃止等、バッチ自体は成功）の場合はレート制限とは
                # 無関係の通常のデータ欠如のため、ここには来ない（statusは既存通りokのまま扱う）。
                stale_entry = _cache_get(f"stockquote:{sym}")
                if stale_entry is not None:
                    out[code] = stale_entry["value"]
                    print(f"  [RateLimitGuard] stockquote:{sym}：取得失敗のため期限切れキャッシュ（stale）を使用")
                    if status_out is not None:
                        status_out[code] = "stale_cache"
                elif status_out is not None:
                    status_out[code] = "rate_limited" if _is_rate_limit_error(exc) else "failed"
            elif status_out is not None:
                status_out[code] = "ok"  # バッチは成功したがこの銘柄だけデータ無し（従来通り欠損扱い、quality影響なし）

    # Market Data高速化指示書 Phase 5（2026-09-15新規、STEP5〜6監査で判明）：
    # _overlay_tachibana_prices()は「今回このget_stock_quotes呼び出しで対象になった
    # watchlist全体」に対して無条件でtachibana_api.get_market_price()を呼んでいた——
    # cache_ttl>0でstockquote:{sym}がキャッシュヒットした銘柄についても毎回オーバーレイ
    # し直していたため、_intraday_stock_snapshot()がwatchlist 1件ずつ
    # get_stock_quotes([item], cache_ttl=90)を呼ぶ既存ループ（Phase1で対応した経路）で、
    # 実は「1銘柄だけのTachibana get_market_price個別呼び出し」がキャッシュヒット時にも
    # 毎回発生し続けていた（Phase1のバッチ化を部分的に無効化していた隠れfallback、
    # 281銘柄で数百秒規模——STEP11のネットワーク禁止fixtureテストで検出）。
    # 修正：cache_ttl>0の場合はオーバーレイ対象を「今回新規に取得した銘柄
    # （newly_fetched_codes、cache missだった銘柄）」だけに絞り、オーバーレイ後の値を
    # cache_ttl>0の場合のみ改めてキャッシュへ保存する（＝一度オーバーレイされた値は
    # TTL内は再オーバーレイしない）。cache_ttl=0の既存呼び出し元（メインダッシュボード等）
    # は従来通りwatchlist全件を毎回オーバーレイし続ける（動作完全維持）。
    if cache_ttl > 0:
        if newly_fetched_codes:
            overlay_targets = [w for w in watchlist if w.get("code") in newly_fetched_codes]
            _overlay_tachibana_prices(out, overlay_targets)
            for code, sym in to_fetch:
                if code in out:
                    _cache_set(f"stockquote:{sym}", out[code])
    else:
        _overlay_tachibana_prices(out, watchlist)
    return out


def _overlay_tachibana_prices(out, watchlist):
    """日本株について、yfinance（遅延）の現在値・高値・安値・前日終値を立花証券APIの
    実測値で上書きする。turnoverはpDV（出来高）×現在値で再計算。spark（履歴）はyfinance
    データのまま維持する（立花のスナップショットには日足履歴が無いため）。
    未接続（認証ファイル無し・ログイン失敗・通信エラー等）の場合は何もせず、
    既存のyfinance値をそのまま使う（機能低下のみで停止しない）。"""
    if tachibana_api is None:
        return
    jp_codes = [w.get("code", "") for w in watchlist if w.get("market", "JP") == "JP" and w.get("code")]
    if not jp_codes:
        return
    try:
        live = tachibana_api.get_market_price(jp_codes)
    except Exception as e:
        print("  立花証券API 時価取得失敗（yfinanceの値を継続使用）", e)
        return
    for code, v in live.items():
        if code not in out or v.get("t") is None:
            continue
        out[code]["t"] = v["t"]
        if v.get("p") is not None:
            out[code]["p"] = v["p"]
        if v.get("open") is not None:  # 2026-09-07新規（ポジション・リアルタイム売却判断）
            out[code]["open"] = v["open"]
        if v.get("high") is not None:
            out[code]["high"] = v["high"]
        if v.get("low") is not None:
            out[code]["low"] = v["low"]
        if v.get("volume") is not None:
            out[code]["turnover"] = v["t"] * v["volume"]
            out[code]["volume"] = v["volume"]  # フロント側の出来高ブレイクアウト判定用
        if v.get("ask") is not None:
            out[code]["ask"] = v["ask"]
        if v.get("bid") is not None:
            out[code]["bid"] = v["bid"]
        out[code]["liveSource"] = "tachibana"


# ============================================================
# Phase QF-1（2026-09-14新規）：FAST QUOTE経路。リアルタイム表示用の現在値系データは
# 立花証券APIを主ソースにし、yfinance（日足履歴・spark等）を一切経由しない。
# get_stock_quotes()（既存・yfinance history＋tachibana上書き、spark付き）はSLOW
# analytics用として無変更のまま残す——既存の呼び出し元（/api/stock-quotes、分析API、
# 「市場」タブの残225銘柄ループ等）は一切変更しない。
# ユーザー指示：PRICE_CHUNK（40件）はいきなり拡大しない。監視56銘柄でも2チャンクで
# 実測2秒程度のため、まずは安定性優先。失敗したチャンクだけ再試行し、成功済みチャンクは
# 再取得しない。
# ============================================================
FAST_QUOTE_CHUNK = 40  # tachibana_api.PRICE_CHUNKと同じ単位を維持（QF-1指示：一気に拡大しない）
FAST_QUOTE_MAX_ATTEMPTS = 3  # 失敗したチャンクだけこの回数まで再試行（無限リトライ禁止）
FAST_QUOTE_CACHE_TTL_SEC = 15  # tachibana取得失敗時のfallback①（直近キャッシュ）のTTL
_fast_quote_cache = {}  # code -> {"value": {...FAST QUOTE dict...}, "at": epoch_sec}


def _fetch_fast_quote_chunk_with_retry(chunk):
    """立花証券APIから1チャンク（最大FAST_QUOTE_CHUNK件）分の時価を取得する。
    tachibana_api.get_market_price()内部では「セッション切れ等は1回だけ再ログイン再試行」
    までしか行わないため、それでも結果に含まれない銘柄が残る場合はここでさらに指数
    バックオフ付きでFAST_QUOTE_MAX_ATTEMPTS回まで再試行する（成功済みの銘柄は再取得しない、
    指示書：既存の_fetch_market_price_with_retryのリトライ設計を流用）。FAST経路のため
    MOMENTUM_STAGE1（3秒→6秒）より短い間隔でバックオフする。
    戻り値: {code: {...}} （最終的に取得できなかった銘柄は含まれない）"""
    remaining = list(dict.fromkeys(chunk))
    result = {}
    for attempt in range(1, FAST_QUOTE_MAX_ATTEMPTS + 1):
        if not remaining:
            break
        try:
            got = tachibana_api.get_market_price(remaining)
        except Exception as e:
            print(f"  [FastQuote] チャンク取得失敗（{attempt}/{FAST_QUOTE_MAX_ATTEMPTS}回目、TACHIBANA_SESSION_FAILEDの可能性）", e)
            got = {}
        result.update(got)
        remaining = [c for c in remaining if c not in got]
        if remaining and attempt < FAST_QUOTE_MAX_ATTEMPTS:
            time.sleep(attempt * 1.5)
    if remaining:
        print(f"  [FastQuote] TACHIBANA_SESSION_FAILED（{FAST_QUOTE_MAX_ATTEMPTS}回失敗）：{remaining}")
    return result


def get_fast_quotes(watchlist):
    """FAST QUOTE経路：立花証券APIを主ソースとしたリアルタイム時価取得（指示書4番の
    ソース優先順位＝TACHIBANA→fallback（直近キャッシュ）→yfinance→last known value）。
    yfinanceの日足履歴取得（get_stock_quotesが行うもの）は一切呼ばない——呼ぶのは
    fallback②として、tachibana・キャッシュのどちらでも取れなかったごく少数の銘柄だけ
    （指示書6番：現在値pollに履歴取得を結合しない。フォールバック時の少数呼び出しのみ許容）。
    戻り値: (quotes_dict, stats_dict)。
    quotes_dict[code] = {t,p,change,changePct,volume,open,high,low,ask,bid,
                          source,quote_timestamp,fetched_at,is_stale}
    stats_dict = {"requested":N,"tachibana":N,"fallback_cache":N,"fallback_yf":N,"failed":N,"duration_ms":N}
    最終的にどこからも値を得られなかった銘柄はquotes_dictに含めない
    （＝フロント側は直前の値＝last known valueをそのまま保持する設計）。"""
    t0 = time.time()
    codes = list(dict.fromkeys(w.get("code", "") for w in watchlist if w.get("code")))
    out = {}
    stats = {"requested": len(codes), "tachibana": 0, "fallback_cache": 0, "fallback_yf": 0, "failed": 0, "duration_ms": 0}
    if not codes:
        return out, stats
    now_iso = datetime.datetime.now(_JST).isoformat()

    fetched_all = {}
    if tachibana_api is not None:
        for i in range(0, len(codes), FAST_QUOTE_CHUNK):
            fetched_all.update(_fetch_fast_quote_chunk_with_retry(codes[i:i + FAST_QUOTE_CHUNK]))

    still_missing = []
    for code in codes:
        v = fetched_all.get(code)
        if v is not None and v.get("t") is not None:
            out[code] = {
                "t": v.get("t"), "p": v.get("p"), "change": v.get("change"), "changePct": v.get("changePct"),
                "volume": v.get("volume"), "open": v.get("open"), "high": v.get("high"), "low": v.get("low"),
                "ask": v.get("ask"), "bid": v.get("bid"),
                "source": "tachibana", "quote_timestamp": now_iso, "fetched_at": now_iso, "is_stale": False,
            }
            stats["tachibana"] += 1
            _fast_quote_cache[code] = {"value": out[code], "at": time.time()}
        else:
            still_missing.append(code)

    # fallback①：直近キャッシュ（TTL内）
    still_missing2 = []
    for code in still_missing:
        cached = _fast_quote_cache.get(code)
        if cached is not None and (time.time() - cached["at"]) <= FAST_QUOTE_CACHE_TTL_SEC:
            out[code] = {**cached["value"], "source": "cache", "fetched_at": now_iso, "is_stale": True}
            stats["fallback_cache"] += 1
        else:
            still_missing2.append(code)

    # fallback②：yfinance（tachibana・キャッシュどちらも失敗した、ごく少数のはずの銘柄のみ。
    # 既存get_stock_quotes()をそのまま再利用するが、対象は少数のため現在値pollを
    # ブロックするほどの遅延にはならない想定）。
    if still_missing2:
        yf_items = [w for w in watchlist if w.get("code") in still_missing2]
        try:
            yf_quotes = get_stock_quotes(yf_items)
        except Exception as e:
            print("  [FastQuote] yfinanceフォールバック失敗", e)
            yf_quotes = {}
        for code in still_missing2:
            v = yf_quotes.get(code)
            if v is not None and v.get("t") is not None:
                out[code] = {
                    "t": v.get("t"), "p": v.get("p"), "change": None, "changePct": None,
                    "volume": v.get("volume"), "open": v.get("open"), "high": v.get("high"), "low": v.get("low"),
                    "ask": v.get("ask"), "bid": v.get("bid"),
                    "source": "yfinance_fallback", "quote_timestamp": now_iso, "fetched_at": now_iso, "is_stale": True,
                }
                stats["fallback_yf"] += 1
                _fast_quote_cache[code] = {"value": out[code], "at": time.time()}
            else:
                stats["failed"] += 1
    stats["duration_ms"] = round((time.time() - t0) * 1000)
    print(f"  [FastQuote] requested={stats['requested']} tachibana={stats['tachibana']} "
          f"fallback_cache={stats['fallback_cache']} fallback_yf={stats['fallback_yf']} "
          f"failed={stats['failed']} duration={stats['duration_ms']}ms")
    return out, stats


def _fmt_published(entry):
    """RSS の pubDate(GMT) を日本時間 'MM/DD HH:MM' に整形。無ければ空。"""
    pp = entry.get("published_parsed")
    if not pp:
        return ""
    try:
        jst = datetime.timezone(datetime.timedelta(hours=9))
        dt = datetime.datetime.fromtimestamp(calendar.timegm(pp), datetime.timezone.utc).astimezone(jst)
        return dt.strftime("%m/%d %H:%M")
    except Exception:
        return ""


def _source_of(entry, title):
    """出典（媒体名）を取り出す。Google ニュースの見出しは末尾が ' - 媒体名'。"""
    src = entry.get("source")
    if isinstance(src, dict):
        s = src.get("title") or src.get("value")
        if s:
            return s
    if " - " in title:
        return title.rsplit(" - ", 1)[1].strip()
    return ""


def _clean_title(title):
    """見出し末尾の ' - 媒体名' を除いた本文だけを返す。"""
    if " - " in title:
        return title.rsplit(" - ", 1)[0].strip()
    return title


def _published_ts(entry):
    """ソート用のUNIX時刻。取得できない場合は0（末尾扱い）にする。"""
    pp = entry.get("published_parsed")
    if not pp:
        return 0
    try:
        return calendar.timegm(pp)
    except Exception:
        return 0


# キーワード一致度優先のGoogleニュース検索では、関連記事が少ないクエリだと数週間〜数ヶ月前の
# 古い記事まで拾ってしまうことがある（重大ニュースのキーワードに偶然一致した過去記事等）。
# 「重要ニュース」表示も含め、鮮度の低い記事が紛れ込まないよう取得時点でここまで絞り込む。
# 個別銘柄の決算・IRは四半期に一度など元々頻度が低いため、マクロニュースより長めの期間を許容する。
NEWS_MAX_AGE_DAYS = 14
STOCK_NEWS_MAX_AGE_DAYS = 45


def _is_recent(entry, max_age_days=NEWS_MAX_AGE_DAYS):
    ts = _published_ts(entry)
    if ts <= 0:
        return False
    return (time.time() - ts) <= max_age_days * 86400


def google_news(query, n=2, max_age_days=NEWS_MAX_AGE_DAYS):
    """GoogleニュースRSSは検索クエリ単位では関連度寄りの順序で返り、必ずしも新しい順ではないため、
    ここで公開日時の降順（新しい記事が先頭）に並べ替えてから返す。古い記事（max_age_days超）は
    ここで除外する。複数クエリの結果を連結して使う呼び出し元（build_stock_news/build_macro_news）でも、
    連結後に改めて全体を日時順に並べ替えている。"""
    if feedparser is None:
        return []
    url = ("https://news.google.com/rss/search?q="
           + urllib.parse.quote(query) + "&hl=ja&gl=JP&ceid=JP:ja")
    try:
        feed = feedparser.parse(url)
        recent_entries = [e for e in feed.entries if _is_recent(e, max_age_days)]
        entries = sorted(recent_entries, key=_published_ts, reverse=True)
        out = []
        for e in entries[:n]:
            raw = e.get("title", "")
            out.append({
                "title": _clean_title(raw),
                "url": e.get("link", ""),
                "source": _source_of(e, raw),
                "published": _fmt_published(e),
                "_ts": _published_ts(e),
            })
        return out
    except Exception:
        return []


#  9章：登録銘柄ニュースは「決算を含むIR・適時開示」のみに絞る。GoogleニュースRSSには構造化
# カテゴリがないため、クエリ自体をIR寄りにした上で、タイトルに以下キーワードを含むものだけに
# 絞り込む代替策を取っている（完全なIR/適時開示フィードではなく、あくまでキーワードベースの近似）。
IR_KEYWORDS = [
    "決算", "上方修正", "下方修正", "業績予想", "業績修正", "自己株式", "自社株買い", "配当",
    "株式分割", "適時開示", "増資", "決算短信", "通期", "四半期", "特別損失", "特別利益",
    "新株予約権", "有価証券報告書", "開示", "IR", "本決算", "決算発表",
    "月次売上高", "月次業績", "月次",  # TSMC等が発表する月次売上高のような月次開示も拾う
    # 2026-09-08追加（ニュース優先順位改善、指示書ir_expansion対応）：決算・配当・自社株買い
    # 以外の重要IRカテゴリ（M&A・業務提携・大型受注・新製品・設備投資・工場新設・KPI・
    # 中期経営計画・経営方針・訴訟/行政処分・人事）を追加し、企業公式情報の取得件数を増やす。
    "M&A", "買収", "合併", "業務提携", "資本提携", "資本業務提携", "TOB", "公開買付",
    "大量保有", "受注", "大型受注", "新製品", "新サービス", "設備投資", "工場新設", "増産",
    "生産能力", "KPI", "中期経営計画", "中計", "経営方針", "経営計画", "訴訟", "提訴",
    "行政処分", "業務改善命令", "人事異動", "役員人事", "代表取締役",
]


def _is_ir_news(title):
    return any(k in title for k in IR_KEYWORDS)


def _title_mentions_name(name, title):
    """Googleニュースの検索結果はクエリ語の一部だけに一致した無関係記事（noteの個人ブログ等）も
    紛れ込むため、IRキーワードだけでなく銘柄名自体が見出しに含まれているかも確認する。
    「三菱重工業」→見出しは「三菱重工」のように、末尾の「業」を省いた略称で報じられることが
    多いため、その形も許容する（ユーザー要望：三菱重工の提携記事が拾えていなかったため
    2026-07-14追加。「重工」等の実在する短い略称に絞るため、name自体が4文字超の場合のみ対象）。"""
    t = title.lower()
    if name.lower() in t:
        return True
    if name.endswith("業") and len(name) > 4 and name[:-1].lower() in t:
        return True
    return False


# ============================================================
# 2026-09-14新規（ニュース機能修正指示書）：ニュース一覧のソート・重要度判定・重複排除・
# 通知の基盤。既存の各build_*_news()が返すitem（code/name/title/url/source/published/_ts）
# に importanceScore（0-100）／notificationLevel（CRITICAL|HIGH|NORMAL）／badges（表示用）
# ／ts（_tsの公開名、JS側は数値のUNIX秒として扱う）を付与する。
#
# 根本原因（指示書A）：newsSummary（trade-cockpit.html）の並べ替えが
# [isImportantNews(title)?0:1, priority, source] を最優先キーにしていたため、キーワード一致
# した古い記事（例：エムスリー 9/12、"上方修正"等に一致）が新しい記事（9/14、キーワード
# 不一致）より常に上に来ていた（日付は最終タイブレークにしかならず、事実上機能していなかった）。
# 修正方針：一覧の並び順はpublished_at（_ts）を必ず主キーにする。重要度は「新着順」を崩す
# ためではなく、①通知の要否判定②別枠「🚨重要ニュース」パネル③一覧内バッジ表示、の3用途に限定する。
# ============================================================

def _clamp_future_ts(ts, now=None, max_skew_sec=6 * 3600):
    """指示書B（異常日時検出）：未来日時（now+6時間超）はソース側のタイムゾーン誤解釈等の
    異常値とみなし0（=末尾扱い）にする。過去日時はそのまま通す（正規のニュースは全て過去）。"""
    if not ts or ts <= 0:
        return 0
    now = now if now is not None else time.time()
    if ts > now + max_skew_sec:
        return 0
    return ts


def resolve_news_ts(item):
    """指示書B（日時正規化フォールバック）：published_at(_ts) → source_published_at(_source_ts)
    → fetched_at(_fetched_ts) → created_at(_created_ts) の順にフォールバックする。
    このリポジトリの各build_*_news()は基本的に_tsだけを持つが、将来ソースごとに複数の時刻
    候補を持たせる場合に備えて汎用にしておく。戻り値：UNIX秒（int/float）、全て無ければ0。"""
    for key in ("_ts", "_source_ts", "_fetched_ts", "_created_ts"):
        ts = item.get(key)
        if ts:
            return _clamp_future_ts(ts)
    return 0


