def _kw_hit(norm_title, keywords):
    return [k for k in keywords if unicodedata.normalize("NFKC", k) in norm_title]


def compute_news_importance(title, code=None, source=None, is_tdnet=False, is_registered_stock=False, source_tier=None):
    """指示書D・Phase2指示書7・8：見出し（と付随情報）からimportance_score（0-100）・
    notificationLevel（CRITICAL|HIGH|NORMAL）・badges（UI表示用の短いラベル）を計算する。
    優先順位：①登録銘柄×TDnet適時開示（最優先）②中央銀行・為替・米統計・サプライチェーン
    規制・日本市場急変マクロ③地政学（市場インパクトの語を伴う場合のみ）。いずれにも該当
    しなければNORMAL・0点。
    Phase2追加：source_tier（1=一次情報〜4=集約）による信頼度ボーナスを補助的に加える。
    ただしsource_tierだけではCRITICAL/HIGHにしない——スコアが既に内容面で0より大きい
    （＝何らかの重要キーワードに一致した）場合のみ、Tier1は+5・Tier2（日経）は+3を上乗せする
    （指示書7番「日経記事という理由だけでHIGHにしない」を厳守）。
    戻り値：{"score":int, "level":"CRITICAL"|"HIGH"|"NORMAL", "badges":[...]}"""
    if not title:
        return {"score": 0, "level": "NORMAL", "badges": []}
    norm_title = unicodedata.normalize("NFKC", title)
    score = 0
    badges = []

    if is_tdnet:
        badges.append("TDnet")
    if is_registered_stock:
        badges.append("登録銘柄")

    tdnet_hits = _kw_hit(norm_title, TDNET_CRITICAL_KEYWORDS) if (is_tdnet or is_registered_stock) else []
    if tdnet_hits:
        always_hit = _kw_hit(norm_title, TDNET_CRITICAL_ALWAYS)
        score = max(score, 95 if always_hit else 75)
        if any(k in ("決算",) for k in tdnet_hits):
            badges.append("決算")
        badges.append("重要開示")

    cb_hits = _kw_hit(norm_title, IMPORTANCE_KEYWORDS_CENTRAL_BANK)
    if cb_hits:
        score = max(score, 80)
        badges.append("中央銀行")

    # Phase2指示書8：半導体輸出規制・米中関税等のサプライチェーン規制、日経先物急変等の
    # 日本市場急変ワードもHIGH候補にする（単純キーワード一致だが、既存カテゴリと同じ
    # 「明確に市場を動かす政策・イベント」の語彙に限定している）。
    supply_hits = _kw_hit(norm_title, IMPORTANCE_KEYWORDS_SUPPLY_CHAIN)
    if supply_hits:
        score = max(score, 80)
        badges.append("サプライチェーン")
    shock_hits = _kw_hit(norm_title, IMPORTANCE_KEYWORDS_JP_MARKET_SHOCK)
    if shock_hits:
        score = max(score, 80)
        badges.append("日本市場急変")

    geo_hits = _kw_hit(norm_title, IMPORTANCE_KEYWORDS_GEOPOLITICAL)
    impact_hits = _kw_hit(norm_title, IMPORTANCE_KEYWORDS_MARKET_IMPACT)
    if geo_hits and impact_hits:
        score = max(score, 70)
        badges.append("地政学")

    # Phase2指示書7：source reliabilityは補助要素。内容面で既に0点超のときだけ小さく加点する
    # （0点のまま＝内容的に無関係な記事は、日経・TDnet等どれだけ信頼度の高いソースでも
    # HIGH/CRITICALへは上がらない）。
    if score > 0 and source_tier is not None:
        score = min(100, score + {1: 5, 2: 3}.get(source_tier, 0))

    if score >= 90:
        level = "CRITICAL"
    elif score >= 60:
        level = "HIGH"
    else:
        level = "NORMAL"
    if level != "NORMAL" and "🚨重要" not in badges:
        badges.insert(0, "🚨重要")
    return {"score": score, "level": level, "badges": badges}


_NEWS_DEDUPE_DECORATION_WORDS = ["速報", "独自", "詳報", "全文", "続報", "号外"]
_NEWS_DEDUPE_CODE_RE = re.compile(r"[<＜(（]\s*\d{4}\s*[>＞)）]|証券コード\s*\d{4}")


def _normalize_news_title_for_dedupe(title):
    """指示書C・「重複排除」指示書7番：媒体名サフィックス・記号・空白差に加え、証券コードの
    括弧書き（例：<1802>）や「速報」等の装飾語の有無で同一記事が別記事扱いになるのを防ぐ
    （実例：大林組1802「M&Aなど投資見通しが計画の約2倍に」が転載媒体差で2件表示された問題）。"""
    if not title:
        return ""
    t = unicodedata.normalize("NFKC", title)
    t = _clean_title(t)
    t = _NEWS_DEDUPE_CODE_RE.sub("", t)
    for w in _NEWS_DEDUPE_DECORATION_WORDS:
        t = t.replace(w, "")
    t = re.sub(r"[\s　]+", "", t)
    t = re.sub(r"[【】\[\]（）()「」『』｜|・、。,.!！?？:：;；\-─―]", "", t)
    return t.lower()


def _normalize_news_url_for_dedupe(url):
    """クエリパラメータ・末尾スラッシュの差異を吸収した正規化URL。"""
    if not url:
        return ""
    try:
        parsed = urllib.parse.urlsplit(url)
        return urllib.parse.urlunsplit((parsed.scheme, parsed.netloc, parsed.path.rstrip("/"), "", ""))
    except Exception:
        return url


_TDNET_DOC_ID_RE = re.compile(r"(\d{14,})")


def _news_dedupe_key(item):
    """指示書C：normalized_url／TDnet document ID／stock_code／normalized_title／
    published_at(日付部分)の組み合わせで同一記事・同一開示を判定するキーを作る。
    TDnetのURLは配信ごとにdocument ID（長い数字列）を含むため、そのIDが取れれば
    URL全体より安定したキーとして優先する。"""
    url = item.get("url") or ""
    m = _TDNET_DOC_ID_RE.search(url)
    tdnet_doc_id = m.group(1) if m else None
    norm_title = _normalize_news_title_for_dedupe(item.get("title"))
    code = item.get("code") or ""
    published_date = str(item.get("published") or "")[:5]  # "MM/DD"部分（年またぎは別記事として扱う）
    if tdnet_doc_id:
        return f"tdnet:{tdnet_doc_id}"
    norm_url = _normalize_news_url_for_dedupe(url)
    if norm_url:
        return f"url:{norm_url}"
    return f"title:{code}:{norm_title}:{published_date}"


_NEWS_DEDUPE_TITLE_SIMILARITY_THRESHOLD = 0.90  # 指示書7番：同一銘柄・48時間以内でこの類似度以上なら同一クラスタ
_NEWS_DEDUPE_CLUSTER_WINDOW_SEC = 48 * 3600


def _news_dedupe_representative_rank(item):
    """指示書7番：同一クラスタ内の代表記事選定順位（小さいほど優先）。
    企業公式IR/TDnet → 日経 → Reuters/Bloomberg等 → 業界専門媒体 → その他転載媒体、の順。
    classify_source_tierのTier（1〜4）をそのまま流用する（地方局・ポータル等の転載媒体は
    Tier4=その他に落ちるため、自動的に代表から外れる）。"""
    try:
        tier, _ = classify_source_tier(item.get("source"), item.get("url"), is_tdnet=(item.get("source") == "TDnet"))
    except Exception:
        tier = SOURCE_TIER_AGGREGATOR
    return tier


def dedupe_news_items(items):
    """指示書C・「重複排除」指示書7番：_news_dedupe_key()が示す完全一致（同一URL・同一TDnet
    開示・正規化タイトル完全一致）に加え、同一銘柄コードかつ48時間以内でタイトル類似度が
    _NEWS_DEDUPE_TITLE_SIMILARITY_THRESHOLD以上のものも同一ニュースclusterとして1件に集約する
    （実例：大林組1802の同一内容記事が別媒体の転載で2件表示されていた問題）。
    クラスタ内の代表記事はsource優先順位（企業公式IR/TDnet＞日経＞Reuters/Bloomberg等＞
    業界専門媒体＞その他転載媒体）で選ぶ（"最初に出てきたもの"は使わない）。"""
    # 1) 完全一致キーでグルーピング（従来通り）。
    exact_groups = {}
    order = []
    for it in items:
        key = _news_dedupe_key(it)
        if key not in exact_groups:
            exact_groups[key] = []
            order.append(key)
        exact_groups[key].append(it)
    exact_reps = []
    for key in order:
        group = exact_groups[key]
        best = min(group, key=_news_dedupe_representative_rank)
        exact_reps.append(best)

    # 2) 完全一致では拾いきれない同一クラスタ（別媒体の転載で表記ゆれがある場合）を、
    #    同一銘柄コード×48時間以内×タイトル類似度で追加集約する。
    clusters = []  # each: {"items": [...], "norm_titles": [...]}
    for it in exact_reps:
        code = it.get("code") or ""
        norm_title = _normalize_news_title_for_dedupe(it.get("title"))
        ts = resolve_news_ts(it)
        placed = False
        if norm_title:
            for cluster in clusters:
                if cluster["code"] != code:
                    continue
                if ts and cluster["ts"] and abs(ts - cluster["ts"]) > _NEWS_DEDUPE_CLUSTER_WINDOW_SEC:
                    continue
                ratio = difflib.SequenceMatcher(None, norm_title, cluster["norm_title"]).ratio()
                if ratio >= _NEWS_DEDUPE_TITLE_SIMILARITY_THRESHOLD:
                    cluster["items"].append(it)
                    if _news_dedupe_representative_rank(it) < _news_dedupe_representative_rank(cluster["rep"]):
                        cluster["rep"] = it
                        cluster["norm_title"] = norm_title
                        cluster["ts"] = ts
                    placed = True
                    break
        if not placed:
            clusters.append({"code": code, "norm_title": norm_title, "ts": ts, "rep": it, "items": [it]})

    return [c["rep"] for c in clusters]


