INTRADAY_REPORT_SNAPSHOT_TIMES = {  # 指示書6番：JST、24h表記
    "OPENING_30M": "09:30", "MORNING_CLOSE": "11:30", "AFTERNOON_30M": "13:00", "MARKET_CLOSE": "15:30",
}
INTRADAY_REPORT_ORDER = ["OPENING_30M", "MORNING_CLOSE", "AFTERNOON_30M", "MARKET_CLOSE"]

# 朝TOP5の答え合わせ結果の強さ順（指示書1番：STRENGTHENED/MAINTAINED/WEAKENED/FAILEDの判定に使う）
_THESIS_RESULT_RANK = {"INVALIDATED": 0, "NOT_TRIGGERED": 1, "PARTIAL": 2, "CONFIRMED": 3}


def _thesis_transition_status(prev_result, new_result):
    """前回レポート時点のthesis_resultから今回への変化を判定する（指示書1番）。データ不足時は
    無理に強弱を判定せずDATA_INSUFFICIENTとする（指示書29番）。INVALIDATEDへ転落した場合は、
    強弱の方向に関わらず明確な失敗として一律FAILEDにする（「何が外れたか」を明確にするため）。"""
    if not prev_result or prev_result == "DATA_INSUFFICIENT" or new_result == "DATA_INSUFFICIENT":
        return "DATA_INSUFFICIENT"
    if new_result == "INVALIDATED":
        return "FAILED"
    prev_rank, new_rank = _THESIS_RESULT_RANK.get(prev_result), _THESIS_RESULT_RANK.get(new_result)
    if prev_rank is None or new_rank is None:
        return "DATA_INSUFFICIENT"
    if new_rank > prev_rank:
        return "STRENGTHENED"
    if new_rank < prev_rank:
        return "WEAKENED"
    return "MAINTAINED"


def _final_top5_result(thesis_history):
    """1銘柄分の当日全時間帯のthesis_result履歴（古い→新しい、現在の評価を含む）から、
    大引け時点の最終結果を判定する（指示書3番）。重要：triggerが一度も発動していない
    （常にNOT_TRIGGERED/DATA_INSUFFICIENTのみ）場合は、株価が下落していてもFAILにせず
    NO_ENTRYとする——朝の仮説と実際のエントリー機会を分けて評価する（ユーザー指示）。"""
    triggered = any(r in ("CONFIRMED", "PARTIAL", "INVALIDATED") for r in thesis_history)
    if not triggered:
        return "NO_ENTRY" if any(r == "NOT_TRIGGERED" for r in thesis_history) else "DATA_INSUFFICIENT"
    final = thesis_history[-1]
    if final == "CONFIRMED":
        return "SUCCESS"
    if final == "PARTIAL":
        return "PARTIAL_SUCCESS"
    if final == "INVALIDATED":
        return "FAIL"
    # 一度は発動したのに最後がNOT_TRIGGERED/DATA_INSUFFICIENTに戻る想定外パターン→安全側でPARTIAL_SUCCESS扱い
    return "PARTIAL_SUCCESS"


def _previous_intraday_reference(database_url, user_id, trade_date, report_type, morning_check):
    """指示書4番「全レポートでprevious_reportを参照する」。直前の時間帯のmarket_intelligence_
    reportsがあればそれを、無ければMorningMarketCheckまで遡る（順序：MorningCheck→09:30→
    11:30→13:00→15:30）。戻り値：(前回レポートdict_or_None, "morning_check"|report_type|None)。"""
    idx = INTRADAY_REPORT_ORDER.index(report_type)
    if investment_db is not None and database_url:
        for prior_type in reversed(INTRADAY_REPORT_ORDER[:idx]):
            rep = investment_db.get_market_intelligence_report(database_url, user_id, trade_date, prior_type)
            if rep:
                return rep, prior_type
    return (morning_check, "morning_check") if morning_check else (None, None)


def _intraday_stock_snapshot(watchlist_item, prefetched=None):
    """TOP5銘柄1件分の「今」の状態（現在値・当日騰落率・VWAP位置・5分足構造）を取得する。
    既存の_intraday_regime()（セクターETFの当日レジーム判定で既に使っている5分足取得＋VWAP計算）
    をそのまま個別銘柄に転用するだけで、新しい分足取得経路は作らない（指示書30番）。
    2026-09-10更新（レート制限耐性）：現在値はget_stock_quotes(cache_ttl指定)、VWAP/5分足構造は
    _intraday_regime_cached()経由でキャッシュ+リトライ+stale fallbackを適用する（指示書1・2・
    3・4番）。cacheStatusも返す（呼び出し側のdata_quality集計用）。

    2026-09-15追加（今買い時TOP5 場中リアルタイム化指示書 レビュー反映：scan-local market
    data reuse）：prefetched（{"quote":..., "quoteStatus":..., "regime":..., "regimeStatus":...}）
    が渡された場合はそれをそのまま使い、get_stock_quotes()・_intraday_regime_cached()（どちらも
    グローバルTTL＝90秒）を呼ばない。呼び出し元（_score_entry_candidates）がprefetch_market_
    data_for_watchlist()の結果をscan-local mapとして渡すことで、daily arraysと同じ理由
    （scan自体が90秒を超えうる）による同一scan内の重複外部取得を防ぐ。省略時（prefetched=None）
    は従来通り個別取得する——他の既存呼び出し元（FAST UPDATE等）への影響は無い。"""
    sym = _yf_symbol(watchlist_item)
    if prefetched is not None:
        quote = prefetched.get("quote")
        quote_status_for_code = prefetched.get("quoteStatus", "failed")
        regime, regime_status = prefetched.get("regime"), prefetched.get("regimeStatus", "failed")
    else:
        quote_status = {}
        quote = get_stock_quotes([watchlist_item], cache_ttl=CACHE_TTL["stock_quote"], status_out=quote_status).get(
            watchlist_item.get("code"))
        quote_status_for_code = quote_status.get(watchlist_item.get("code"), "failed")
        regime, regime_status = _intraday_regime_cached(sym, "5m", CACHE_TTL["stock5m"])
    current_change_pct = None
    if quote and quote.get("t") is not None and quote.get("p"):
        current_change_pct = round((quote["t"] - quote["p"]) / quote["p"] * 100, 2)
    cache_status = quote_status_for_code if quote else regime_status
    # 両方stale/rate_limitedならその中でより深刻な方（missing相当）を優先して報告する
    if regime_status in ("rate_limited", "failed") and cache_status == "ok":
        cache_status = regime_status
    elif regime_status == "stale_cache" and cache_status == "ok":
        cache_status = "stale_cache"
    return {
        "current": quote.get("t") if quote else None,
        "currentChangePct": current_change_pct,
        "vwap": regime["vwap"] if regime else None,  # トレード分析リアルタイム自動更新（2026-09-12）で使用。既存のaboveVwap判定は無変更
        "aboveVwap": regime["aboveVwap"] if regime else None,
        "fiveMinStructure": regime["pattern"] if regime else None,
        "dataStatus": "ok" if (quote and regime) else ("partial" if (quote or regime) else "failed"),
        "cacheStatus": cache_status,
    }


def evaluate_morning_thesis(morning_top5_item, snapshot, nikkei_chg):
    """朝の仮説（Morning CheckのTOP5候補1件）が実市場で成立したかを判定する（指示書5・6番）。
    「株価が上がった＝当たり」にはせず、VWAP位置・5分足構造・対市場相対強度（地合いに対する
    相対強度）を合わせて見る。データ不足時はDATA_INSUFFICIENTとし、無理に当たり外れを判定しない
    （指示書29番）。"""
    if snapshot["dataStatus"] == "failed" or snapshot["currentChangePct"] is None:
        return "DATA_INSUFFICIENT"
    chg = snapshot["currentChangePct"]
    above_vwap = snapshot["aboveVwap"]
    structure = snapshot["fiveMinStructure"]
    market_rs = (chg - nikkei_chg) if nikkei_chg is not None else None
    relatively_strong = market_rs is not None and market_rs >= 1.0
    if chg <= 0 and not relatively_strong:
        # トリガー（VWAP上・出来高増）未発動のまま下落＝まだ検証材料が無いのか、外れたのかを分ける
        if above_vwap is False and structure == "lower_lows":
            return "INVALIDATED"
        return "NOT_TRIGGERED"
    if above_vwap and structure == "higher_highs" and (chg > 0 or relatively_strong):
        return "CONFIRMED"
    if above_vwap is None:
        return "DATA_INSUFFICIENT"
    if above_vwap or relatively_strong:
        return "PARTIAL"
    return "INVALIDATED"


# ============================================================
# Market Intelligence Timeline Phase2-C（今買い時TOP5＋Thesis永続化）。2026-09-10新規。
# 「今日の注目TOP5」（trade-cockpit.htmlのenrichWatchRow()だけを使うフロント側の既存軽量
# ロジック、v3-4）とは別物。こちらは「現在最も条件が整っているENTRY候補」（entry_ready_top5）を
# ENTRY SCORE（0-100、重み付け）でサーバー側から算出し、Watch候補とは明確に分離する。既存の
# 5エンジン（run_momentum_stage1・AUTO_RS・AUTO_SECTOR_LEADER・AUTO_VOLUME）・Market
# Intelligence Timelineの個別銘柄5分足判定（_intraday_stock_snapshot・evaluate_morning_thesis・
# _thesis_transition_status・_final_top5_result）をそのまま再利用し、新しい全市場スキャン・
# 新しい判定ロジックの重複実装はしない。missed_opportunities本格分析・sector_rotation統計・
# 5/20/60営業日統計・自動ルール生成・自動売買はPhase2-Cの範囲外（ユーザー指示）。
# ============================================================

ENTRY_STATE_META = {
    "NOW_BUYABLE":   {"label": "今すぐ買える", "tier": 5},
    "ENTRY_READY":   {"label": "エントリー準備完了", "tier": 4},
    "WAIT_PULLBACK": {"label": "押し目待ち", "tier": 3},
    "WAIT_BREAKOUT": {"label": "ブレイク待ち", "tier": 3},
    "WATCH":         {"label": "監視継続", "tier": 2},
    "CHASE_RISK":    {"label": "高値掴みリスク", "tier": 1},
    "WEAK":          {"label": "弱い", "tier": 0},
    "INVALID":       {"label": "根拠崩れ", "tier": 0},
    "PROVISIONAL":   {"label": "データ不足（暫定）", "tier": 0},
}


def _entry_score_components(row, stage2, snapshot, auto_rs_current, auto_sector_current, catalysts, event_signals,
                             entry_risk=None):
    """entry_score（0-100、内訳の合計をclampしたもの）を配点ごとに算出する。既存の各エンジンが
    既に計算済みの値だけを使い、新しい取得経路は増やさない。データが無い項目は0点（無理に
    加点も減点もしない、「取得できない値は推測しない」の踏襲）。
    配点：Momentum20/VWAP15/5分足構造15/MarketRelative15/Volume10/AUTO_RS10/AUTO_SECTOR5/
    Catalyst5/RiskEvent-5〜0/Overheat-10〜0/Experience-8〜+3（2026-09-15新規、指示書3・4番）。
    entry_risk（compute_entry_risk_assessment()の戻り値）は信頼度MEDIUM/HIGH（サンプル5件以上）
    の時だけ加減点し、サンプル不足（LOW）では一切スコアに影響させない（過去の損切り学習を
    「過大評価しない」既存方針＝compute_experience_score等と同じキャップ思想を踏襲）。"""
    day_change = row.get("changePct")
    market_rs = row.get("marketRS")
    momentum = _scale_score(day_change, 0, 5, 20) if day_change is not None else 0.0

    above_vwap = snapshot.get("aboveVwap") if snapshot else None
    vwap_score = 15.0 if above_vwap else 0.0

    structure = snapshot.get("fiveMinStructure") if snapshot else None
    structure_score = 15.0 if structure == "higher_highs" else (7.0 if structure == "mixed" else 0.0)

    market_rel_score = _scale_score(market_rs, 0, 5, 15) if market_rs is not None else 0.0

    volume_type = _volume_type(stage2, row) if stage2 else "NEUTRAL_VOLUME"
    tavr = stage2.get("timeAdjustedVolumeRatio") if stage2 else None
    volume_score = 0.0 if volume_type in ("NEGATIVE_VOLUME", "CLIMAX_DOWN") else _scale_score(tavr, 1.0, 3.0, 10)

    auto_rs_score = 10.0 if row.get("code") in auto_rs_current else 0.0
    auto_sector_score = 5.0 if row.get("code") in auto_sector_current else 0.0

    pos_cat = [c for c in (catalysts or []) if c.get("sentiment") == "positive" and c.get("freshness") in ("LIVE", "CURRENT")]
    neg_cat = [c for c in (catalysts or []) if c.get("sentiment") == "negative" and c.get("freshness") in ("LIVE", "CURRENT")]
    catalyst_score = 5.0 if pos_cat else 0.0

    risk_event_penalty = 0.0
    if "EVENT_RISK_HIGH" in (event_signals or []):
        risk_event_penalty = -5.0
    if neg_cat:
        risk_event_penalty = -5.0

    overheat_penalty = 0.0
    if volume_type == "CLIMAX_UP":
        overheat_penalty = -10.0
    elif stage2 and stage2.get("aboveRecentHigh") and stage2.get("distanceFromHighPct") is not None:
        d = stage2["distanceFromHighPct"]
        if d >= 5:
            overheat_penalty = -10.0
        elif d >= 2:
            overheat_penalty = -5.0

    experience_penalty = 0.0
    experience_bonus = 0.0
    if entry_risk and entry_risk.get("confidence") in ("MEDIUM", "HIGH"):
        risk_score = entry_risk.get("entry_risk_score") or 0.0
        if risk_score >= 50:
            experience_penalty = -8.0
        elif risk_score >= 25:
            experience_penalty = -4.0
        good_sim = entry_risk.get("good_entry_similarity") or 0.0
        if experience_penalty == 0.0 and good_sim >= 0.5:
            experience_bonus = 3.0

    total = (momentum + vwap_score + structure_score + market_rel_score + volume_score
             + auto_rs_score + auto_sector_score + catalyst_score + risk_event_penalty + overheat_penalty
             + experience_penalty + experience_bonus)
    total = max(0.0, min(100.0, total))
    return {
        "total": round(total, 1),
        "momentum": round(momentum, 1), "vwap": round(vwap_score, 1), "fiveMinStructure": round(structure_score, 1),
        "marketRelative": round(market_rel_score, 1), "volume": round(volume_score, 1),
        "autoRs": round(auto_rs_score, 1), "autoSector": round(auto_sector_score, 1),
        "catalyst": round(catalyst_score, 1), "riskEvent": round(risk_event_penalty, 1),
        "overheat": round(overheat_penalty, 1),
        "experiencePenalty": round(experience_penalty, 1), "experienceBonus": round(experience_bonus, 1),
        "volumeType": volume_type, "positiveCatalysts": pos_cat[:1], "negativeCatalysts": neg_cat[:1],
    }


def _classify_entry_state(entry_score, row, stage2, snapshot, data_quality, event_signals, neg_cat_present, nikkei_chg=None,
                           entry_risk=None):
    """ENTRY_STATE（8種＋PROVISIONAL）をルールベースで決定する（AI不使用、既存AUTO系エンジンと
    同じ方針）。2026-09-10更新（Phase2-C「TOP5選考基準の全面見直し」指示書2・3・24番）：
    「原則プラス銘柄からしか選ばない」ゲートを追加した。当日騰落率がマイナスの銘柄は、以下を
    "すべて"満たす例外（逆行耐性例外）でない限りNOW_BUYABLE/ENTRY_READYにはならない
    （WATCH/WEAKへ回り、Watchlist側で「反転待ち」等として扱われる想定）：
      ①市場全体が大幅安（nikkei_chg<=-1.0%）②銘柄は小幅マイナス（changePct>=-1.0%）
      ③対市場RSが極めて強い（marketRS>=+2.0pt）④VWAP回復済み（aboveVwap）
      ⑤5分足で明確な反転（fiveMinStructure=="higher_highs"）⑥出来高増加
      （POSITIVE_VOLUME、または時間帯補正済み出来高倍率>=1.3）
    戻り値：(entry_state, exception_applied)。exception_applied=Trueの時、呼び出し側は
    reasonsに「逆行耐性例外」を明示する（指示書3番「その場合UIで理由を明示」）。
    data_quality=DEGRADED（Stage2・5分足スナップショットの両方が欠落）の場合はPROVISIONAL固定
    ＝confidence=LOWの銘柄をNOW_BUYABLEにしない（指示書26番）。"""
    if data_quality == "DEGRADED":
        return "PROVISIONAL", False
    above_vwap = snapshot.get("aboveVwap") if snapshot else None
    structure = snapshot.get("fiveMinStructure") if snapshot else None
    market_rs = row.get("marketRS")
    day_change = row.get("changePct")
    volume_type = _volume_type(stage2, row) if stage2 else "NEUTRAL_VOLUME"
    tavr = stage2.get("timeAdjustedVolumeRatio") if stage2 else None
    making_new_low = bool(stage2 and stage2.get("makingNewLowToday"))
    overheated = volume_type == "CLIMAX_UP" or bool(
        stage2 and stage2.get("aboveRecentHigh") and (stage2.get("distanceFromHighPct") or 0) >= 5)

    exception_applied = False
    if day_change is not None and day_change <= 0:
        market_selloff = nikkei_chg is not None and nikkei_chg <= -1.0
        small_decline = day_change >= -1.0
        strong_market_rs = market_rs is not None and market_rs >= 2.0
        vwap_recovered = above_vwap is True
        reversal_structure = structure == "higher_highs"
        volume_up = volume_type == "POSITIVE_VOLUME" or (tavr is not None and tavr >= 1.3)
        exception_applied = all([market_selloff, small_decline, strong_market_rs,
                                  vwap_recovered, reversal_structure, volume_up])
        if not exception_applied:
            # プラス転換の根拠が無いマイナス銘柄はNOW_BUYABLE/ENTRY_READYの対象から除外
            # （後段のCHASE_RISK/INVALID/WEAKの判定はこの後も通常どおり行う）。
            if neg_cat_present and (making_new_low or (market_rs is not None and market_rs < 0)):
                return "INVALID", False
            return ("WATCH" if entry_score >= 30 else "WEAK"), False

    if neg_cat_present and (making_new_low or (market_rs is not None and market_rs < 0)):
        return "INVALID", False
    if overheated:
        return "CHASE_RISK", exception_applied
    if entry_score < 30:
        return "WEAK", exception_applied
    if "EVENT_RISK_HIGH" in (event_signals or []) and entry_score < 60:
        return "WATCH", exception_applied
    # 指示書4番：過去の損切りパターンとの類似度が高く信頼できるサンプル数がある場合は、
    # NOW_BUYABLE/ENTRY_READYへの昇格をWATCHに留める（entry_score自体は変更しない、
    # 状態遷移だけを止める＝「ENTRYを止めている理由」を呼び出し側がreasonsで明示できるようにする）。
    loss_pattern_block = bool(entry_risk and entry_risk.get("risk_level") == "HIGH"
                               and entry_risk.get("confidence") != "LOW")
    if above_vwap and structure == "higher_highs" and (market_rs is not None and market_rs > 0) and entry_score >= 70:
        return ("WATCH" if loss_pattern_block else "NOW_BUYABLE"), exception_applied
    if above_vwap and structure in ("higher_highs", "mixed") and entry_score >= 55:
        return ("WATCH" if loss_pattern_block else "ENTRY_READY"), exception_applied
    if entry_score >= 40 and above_vwap is False:
        return "WAIT_BREAKOUT", exception_applied
    if entry_score >= 40 and above_vwap:
        return "WAIT_PULLBACK", exception_applied
    if entry_score >= 30:
        return "WATCH", exception_applied
    return "WEAK", exception_applied


ENTRY_TOP5_TIER2_MIN_SCORE = 60
ENTRY_TOP5_TIER3_MIN_SCORE = 45
ENTRY_TOP5_TIER1_STATES = ("NOW_BUYABLE", "ENTRY_READY")
ENTRY_TOP5_TIER2_STATES = ("WAIT_BREAKOUT", "WAIT_PULLBACK")
ENTRY_TOP5_RISK_STATES = ("CHASE_RISK", "INVALID")


def _select_entry_ready_top5(candidates):
    """TOP5表示ロジック修正指示（2026-09-12）：entry_score降順ソート済みのcandidates
    （_score_entry_candidates()の中間結果、各要素はentryState/entryScore/codeを持つdict）から
    entry_ready_top5・watch_candidates・デバッグ集計を算出する純粋関数（DB書き込みなし、
    ネットワークアクセスなし）。単体テストしやすいよう_score_entry_candidates()から分離した。

    「TOP5は必ず5件」ではなく「候補があるだけ表示（0〜5件）」に統一。ENTRY READY銘柄が
    ありながらTOP5が0件になる不整合を無くすため、候補母集団をentry_state単独ではなく
    優先度3階層（Tier）に広げる：
      Tier1: NOW_BUYABLE / ENTRY_READY（そのまま今買える）
      Tier2: WAIT_BREAKOUT / WAIT_PULLBACK かつ entry_score>=ENTRY_TOP5_TIER2_MIN_SCORE
             （指示書の「ACTIVE BREAKかつentry_score高」に相当。まだブレイク/押し目待ちだが
             スコアが高く「もうすぐ入れる」候補）
      Tier3: WATCH かつ entry_score>=ENTRY_TOP5_TIER3_MIN_SCORE
             （指示書の「WATCHだが直近でENTRY READY昇格条件に近い」。ENTRY_READY昇格の
             entry_score閾値55に対し、45以上を「近い」とみなす）
    CHASE_RISK/INVALID（RISK相当）・WEAK・PROVISIONAL（データ不足で確信度LOW固定、指示書
    26番の既存方針を維持）はTier対象外＝原則TOP5に出さない。Tier内はentry_score降順（呼び出し
    元で既にソート済み）、Tier間はTier1→2→3の優先順位（Tierをまたいで単純スコア降順には
    しない＝「今すぐ入れる」を常に最優先する）。

    戻り値：(entry_ready_top5, watch_candidates, debug)。debugは指示書7番の開発用デバッグ
    表示用（0件時にどの条件で候補が落ちたかを追える）。"""
    tier1 = [c for c in candidates if c["entryState"] in ENTRY_TOP5_TIER1_STATES]
    tier2 = [c for c in candidates if c["entryState"] in ENTRY_TOP5_TIER2_STATES and c["entryScore"] >= ENTRY_TOP5_TIER2_MIN_SCORE]
    tier3 = [c for c in candidates if c["entryState"] == "WATCH" and c["entryScore"] >= ENTRY_TOP5_TIER3_MIN_SCORE]
    risk_excluded = [c for c in candidates if c["entryState"] in ENTRY_TOP5_RISK_STATES]
    weak_excluded = [c for c in candidates if c["entryState"] == "WEAK"]
    provisional_excluded = [c for c in candidates if c["entryState"] == "PROVISIONAL"]

    for c in tier1:
        c["candidateTier"] = 1
    for c in tier2:
        c["candidateTier"] = 2
    for c in tier3:
        c["candidateTier"] = 3

    entry_ready_top5 = (tier1 + tier2 + tier3)[:5]
    top5_codes = {c["code"] for c in entry_ready_top5}
    watch_candidates = [c for c in candidates
                         if c["entryState"] in ("WAIT_PULLBACK", "WAIT_BREAKOUT", "WATCH")
                         and c["code"] not in top5_codes][:15]

    debug = {
        "scanned": len(candidates),
        "entry_ready": len(tier1),
        "active_break": len(tier2),
        "watch_near_ready": len(tier3),
        "risk_excluded": len(risk_excluded),
        "failed_break_excluded": 0,  # breakType/FAILED_BREAKはフロント側enrichWatchRow()専用の概念（サーバー側entry_stateには存在しない）
        "weak_excluded": len(weak_excluded),
        "provisional_excluded": len(provisional_excluded),
        "final_candidates": len(entry_ready_top5),
        "rendered": len(entry_ready_top5),
    }
    return entry_ready_top5, watch_candidates, debug


ENTRY_CANDIDATE_EVENT_LOOKBACK_DAYS = 7  # build_ticker_intelligence_summary()のデフォルトlookback_daysと合わせる
ENTRY_CANDIDATE_EVENT_SIGNALS_DAYS_AHEAD = 7  # upcoming_event_signals()のデフォルトdays_aheadと合わせる
ENTRY_CANDIDATE_CATALYSTS_LIMIT = 3  # 既存の個別呼び出し（relevant_catalysts_for(..., limit=3)）と同じ値


def get_entry_candidate_support_context(database_url, user_id, codes_with_sector):
    """Market Data高速化指示書 Phase 2（2026-09-15新規）：ENTRY TOP5のDB N+1解消。
    _score_entry_candidates()のwatchlistループが候補1件ごとに個別DB取得していた
    catalysts/events/event_support/trade_experienceを、symbol数によらず高々4回のDB取得
    （news_catalysts一覧・market_events一覧・trade_experiences一覧・event_decision_support
    バッチ）にまとめる。実測（Phase 1完了後）：30銘柄で計約238秒（4 helper×30回＝120回の
    個別DB接続）かかっていたが、catalysts/events/trade_experiencesの取得クエリ自体はcode/
    sectorに依存しないuser_id単位のものだった（絞り込みはPython側）ため、1回だけ取得して
    使い回せる。event_decision_supportだけticker単位のWHERE句が要るため、
    list_event_decision_support_for_tickers()（ANY(%s)によるバッチSQL）を新設した。

    判定ロジックは一切変更していない——既存の各helper関数（relevant_catalysts_for・
    upcoming_event_signals・build_entry_top5_event_support_label・
    build_trade_experience_summary_for_symbol）へ_preloaded_*引数で事前取得済みデータを
    渡すだけで、フィルタ・集計・スコアリングの実装そのものは完全に同じコードパスを通る
    （指示書E・F「判定式をSQLへ移植しない」、ゴールデン比較テストで既存結果と一致を確認）。

    codes_with_sector: [(code, sector), ...]（sectorはNone可）。
    戻り値: (context, diagnostics)。
    context = {code: {"catalysts": [...], "eventInfo": {"events":[...],"signals":[...]},
                        "eventSupport": "STRONG"|"NEUTRAL"|"CAUTION"|"AVOID_CHASE"|None,
                        "tradeExperience": {"experience_score":..,"similar":{...}}|None}, ...}
    diagnostics = {"symbols":N,"db_connections":N,"db_queries":N,"db_elapsed_ms":N,
                    "batch_loaded":bool,"fallback_queries":0,"errors":[...]}

    指示書I：データ種別ごとの取得が失敗しても、その種別だけ空データにして残りは継続する
    （catalysts取得だけ失敗してもevents/event_support/trade_experienceは通常通り計算される）。
    281件全部を個別クエリへフォールバックすることはしない（fallback_queriesは常に0＝
    このバッチ経路を使う限り追加のper-symbol DB接続を発生させない設計）。"""
    # 指示書R5：同一symbolがwatchlistに重複して含まれていても（想定外の入力でも）、
    # DB取得・後続ループとも1回だけ処理する（最初に出てきたsectorを採用、code単位でdedupe）。
    _seen_codes = set()
    _deduped = []
    for code, sector in codes_with_sector:
        if code in _seen_codes:
            continue
        _seen_codes.add(code)
        _deduped.append((code, sector))
    codes_with_sector = _deduped
    result = {code: {"catalysts": [], "eventInfo": {"events": [], "signals": []},
                       "eventSupport": None, "tradeExperience": None}
               for code, _sector in codes_with_sector}
    diagnostics = {"symbols": len(codes_with_sector), "db_connections": 0, "db_queries": 0,
                    "db_elapsed_ms": 0, "batch_loaded": False, "fallback_queries": 0, "errors": []}
    if investment_db is None or not database_url or not codes_with_sector:
        return result, diagnostics

    t0 = time.time()
    today = datetime.date.today()

    catalysts_all = None
    try:
        catalysts_all = investment_db.list_news_catalysts(database_url, user_id, limit=200)
        diagnostics["db_connections"] += 1
        diagnostics["db_queries"] += 1
    except Exception as e:
        print("  entry-candidates(batch): catalysts一括取得で例外（catalystsは空扱いで続行）", e)
        diagnostics["errors"].append(f"catalysts:{e}")

    events_all = None
    try:
        events_all = investment_db.list_market_events(
            database_url, user_id, from_date=today.isoformat(),
            to_date=(today + datetime.timedelta(days=ENTRY_CANDIDATE_EVENT_SIGNALS_DAYS_AHEAD)).isoformat())
        diagnostics["db_connections"] += 1
        diagnostics["db_queries"] += 1
    except Exception as e:
        print("  entry-candidates(batch): market_events一括取得で例外（eventsは空扱いで続行）", e)
        diagnostics["errors"].append(f"events:{e}")

    experiences_all = None
    try:
        experiences_all = investment_db.list_trade_experiences(database_url, user_id, limit=1000)
        diagnostics["db_connections"] += 1
        diagnostics["db_queries"] += 1
    except Exception as e:
        print("  entry-candidates(batch): trade_experiences一括取得で例外（trade_experienceは空扱いで続行）", e)
        diagnostics["errors"].append(f"experiences:{e}")

    codes = [c for c, _s in codes_with_sector]
    event_support_rows = {}
    try:
        since_iso = (datetime.datetime.now(datetime.timezone.utc)
                     - datetime.timedelta(days=ENTRY_CANDIDATE_EVENT_LOOKBACK_DAYS)).isoformat()
        event_support_rows = investment_db.list_event_decision_support_for_tickers(database_url, codes, since_iso)
        diagnostics["db_connections"] += 1
        diagnostics["db_queries"] += 1
    except Exception as e:
        print("  entry-candidates(batch): event_decision_support一括取得で例外（event_supportは空扱いで続行）", e)
        diagnostics["errors"].append(f"event_support:{e}")

    for code, sector in codes_with_sector:
        entry = result[code]
        if catalysts_all is not None:
            try:
                entry["catalysts"] = investment_db.relevant_catalysts_for(
                    database_url, user_id, code=code, sector=sector, limit=ENTRY_CANDIDATE_CATALYSTS_LIMIT,
                    _preloaded_catalysts=catalysts_all)
            except Exception as e:
                print("  entry-candidates(batch): catalystsフィルタで例外", code, e)
        if events_all is not None:
            try:
                entry["eventInfo"] = investment_db.upcoming_event_signals(
                    database_url, user_id, code=code, sector=sector, _preloaded_events=events_all)
            except Exception as e:
                print("  entry-candidates(batch): eventsフィルタで例外", code, e)
        try:
            entry["eventSupport"] = build_entry_top5_event_support_label(
                database_url, code, _preloaded_rows=event_support_rows.get(code, []))
        except Exception as e:
            print("  entry-candidates(batch): event_support算出で例外", code, e)
        if experiences_all is not None:
            try:
                entry["tradeExperience"] = build_trade_experience_summary_for_symbol(
                    database_url, user_id, code, _preloaded_experiences=experiences_all)
            except Exception as e:
                print("  entry-candidates(batch): trade_experience算出で例外", code, e)

    diagnostics["db_elapsed_ms"] = round((time.time() - t0) * 1000)
    diagnostics["batch_loaded"] = True
    print(f"  [EntrySupportPrefetch] symbols={diagnostics['symbols']} db_connections={diagnostics['db_connections']} "
          f"db_queries={diagnostics['db_queries']} errors={len(diagnostics['errors'])} elapsed={diagnostics['db_elapsed_ms']}ms")
    return result, diagnostics


def _summarize_per_symbol_ms(per_symbol_ms):
    """Market Data高速化指示書 Phase 5 STEP3：per_symbol_ms（[(code, elapsed_ms), ...]）から
    count/avg/median/p90/p95/max・slowest上位10件を集計する（通常ログへ281行出さないための
    集計専用ヘルパー、分析ロジックには関与しない）。"""
    if not per_symbol_ms:
        return {"count": 0, "avgMs": 0, "medianMs": 0, "p90Ms": 0, "p95Ms": 0, "maxMs": 0, "slowest": []}
    values = sorted(per_symbol_ms, key=lambda x: x[1])
    ms_values = [v for _c, v in values]
    n = len(ms_values)

    def _percentile(p):
        idx = min(n - 1, max(0, int(round(p * (n - 1)))))
        return round(ms_values[idx], 2)

    slowest = sorted(per_symbol_ms, key=lambda x: -x[1])[:10]
    return {
        "count": n,
        "avgMs": round(sum(ms_values) / n, 2),
        "medianMs": _percentile(0.5),
        "p90Ms": _percentile(0.9),
        "p95Ms": _percentile(0.95),
        "maxMs": round(max(ms_values), 2),
        "slowest": [{"code": c, "elapsedMs": round(v, 2)} for c, v in slowest],
    }


def _score_entry_candidates(database_url, user_id):
    """今買い時TOP5（entry_ready_top5）とWatch候補を算出する純粋関数（DB書き込みなし）。
    既存の共有Stage1（run_momentum_stage1、複数AUTOエンジンとキャッシュ共有）・
    AUTO_RS/AUTO_SECTOR_LEADERのCURRENT登録・AUTO_VOLUMEのStage2（_volume_stage2_detail）・
    Market Intelligence Timelineの個別銘柄5分足判定（_intraday_stock_snapshot）をそのまま
    再利用する（新規の全市場スキャン・新規の分足取得経路は追加しない）。対象は監視銘柄
    （watchlist）のみ（全市場4000銘柄には広げない。「Watch候補との分離」は監視銘柄内での話）。
    2026-09-10更新（Phase2-C）：「Current TOP5」（/api/entry-candidates、いつでも再計算）と
    「朝TOP5」（MorningMarketCheck、08:50固定・成績評価用）の両方がこの同じ関数を使う——
    永続化（stock_thesesへの書き込み）はしない副作用フリーな関数にし、呼び出し側
    （generate_morning_market_check）だけが朝TOP5として結果を保存する設計にした（指示書
    22・23番「Current TOP5とMorning TOP5は別物、Morning TOP5は後から書き換えない」）。"""
    empty = {"entryReadyTop5": [], "watchCandidates": [], "dataQuality": "DEGRADED", "generatedAt": None,
             "debug": {"scanned": 0, "entry_ready": 0, "active_break": 0, "watch_near_ready": 0,
                       "risk_excluded": 0, "failed_break_excluded": 0, "weak_excluded": 0,
                       "provisional_excluded": 0, "final_candidates": 0, "rendered": 0}}
    if investment_db is None or not database_url:
        return empty

    # Market Data高速化指示書 Phase 5（2026-09-15新規）：STEP2区間計測。ロジックには一切
    # 関与しない計測専用のtime.time()呼び出しのみを追加している（既存の分岐・計算式は不変）。
    # section_msはdebugへ追加専用フィールドとして格納するだけ（デバッグ/ログ専用、UI必須ではない）。
    _t_start = time.time()
    section_ms = {}

    watchlist = investment_db.list_watchlist(database_url, user_id, market="JP")
    section_ms["watchlistLoad"] = round((time.time() - _t_start) * 1000)
    if not watchlist:
        return empty

    _t = time.time()
    stage1 = run_momentum_stage1()
    section_ms["stage1"] = round((time.time() - _t) * 1000)
    stage1_rows = stage1.get("rows", {})
    nikkei_chg = stage1.get("nikkeiChangePct")

    _t = time.time()
    auto_rs_current = investment_db.get_codes_with_auto_tag(database_url, user_id, "AUTO_RS_CURRENT", market="JP")
    auto_sector_current = investment_db.get_codes_with_auto_tag(database_url, user_id, "AUTO_SECTOR_LEADER_CURRENT", market="JP")
    section_ms["autoTags"] = round((time.time() - _t) * 1000)

    # Market Data高速化指示書 Phase B（2026-09-15新規）：この関数は以下のwatchlist全件
    # （監視銘柄すべて、Phase 0計測で300件超を確認）に対して1件ずつ_intraday_stock_snapshot()
    # →get_stock_quotes([item])・_intraday_regime_cached()を呼ぶ既存ループを持つ。個別呼び出し
    # 自体は既にキャッシュ+リトライ+stale fallback済みだが、キャッシュが空の初回実行では
    # 「1銘柄ずつ」ネットワーク往復するため合計で数分かかる（Phase0実測、根本原因）。
    # ここでループに入る前に対象銘柄をまとめてバッチ取得しキャッシュへ事前投入すること
    # （prefetch）で、ループ内の個別呼び出しをキャッシュヒットに変える。ループ内の既存ロジック
    # （_intraday_stock_snapshot・_volume_stage2_detail・_entry_score_components等）は一切
    # 変更していない——prefetch失敗時も個別フォールバックでこれまで通り動作する。
    _t = time.time()
    try:
        market_data_diagnostics = prefetch_market_data_for_watchlist(watchlist)
    except Exception as e:
        # prefetch自体は内部で各取得を個別にtry/exceptしているため通常ここには来ないが、
        # 万一の場合でも「データがないのに分析全体を止める」ことがないよう、既存の他の
        # 「無視して続行」ブロックと同じ方針でここでも握りつぶす（後続ループは個別フォールバック
        # 経路でこれまで通り動作する）。
        print("  entry-candidates: market data prefetchで例外（無視して続行）", e)
        market_data_diagnostics = {"error": str(e)}
    section_ms["marketDataPrefetch"] = round((time.time() - _t) * 1000)

    # 場中リアルタイム化指示書 レビュー反映（scan-local quote/5分足 reuse）：daily arraysと
    # 全く同じ理由（このscan自体がグローバルTTL=90秒を超えうる）で、quote/5分足も同一scan内は
    # prefetch結果を使い回す。market_data_diagnosticsからpopするのもdaily_arraysと同じ理由
    # （marketDataByCodeは281銘柄分のquote/5分足そのものを含み巨大——debug["marketDataDiagnostics"]
    # 経由でAPIレスポンスへ漏れるとpayloadが肥大化する）。
    market_data_by_code = market_data_diagnostics.pop("marketDataByCode", {}) or {}
    quote_scan_local_hit = 0
    quote_fallback_count = 0
    intraday_scan_local_hit = 0
    intraday_fallback_count = 0

    # Market Data高速化指示書 Phase 2（2026-09-15新規）：DB N+1解消。この下のループは
    # candidate 1件ごとにrelevant_catalysts_for/upcoming_event_signals/
    # build_entry_top5_event_support_label/build_trade_experience_summary_for_symbolを
    # 個別に呼んでいた（Phase 1完了後の実測で判明：30銘柄で計約238秒、281銘柄では約60分に
    # 達する根本原因）。実際にはcatalysts/events/trade_experiencesの取得クエリ自体は
    # user_id単位で銘柄非依存（code/sectorによる絞り込みはPython側で行っている）ため、
    # ループへ入る前に対象銘柄分だけまとめて1回ずつ取得し、既存のフィルタ・集計ロジック
    # そのもの（_preloaded_*引数経由で同じ関数を再利用）へ渡す。判定ロジックは一切変更
    # していない（ゴールデン比較テストで確認）。対象はこの後のループと同じ判定条件
    # （stage1_rowsに有効な現在値がある銘柄のみ）に絞る。
    support_targets = []
    for w in watchlist:
        code = w.get("code")
        row = stage1_rows.get(code)
        if row and row.get("current") is not None:
            support_targets.append((code, row.get("sector")))
    _t = time.time()
    try:
        support_context, entry_support_diagnostics = get_entry_candidate_support_context(database_url, user_id, support_targets)
    except Exception as e:
        # 指示書I：batch失敗時に281件へ無制限フォールバックするとまたDB N+1（約60分）に戻って
        # しまうため、ここでは個別フォールバックをしない——catalysts/events/event_support/
        # trade_experienceが空のまま後続ループを続行する（価格分析・entry_score自体は
        # catalysts等が空でも計算できる設計のため、分析全体は落ちない）。
        print("  entry-candidates: support contextバッチ取得で例外（catalysts等は空扱いで続行、個別フォールバックはしない）", e)
        support_context, entry_support_diagnostics = {}, {"error": str(e)}
    section_ms["dbSupportPrefetch"] = round((time.time() - _t) * 1000)

    # Market Data高速化指示書 Phase 3（2026-09-15新規）：この下のループが候補1件ごとに呼ぶ
    # _volume_stage2_detail()→_cached_daily_arrays()→tachibana_api.get_daily_history()
    # （立花証券APIの日足履歴、1銘柄のみ・batch endpoint無し）を、ループへ入る前にまとめて
    # 取得しキャッシュへ事前投入する。実測：20銘柄サンプルで平均2.19秒/件、281銘柄で
    # 約615秒に達していた根本原因（Phase1・2のどちらの対象にも含まれていなかった第3の
    # 経路）。STEP3実測でTachibanaのセッションが同時アクセスに弱いと判明したため
    # （関数側のコメント参照）、既定では並列化せずキャッシュ事前投入とget_market_price
    # 個別呼び出しの排除（このループより上の_cached_daily_arrays呼び出しでも同様）で
    # 削減する。失敗時も281件への無制限フォールバックはせず、ループ内の既存
    # _cached_daily_arrays()がキャッシュミス分だけ個別に取得を試みる（既存の安全側動作）。
    _t = time.time()
    try:
        daily_arrays_diagnostics = prefetch_daily_arrays_for_watchlist(watchlist, stage1_rows)
    except Exception as e:
        print("  entry-candidates: daily arrays prefetchで例外（無視して続行、既存の個別取得へ委ねる）", e)
        daily_arrays_diagnostics = {"error": str(e)}
    section_ms["dailyArraysPrefetch"] = round((time.time() - _t) * 1000)

    # 場中リアルタイム化指示書 レビュー反映（scan-local daily arrays reuse）：このscan内では
    # prefetch_daily_arrays_for_watchlist()が実際に使った値（arraysByCode）をそのまま
    # candidate loopで使い回し、_cached_daily_arrays()のグローバルTTL（90秒）を経由しない。
    # 281銘柄の逐次prefetch自体が90秒を超えうるため、TTL経由だと同一scan内でも後半の
    # 銘柄で二重取得が発生していた（実測682秒中、dailyArraysPrefetch=295秒・
    # candidateLoopTotalの一部がこの二重取得によるもの）。
    daily_arrays_by_code = daily_arrays_diagnostics.pop("arraysByCode", {}) or {}
    # popで取り除く理由：daily_arrays_diagnosticsはこの後debug["dailyArraysDiagnostics"]へ
    # 丸ごと格納されAPIレスポンス（/api/entry-candidates・/api/entry-candidates/live）に
    # 直接乗る。arraysByCodeは281銘柄×直近400営業日分のOHLCV配列を含み巨大（実測でJSON化
    # すると数MB級）なため、ここで除去しないとAPIレスポンスサイズ・シリアライズ時間を
    # 不必要に膨張させてしまう（診断ログ用途はcandidateループでの再利用のみで十分）。
    daily_arrays_scan_local_hit = 0
    daily_arrays_fallback_count = 0

    # Phase5 STEP3・STEP4：銘柄ごとのtotal elapsed（percentile集計用）と、
    # ループ内で実際に呼ばれる2関数（_volume_stage2_detail・_intraday_stock_snapshot）
    # それぞれのcall count/total_ms/max_msを集計する（通常ログへは281行出さない）。
    per_symbol_ms = []
    func_stats = {"_volume_stage2_detail": {"calls": 0, "total_ms": 0.0, "max_ms": 0.0},
                  "_intraday_stock_snapshot": {"calls": 0, "total_ms": 0.0, "max_ms": 0.0}}
    _t_loop = time.time()
    candidates = []
    quality_counts = {"FULL": 0, "PARTIAL": 0, "DEGRADED": 0}
    snapshot_ready_count = 0  # 場中リアルタイム化指示書 STEP1・20：5分足スナップショットが取得できた銘柄数（"intraday_ready"の実体）
    for w in watchlist:
        code = w.get("code")
        row = stage1_rows.get(code)
        if not row or row.get("current") is None:
            continue
        _t_symbol = time.time()
        stage2 = None
        try:
            _t_fn = time.time()
            if code in daily_arrays_by_code:
                daily_arrays_scan_local_hit += 1
                stage2 = _volume_stage2_detail(code, row, daily_arrays=daily_arrays_by_code[code])
            else:
                # prefetchが対象外だった銘柄（米国株等、対象外市場）・prefetch自体が丸ごと
                # 例外で失敗した場合のみここへ来る。既存の個別取得（_cached_daily_arrays経由）
                # へ安全側でフォールバックする。
                daily_arrays_fallback_count += 1
                stage2 = _volume_stage2_detail(code, row)
            fn_ms = (time.time() - _t_fn) * 1000
            func_stats["_volume_stage2_detail"]["calls"] += 1
            func_stats["_volume_stage2_detail"]["total_ms"] += fn_ms
            func_stats["_volume_stage2_detail"]["max_ms"] = max(func_stats["_volume_stage2_detail"]["max_ms"], fn_ms)
        except Exception as e:
            print("  entry-candidates: Stage2取得失敗", code, e)
        snapshot = None
        market_data_cache_status = "failed"  # 場中リアルタイム化指示書STEP9：ranking_generated_atだけでなく
        # 銘柄ごとのquote/5分足が実際に"ok"（今回のスキャンでライブ取得できた値）か
        # "stale_cache"（取得失敗しキャッシュ済みの古い値にフォールバックした値）かを
        # 記録する。ranking全体が新しくても、この銘柄だけ古いデータで判定されている
        # ケースを個別に検出するために必要（指示書「market_data_atも確認すること」）。
        prefetched_md = market_data_by_code.get(code)
        if prefetched_md is not None:
            quote_scan_local_hit += 1
            intraday_scan_local_hit += 1
        else:
            # prefetch_market_data_for_watchlist()の対象外だった銘柄（このscan対象watchlistは
            # market="JP"のみのため、通常は発生しない安全側フォールバック）だけがここへ来る。
            quote_fallback_count += 1
            intraday_fallback_count += 1
        try:
            _t_fn = time.time()
            snap = _intraday_stock_snapshot(w, prefetched=prefetched_md)
            fn_ms = (time.time() - _t_fn) * 1000
            func_stats["_intraday_stock_snapshot"]["calls"] += 1
            func_stats["_intraday_stock_snapshot"]["total_ms"] += fn_ms
            func_stats["_intraday_stock_snapshot"]["max_ms"] = max(func_stats["_intraday_stock_snapshot"]["max_ms"], fn_ms)
            market_data_cache_status = snap.get("cacheStatus", "failed")
            if snap.get("dataStatus") != "failed":
                snapshot = snap
                snapshot_ready_count += 1
        except Exception as e:
            print("  entry-candidates: 5分足スナップショット失敗", code, e)

        if stage2 is not None and snapshot is not None:
            data_quality = "FULL"
        elif stage2 is not None or snapshot is not None:
            data_quality = "PARTIAL"
        else:
            data_quality = "DEGRADED"
        quality_counts[data_quality] += 1
        analysis_confidence = {"FULL": "HIGH", "PARTIAL": "MEDIUM", "DEGRADED": "LOW"}[data_quality]

        support = support_context.get(code) or {}
        catalysts = support.get("catalysts", [])
        event_signals = (support.get("eventInfo") or {}).get("signals", [])

        # Trade Experience Learning新規（指示書3・4番）：ENTRY_RISK_SCOREをentry_score本体・
        # entry_stateの両方が参照できるよう、_entry_score_components()の前に取り出す。
        exp_summary = support.get("tradeExperience")
        entry_risk = (exp_summary or {}).get("entryRisk")

        comp = _entry_score_components(row, stage2, snapshot or {}, auto_rs_current, auto_sector_current, catalysts,
                                        event_signals, entry_risk=entry_risk)
        neg_cat_present = bool(comp["negativeCatalysts"])
        entry_score = comp["total"]
        entry_state, exception_applied = _classify_entry_state(
            entry_score, row, stage2, snapshot, data_quality, event_signals, neg_cat_present, nikkei_chg,
            entry_risk=entry_risk)
        resilience = _rs_resilience_tier({"changePct": row.get("changePct"), "marketRS": row.get("marketRS")}, nikkei_chg)

        reasons = []
        if comp["momentum"] > 0:
            reasons.append(f"当日+{row.get('changePct'):.1f}%の勢い")
        if comp["vwap"] > 0:
            reasons.append("VWAP上を維持")
        if comp["fiveMinStructure"] >= 15:
            reasons.append("5分足で高値切り上げ")
        if comp["marketRelative"] > 0:
            reasons.append(f"対市場+{row.get('marketRS'):.1f}pt")
        if comp["autoRs"] > 0:
            reasons.append("AUTO_RS選出中")
        if comp["autoSector"] > 0:
            reasons.append("セクター内優位（AUTO_SECTOR_LEADER）")
        if comp["positiveCatalysts"]:
            reasons.append(f"好材料：{comp['positiveCatalysts'][0].get('title','')[:20]}")
        if exception_applied:
            reasons.append("⚠逆行耐性例外（地合い逆風下でも対市場優位・VWAP回復・反転構造・出来高増を確認）")
        risks = []
        if comp["negativeCatalysts"]:
            risks.append(f"悪材料：{comp['negativeCatalysts'][0].get('title','')[:20]}")
        if comp["riskEvent"] < 0 and not comp["negativeCatalysts"]:
            risks.append("重要イベント接近")
        if comp["overheat"] < 0:
            risks.append("直近高値からの乖離が大きい（高値掴み注意）")
        # 指示書4番：「何が似ているのか」「過去何件中何件失敗したか」を具体的に表示する。
        if entry_risk and entry_risk.get("risk_level") in ("HIGH", "MEDIUM") and entry_risk.get("explanation"):
            risks.append(f"⚠ 過去の損切りパターンと類似：{entry_risk['explanation']}")

        # Market Intelligence Phase9新規（指示書21・38番）：entry_score自体には一切加点も
        # 減点もしない、隣に並べるだけの追加専用表示。
        # Market Data Phase 2：event_support/experienceはsupport_context（バッチprefetch）
        # から読むだけ——個別DB取得はしない（バッチ側で例外は既に握りつぶし済み）。
        event_support = support.get("eventSupport")

        # Trade Experience Learning新規（指示書7・20番）：EXPERIENCE_SCORE（0〜10）。
        # 既存entry_scoreには一切加点しない、完全に別枠の補助スコア（ENTRY_RISK_SCOREのみ
        # comp側で既に加減点済み——ここでは表示用にそのまま添えるだけ）。
        if exp_summary:
            experience_score = exp_summary["experience_score"]
            experience_summary = exp_summary["similar"]
        else:
            experience_score, experience_summary = None, None

        candidates.append({
            "code": code, "name": w.get("name"), "sector": w.get("sector"),
            "current": row.get("current"),
            "changePct": round(row.get("changePct"), 2) if row.get("changePct") is not None else None,
            "marketRS": round(row.get("marketRS"), 2) if row.get("marketRS") is not None else None,
            "entryScore": round(entry_score), "entryState": entry_state, "resilience": resilience,
            "analysisConfidence": analysis_confidence, "dataQuality": data_quality,
            "scoreBreakdown": comp, "reasons": reasons or ["総合スコア上位"], "risks": risks,
            "eventSupport": event_support,
            "experienceScore": experience_score, "experienceSummary": experience_summary, "entryRisk": entry_risk,
            "marketDataCacheStatus": market_data_cache_status,  # "ok"|"stale_cache"|"rate_limited"|"failed"（指示書STEP9）
        })
        per_symbol_ms.append((code, (time.time() - _t_symbol) * 1000))

    section_ms["candidateLoopTotal"] = round((time.time() - _t_loop) * 1000)

    # 指示書6番「値上がり率だけでは選ばない」：ソート基準はentry_score（既に過熱ペナルティ・
    # VWAP/構造/RS等を織り込み済み）であり、changePct単純降順ではない。
    _t = time.time()
    candidates.sort(key=lambda c: -c["entryScore"])
    section_ms["sortRank"] = round((time.time() - _t) * 1000)

    _t = time.time()
    entry_ready_top5, watch_candidates, debug = _select_entry_ready_top5(candidates)
    section_ms["top5Selection"] = round((time.time() - _t) * 1000)
    overall_quality = "FULL" if quality_counts["DEGRADED"] == 0 and quality_counts["PARTIAL"] == 0 else (
        "DEGRADED" if quality_counts["FULL"] == 0 else "PARTIAL")

    # Market Intelligence Phase11新規（指示書1・3・4・29・30番）：ENTRY TOP5・WAIT候補は
    # 買わなかったものも含め原則すべてsnapshot保存する（survivorship bias防止）。entry_score・
    # entryState自体は一切変更しない、隣で記録するだけ。dedupe_keyが1日・銘柄・状態単位で
    # 重複保存を防ぐ。
    _t = time.time()
    snapshot_persistence_calls = 0
    try:
        for i, c in enumerate(entry_ready_top5):
            capture_entry_candidate_snapshot_safe(
                database_url, user_id, c["code"], "ENTRY", price=c.get("current"), entry_score=c.get("entryScore"),
                event_support=c.get("eventSupport"), candidate_state=c.get("eventSupport") or c.get("entryState"),
                candidate_rank=i + 1)
            snapshot_persistence_calls += 1
        for c in watch_candidates:
            capture_entry_candidate_snapshot_safe(
                database_url, user_id, c["code"], "WAIT", price=c.get("current"), entry_score=c.get("entryScore"),
                event_support=c.get("eventSupport"), candidate_state=c.get("eventSupport") or c.get("entryState"),
                wait_reason=c.get("entryState"))
            snapshot_persistence_calls += 1
    except Exception as e:
        print("  entry-candidates: candidate snapshot保存で例外（無視して続行）", e)
    section_ms["snapshotPersistence"] = round((time.time() - _t) * 1000)

    # Phase5 STEP3：per-symbol timingのpercentile集計（通常ログには281行出さない、
    # debugへ集計値とslowest上位10件だけ格納する）。
    _t = time.time()
    per_symbol_summary = _summarize_per_symbol_ms(per_symbol_ms)
    func_call_counts = {name: {"calls": v["calls"], "totalMs": round(v["total_ms"]),
                                 "avgMs": round(v["total_ms"] / v["calls"], 2) if v["calls"] else 0,
                                 "maxMs": round(v["max_ms"], 2)}
                          for name, v in func_stats.items()}
    section_ms["payloadConstruction"] = round((time.time() - _t) * 1000)
    section_ms["total"] = round((time.time() - _t_start) * 1000)
    section_ms["other"] = max(0, section_ms["total"] - sum(
        v for k, v in section_ms.items() if k not in ("total", "other")))

    # 場中リアルタイム化指示書 STEP2・20：ENTRY_TOP5_DIAGNOSTICS用の追加専用フィールド
    # （watchlist_count/intraday_ready相当）。既存のscanned等の集計ロジックには一切影響しない。
    debug["watchlistCount"] = len(watchlist)
    debug["readyCount"] = snapshot_ready_count
    debug["qualityCounts"] = quality_counts
    debug["dailyArraysScanLocalHit"] = daily_arrays_scan_local_hit  # scan-local daily arrays reuse：TTLを経由せずprefetch結果をそのまま使った件数
    debug["dailyArraysFallbackCount"] = daily_arrays_fallback_count  # 同上：scan-local mapに無くグローバルキャッシュへフォールバックした件数
    debug["quoteScanLocalHit"] = quote_scan_local_hit  # scan-local quote reuse：同上（quote）
    debug["quoteFallbackCount"] = quote_fallback_count
    debug["intradayScanLocalHit"] = intraday_scan_local_hit  # scan-local 5分足reuse：同上（intraday regime）
    debug["intradayFallbackCount"] = intraday_fallback_count
    debug["marketDataDiagnostics"] = market_data_diagnostics  # Phase I：デバッグ/ログ専用の追加フィールド（UI必須ではない）
    debug["entrySupportContextDiagnostics"] = entry_support_diagnostics  # Phase 2 G：DB N+1解消の診断情報（デバッグ/ログ専用）
    debug["dailyArraysDiagnostics"] = daily_arrays_diagnostics  # Phase 3 STEP10：日足prefetchの診断情報（デバッグ/ログ専用）
    debug["sectionTimingsMs"] = section_ms  # Phase5 STEP2：デバッグ/ログ専用の追加フィールド
    debug["perSymbolTiming"] = per_symbol_summary  # Phase5 STEP3
    debug["funcCallCounts"] = func_call_counts  # Phase5 STEP4
    debug["snapshotPersistenceCalls"] = snapshot_persistence_calls  # Phase5 STEP8
    print(f"  [EntryCandidatesTiming] total={section_ms['total']}ms "
          f"watchlistLoad={section_ms['watchlistLoad']} stage1={section_ms['stage1']} "
          f"marketDataPrefetch={section_ms['marketDataPrefetch']} dbSupportPrefetch={section_ms['dbSupportPrefetch']} "
          f"dailyArraysPrefetch={section_ms['dailyArraysPrefetch']} candidateLoopTotal={section_ms['candidateLoopTotal']} "
          f"snapshotPersistence={section_ms['snapshotPersistence']} other={section_ms['other']}")
    return {
        "entryReadyTop5": [{**c, "rank": i + 1} for i, c in enumerate(entry_ready_top5)],
        "watchCandidates": watch_candidates,
        "dataQuality": overall_quality,
        "generatedAt": datetime.datetime.now(datetime.timezone.utc).isoformat(),
        "debug": debug,
    }


def compute_entry_ready_candidates(database_url, user_id):
    """Current TOP5（/api/entry-candidates、いつでも再計算できる表示用）。_score_entry_
    candidates()をそのまま返すだけで、stock_thesesへの永続化は行わない（永続化は朝TOP5＝
    generate_morning_entry_top5+persist_morning_thesesの専任、指示書22・23番）。"""
    return _score_entry_candidates(database_url, user_id)


# ============================================================
# 今買い時TOP5 場中リアルタイム化指示書（2026-09-15新規）。
#
# 背景：2026-09-15、/api/entry-candidates（_score_entry_candidates）は監視銘柄281件を
# 毎回フルスキャンする重い同期処理で、本日Phase1〜5（DB N+1解消・Tachibana個別API呼び出し
# 削減・restart warmupガード追加）で初めて実用的な速度になった。それ以前はボタン押下1回が
# 数十分かかることがあり、これが15:36頃までまともなENTRY候補が出なかった主因だった
# （調査結果）。_score_entry_candidates自体のロジック・Phase1〜5の高速化は一切変更しない。
#
# ここで追加するのは「_score_entry_candidates を5分足更新に合わせて自動的に呼び、結果を
# メモリキャッシュへ保存し、frontendはそのキャッシュを軽量APIで読むだけにする」仕組み。
# 新しい全市場スキャン・新しい判定ロジックは追加しない（指示書の最重要注意点：重いフルスキャンを
# そのまま5分ごとにscheduler化するとPhase1〜5で潰したDB N+1・Tachibana個別取得・warmup競合が
# 別経路で再発するため、既存のprefetch/batch化された_score_entry_candidates経路を"1本だけ"
# 定期的に叩く設計にし、二重化はしない）。
# ============================================================

ENTRY_TOP5_SCAN_INTERVAL_MIN = 5  # 5分足更新に合わせた場中再評価間隔
ENTRY_TOP5_MORNING_WINDOW = ("09:05", "11:30")  # 寄り後、最初の5分足確定後から前場終了まで
ENTRY_TOP5_AFTERNOON_WINDOW = ("12:30", "15:30")  # 後場再開〜大引け（昼休みは不要な再計算をしない）
ENTRY_TOP5_UPDATE_DELAY_WARNING_SEC = 600  # 2周期（10分）以上更新が無ければ「⚠更新遅延」表示
ENTRY_TOP5_STALE_DATA_SEC = 900  # 3周期（15分）以上更新が無ければENTRY READY等を安全側（WAIT_DATA_STALE）へ降格


def _entry_top5_scan_time_marks(window):
    """windowの開始〜終了（"HH:MM"）を5分刻みで列挙する（scheduler発火時刻の集合を作るためだけの
    純粋関数）。"""
    start_h, start_m = (int(x) for x in window[0].split(":"))
    end_h, end_m = (int(x) for x in window[1].split(":"))
    cur = start_h * 60 + start_m
    end = end_h * 60 + end_m
    marks = []
    while cur <= end:
        marks.append(f"{cur // 60:02d}:{cur % 60:02d}")
        cur += ENTRY_TOP5_SCAN_INTERVAL_MIN
    return marks


ENTRY_TOP5_SCAN_TIMES = set(
    _entry_top5_scan_time_marks(ENTRY_TOP5_MORNING_WINDOW) + _entry_top5_scan_time_marks(ENTRY_TOP5_AFTERNOON_WINDOW))

_ENTRY_TOP5_CACHE = {}  # user_id -> 最新スキャン結果（軽量API・手動更新の両方がここを読み書きする）
_ENTRY_TOP5_CACHE_LOCK = threading.Lock()
_ENTRY_TOP5_SCAN_LOCK = threading.Lock()  # scheduler・手動更新の二重スキャン防止（1プロセス内で常に1本だけ実行）


def get_entry_top5_cached(user_id):
    """軽量API（frontend polling用）が読むだけの関数。ここでは一切の再計算をしない。"""
    with _ENTRY_TOP5_CACHE_LOCK:
        entry = _ENTRY_TOP5_CACHE.get(user_id)
    return dict(entry) if entry is not None else None


def _apply_entry_top5_staleness(cache_entry):
    """指示書「stale data対策」（2026-09-15追記：レビュー指摘反映）：ranking_generated_at
    （=market_data_at、_score_entry_candidatesは毎回フレッシュにmarket dataを取り直すため
    両者は同一時刻になる）だけを見て安全側に倒すのでは不十分——prefetch/個別取得の両方に
    stale_cache fallback（取得失敗時に期限切れキャッシュを返す既存の安全動作、
    _intraday_regime_cached等）があるため、"ranking自体は今回生成されたばかりだが、
    その銘柄個別のquote/5分足は実際には古い値のまま"というケースが起こり得る。そのため
    二段構えで判定する：
      ①ranking全体の経過時間（age_sec）：schedulerが止まった等、ranking自体が更新されて
        いない場合の安全弁。ENTRY_TOP5_STALE_DATA_SEC超でTOP5全体を降格。
      ②銘柄ごとのmarketDataCacheStatus（"ok"以外＝stale_cache/rate_limited/failedの
        フォールバック値で判定された銘柄）：ranking自体は新しくても、その銘柄個別のNOW_BUYABLE/
        ENTRY_READY判定の根拠になった市場データが古い場合は個別に降格する。
    どちらの条件でもNOW_BUYABLE/ENTRY_READYはWAIT_DATA_STALEへ降格する（キャッシュ本体は
    書き換えない、レスポンス生成時だけの変換）。"""
    now = time.time()
    age_sec = max(0.0, now - cache_entry["generatedAtEpoch"])
    stale = age_sec > ENTRY_TOP5_STALE_DATA_SEC
    delayed = age_sec > ENTRY_TOP5_UPDATE_DELAY_WARNING_SEC
    top5 = cache_entry["entryReadyTop5"]
    downgraded = []
    any_symbol_stale = False
    for c in top5:
        symbol_stale = c.get("marketDataCacheStatus") not in ("ok", None)
        if symbol_stale:
            any_symbol_stale = True
        if c.get("entryState") in ("NOW_BUYABLE", "ENTRY_READY") and (stale or symbol_stale):
            reason = "ranking_age" if stale else "symbol_market_data"
            c = {**c, "entryState": "WAIT_DATA_STALE", "staleDowngraded": True, "staleReason": reason}
        downgraded.append(c)
    top5 = downgraded
    return {
        "entryReadyTop5": top5,
        "watchCandidates": cache_entry["watchCandidates"],
        "dataQuality": cache_entry["dataQuality"],
        "generatedAt": cache_entry["generatedAt"],
        "marketDataAt": cache_entry["marketDataAt"],
        "watchlistCount": cache_entry["watchlistCount"],
        "readyCount": cache_entry["readyCount"],
        "scoredCount": cache_entry["scoredCount"],
        "entryReadyCount": cache_entry["entryReadyCount"],
        "waitCount": cache_entry["waitCount"],
        "riskCount": cache_entry["riskCount"],
        "debug": cache_entry.get("debug", {}),
        "durationMs": cache_entry["durationMs"],
        "trigger": cache_entry["trigger"],
        "rankingAgeSec": round(age_sec),
        "dataStale": stale,
        "anySymbolMarketDataStale": any_symbol_stale,  # 指示書STEP9：ranking全体は新しくても個別銘柄のmarket dataがstale fallbackだった場合にTrue
        "updateDelayWarning": delayed,
    }


def _run_entry_top5_scan(database_url, user_id, trigger="AUTO", wait_for_lock=False, lock_timeout=120):
    """_score_entry_candidates()を1回実行してキャッシュへ保存する。指示書「scheduler二重起動
    防止」「手動更新と自動更新が競合して二重スキャンしない」：_ENTRY_TOP5_SCAN_LOCKで
    プロセス内の同時実行を1本に制限する。
    trigger="SCHEDULER"（自動、5分ごと）：ロック取得できなければ即座に諦めて既存キャッシュを返す
    （次の5分周期でまた試みるため、待ち合わせて処理を積み重ねない＝指示書「同一5分足に対する
    重複計算」防止）。
    trigger="MANUAL"（手動「今買い時TOP5を更新」ボタン）：ロックが空くまで待ってから必ず
    フルスキャンを実行する（ユーザーが明示的に最新化を求めているため）。lock_timeout秒待っても
    空かない場合はタイムアウトして既存キャッシュを返す（フリーズ防止）。"""
    acquired = _ENTRY_TOP5_SCAN_LOCK.acquire(blocking=wait_for_lock, timeout=lock_timeout if wait_for_lock else -1)
    if not acquired:
        print(f"  [EntryTop5Scan] trigger={trigger} user={user_id}: 既存スキャン実行中のためスキップ（既存キャッシュを使用）")
        return get_entry_top5_cached(user_id)
    try:
        t0 = time.time()
        result = _score_entry_candidates(database_url, user_id)
        t1 = time.time()
        debug = result.get("debug", {})
        cache_entry = {
            "entryReadyTop5": result["entryReadyTop5"],
            "watchCandidates": result["watchCandidates"],
            "dataQuality": result["dataQuality"],
            "generatedAt": result["generatedAt"],
            "generatedAtEpoch": t1,
            "marketDataAt": result["generatedAt"],
            "watchlistCount": debug.get("watchlistCount", 0),
            "readyCount": debug.get("readyCount", 0),
            "scoredCount": debug.get("scanned", 0),
            "entryReadyCount": debug.get("entry_ready", 0),
            "waitCount": debug.get("active_break", 0) + debug.get("watch_near_ready", 0),
            "riskCount": debug.get("risk_excluded", 0),
            "debug": debug,  # 既存の🔧デバッグ表示（scanned/entry_ready/…）を維持するため丸ごと保持
            "durationMs": round((t1 - t0) * 1000),
            "trigger": trigger,
            "scanStartedAt": datetime.datetime.fromtimestamp(t0, datetime.timezone.utc).isoformat(),
            "scanFinishedAt": datetime.datetime.fromtimestamp(t1, datetime.timezone.utc).isoformat(),
        }
        with _ENTRY_TOP5_CACHE_LOCK:
            _ENTRY_TOP5_CACHE[user_id] = cache_entry
        print(f"  [EntryTop5Scan] trigger={trigger} user={user_id} duration={cache_entry['durationMs']}ms "
              f"watchlist={cache_entry['watchlistCount']} ready={cache_entry['readyCount']} "
              f"scored={cache_entry['scoredCount']} entryReady={cache_entry['entryReadyCount']} "
              f"wait={cache_entry['waitCount']} risk={cache_entry['riskCount']}")
        return cache_entry
    except Exception as e:
        print(f"  [EntryTop5Scan] trigger={trigger} user={user_id}: スキャン失敗", e)
        return get_entry_top5_cached(user_id)
    finally:
        _ENTRY_TOP5_SCAN_LOCK.release()


def _entry_top5_scheduler_loop():
    """場中5分足更新に合わせてENTRY TOP5を自動再評価するデーモンスレッド。他のscheduler
    （_morning_check_scheduler_loop等）と同じ「60秒間隔でJST時刻をポーリングし、対象HH:MMの
    分に一度だけ発火（プロセス内fired setで二重発火防止）」パターンを踏襲する——新しい
    poll方式は増やさない。営業日のみ、ENTRY_TOP5_SCAN_TIMES（09:05〜11:30・12:30〜15:30の
    5分刻み、昼休みは対象外）の時刻だけ発火する。"""
    fired = set()  # {(trade_date, hhmm, user_id)}
    JST = datetime.timezone(datetime.timedelta(hours=9))
    while True:
        try:
            now_jst = datetime.datetime.now(JST)
            hhmm = now_jst.strftime("%H:%M")
            if _is_jp_market_business_day(now_jst) and hhmm in ENTRY_TOP5_SCAN_TIMES:
                trade_date = now_jst.date().isoformat()
                for user_id in _morning_check_scheduler_users():
                    key = (trade_date, hhmm, user_id)
                    if key in fired:
                        continue
                    fired.add(key)
                    try:
                        _run_entry_top5_scan(DATABASE_URL, user_id, trigger="SCHEDULER", wait_for_lock=False)
                    except Exception as e:
                        print(f"  [EntryTop5Scheduler] {user_id} {hhmm} 実行失敗", e)
                if len(fired) > 400:
                    fired = {k for k in fired if k[0] == now_jst.date().isoformat()}
        except Exception as e:
            print("  [EntryTop5Scheduler] スケジューラループで例外", e)
        time.sleep(60)


# ============================================================
# トレード分析 リアルタイム自動更新（2026-09-12新規）。
# 「今すぐ更新」ボタンを押さなくても現在値・ENTRY条件・WAIT/ENTRY READY/RISK等が自動追従する
# ためのFAST UPDATE（軽量・5〜15秒間隔）専用エンドポイント。analyze_stock()（ニュース・
# Expert View・ルール評価等を含む重い分析＝HEAVY ANALYSIS）は呼ばない。既存の共有Stage1
# キャッシュ・_intraday_stock_snapshot・_volume_stage2_detail（_cached_daily_arrays経由で
# TTLキャッシュ済み）・_entry_score_components/_classify_entry_state・Trade Experience
# Learningのbuild_trade_experience_summary_for_symbolをそのまま再利用し、新規の重い計算・
# 新規の外部API呼び出し経路は追加しない（指示書9番「API負荷対策」）。
# ============================================================

def _light_entry_conditions(comp):
    """entry_score内訳（_entry_score_components()の戻り値）のうち、方向性を持つ5項目
    （momentum/vwap/5分足構造/対市場RS/出来高）が何個「成立」しているかを簡易カウントする。
    重いanalyze_stock()のentry_checklist（8項目・ファンダ含む）とは別物の軽量版——FAST UPDATE
    専用であり、既存のentryConditionsMet/Totalを置き換えるものではない。"""
    checks = [comp.get("momentum", 0) > 0, comp.get("vwap", 0) > 0, comp.get("fiveMinStructure", 0) > 0,
              comp.get("marketRelative", 0) > 0, comp.get("volume", 0) > 0]
    return {"passed": sum(1 for c in checks if c), "total": len(checks)}


def _light_snapshot_fields(code, row, comp, entry_state, snapshot, rsi_val, short_ma_val, experience_score):
    """FAST UPDATE応答の形を組み立てる純粋関数（DB/ネットワークアクセスなし、単体テスト用に
    分離）。既存entry_score・entry_state自体は一切変更せず、そのまま乗せるだけ。"""
    entry_conditions = _light_entry_conditions(comp)
    risk = entry_state in ENTRY_TOP5_RISK_STATES
    return {
        "symbol": code,
        "price": row.get("current"),
        "pct": round(row["changePct"], 2) if row.get("changePct") is not None else None,
        "vwap": (snapshot or {}).get("vwap"),
        "rsi": round(rsi_val, 1) if rsi_val is not None else None,
        "short_ma": round(short_ma_val, 2) if short_ma_val is not None else None,
        "entry_state": entry_state,
        "entry_conditions": entry_conditions,
        "signal": entry_state,  # 簡易signal＝entry_stateそのまま（表示ラベルはフロント側ENTRY_STATE_METAで変換）
        "risk": risk,
        "experience_score": experience_score,
    }


def compute_light_trade_analysis_snapshot(database_url, user_id, code, market="JP"):
    """FAST UPDATE用の軽量スナップショットを取得するI/Oラッパー。_score_entry_candidates()と
    同じ共有Stage1（run_momentum_stage1、複数エンジンとプロセス内キャッシュ共有）を使うため、
    このAPIが10秒間隔で叩かれても市場全体の再取得は増えない。対象コードがStage1（監視銘柄が
    属する市場全体の当日値、既存のrun_momentum_stage1）に存在しない、または当日値が
    まだ無い場合はNoneを返す（呼び出し側は404を返す）。"""
    stage1 = run_momentum_stage1()
    stage1_rows = stage1.get("rows", {})
    nikkei_chg = stage1.get("nikkeiChangePct")
    row = stage1_rows.get(code)
    if not row or row.get("current") is None:
        return None
    w = {"code": code, "market": market, "sector": row.get("sector")}
    auto_rs_current = investment_db.get_codes_with_auto_tag(database_url, user_id, "AUTO_RS_CURRENT", market="JP") \
        if (investment_db and database_url) else set()
    auto_sector_current = investment_db.get_codes_with_auto_tag(database_url, user_id, "AUTO_SECTOR_LEADER_CURRENT", market="JP") \
        if (investment_db and database_url) else set()
    stage2 = None
    try:
        stage2 = _volume_stage2_detail(code, row)
    except Exception as e:
        print("  trade-analysis/live: Stage2取得失敗", code, e)
    snapshot = None
    try:
        snap = _intraday_stock_snapshot(w)
        if snap.get("dataStatus") != "failed":
            snapshot = snap
    except Exception as e:
        print("  trade-analysis/live: 5分足スナップショット失敗", code, e)
    data_quality = "FULL" if (stage2 is not None and snapshot is not None) else (
        "PARTIAL" if (stage2 is not None or snapshot is not None) else "DEGRADED")

    catalysts = investment_db.relevant_catalysts_for(database_url, user_id, code=code, sector=row.get("sector"), limit=3) \
        if (investment_db and database_url) else []
    events = investment_db.upcoming_event_signals(database_url, user_id, code=code, sector=row.get("sector")) \
        if (investment_db and database_url) else {"signals": []}
    event_signals = events.get("signals", [])

    experience_score, entry_risk = None, None
    try:
        exp_summary = build_trade_experience_summary_for_symbol(database_url, user_id, code)
        experience_score = exp_summary["experience_score"]
        entry_risk = exp_summary.get("entryRisk")
    except Exception as e:
        print("  trade-analysis/live: experience score取得で例外（無視して続行）", code, e)

    comp = _entry_score_components(row, stage2, snapshot or {}, auto_rs_current, auto_sector_current, catalysts,
                                    event_signals, entry_risk=entry_risk)
    neg_cat_present = bool(comp["negativeCatalysts"])
    entry_score = comp["total"]
    entry_state, _exception_applied = _classify_entry_state(
        entry_score, row, stage2, snapshot, data_quality, event_signals, neg_cat_present, nikkei_chg,
        entry_risk=entry_risk)

    rsi_val, short_ma_val = None, None
    daily = _cached_daily_arrays(code, CACHE_TTL["daily_arrays"])
    if daily:
        closes = daily[0]
        try:
            if len(closes) >= 15:
                rsi_val = _rsi(closes)
            if len(closes) >= 5:
                short_ma_val = _sma(closes, 5)
        except Exception as e:
            print("  trade-analysis/live: RSI/短期MA計算失敗", code, e)

    fields = _light_snapshot_fields(code, row, comp, entry_state, snapshot, rsi_val, short_ma_val, experience_score)

    # Choruco Style / ちょる子式（2026-09-12新規、指示書59番）：FAST UPDATE連携。
    # market_mode/event_riskはキャッシュ済み（CHORUCO_MARKET_MODE_CACHE_TTL）の値を再利用する
    # だけで重い計算は追加しない。story_statusは既存storyがある場合のみdetect_story_break()
    # （軽量・純粋関数）で毎回再評価する。
    try:
        market_mode_result = compute_choruco_market_mode_cached(database_url, user_id) \
            if (investment_db and database_url) else None
        market_mode = (market_mode_result or {}).get("mode")
        event_risk_level = (market_mode_result or {}).get("event_risk_level", "LOW")
        story = investment_db.get_latest_choruco_story(database_url, user_id, code) \
            if (investment_db and database_url) else None

        # Cross-Market Link Phase 2新規（指示書10番）：FAST UPDATE連携。5分足系列はキャッシュ
        # （_cached_5m_bars、CACHE_TTL["stock5m"]）済みのため、10秒間隔で呼ばれても相関の
        # 再計算自体はTTLごとに1回で済む。半導体・AI関連銘柄以外はis_cross_market_eligible_
        # sector()がFalseを返しゲートされる（重い計算は禁止、指示書18番）。
        cross_market = None
        try:
            cross_market = build_cross_market_link(code, sector=row.get("sector"))
        except Exception as e:
            print("  trade-analysis/live: cross-market取得で例外（無視して続行）", code, e)

        # Sector Rotation Engine新規（指示書32番）：FAST UPDATE連携。
        # build_sector_rotation_snapshot_cached()（TTL30秒）を再利用するだけで重い再集計は
        # しない。半導体・AI関連以外の対象外テーマの銘柄はsector_infoがNoneのまま。
        sector_info = None
        try:
            themes = get_stock_themes(code)
            if themes:
                rotation_snapshot = build_sector_rotation_snapshot_cached(database_url, user_id)
                sector_info = {"sector": themes[0], **(rotation_snapshot.get("sectors", {}).get(themes[0]) or {})}
        except Exception as e:
            print("  trade-analysis/live: sector rotation取得で例外（無視して続行）", code, e)

        story_status = None
        if story and story.get("status") != "BROKEN":
            fast_snapshot = {"price": fields.get("price"), "vwap": fields.get("vwap"),
                               "short_ma": fields.get("short_ma"), "entry_state": entry_state,
                               "market_mode": market_mode}
            if cross_market and cross_market.get("primary_driver"):
                fast_snapshot["cross_market"] = {
                    "primary_driver": cross_market.get("primary_driver"),
                    "driver_recent_change_pct": next(
                        (d.get("recent_change_pct") for d in (cross_market.get("drivers") or [])
                         if d.get("label") == cross_market.get("primary_driver")), None),
                    "direction": cross_market.get("direction"),
                }
            if sector_info:
                fast_snapshot["sector_rotation"] = {"state": sector_info.get("state")}
            break_reasons = detect_story_break(story.get("story_json") or {}, fast_snapshot)
            story_status = classify_story_status(story.get("story_score"), break_reasons)
        elif story:
            story_status = "BROKEN"
        sector_flow_label = "NEUTRAL"
        fields["market_mode"] = market_mode
        fields["event_risk_level"] = event_risk_level
        fields["story_status"] = story_status
        fields["choruco_fit"] = compute_choruco_fit(market_mode, sector_flow_label, event_risk_level,
                                                        (story or {}).get("story_score"))
        if cross_market and cross_market.get("primary_driver"):
            fields["cross_market_primary_driver"] = cross_market.get("primary_driver")
            fields["cross_market_correlation"] = cross_market.get("correlation")
            fields["cross_market_divergence"] = cross_market.get("divergence")
            fields["cross_market_leading_alert"] = cross_market.get("leading_alert")
            fields["cross_market_score"] = cross_market.get("cross_market_score")
        if sector_info:
            fields["sector_rotation_sector"] = sector_info.get("sector")
            fields["sector_rotation_state"] = sector_info.get("state")
            fields["sector_rotation_score"] = sector_info.get("score")
    except Exception as e:
        print("  trade-analysis/live: choruco連携で例外（無視して続行）", code, e)
        fields["market_mode"] = None
        fields["event_risk_level"] = None
        fields["story_status"] = None
        fields["choruco_fit"] = None

    fields["updated_at"] = datetime.datetime.now(datetime.timezone.utc).isoformat()
    return fields


def generate_morning_entry_top5(database_url, user_id):
    """朝TOP5（entry_ready_top5、08:50MorningMarketCheck生成時点のスナップショット）を算出
    する。Current TOP5と全く同じ_score_entry_candidates()を使う（指示書「同じ選考基準」）。
    永続化はしない（呼び出し側でsave_morning_check後にpersist_morning_thesesを呼ぶ）。"""
    return _score_entry_candidates(database_url, user_id)


def persist_morning_theses(database_url, user_id, trade_date, morning_check_id, entry_ready_top5):
    """朝TOP5（generate_morning_entry_top5の結果のentryReadyTop5）をstock_thesesへ永続化する
    （source='MORNING'固定、指示書11・12番）。同じ(user_id, code, market, entry_date)が既に
    あれば何もしない＝1日1仮説・後から書き換えない。"""
    if investment_db is None or not database_url or not entry_ready_top5:
        return
    for c in entry_ready_top5:
        bd = c.get("scoreBreakdown", {})
        try:
            investment_db.ensure_stock_thesis(
                database_url, user_id, c["code"], "JP", trade_date, c["name"],
                c["entryScore"], c["entryState"], c["reasons"], c["analysisConfidence"],
                source="MORNING", morning_check_id=morning_check_id, morning_rank=c.get("rank"),
                vwap_state=("ABOVE" if bd.get("vwap", 0) > 0 else "BELOW_OR_UNKNOWN"),
                auto_rs=bd.get("autoRs", 0) > 0, auto_sector=bd.get("autoSector", 0) > 0,
                resilience=c.get("resilience"),
                trigger_text="寄り後VWAP維持＋5分足安値切り上げを確認してからのエントリーを推奨",
                avoid_condition="寄り天・出来高を伴わない上昇・悪材料の追加",
                morning_price=c.get("current"))
        except Exception as e:
            print("  朝TOP5 thesis永続化失敗", c.get("code"), e)


def _reevaluate_active_stock_theses(database_url, user_id, trade_date, report_type, nikkei_chg):
    """entry_ready_top5から作られたstock_thesesを答え合わせする。朝TOP5の答え合わせと全く
    同じevaluate_morning_thesis/_thesis_transition_status/_final_top5_resultを再利用する
    （別ロジックは作らない）。report_type=MARKET_CLOSEの回だけ、当日の履歴から最終結果
    （SUCCESS/PARTIAL_SUCCESS/FAIL/NO_ENTRY/DATA_INSUFFICIENT）を確定する。"""
    if investment_db is None or not database_url:
        return
    active = investment_db.list_active_stock_theses(database_url, user_id, trade_date)
    for thesis in active:
        code, market = thesis.get("code"), thesis.get("market", "JP")
        w = {"code": code, "market": market, "name": thesis.get("name")}
        try:
            snap = _intraday_stock_snapshot(w)
        except Exception as e:
            print("  Thesis答え合わせ: スナップショット失敗", code, e)
            continue
        result = evaluate_morning_thesis({"code": code}, snap, nikkei_chg)
        prev_result = thesis.get("latest_thesis_result")
        transition = _thesis_transition_status(prev_result, result) if prev_result else None
        try:
            investment_db.update_stock_thesis_evaluation(
                database_url, user_id, code, market, trade_date, result, transition,
                thesis.get("latest_entry_score"), report_type)
        except Exception as e:
            print("  Thesis答え合わせ: 更新失敗", code, e)

    if report_type == "MARKET_CLOSE":
        for thesis in investment_db.list_active_stock_theses(database_url, user_id, trade_date):
            history = [h.get("thesis_result") for h in (thesis.get("status_history_json") or []) if h.get("thesis_result")]
            if not history:
                continue
            final = _final_top5_result(history)
            try:
                investment_db.finalize_stock_thesis(
                    database_url, user_id, thesis["code"], thesis.get("market", "JP"), trade_date, final)
            except Exception as e:
                print("  Thesis最終確定失敗", thesis.get("code"), e)


