# ---- source_type別の一次情報リンク判定・投稿分類（指示書11・12番） ----

PRIMARY_SOURCE_DOMAIN_HINTS = (
    ("release.tdnet.info", "TDNET"), ("tdnet", "TDNET"),
    ("kantei.go.jp", "GOV"), ("fsa.go.jp", "GOV"), (".go.jp", "GOV"),
    ("bloomberg", "NEWS"), ("reuters", "NEWS"), ("nikkei.com", "NEWS"), ("nikkei.co.jp", "NEWS"),
)


def classify_primary_source_type(url):
    """指示書11番：一次情報リンク先をTDNET|GOV|NEWS|IRのいずれかに分類する（判定不能ならNone、
    無理に断定しない）。"""
    if not url:
        return None
    host = (urllib.parse.urlparse(url).netloc or "").lower()
    for hint, kind in PRIMARY_SOURCE_DOMAIN_HINTS:
        if hint in host:
            return kind
    if host.endswith(".co.jp") or "ir" in host:
        return "IR"
    return None


# 指示書12番：投稿を「独自見解」「事実の紹介」「速報の紹介」「単純な感想」に分類する。
POST_RELAY_BREAKING_KEYWORDS = ["速報", "上方修正", "下方修正", "TOB", "M&A", "自社株買い", "増資", "業績修正", "不祥事"]


def classify_post_relay_type(text, has_link):
    """指示書12番：ORIGINAL_ANALYSIS/FACT_RELAY/BREAKING_RELAY/OPINIONを判定する。企業開示を
    早く紹介しただけの投稿（リンクのみ＋速報系キーワード）は投稿者の「予測的中率」評価対象に
    せず、discovery_speed等の別軸で評価する設計にする土台（指示書12番）。"""
    if not text:
        return "OPINION"
    if has_link and any(kw in text for kw in POST_RELAY_BREAKING_KEYWORDS):
        return "BREAKING_RELAY"
    if has_link:
        return "FACT_RELAY"
    if any(kw in text for kw in SOCIAL_EVAL_BULLISH_KEYWORDS + SOCIAL_EVAL_BEARISH_KEYWORDS
           + SIGNAL_KIND_TECHNICAL_KEYWORDS):
        return "ORIGINAL_ANALYSIS"
    return "OPINION"


# ---- @polymarketjapan専用解析（指示書5・6番） ----

POLYMARKET_PROBABILITY_SHIFT_RE = re.compile(r"(\d{1,3}(?:\.\d+)?)\s*%\s*(?:→|->|から)\s*(\d{1,3}(?:\.\d+)?)\s*%")
POLYMARKET_SINGLE_PROBABILITY_RE = re.compile(r"(\d{1,3}(?:\.\d+)?)\s*%")
POLYMARKET_CATEGORY_KEYWORDS = {
    "POLITICS": ["大統領選", "選挙", "政権", "議会"],
    "MACRO": ["FRB", "FOMC", "利下げ", "利上げ", "日銀", "CPI", "GDP", "政府閉鎖"],
    "CRYPTO": ["ビットコイン", "BTC", "仮想通貨", "クリプト"],
    "TECH": ["AI", "テック"],
}


def extract_prediction_market_data(text):
    """指示書5・6番：prediction probability・probability_change等を抽出する。単純な
    「70%」だけの投稿ではprevious_probabilityは取れないためNoneのまま（無理に推測しない）。
    resolution_date抽出は本文の書式が定まらないため今回は未実装（既知の制約）。"""
    if not text:
        return None
    prev_p = cur_p = None
    m = POLYMARKET_PROBABILITY_SHIFT_RE.search(text)
    if m:
        prev_p, cur_p = float(m.group(1)), float(m.group(2))
    else:
        m2 = POLYMARKET_SINGLE_PROBABILITY_RE.search(text)
        if m2:
            cur_p = float(m2.group(1))
    probability_change = round(cur_p - prev_p, 1) if (prev_p is not None and cur_p is not None) else None
    category = next((cat for cat, kws in POLYMARKET_CATEGORY_KEYWORDS.items() if any(kw in text for kw in kws)), "OTHER")
    urls = re.findall(r"https?://\S+", text)
    return {
        "prediction_topic": text[:40], "event_name": text[:60],
        "probability": cur_p, "previous_probability": prev_p, "probability_change": probability_change,
        "resolution_date": None, "market_url": urls[0] if urls else None, "category": category,
    }


def classify_prediction_market_shift(probability_change, threshold=10):
    """指示書6番：52%→70%のような急変（閾値10ptを既定）をPREDICTION_MARKET_SHIFTとして
    重要視する。"""
    if probability_change is None:
        return False
    return abs(probability_change) >= threshold


# ---- @kgbukabu専用解析（指示書8・9番） ----

STOCK_TICKER_RE = re.compile(r"(?<!\d)(\d{4})(?!\d)")
STOCK_CHANGE_PCT_RE = re.compile(r"[+＋▲△]\s*(\d+(?:\.\d+)?)\s*%|[-−▼▽]\s*(\d+(?:\.\d+)?)\s*%")
STOCK_CATALYST_KEYWORDS = ["上方修正", "下方修正", "新製品", "提携", "業務提携", "受注", "テーマ"]
STOCK_DISCLOSURE_KEYWORDS = ["開示", "適時開示", "TDnet", "TDNET"]
STOCK_LIMIT_KEYWORDS = {"ストップ高": "LIMIT_UP", "ストップ安": "LIMIT_DOWN"}
# 指示書9番：kgbukabu専用のsignal_kind追加（既存enumはそのまま、追加のみ）。
KGBUKABU_MOMENTUM_KEYWORDS = ["出来高急増", "急伸", "急変", "急増"]
KGBUKABU_BREAKING_KEYWORDS = ["ストップ高", "ストップ安", "急騰", "急落"]


def extract_stock_breaking_data(text, watchlist=None):
    """指示書8番：ticker/company_name/change_pct/catalyst/disclosure/limit_statusを抽出する
    （画像内のチャート・出来高等は今回のテキスト解析範囲外、既知の制約）。"""
    if not text:
        return None
    watchlist = watchlist or []
    tickers = STOCK_TICKER_RE.findall(text)
    company_name, ticker = None, (tickers[0] if tickers else None)
    for w in watchlist:
        name = (w.get("name") or "").strip()
        if name and name in text:
            company_name = name
            if not ticker:
                ticker = w.get("code")
            break
    change_pct = None
    m = STOCK_CHANGE_PCT_RE.search(text)
    if m:
        val = m.group(1) or m.group(2)
        sign = 1 if m.group(1) else -1
        change_pct = sign * float(val)
    catalyst = next((kw for kw in STOCK_CATALYST_KEYWORDS if kw in text), None)
    disclosure = any(kw in text for kw in STOCK_DISCLOSURE_KEYWORDS)
    limit_status = next((v for kw, v in STOCK_LIMIT_KEYWORDS.items() if kw in text), None)
    return {"ticker": ticker, "company_name": company_name, "change_pct": change_pct,
            "catalyst": catalyst, "disclosure": disclosure, "limit_status": limit_status}


def classify_signal_kind_for_source(sentence, source_type=None):
    """指示書9番：STOCK_BREAKING（kgbukabu）ソースだけBREAKING_STOCK/MOMENTUM_ALERT/
    CATALYST_ALERTを優先判定する。それ以外のsource_typeでは既存classify_signal_kind
    （Phase5）と完全に同じ結果を返す（指示書「既存enumとの互換性を壊さない」）。"""
    if source_type == "STOCK_BREAKING" and sentence:
        if any(kw in sentence for kw in KGBUKABU_BREAKING_KEYWORDS):
            return "BREAKING_STOCK"
        if any(kw in sentence for kw in KGBUKABU_MOMENTUM_KEYWORDS):
            return "MOMENTUM_ALERT"
        if any(kw in sentence for kw in STOCK_CATALYST_KEYWORDS):
            return "CATALYST_ALERT"
    return classify_signal_kind(sentence)


# ---- @aryarya専用解析（指示書10・11番） ----

def extract_corporate_breaking_data(text, url=None):
    """指示書10・11番：投稿本文にリンクがある場合のlinked_domain/linked_url/headlineを保持
    する。一次情報かどうかの分類自体はclassify_primary_source_typeが担う（役割を分離）。"""
    if not text and not url:
        return None
    return {
        "linked_url": url, "linked_domain": (urllib.parse.urlparse(url).netloc if url else None),
        "headline": (text or "")[:60],
    }


# 指示書5番：投稿の自動分類（複数カテゴリ付与可）。AI不使用のキーワードベース分類
# （他のSmart Import/AUTO系エンジンと同じ方針）。
X_POST_CATEGORY_KEYWORDS = {
    "MARKET_HEATMAP":    ["ヒートマップ"],
    "INDEX_TECHNICAL":   ["日経平均", "日経先物", "TOPIX", "グロース250", "225先物"],
    "STOCK_TECHNICAL":   ["日足", "移動平均", "出来高", "ローソク足", "チャート"],
    "ECONOMIC_EVENT":    ["CPI", "PPI", "雇用統計", "小売売上高", "経済指標", "GDP"],
    "CENTRAL_BANK":      ["FOMC", "FRB", "日銀", "ECB", "利上げ", "利下げ", "金融政策"],
    "FX":                ["ドル円", "為替", "円安", "円高", "ユーロ円"],
    "US_MARKET":         ["NYダウ", "ダウ平均", "ナスダック", "S&P", "米株", "米国株"],
    "INTEREST_RATE":     ["金利", "国債利回り", "10年債"],
    "SEMICONDUCTOR":     ["半導体", "SOX", "NVIDIA", "エヌビディア"],
    "COMMODITY":         ["原油", "金相場", "商品市況", "WTI"],
    "SHIPPING":          ["海運", "バルチック", "運賃指数"],
    "SECTOR_ROTATION":   ["セクターローテーション", "資金循環", "物色"],
    "MARKET_SENTIMENT":  ["センチメント", "投資家心理", "リスクオン", "リスクオフ"],
    "MARKET_OVERVIEW":   ["相場全体", "本日の相場", "地合い", "全体観"],
}
X_POST_SQ_KEYWORDS = ["SQ", "メジャーSQ"]
X_POST_HIGH_KEYWORDS = (["CPI", "PPI", "雇用統計", "FOMC", "FRB", "日銀", "ECB", "為替急変",
                          "米金利急変", "SOX", "NVIDIA", "エヌビディア", "セクターローテーション"]
                         + X_POST_SQ_KEYWORDS)
X_POST_CRITICAL_KEYWORDS = ["急落", "急騰", "暴落", "暴騰", "サーキットブレーカー", "ストップ安", "ストップ高"]
# 見解（author_opinion）を示す表現。事実（facts）との混同を防ぐための最重要ロジック（指示書7番）。
X_POST_OPINION_MARKERS = ["だろう", "と思う", "と見ている", "べきではない", "べき", "山場",
                           "かもしれない", "警戒したい", "期待したい", "注意したい", "懸念",
                           "強気", "弱気", "個人的に", "想定", "様子見でいい", "お勧め", "推奨"]
X_POST_FACT_TIME_RE = re.compile(r"\d{1,2}[:：]\d{2}|\d{1,2}/\d{1,2}|\d{4}年\d{1,2}月\d{1,2}日")
# 指示書15番：直接銘柄名が無くてもテーマ経由で間接関連付けする対象キーワード。ここでは
# キーワード検出だけ行い、実際の銘柄マッピングは監視銘柄の既存theme欄（2026-09-08
# SECTOR_RELATIVE_STRENGTH機能で使われているもの）と突き合わせる——独自の銘柄マップを
# ハードコードで作らない（不正確な固定マップの方が実害が大きいため、既存の登録データだけを
# 根拠にする）。
X_POST_THEME_KEYWORDS = ["AI", "半導体", "GPU", "データセンター", "電線", "銅", "SaaS",
                          "海運", "銀行", "保険", "自動運転", "原油"]
# 指示書8番：投稿からの将来イベント自動検出。日付（M/D）＋イベント種別キーワードの組み合わせ
# だけを拾う軽量な正規表現ベース検出（既存Smart Import EVENTカテゴリの判定とは別の専用ロジック
# ——にこそく投稿はイベントカレンダー画像＋短い日付列挙が多く、Smart Importの自然文パターンと
# 形が異なるため）。
X_POST_EVENT_DATE_RE = re.compile(r"(\d{1,2})/(\d{1,2})\s*([^\d/\n、。]{0,12})")
X_POST_EVENT_TYPE_KEYWORDS = {
    "ECONOMIC": ["CPI", "PPI", "雇用統計", "小売売上高", "GDP", "経済指標"],
    "CENTRAL_BANK": ["FOMC", "日銀会合", "日銀", "ECB", "金融政策"],
    "INDEX_REBALANCE": ["メジャーSQ", "SQ"],
}


def _classify_social_post_categories(text):
    """指示書5番：キーワード一致で複数カテゴリを付与する（1つも一致しなければOTHER）。"""
    if not text:
        return ["OTHER"]
    cats = [cat for cat, kws in X_POST_CATEGORY_KEYWORDS.items() if any(kw in text for kw in kws)]
    return cats or ["OTHER"]


def _classify_social_post_importance(text, categories, direct_mentions=None, position_codes=None):
    """指示書6番：LOW/MEDIUM/HIGH/CRITICALを判定する。CRITICALは「市場を即時に動かしている・
    現在保有銘柄へ直接影響・当日のトレード判断を変更する可能性が高い」場合だけに限定
    （指示書の明示的な限定条件）——緊急性を示すキーワードがあり、かつ直接言及銘柄が実際の
    保有銘柄と重なる場合のみCRITICALとする（無関係な急騰急落報告を無条件にCRITICAL化しない）。"""
    if not text:
        return "LOW"
    direct_mentions = direct_mentions or []
    position_codes = position_codes or set()
    has_critical_kw = any(kw in text for kw in X_POST_CRITICAL_KEYWORDS)
    affects_position = bool(set(direct_mentions) & set(position_codes))
    if has_critical_kw and affects_position:
        return "CRITICAL"
    if any(kw in text for kw in X_POST_HIGH_KEYWORDS) or has_critical_kw:
        return "HIGH"
    if categories and categories != ["OTHER"]:
        return "MEDIUM"
    return "LOW"


def _split_facts_opinions(text):
    """指示書7番：本文を「事実」と「投稿者の見解」に分離する（system_inferenceはPhase1では
    生成しない——実際の売買判断ロジックと結び付けない段階のため、AIによる断定的な推論を
    捏造しない。指示書12番「投稿だけで売買判断しない」の精神に合わせた保守的な実装）。
    文分割は句点・改行の単純な区切り。見解マーカーが1つでも含まれる文はauthor_opinionへ、
    それ以外はfactsへ（事実の断定はしすぎず、単純な列挙文もfactsとして保持する）。"""
    if not text:
        return [], []
    sentences = re.split(r"[。\n]", text)
    facts, opinions = [], []
    for s in sentences:
        s = s.strip()
        if not s:
            continue
        if any(m in s for m in X_POST_OPINION_MARKERS):
            opinions.append(s)
        else:
            facts.append(s)
    return facts, opinions


def _detect_social_post_mentions(database_url, user_id, text):
    """指示書15番：登録銘柄の直接言及（銘柄名が本文に文字列として含まれるか）と、テーマ
    キーワード経由の間接関連（監視銘柄の既存theme欄に同じキーワードが含まれる銘柄）を分離
    して返す。独自の固定銘柄マップは使わない（既存の登録データのみを根拠にする）。
    戻り値：{"direct_mentions": [code,...], "theme_related": [code,...]}"""
    result = {"direct_mentions": [], "theme_related": []}
    if investment_db is None or not database_url or not text:
        return result
    try:
        watchlist = investment_db.list_watchlist(database_url, user_id, market="JP")
    except Exception:
        return result
    direct, theme = set(), set()
    matched_themes = [kw for kw in X_POST_THEME_KEYWORDS if kw in text]
    for w in watchlist:
        name = (w.get("name") or "").strip()
        if name and name in text:
            direct.add(w.get("code"))
        if matched_themes:
            item_theme = (w.get("theme") or "")
            if any(kw in item_theme for kw in matched_themes):
                theme.add(w.get("code"))
    theme -= direct  # 直接言及と間接関連は排他（指示書15番「直接言及と間接関連は区別する」）
    result["direct_mentions"] = sorted(direct)
    result["theme_related"] = sorted(theme)
    return result


def _detect_events_from_social_text(text, posted_at_date, source_handle=None, source_display_name=None,
                                     post_id=None, post_url=None):
    """指示書8番：投稿本文から将来イベント候補を検出する（M/D＋イベント種別キーワード）。
    確定登録はせずdraft（verification_status='UNVERIFIED'）として返す。呼び出し側で
    investment_db.import_market_eventsへ渡す前に重複チェックを行う。
    2026-09-15更新（X Intelligence Phase1B）：従来はにこそく専用でsource="nicosoku_x"を
    固定していたが、複数アカウント対応のためsource_handle等を引数化した（省略時は
    従来通りnicosokufx相当の表示に倒れる、既存呼び出し元への後方互換）。source_handle・
    post_id・posted_at相当の情報はraw_payloadへ保持し、Phase3（X由来イベントのsource追跡）
    で専用列へ昇格させる前段として残す。"""
    if not text:
        return []
    handle = source_handle or "nicosokufx"
    display_name = source_display_name or (MARKET_SOURCE_BY_HANDLE.get(handle) or {}).get("display_name") or "にこそく"
    drafts = []
    for m in X_POST_EVENT_DATE_RE.finditer(text):
        month, day, tail = int(m.group(1)), int(m.group(2)), m.group(3)
        event_type = next((et for et, kws in X_POST_EVENT_TYPE_KEYWORDS.items() if any(kw in tail for kw in kws)), None)
        title = tail.strip()
        if not event_type or not title:
            continue
        year = posted_at_date.year
        try:
            event_date = datetime.date(year, month, day)
        except ValueError:
            continue
        if event_date < posted_at_date - datetime.timedelta(days=3):
            event_date = datetime.date(year + 1, month, day)  # 年またぎ（12月の投稿で1月のイベント等）
        drafts.append({
            # 2026-09-15更新（X Intelligence Phase3）：タイトルへ発信者名を埋め込むと
            # （旧「（にこそく投稿より検出）」）、同じイベントを別アカウントが投稿した場合に
            # 自然キーUNIQUE(user_id,event_date,title)が一致せず、常に別行になってしまい
            # 複数source統合ができなかった。汎用の「（X投稿より検出）」へ変更し、発信者の
            # 識別は専用列（source_handle等）とraw_payload.additional_sourcesへ委ねる。
            "event_date": event_date.isoformat(), "title": f"{title}（X投稿より検出）",
            "event_type": event_type, "importance": "MEDIUM",
            "source": f"x:{handle}", "source_type": "X_POST", "verification_status": "UNVERIFIED",
            "raw_payload": {"confidence": "LOW", "detected_text": tail.strip(), "source_handle": handle,
                             "source_post_id": post_id, "source_post_url": post_url,
                             "published_at": posted_at_date.isoformat()},
        })
    return drafts


# ============================================================
# X Intelligence Phase1B（2026-09-15新規）：手動X投稿取り込み経路。
# 監査（2026-09-14）で判明した問題点：
#  - X_API_BEARER_TOKEN未設定のため自動取得が0件のまま（Phase1A時点）。
#  - 既存のSOCIAL_IMAGE_ANALYSIS経路はsocial_market_postsへのUPDATE-onlyで、
#    対象投稿が事前に存在しない限り保存できなかった（新規X投稿を取り込む手段が無い）。
# この2点を解消するため、ユーザーがSmart ImportへX投稿のURL・本文・投稿日時・画像解析結果
# を手動で貼り付けるだけで、既存のsocial_market_postsテーブル・既存カラムへそのまま保存
# できる経路を追加する（別テーブルは新設しない、既存のX自動取得経路と完全に同じ形の
# レコードを組み立てて共有する）。
# ============================================================

X_POST_URL_RE = re.compile(r"(?:x\.com|twitter\.com)/([A-Za-z0-9_]+)/status/(\d+)")


def parse_x_post_url(url):
    """X/Twitter投稿URLから(source_handle, post_id)を抽出する。マッチしなければ(None, None)
    （不明な値を推測して埋めない、判定不能ならNoneのまま呼び出し側に委ねる）。"""
    if not url:
        return None, None
    m = X_POST_URL_RE.search(url)
    if not m:
        return None, None
    return m.group(1), m.group(2)


def _manual_import_post_id(handle, url, text, posted_at_str):
    """手動投入でpost_id（実際のX投稿ID）を解決できない場合の代替ID。同一入力からは常に
    同じIDになるUUID5（uuid標準ライブラリのみ使用、新規依存を増やさない）にすることで、
    同一投稿の再貼り付けによる重複登録を防ぐ（指示書7番）。実際のX post_idではないことが
    分かるよう"manual:"を付与する。"""
    basis = f"{handle}|{url or ''}|{text or ''}|{posted_at_str or ''}"
    return "manual:" + str(uuid.uuid5(uuid.NAMESPACE_URL, basis))


def normalize_social_post_import(database_url, user_id, draft, raw_text=None, import_source="unknown"):
    """Smart Import「X投稿の手動貼り付け」経路（指示書1・2・3・5番）。X_API_BEARER_TOKEN
    無しでも、投稿URL・source_handle・本文・投稿日時・画像解析結果を受け取り、既存の
    _build_social_post_record()と同じ形のレコードへ正規化する（自動取得経路と完全に
    同じテーブル・列を共有し、別スキーマを作らない）。
    urlからhandleが解決できる場合はそちらを優先せず、明示的なsource_handle指定を優先する
    （ユーザーが意図的に上書きした場合を尊重する）。
    戻り値：Noneまたは{"post_record":..., "image_analysis":..., "is_official_source":bool,
    "resolved_handle":...}。post_record単体でinvestment_db.insert_social_post_if_new()へ
    そのまま渡せる。"""
    draft = draft or {}
    text = draft.get("text") or draft.get("post_text") or ""
    post_url = draft.get("post_url") or draft.get("url")
    if not text and not post_url:
        return None
    url_handle, url_post_id = parse_x_post_url(post_url)
    handle = draft.get("source_handle") or url_handle
    if not handle:
        return None
    handle = str(handle).lstrip("@").strip()
    if not handle:
        return None
    post_id = draft.get("post_id") or url_post_id

    posted_at_str = draft.get("posted_at") or draft.get("published_at")
    posted_at = None
    if posted_at_str:
        try:
            posted_at = datetime.datetime.fromisoformat(str(posted_at_str).replace("Z", "+00:00"))
        except ValueError:
            posted_at = None  # 不正な日時は推測せずNoneのまま（指示書「不明な値を推測して埋めない」）

    if not post_id:
        post_id = _manual_import_post_id(handle, post_url, text, posted_at_str)

    cfg = MARKET_SOURCE_BY_HANDLE.get(handle)
    is_official = cfg is not None
    source_name = (cfg or {}).get("display_name") or handle
    account_type = (cfg or {}).get("source_type") or "MARKET_COMMENTARY"

    categories = _classify_social_post_categories(text)
    mentions = _detect_social_post_mentions(database_url, user_id, text)
    try:
        positions = investment_db.list_portfolio(database_url, user_id) if investment_db else []
        position_codes = {p.get("code") for p in positions}
        watchlist = investment_db.list_watchlist(database_url, user_id, market="JP") if investment_db else []
    except Exception:
        position_codes, watchlist = set(), []
    importance = _classify_social_post_importance(text, categories, mentions["direct_mentions"], position_codes)
    facts, opinions = _split_facts_opinions(text)

    # 画像解析結果（ユーザー/ChatGPT等が目視解析した構造化JSON）があれば、FACTと
    # 投稿者見解の分離方針を維持したままfacts/author_opinionへ統合する（指示書2番
    # 「投稿者の意見をFACT扱いしない」を、画像由来の情報にも一貫して適用する）。
    image_analysis = draft.get("image_analysis") if isinstance(draft.get("image_analysis"), dict) else None
    if image_analysis:
        img_facts = image_analysis.get("facts")
        if isinstance(img_facts, list):
            facts = facts + [str(x) for x in img_facts if x]
        img_view = image_analysis.get("author_view") or image_analysis.get("author_opinion")
        if img_view:
            opinions = opinions + [str(img_view)]

    prediction_market = extract_prediction_market_data(text) if account_type == "PREDICTION_MARKET" and text else None
    stock_breaking = extract_stock_breaking_data(text, watchlist=watchlist) if account_type == "STOCK_BREAKING" and text else None
    corporate_breaking = extract_corporate_breaking_data(text, url=post_url) if account_type == "CORPORATE_BREAKING" and text else None
    if prediction_market and classify_prediction_market_shift(prediction_market.get("probability_change")):
        importance = "HIGH" if importance in ("LOW", "MEDIUM") else importance

    urls = re.findall(r"https?://\S+", text)
    primary_source_url = next((u for u in urls if u != post_url), None)
    primary_source_type = classify_primary_source_type(primary_source_url) if primary_source_url else None
    post_classification = classify_post_relay_type(text, bool(urls))

    post_record = {
        "source_type": "X_MARKET_SOURCE", "source_name": source_name, "source_handle": handle,
        "post_id": post_id, "posted_at": posted_at.isoformat() if posted_at else None,
        "text": text, "url": post_url or f"https://x.com/{handle}/status/{post_id}",
        # 実ファイルは保存しない（指示書「自動OCRは必須ではない」＝画像バイナリ管理は対象外）。
        # 画像添付の事実自体はmedia_jsonへ簡易メモとして残す（指示書6番の前提「media情報を保持」）。
        "media": draft.get("media") or ([{"attached": True, "analyzed": True}] if image_analysis else []),
        "quoted_post": None, "public_metrics": {},
        "categories": categories, "importance": importance,
        "facts": facts, "author_opinion": opinions, "system_inference": [],
        "direct_mentions": mentions["direct_mentions"], "theme_related": mentions["theme_related"],
        "verification_status": "UNVERIFIED",
        "post_classification": post_classification, "prediction_market": prediction_market,
        "stock_breaking": stock_breaking, "corporate_breaking": corporate_breaking,
        "primary_source_url": primary_source_url, "primary_source_type": primary_source_type,
        "discovered_via_social": bool(urls),
    }
    return {"post_record": post_record, "image_analysis": image_analysis,
            "is_official_source": is_official, "resolved_handle": handle}


# ============================================================
# にこそく画像解析待ちキュー。2026-09-10新規。
# 画像付き投稿はimage_analysis_status=PENDINGで保存され、ユーザーがChatGPT等で解析した
# 結果を既存の「ChatGPT連携」窓口（Smart Import）へ貼り付けるとSOCIAL_IMAGE_ANALYSISとして
# 自動分類され、POST /api/social-posts/image-analysisと同じ保存経路へ振り分けられる
# （smart_import_confirm()のSOCIAL_IMAGE_ANALYSIS分岐）。解析結果はrecent_social_market_
# signals・朝一チェック・INTRADAY_REPORT・イベント検出・関連銘柄付けに使うが、売買スコアへは
# 一切加点しない（既存方針の継続）。
# ============================================================

def normalize_social_image_analysis(draft, raw_text=None, import_source="unknown"):
    """{"type":"social_market_image_analysis","post_id":...,"analysis":{...}}形式のJSONを
    (post_id, analysis_dict)へ正規化する。post_idが無ければ保存できないためNoneを返す
    （呼び出し側でconfidence=LOWとして自動保存対象外になる想定と一致させる）。analysisの
    中身はユーザー/ChatGPT側の自由記述を許容し、厳密なスキーマ検証はしない（他のSmart
    Import正規化関数と同じ「形を強制しすぎない」方針）。"""
    if not isinstance(draft, dict):
        return None
    post_id = draft.get("post_id")
    if not post_id:
        return None
    analysis = draft.get("analysis")
    if not isinstance(analysis, dict):
        # analysisキーが無い場合、post_id・type以外の残りのキー全体をanalysisとして扱う
        # （ユーザーがrequestで例示した8項目をトップレベルに直接貼り付けるケースにも対応）。
        analysis = {k: v for k, v in draft.items() if k not in ("type", "post_id", "posted_at", "text", "image_urls", "request")}
    return post_id, analysis


def _extract_stock_mentions_from_analysis(analysis):
    """analysis中のstock_mentions（または旧仕様のstocks）から銘柄名/コード候補の文字列一覧を
    取り出す（{"name":...}/{"stock":...}/{"code":...}/文字列、いずれの形も許容）。"""
    raw = (analysis or {}).get("stock_mentions") or (analysis or {}).get("stocks") or []
    if not isinstance(raw, list):
        return []
    names = []
    for item in raw:
        if isinstance(item, str) and item.strip():
            names.append(item.strip())
        elif isinstance(item, dict):
            n = item.get("name") or item.get("stock") or item.get("code")
            if n:
                names.append(str(n).strip())
    return names


def _resolve_stock_mentions_to_codes(database_url, user_id, mention_names):
    """画像解析が返した銘柄名候補を、既存監視銘柄の名前と突き合わせてコードへ解決する
    （指示書15番と同じ「既存の登録データのみを根拠にする」方針、独自の固定マップは使わない）。"""
    if investment_db is None or not database_url or not mention_names:
        return []
    try:
        watchlist = investment_db.list_watchlist(database_url, user_id, market="JP")
    except Exception:
        return []
    codes = set()
    for name in mention_names:
        for w in watchlist:
            wname = (w.get("name") or "").strip()
            if wname and (wname in name or name in wname):
                codes.add(w.get("code"))
    return sorted(codes)


def _normalize_image_economic_events(analysis, posted_date, source_handle=None, source_display_name=None,
                                      post_id=None, post_url=None):
    """analysis中のeconomic_eventsを market_events importable な draft へ変換する
    （文字列「9/10 PPI」形式は既存の_detect_events_from_social_textを再利用、
    {"date":...,"title":...}形式は直接構築——別ロジックの重複実装を避ける）。
    2026-09-15更新（X Intelligence Phase1B）：source_handle等を引数化し、にこそく専用の
    固定文言から複数アカウント対応へ拡張（省略時は従来通りにこそく相当、後方互換）。"""
    handle = source_handle or "nicosokufx"
    display_name = source_display_name or (MARKET_SOURCE_BY_HANDLE.get(handle) or {}).get("display_name") or "にこそく"
    raw = (analysis or {}).get("economic_events") or []
    if not isinstance(raw, list):
        return []
    drafts = []
    for item in raw:
        if isinstance(item, str) and item.strip():
            drafts.extend(_detect_events_from_social_text(item, posted_date, source_handle=handle,
                                                            source_display_name=display_name,
                                                            post_id=post_id, post_url=post_url))
        elif isinstance(item, dict) and item.get("title"):
            event_date = posted_date
            date_str = item.get("date")
            if date_str:
                m = re.match(r"(\d{1,2})/(\d{1,2})", str(date_str))
                if m:
                    try:
                        event_date = datetime.date(posted_date.year, int(m.group(1)), int(m.group(2)))
                    except ValueError:
                        event_date = posted_date
            drafts.append({
                # 2026-09-15更新（X Intelligence Phase3）：タイトルへ発信者名を埋め込まない
                # （_detect_events_from_social_textと同じ理由：自然キー一致による複数source
                # 統合を可能にするため）。
                "event_date": event_date.isoformat(), "title": f"{item['title']}（X投稿の画像解析より検出）",
                "event_type": item.get("event_type") or "OTHER", "importance": item.get("importance") or "MEDIUM",
                "source": f"x:{handle}", "source_type": "X_POST_IMAGE", "verification_status": "UNVERIFIED",
                "raw_payload": {"confidence": "MEDIUM", "detected_from": "image_analysis",
                                 "source_handle": handle, "source_post_id": post_id, "source_post_url": post_url,
                                 "published_at": posted_date.isoformat()},
            })
    return drafts


def _x_api_request(path, params=None):
    """X API v2への共通リクエスト。戻り値：(json_or_None, status, detail)。
    status："ok"|"no_key"|"rate_limited"|"timeout"|"failed"。指示書1番により実装方式は
    公式APIのみ（スクレイピング等は一切実装しない）。指示書2番「レート制限を検出したら
    exponential backoff」は呼び出し側（_nicosoku_poll_scheduler_loop）が担当する
    （このレイヤーは1回の試行結果を正しく分類して返すだけ）。"""
    if not X_API_BEARER_TOKEN:
        return None, "no_key", "X_API_BEARER_TOKEN未設定"
    url = f"{X_API_BASE}{path}"
    if params:
        url += "?" + urllib.parse.urlencode(params)
    req = urllib.request.Request(url, headers={"Authorization": f"Bearer {X_API_BEARER_TOKEN}",
                                                 "User-Agent": "trade-cockpit/1.0"})
    try:
        with urllib.request.urlopen(req, timeout=10) as res:
            return json.loads(res.read().decode("utf-8")), "ok", None
    except urllib.error.HTTPError as e:
        if e.code == 429:
            return None, "rate_limited", "429 Too Many Requests"
        try:
            body = e.read().decode("utf-8")
        except Exception:
            body = str(e)
        return None, "failed", f"HTTP {e.code}: {body[:200]}"
    except TimeoutError:
        return None, "timeout", "タイムアウト"
    except Exception as e:
        return None, "failed", str(e)


def _x_resolve_user_id(username):
    """GET /2/users/by/username/:username 相当（指示書1番）。"""
    data, status, detail = _x_api_request(f"/users/by/username/{username}")
    if status != "ok" or not data or not data.get("data"):
        return None, status, detail
    return data["data"].get("id"), "ok", None


def _x_fetch_recent_tweets(user_id, since_id=None):
    """GET /2/users/:id/tweets 相当（指示書1番）。リプライ・リポストは除外
    （exclude=replies,retweets、引用投稿は本人のオリジナル投稿として残る）。"""
    params = {
        "max_results": "20",
        "exclude": "replies,retweets",
        "tweet.fields": "created_at,public_metrics,entities,attachments,referenced_tweets",
        "expansions": "attachments.media_keys,referenced_tweets.id",
        "media.fields": "url,preview_image_url,type,width,height,alt_text",
    }
    if since_id:
        params["since_id"] = since_id
    return _x_api_request(f"/users/{user_id}/tweets", params)


def _build_social_post_record(database_url, user_id, tweet, media_by_key, source_handle, source_name,
                               source_config=None):
    """1件のtweet dict（X API v2形式）から、DB保存用のsocial_market_posts行を組み立てる
    （指示書3・4・5・6・7・15番）。Market Intelligence Phase6（指示書4・5・8・10・11・12番）：
    source_configのsource_type別に専用解析（Polymarket確率抽出・kgbukabu銘柄速報抽出・
    aryarya一次情報リンク抽出）を追加専用フィールドとして付与する。source_config省略時は
    従来通りnicosoku（MARKET_COMMENTARY）相当の扱い（後方互換）。"""
    account_type = (source_config or {}).get("source_type") or "MARKET_COMMENTARY"
    text = tweet.get("text") or ""
    post_id = tweet.get("id")
    media_keys = (tweet.get("attachments") or {}).get("media_keys") or []
    media = [media_by_key[k] for k in media_keys if k in media_by_key]
    quoted = None
    for ref in (tweet.get("referenced_tweets") or []):
        if ref.get("type") == "quoted":
            quoted = {"id": ref.get("id")}
    posted_at_str = tweet.get("created_at")
    try:
        posted_at = datetime.datetime.fromisoformat((posted_at_str or "").replace("Z", "+00:00"))
    except Exception:
        posted_at = datetime.datetime.now(datetime.timezone.utc)
    categories = _classify_social_post_categories(text)
    mentions = _detect_social_post_mentions(database_url, user_id, text)
    try:
        positions = investment_db.list_portfolio(database_url, user_id) if investment_db else []
        position_codes = {p.get("code") for p in positions}
        watchlist = investment_db.list_watchlist(database_url, user_id, market="JP") if investment_db else []
    except Exception:
        position_codes, watchlist = set(), []
    importance = _classify_social_post_importance(text, categories, mentions["direct_mentions"], position_codes)
    facts, opinions = _split_facts_opinions(text)

    urls = re.findall(r"https?://\S+", text)
    has_link = bool(urls)
    primary_source_url = urls[0] if urls else None
    primary_source_type = classify_primary_source_type(primary_source_url) if primary_source_url else None
    post_classification = classify_post_relay_type(text, has_link)

    prediction_market = extract_prediction_market_data(text) if account_type == "PREDICTION_MARKET" else None
    stock_breaking = extract_stock_breaking_data(text, watchlist=watchlist) if account_type == "STOCK_BREAKING" else None
    corporate_breaking = extract_corporate_breaking_data(text, url=primary_source_url) \
        if account_type == "CORPORATE_BREAKING" else None

    # 指示書6番：Polymarketのprobability急変はimportanceをHIGH以上へ引き上げる（既存の
    # キーワードベース判定とは別の追加条件、他sourceには影響しない）。
    if prediction_market and classify_prediction_market_shift(prediction_market.get("probability_change")):
        importance = "HIGH" if importance in ("LOW", "MEDIUM") else importance

    return {
        "source_type": "X_MARKET_SOURCE", "source_name": source_name, "source_handle": source_handle,
        "post_id": post_id, "posted_at": posted_at.isoformat(),
        "text": text, "url": f"https://x.com/{source_handle}/status/{post_id}",
        "media": media, "quoted_post": quoted, "public_metrics": tweet.get("public_metrics") or {},
        "categories": categories, "importance": importance,
        "facts": facts, "author_opinion": opinions, "system_inference": [],
        "direct_mentions": mentions["direct_mentions"], "theme_related": mentions["theme_related"],
        "verification_status": "UNVERIFIED",
        "post_classification": post_classification, "prediction_market": prediction_market,
        "stock_breaking": stock_breaking, "corporate_breaking": corporate_breaking,
        "primary_source_url": primary_source_url, "primary_source_type": primary_source_type,
        "discovered_via_social": bool(has_link),
    }, posted_at.date()


# ============================================================
# にこそくX連携 Phase2（2026-09-10）：診断機能・優先度スコア・画像解析待ちキューの状態管理強化。
# 既存の売買スコア・AUTO_RS・ENTRY TOP5等には一切加点しない（指示書冒頭・20番）。
# ============================================================

# プロセス内メモリの診断情報（指示書17番）。トークン等の秘密情報は絶対に入れない。
# last_success_at・last_errorはmarket_sources側（DB永続化済み）を正とし、ここは
# 「直近1回の呼び出し」の詳細（プロセス再起動で消えても実害が無い情報）だけを持つ。
_nicosoku_diag = {
    "last_fetch_started_at": None, "last_fetch_finished_at": None,
    "last_error_at": None, "last_error_message": None,
    "fetched_count": 0, "inserted_count": 0, "duplicate_count": 0,
    "last_http_status": None, "poller_running": False,
}

# Market Intelligence Phase6（指示書2・30番）：他3source用の同形の診断dict。nicosokuは
# 既存の_nicosoku_diagをそのまま使う（後方互換、nicosoku_diagnostics()の戻り値を変えない）。
_market_source_diag = {}


def _get_source_diag(handle):
    if handle == NICOSOKU_X_USERNAME:
        return _nicosoku_diag
    return _market_source_diag.setdefault(handle, {
        "last_fetch_started_at": None, "last_fetch_finished_at": None,
        "last_error_at": None, "last_error_message": None,
        "fetched_count": 0, "inserted_count": 0, "duplicate_count": 0,
        "last_http_status": None, "poller_running": False,
    })


SOCIAL_IMAGE_ANALYSIS_STATUSES = ("NONE", "PENDING", "ANALYZED", "SKIPPED", "FAILED")


def _initial_image_analysis_status(media):
    """指示書1番：新規X投稿保存時のimage_analysis_status初期値。image_urls（media）が
    1件以上あればPENDING、無ければNONE。"""
    return "PENDING" if media else "NONE"


# 指示書5番：解析優先度スコアの配点。同じ理由を重複加点しないよう、「言及」区分（保有/監視/
# テーマ）と「カテゴリ」区分はそれぞれ最も高い1件のみを加点する。
_SOCIAL_PRIORITY_IMPORTANCE = {"CRITICAL": 35, "HIGH": 25, "MEDIUM": 10}
_SOCIAL_PRIORITY_CATEGORY = {
    "ECONOMIC_EVENT": 15, "CENTRAL_BANK": 15, "MARKET_HEATMAP": 12,
    "INDEX_TECHNICAL": 10, "STOCK_TECHNICAL": 10, "MARKET_SENTIMENT": 8,
}


def _post_age_minutes(posted_at, now=None):
    """posted_at（ISO文字列）から現在までの経過分。解析不能ならNone。"""
    if not posted_at:
        return None
    try:
        dt = datetime.datetime.fromisoformat(str(posted_at).replace("Z", "+00:00"))
        if dt.tzinfo is None:
            dt = dt.replace(tzinfo=datetime.timezone.utc)
    except Exception:
        return None
    now = now or datetime.datetime.now(datetime.timezone.utc)
    return (now - dt).total_seconds() / 60


def compute_social_post_priority_score(post, watch_codes=None, position_codes=None, now=None):
    """指示書5番：投稿1件のanalysis_priority_score（0〜100）を動的計算する。DBへ新規列を
    足さず、APIレスポンス生成時に都度計算する方針（指示書「必須保存する必要はない」）。"""
    watch_codes = watch_codes or set()
    position_codes = position_codes or set()
    score = 0
    score += _SOCIAL_PRIORITY_IMPORTANCE.get(post.get("importance"), 0)
    age_min = _post_age_minutes(post.get("posted_at"), now=now)
    if age_min is not None:
        if age_min <= 30:
            score += 20
        elif age_min <= 60:
            score += 10
    direct = set(post.get("direct_mentions_json") or [])
    theme = set(post.get("theme_related_json") or [])
    if direct & position_codes:
        score += 20
    elif direct & watch_codes:
        score += 15
    elif theme:
        score += 8
    cats = set(post.get("categories_json") or [])
    cat_bonus = max((_SOCIAL_PRIORITY_CATEGORY[c] for c in cats if c in _SOCIAL_PRIORITY_CATEGORY), default=0)
    score += cat_bonus
    if len(post.get("media_json") or []) > 1:
        score += 5
    return min(score, 100)


def social_post_priority_label(score):
    """指示書6番：スコアからURGENT/HIGH/NORMAL/LOWラベルを生成する。"""
    if score >= 80:
        return "URGENT"
    if score >= 60:
        return "HIGH"
    if score >= 30:
        return "NORMAL"
    return "LOW"


def _enrich_social_post_priority(post, watch_codes=None, position_codes=None, now=None):
    """指示書5・6・9番：投稿dictにanalysis_priority_score・priority_label・
    related_positions・related_watchlist を追加専用フィールドとして付与する（既存キーは
    一切変更しない）。"""
    watch_codes = watch_codes or set()
    position_codes = position_codes or set()
    score = compute_social_post_priority_score(post, watch_codes, position_codes, now=now)
    direct = set(post.get("direct_mentions_json") or [])
    theme = set(post.get("theme_related_json") or [])
    mentions = direct | theme
    post = dict(post)
    post["analysis_priority_score"] = score
    post["priority_label"] = social_post_priority_label(score)
    post["related_positions"] = sorted(mentions & position_codes)
    post["related_watchlist"] = sorted(mentions & watch_codes)
    return post


def sort_pending_posts_by_priority(posts):
    """指示書7番：PENDING投稿をanalysis_priority_score DESC・posted_at DESCで並べる。
    posts中の各要素は事前にanalysis_priority_scoreが付与済みである前提（未付与は0扱い）。
    PENDING以外の投稿は並び替えの対象にせずそのままの順序で末尾に残す（安定ソート）。"""
    def key(p):
        return (p.get("image_analysis_status") != "PENDING",
                -(p.get("analysis_priority_score") or 0),
                "" if not p.get("posted_at") else "")
    pending = [p for p in posts if p.get("image_analysis_status") == "PENDING"]
    others = [p for p in posts if p.get("image_analysis_status") != "PENDING"]
    pending.sort(key=lambda p: (p.get("posted_at") or ""), reverse=True)
    pending.sort(key=lambda p: p.get("analysis_priority_score") or 0, reverse=True)
    return pending + others


def _normalize_confidence(value):
    """指示書10番：画像解析結果のconfidenceを0.0〜1.0へ正規化する。値が無い/変換不能なら
    None（無理に0埋めしない）。"""
    if value is None or value == "":
        return None
    try:
        v = float(value)
    except (TypeError, ValueError):
        return None
    if v != v:  # NaN
        return None
    return max(0.0, min(1.0, v))


def _nicosoku_market_hours_jst(now_jst=None):
    jst = datetime.timezone(datetime.timedelta(hours=9))
    now_jst = now_jst or datetime.datetime.now(jst)
    hhmm = now_jst.strftime("%H:%M")
    return "08:00" <= hhmm <= "15:40"


def _nicosoku_source_is_stale(source, now=None):
    """指示書14番：last_success_atをもとにSTALE判定する。市場時間中(08:00-15:40 JST)は
    15分、それ以外は30分を閾値とする。last_success_atが無ければ（一度も成功していない）
    STALE扱い。"""
    last_success_at = (source or {}).get("last_success_at")
    if not last_success_at:
        return True
    try:
        dt = datetime.datetime.fromisoformat(str(last_success_at).replace("Z", "+00:00"))
        if dt.tzinfo is None:
            dt = dt.replace(tzinfo=datetime.timezone.utc)
    except Exception:
        return True
    now = now or datetime.datetime.now(datetime.timezone.utc)
    age_min = (now - dt).total_seconds() / 60
    jst = datetime.timezone(datetime.timedelta(hours=9))
    threshold = 15 if _nicosoku_market_hours_jst(now.astimezone(jst)) else 30
    return age_min > threshold


def build_social_posts_response(database_url, user_id, limit=10, min_importance=None, source_handle=None):
    """GET /api/social-posts の実体（指示書5・6・7・8番）。各投稿へanalysis_priority_score等を
    付与し、PENDING投稿はスコア降順→新しさ降順で並べ替える。pendingSummaryは表示件数
    （limit）に関わらず、SKIPPEDを除く全PENDING件数を対象にする（指示書8番「解析待ち件数」・
    3番「SKIPPED投稿は通常の解析待ち件数から除外」）。Market Intelligence Phase6
    （指示書26番）：source_handleを指定すると他source（polymarketjapan/kgbukabu/aryarya）の
    投稿一覧も同じ関数で取得できる（省略時は従来通りにこそく、後方互換）。"""
    source_handle = source_handle or NICOSOKU_X_USERNAME
    if investment_db is None or not database_url:
        return {"posts": [], "pendingSummary": {"pending": 0, "urgent": 0}}
    posts = investment_db.list_recent_social_posts(
        database_url, source_handle=source_handle, min_importance=min_importance, limit=limit)
    try:
        watch_codes = {w.get("code") for w in investment_db.list_watchlist(database_url, user_id, market="JP")}
        position_codes = {p.get("code") for p in investment_db.list_portfolio(database_url, user_id)}
    except Exception:
        watch_codes, position_codes = set(), set()
    enriched = [_enrich_social_post_priority(p, watch_codes, position_codes) for p in posts]
    # Phase3新規（指示書15番）：ANALYZED投稿だけ、評価済み時間軸があれば簡潔表示を添える
    # （未評価なら何も追加しない＝evaluation_summaryキー自体を付けない）。表示件数（limit）
    # 分だけの軽い追加取得のため、DB負荷は限定的。
    for p in enriched:
        if p.get("image_analysis_status") == "ANALYZED":
            try:
                evals = investment_db.list_social_signal_evaluations_for_post(database_url, source_handle, p.get("post_id"))
                summary = _post_evaluation_summary(evals)
                if summary:
                    p["evaluation_summary"] = summary
                # Phase5新規（指示書22番）：投稿カードに小さくsignal_kindバッジ・高信頼度
                # マーカーを出すための代表signal情報（OBSERVATIONより予測系を優先）。
                rep = (next((e for e in evals if e.get("signal_kind") and e.get("signal_kind") != "OBSERVATION"), None)
                       or (evals[0] if evals else None))
                if rep:
                    p["signal_kind"] = rep.get("signal_kind")
                    p["signal_confidence"] = rep.get("signal_confidence")
            except Exception:
                pass
    ordered = sort_pending_posts_by_priority(enriched)
    all_pending = investment_db.list_recent_social_posts(
        database_url, source_handle=source_handle, limit=500, image_analysis_status="PENDING")
    pending_scores = [compute_social_post_priority_score(p, watch_codes, position_codes) for p in all_pending]
    pending_summary = {"pending": len(all_pending), "urgent": sum(1 for s in pending_scores if s >= 80)}
    return {"posts": ordered, "pendingSummary": pending_summary}


def get_market_source_diagnostics(database_url, handle, user_id=None):
    """Market Intelligence Phase6新規（指示書2・30番）：nicosoku_diagnostics()を一般化した
    もの。GET /api/market-sources/:handle/diagnostics の実体。Bearer Tokenそのものは絶対に
    返さない（token_configuredの真偽値のみ）。1source分のみを見るため、他sourceの障害の
    影響を受けない（指示書30番「1sourceの障害で全体をDEGRADEDにしない」）。"""
    diag = _get_source_diag(handle)
    source = investment_db.get_market_source(database_url, handle) \
        if (investment_db is not None and database_url) else None
    latest = investment_db.list_recent_social_posts(database_url, source_handle=handle, limit=1) \
        if (investment_db is not None and database_url) else []
    latest_post = latest[0] if latest else None
    rate_limit_status = "RATE_LIMITED" if diag.get("last_http_status") == "429" else "OK"
    # snapshot_status：market_snapshot_cache（既存_cache_get流用）に日経平均の鮮度の高い
    # エントリがあればOK、無ければUNKNOWN（診断呼び出し自体では新規取得しない——重い・
    # レート制限の対象になり得るライブ取得を診断のたびに走らせない設計）。
    nikkei_sym = SOCIAL_EVAL_MARKET_YF_SYMBOL.get("NIKKEI225")
    snapshot_entry = _cache_get(f"socialsnap:{nikkei_sym}") if nikkei_sym else None
    if snapshot_entry and _cache_fresh(snapshot_entry, SOCIAL_SNAPSHOT_CACHE_TTL_SEC):
        snapshot_status = "OK"
    elif snapshot_entry:
        snapshot_status = "STALE_CACHE"
    else:
        snapshot_status = "UNKNOWN"
    try:
        market_calendar_status = "OK" if isinstance(is_jp_trading_day(datetime.datetime.now(_JST).date()), bool) else "ERROR"
    except Exception:
        market_calendar_status = "ERROR"
    pending_evaluations = investment_db.count_social_signal_evaluations(database_url, handle, "PENDING") \
        if (investment_db is not None and database_url) else 0
    no_data_evaluations = investment_db.count_social_signal_evaluations(database_url, handle, "NO_DATA") \
        if (investment_db is not None and database_url) else 0
    # Phase5（指示書24番）：JST当日0時からの集計。
    today_start_iso = datetime.datetime.now(_JST).replace(hour=0, minute=0, second=0, microsecond=0) \
        .astimezone(datetime.timezone.utc).isoformat()
    duplicate_signal_groups = investment_db.count_duplicate_signal_groups_since(database_url, handle, today_start_iso) \
        if (investment_db is not None and database_url) else 0
    alerts_generated_today = investment_db.count_social_signal_alerts_since(database_url, handle, today_start_iso) \
        if (investment_db is not None and database_url) else 0
    high_confidence_signals_today = investment_db.count_high_confidence_signals_since(database_url, handle, today_start_iso) \
        if (investment_db is not None and database_url) else 0
    return {
        "token_configured": bool(X_API_BEARER_TOKEN),
        "username": handle,
        "source_type": (source or {}).get("source_type") or (MARKET_SOURCE_BY_HANDLE.get(handle) or {}).get("source_type"),
        "user_id_resolved": bool(_x_user_id_cache.get(handle)),
        "last_success_at": (source or {}).get("last_success_at"),
        "last_error": (source or {}).get("last_error"),
        "rate_limit_status": rate_limit_status,
        "latest_post_id": (latest_post or {}).get("post_id"),
        "latest_post_at": (latest_post or {}).get("posted_at"),
        "latest_post_has_media": bool((latest_post or {}).get("media_json")),
        "poller_running": diag["poller_running"],
        "stale": _nicosoku_source_is_stale(source),
        "last_fetch_started_at": diag["last_fetch_started_at"],
        "last_fetch_finished_at": diag["last_fetch_finished_at"],
        "last_fetched_count": diag["fetched_count"],
        "last_inserted_count": diag["inserted_count"],
        "last_duplicate_count": diag["duplicate_count"],
        "snapshot_status": snapshot_status,
        "market_calendar_status": market_calendar_status,
        "pending_evaluations": pending_evaluations,
        "no_data_evaluations": no_data_evaluations,
        "duplicate_signal_groups": duplicate_signal_groups,
        "pending_signal_evaluations": pending_evaluations,  # 指示書24番の名称に合わせたエイリアス
        "alerts_generated_today": alerts_generated_today,
        "high_confidence_signals_today": high_confidence_signals_today,
    }


def nicosoku_diagnostics(database_url, user_id):
    """指示書11番・Phase6指示書2番：GET /api/social-sources/nicosoku/diagnostics の実体
    （既存API後方互換のための薄いラッパー）。"""
    return get_market_source_diagnostics(database_url, NICOSOKU_X_USERNAME, user_id=user_id)


def get_all_market_source_diagnostics(database_url, user_id=None):
    """Market Intelligence Phase6新規（指示書30番）：sourceごとに診断を返す。1sourceの障害が
    他sourceの結果に影響しない（各handleを独立に処理、例外はそのsourceだけERROR扱い）。"""
    out = {}
    for cfg in MARKET_SOURCE_CONFIGS:
        try:
            out[cfg["handle"]] = get_market_source_diagnostics(database_url, cfg["handle"], user_id=user_id)
        except Exception as e:
            out[cfg["handle"]] = {"status": "ERROR", "error": str(e)}
    return out


# ============================================================
# にこそくX連携 Phase3（2026-09-10新規）：投稿→実際の市場変化の的中率・先行性・テーマ別
# 信頼度を定量評価する。投稿単独では既存の売買スコア（AUTO_RS/ENTRY TOP5/thesis score/
# BUY・WAIT・SELL・stop loss・position sizing）へ一切加点しない（指示書冒頭・21番）——
# ここで作るのは「参考情報源としての質」＝source reliability contextのみ。
#
# Phase4（2026-09-10）でbaseline/resultの精度を改善：baseline_value/result_valueは
# signal生成時点・評価時点それぞれの実スナップショット（raw価格）から取得し、
# change_pct=(result-baseline)/baseline*100を直接計算する（Phase3の「前日終値比%を比較する」
# 方式は廃止）。due_atのMARKET_CLOSE/NEXT_OPEN/NEXT_CLOSEは日本市場カレンダー（土日＋祝日＋
# 年末年始）を考慮する（jp_public_holidays/is_jp_trading_day、Phase4新規）。
# 既知の制約（完了報告にも明記）：春分・秋分の日は近似式（~2099年頃まで有効な範囲）。
# 1分足が取得できない銘柄・時間帯はevaluation_quality=ESTIMATEDへ自動的に分類される。
# ============================================================

SOCIAL_EVAL_WINDOWS = ("30M", "1H", "MARKET_CLOSE", "NEXT_OPEN", "NEXT_CLOSE")

# 指示書2番：投稿カテゴリごとに評価すべき時間軸だけを生成する（全投稿で全時間軸を評価しない）。
