def classify_event_timing(dt_utc):
    """指示書4番：PRE_MARKET/IN_SESSION/LUNCH_BREAK/AFTER_CLOSE/OVERNIGHT/NON_TRADING_DAYを
    JPX calendar helper（Phase4）を再利用して判定する。時刻の境界はここに集約する
    （指示書「時刻をコード内に散在させない」の方針をPhase8でも踏襲）。"""
    dt_jst = dt_utc.astimezone(_JST)
    if not is_jp_trading_day(dt_jst.date()):
        return "NON_TRADING_DAY"
    hhmm = dt_jst.strftime("%H:%M")
    if hhmm < "06:00":
        return "OVERNIGHT"
    if hhmm < "09:00":
        return "PRE_MARKET"
    if hhmm < "11:30":
        return "IN_SESSION"
    if hhmm < "12:30":
        return "LUNCH_BREAK"
    if hhmm < "15:30":
        return "IN_SESSION"
    if hhmm < "21:00":
        return "AFTER_CLOSE"
    return "OVERNIGHT"


def resolve_event_market_relevant_at(event, evidence_list=None):
    """指示書3番：baselineに使う時刻の優先順位＝official event_at→primary_source posted_at→
    first_seen_at。system_observed_at（システムが実際に検知した時刻＝now）は別途保持し、
    look-ahead biasを起こさない（過去に遡ってbaselineを捏造しない——baseline_priceの取得
    自体はsystem_observed_at時点で行う、Phase4の設計をそのまま踏襲）。"""
    if event.get("event_at"):
        return event["event_at"]
    if evidence_list:
        primary = next((e for e in evidence_list if e.get("is_primary")), None)
        if primary and primary.get("posted_at"):
            return primary["posted_at"]
        # is_primaryが立っていなくても、現在のprimary_source_typeと一致するevidenceを使う。
        for e in evidence_list:
            if e.get("posted_at") and SOURCE_KIND_TO_PRIMARY_TYPE.get(e.get("source_kind")) == event.get("primary_source_type"):
                return e["posted_at"]
    return event.get("first_seen_at")


def _event_reaction_due_at(market_relevant_at, window, timing):
    """指示書2・4・5・6番：windowとevent timingに応じてdue_atを計算する。AFTER_CLOSEの
    企業材料はCLOSEを評価せずNEXT_OPENを最初の反応として重視する（指示書5番）。"""
    minutes = EVENT_REACTION_WINDOW_MINUTES.get(window)
    if minutes is not None:
        return market_relevant_at + datetime.timedelta(minutes=minutes)
    jst_at = market_relevant_at.astimezone(_JST)
    if window == "CLOSE":
        if timing == "AFTER_CLOSE":
            return None  # 指示書5番：当日CLOSEを評価しない
        d = jst_at.date() if is_jp_trading_day(jst_at.date()) and jst_at < jp_market_close_dt(jst_at.date()) \
            else next_jp_trading_day(jst_at.date())
        return jp_market_close_dt(d).astimezone(datetime.timezone.utc)
    if window == "NEXT_OPEN":
        return jp_market_open_dt(next_jp_trading_day(jst_at.date())).astimezone(datetime.timezone.utc)
    if window == "NEXT_CLOSE":
        return jp_market_close_dt(next_jp_trading_day(jst_at.date())).astimezone(datetime.timezone.utc)
    return None


def _reaction_windows_for_event(event, timing):
    """指示書2・5・6番：event_type別windowセットをtimingで調整する。AFTER_CLOSEはCLOSEを
    除きNEXT_OPEN/NEXT_CLOSEを優先、PRE_MARKETは寄り付き後の短い時間軸を重視する。"""
    base = set(EVENT_REACTION_WINDOWS_BY_TYPE.get(event.get("event_type"), EVENT_REACTION_WINDOWS_BY_TYPE["OTHER"]))
    if timing == "AFTER_CLOSE":
        base.discard("CLOSE")
        base.add("NEXT_OPEN")
    elif timing in ("PRE_MARKET", "OVERNIGHT"):
        base |= {"5M", "30M"}
    return base


def generate_event_market_reactions_for_event(database_url, user_id, event):
    """指示書1・7・8・9・10番：eventのdirect_tickers（最優先）・related_tickers（別集計）・
    sector・marketについてreaction候補行をPENDINGで作成する。baselineはこの時点
    （resolve_event_market_relevant_atの時刻を意識しつつ、実際の価格取得は現在時点で行う、
    Phase4と同じ設計）で確定する。戻り値：新規作成した行数。"""
    if investment_db is None or not database_url:
        return 0
    evidence = investment_db.list_underlying_event_evidence(database_url, event["id"])
    market_relevant_at_str = resolve_event_market_relevant_at(event, evidence)
    try:
        market_relevant_at = datetime.datetime.fromisoformat(str(market_relevant_at_str).replace("Z", "+00:00"))
        if market_relevant_at.tzinfo is None:
            market_relevant_at = market_relevant_at.replace(tzinfo=datetime.timezone.utc)
    except Exception:
        market_relevant_at = datetime.datetime.now(datetime.timezone.utc)
    timing = classify_event_timing(market_relevant_at)
    windows = _reaction_windows_for_event(event, timing)
    targets = []
    for t in (event.get("direct_tickers_json") or []):
        targets.append(("STOCK", t, "DIRECT"))
    for t in (event.get("related_tickers_json") or []):
        targets.append(("STOCK", t, "RELATED"))
    if event.get("sector"):
        targets.append(("SECTOR", event["sector"], "DIRECT"))
    if event.get("event_type") in ("ECONOMIC_INDICATOR", "CENTRAL_BANK", "GEOPOLITICS", "PREDICTION_MARKET"):
        targets.append(("MARKET", "NIKKEI225", "DIRECT"))
    if not targets:
        return 0
    rows = []
    for target_type, ticker, relevance in targets:
        baseline_price, baseline_quality = None, "NO_DATA"
        try:
            if target_type == "STOCK":
                snap = _fetch_raw_price_snapshot("STOCK", ticker)
            elif target_type == "MARKET":
                snap = _fetch_raw_price_snapshot("MARKET", ticker)
            else:
                snap = None  # SECTORはper-member snapshotが必要なため、result側でまとめて処理する
            if snap:
                baseline_price = snap["price"]
                baseline_quality = _classify_evaluation_quality(snap.get("captured_at"), market_relevant_at, snap.get("quality_hint"))
        except Exception as e:
            print("  Market Intelligence: reaction baseline取得失敗", ticker, e)
        for window in windows:
            due_at = _event_reaction_due_at(market_relevant_at, window, timing)
            if due_at is None:
                continue
            rows.append({
                "event_id": event["id"], "ticker": ticker, "target_type": target_type, "relevance": relevance,
                "reaction_window": window, "baseline_at": datetime.datetime.now(datetime.timezone.utc).isoformat(),
                "baseline_price": baseline_price, "due_at": due_at.isoformat(),
                "evaluation_status": "PENDING",
                "notes": None if baseline_price is not None else f"quality={baseline_quality}",
            })
    return investment_db.create_event_market_reactions(database_url, rows)


def generate_event_market_reactions_for_event_safe(database_url, user_id, event):
    try:
        return generate_event_market_reactions_for_event(database_url, user_id, event)
    except Exception as e:
        print("  Market Intelligence: reaction生成で例外（無視して続行）", e)
        return 0


EVENT_REACTION_EXTENDED_MOVE_THRESHOLD_PCT = {"5M": 5.0, "30M": 8.0, "1H": 10.0}


def classify_extended_move(window, return_pct):
    """指示書36番：強反応（5M+10%等）をEXTENDED_MOVEとしてフラグする——高値掴み防止材料。
    「良い材料」と「今から買って良い」は別物という原則をコードで担保する（指示書44番）。"""
    if return_pct is None:
        return False
    threshold = EVENT_REACTION_EXTENDED_MOVE_THRESHOLD_PCT.get(window)
    if threshold is None:
        return False
    return abs(return_pct) >= threshold


def classify_event_reaction(stock_return_pct, market_relative_return_pct=None, sector_relative_return_pct=None,
                             volume_ratio=None):
    """指示書11番：absolute returnだけでなくmarket/sector relative returnとvolumeも考慮した
    5段階分類。相対リターンが取れる場合はそちらを優先する（地合いだけの値動きを過大評価
    しない、Phase5のconfirmation_v2と同じ思想）。"""
    if stock_return_pct is None:
        return None
    base = sector_relative_return_pct if sector_relative_return_pct is not None else \
        (market_relative_return_pct if market_relative_return_pct is not None else stock_return_pct)
    volume_confirmed = volume_ratio is not None and volume_ratio >= 1.5
    if base >= 5 or (base >= 3 and volume_confirmed):
        return "STRONG_POSITIVE"
    if base >= 1:
        return "POSITIVE"
    if base <= -5 or (base <= -3 and volume_confirmed):
        return "STRONG_NEGATIVE"
    if base <= -1:
        return "NEGATIVE"
    return "NEUTRAL"


def classify_reaction_pattern(returns_by_window):
    """指示書13番：FADE/PERSISTENT/DELAYED/REVERSAL/NO_REACTIONを判定する。
    returns_by_windowは{"5M":pct,"30M":pct,"1H":pct,"CLOSE":pct,...}（無い時間軸はNone可）。
    order（早い順）で値の推移を見る——初動が大きく後で縮小＝FADE、終始拡大＝PERSISTENT、
    序盤は動かず終盤に動く＝DELAYED、途中で符号反転＝REVERSAL、終始小さい＝NO_REACTION。"""
    order = ["5M", "30M", "1H", "CLOSE", "NEXT_OPEN", "NEXT_CLOSE"]
    seq = [(w, returns_by_window[w]) for w in order if returns_by_window.get(w) is not None]
    if not seq:
        return None
    values = [v for _, v in seq]
    if all(abs(v) < 1 for v in values):
        return "NO_REACTION"
    signs = {1 if v > 0 else (-1 if v < 0 else 0) for v in values if abs(v) >= 1}
    if len(signs) > 1 and 0 not in signs:
        return "REVERSAL"
    first, last = values[0], values[-1]
    if abs(first) < 1 and abs(last) >= 2:
        return "DELAYED"
    if abs(first) >= 2 and abs(last) < abs(first) * 0.5:
        return "FADE"
    if abs(last) >= abs(first):
        return "PERSISTENT"
    return "FADE"


def compute_event_effectiveness_score(magnitude=None, relative_strength=None, breadth=None,
                                        volume_ratio=None, persistence_pattern=None):
    """指示書12番：0〜100。impact_score（事前重要度）とは完全に別軸——実際にどれだけ動いたか
    だけを見る。"""
    score = 0
    if magnitude is not None:
        score += min(abs(magnitude) * 6, 40)  # 目安：magnitude 6.7%で満点40
    if relative_strength is not None:
        score += min(abs(relative_strength) * 6, 25)
    if breadth is not None:
        score += breadth * 15  # breadthは0〜1
    if volume_ratio is not None and volume_ratio >= 1:
        score += min((volume_ratio - 1) * 10, 10)
    persistence_bonus = {"PERSISTENT": 10, "DELAYED": 6, "FADE": 2, "REVERSAL": 0, "NO_REACTION": 0}
    score += persistence_bonus.get(persistence_pattern, 0)
    return round(min(score, 100), 1)


def run_due_event_market_reactions(database_url, user_id, limit=50):
    """指示書28番：due_at到来分・PENDINGのみ処理する独立scheduler向け関数。既存の
    にこそくpoller・social evaluation schedulerとは競合しない（別テーブル・別関数）。"""
    result = {"evaluated": 0, "no_data": 0}
    if investment_db is None or not database_url:
        return result
    now_utc = datetime.datetime.now(datetime.timezone.utc)
    due = investment_db.list_due_event_market_reactions(database_url, now_utc.isoformat(), limit=limit)
    if not due:
        return result
    topix_pct = _concurrent_topix_change_pct()
    for r in due:
        result_price, quality, volume_ratio, breadth = None, "NO_DATA", None, None
        try:
            if r["target_type"] == "SECTOR":
                event = investment_db.get_underlying_event(database_url, r["event_id"])
                snap = _fetch_sector_snapshot(database_url, user_id, r["ticker"]) if event else None
                if snap:
                    result_price = snap["price"]
                    quality = "NEAR_EXACT"
                    watchlist = investment_db.list_watchlist(database_url, user_id, market="JP")
                    members = [w for w in watchlist if _matches_sector(w, r["ticker"])]
                    quotes = get_stock_quotes(members) if members else {}
                    pcts = [(quotes[w["code"]]["t"] - quotes[w["code"]]["p"]) / quotes[w["code"]]["p"] * 100
                            for w in members if quotes.get(w["code"]) and quotes[w["code"]].get("p")]
                    breadth = round(sum(1 for p in pcts if p > 0) / len(pcts), 3) if pcts else None
            else:
                snap = _fetch_raw_price_snapshot(r["target_type"], r["ticker"])
                if snap:
                    result_price = snap["price"]
                    quality = _classify_evaluation_quality(snap.get("captured_at"), now_utc, snap.get("quality_hint"))
        except Exception as e:
            print("  Market Intelligence: reaction result取得失敗", r.get("ticker"), e)
        if result_price is None or r.get("baseline_price") is None:
            investment_db.save_event_market_reaction_result(database_url, r["id"], evaluation_status="NO_DATA",
                                                               evaluation_quality="NO_DATA", notes="市場データ取得不能")
            result["no_data"] += 1
            continue
        stock_return_pct = round((result_price - float(r["baseline_price"])) / float(r["baseline_price"]) * 100, 3)
        market_relative = round(stock_return_pct - topix_pct, 3) if topix_pct is not None else None
        extended = classify_extended_move(r["reaction_window"], stock_return_pct)
        classification = classify_event_reaction(stock_return_pct, market_relative_return_pct=market_relative,
                                                   volume_ratio=volume_ratio)
        investment_db.save_event_market_reaction_result(
            database_url, r["id"], result_at=now_utc.isoformat(), result_price=result_price,
            stock_return_pct=stock_return_pct, market_relative_return_pct=market_relative, volume_ratio=volume_ratio,
            breadth=breadth, evaluation_quality=quality, evaluation_status="EVALUATED",
            reaction_classification=classification, extended_move=extended)
        result["evaluated"] += 1
        _maybe_update_event_after_reaction_safe(database_url, r["event_id"])
    return result


def _maybe_update_event_after_reaction_safe(database_url, event_id):
    """指示書12・13・35番：reaction評価が入るたびにeffectiveness_score/reaction_patternを
    再計算し、閾値を満たせばMARKET_REACTION_CONFIRMED alertを出す。"""
    try:
        reactions = investment_db.list_event_market_reactions_for_event(database_url, event_id)
        evaluated = [r for r in reactions if r.get("evaluation_status") == "EVALUATED" and r.get("relevance") == "DIRECT"
                     and r.get("target_type") == "STOCK"]
        if not evaluated:
            return
        returns_by_window = {r["reaction_window"]: r.get("stock_return_pct") for r in evaluated}
        pattern = classify_reaction_pattern(returns_by_window)
        magnitudes = [abs(r.get("stock_return_pct") or 0) for r in evaluated]
        relatives = [r.get("market_relative_return_pct") for r in evaluated if r.get("market_relative_return_pct") is not None]
        breadths = [r.get("breadth") for r in evaluated if r.get("breadth") is not None]
        effectiveness = compute_event_effectiveness_score(
            magnitude=max(magnitudes) if magnitudes else None,
            relative_strength=max((abs(x) for x in relatives), default=None) if relatives else None,
            breadth=max(breadths) if breadths else None, persistence_pattern=pattern)
        event = investment_db.get_underlying_event(database_url, event_id)
        if not event:
            return
        extended_move = any(r.get("extended_move") for r in evaluated)
        investment_db.update_underlying_event(database_url, event_id, {
            "effectiveness_score": effectiveness, "reaction_pattern": pattern, "extended_move": extended_move,
        })
        # 指示書35番：MATERIAL_UPDATE等とは別の、材料+実値確認のalert。
        thirty_m = next((r for r in evaluated if r["reaction_window"] == "30M"), None)
        if (event.get("impact_score") or 0) >= 70 and thirty_m and \
                abs(thirty_m.get("market_relative_return_pct") or 0) >= 3.0:
            investment_db.create_underlying_event_alert(database_url, event_id, "MARKET_REACTION_CONFIRMED", payload={
                "event_type": event.get("event_type"), "title": event.get("title"),
                "reaction_30m_relative_pct": thirty_m.get("market_relative_return_pct"),
            })
    except Exception as e:
        print("  Market Intelligence: reaction後のevent更新で例外（無視して続行）", e)


def _event_reaction_scheduler_loop():
    """指示書28番：既存scheduler（にこそくポーリング・social signal評価等）と競合しない
    独立処理。pending reaction（due_at到来分）だけを5分間隔で処理する。"""
    while True:
        _mark_scheduler_tick("event_reaction")
        try:
            if investment_db is not None and DATABASE_URL:
                user_id = _morning_check_scheduler_users()[0]
                result = run_due_event_market_reactions(DATABASE_URL, user_id, limit=50)
                if result["evaluated"] or result["no_data"]:
                    print(f"  [Market Intelligence] event reaction evaluated={result['evaluated']}件 no_data={result['no_data']}件")
                _mark_scheduler_success("event_reaction", processed_count=result["evaluated"] + result["no_data"])
            else:
                _mark_scheduler_success("event_reaction")
        except Exception as e:
            print("  [Market Intelligence] event reaction schedulerループで例外", e)
            _mark_scheduler_error("event_reaction", e)
        time.sleep(300)


def aggregate_event_type_performance(reactions, min_sample=5):
    """指示書14番：event_type別のsample_count・avg_30m_return・avg_close_return・
    positive_rateを集計する。sample不足のtypeも数値は出す（sample_countで呼び出し側が
    判断できるようにする、指示書34番のUI側「sample不足は表示しない」はここでは行わない）。"""
    by_type = {}
    for r in reactions:
        by_type.setdefault(r.get("event_type"), []).append(r)
    out = {}
    for et, items in by_type.items():
        thirty_m = [r["stock_return_pct"] for r in items if r.get("reaction_window") == "30M" and r.get("stock_return_pct") is not None]
        close = [r["stock_return_pct"] for r in items if r.get("reaction_window") == "CLOSE" and r.get("stock_return_pct") is not None]
        positives = [r for r in items if r.get("reaction_window") == "30M" and (r.get("stock_return_pct") or 0) > 0]
        directional = [r for r in items if r.get("reaction_window") == "30M"]
        entry = {"sample_count": len({r.get("event_id") for r in items})}
        if thirty_m:
            entry["avg_30m_return"] = round(sum(thirty_m) / len(thirty_m), 2)
        if close:
            entry["avg_close_return"] = round(sum(close) / len(close), 2)
        if directional:
            entry["positive_rate"] = round(len(positives) / len(directional), 3)
        out[et] = entry
    return out


# ---- 指示書15・16・17・19番：material magnitude・event_type別の詳細抽出（best-effort） ----

_MATERIAL_AMOUNT_TO_OKU_RE = re.compile(r"(\d+(?:\.\d+)?)\s*億円")
_MATERIAL_PCT_RE = re.compile(r"上限\s*(\d+(?:\.\d+)?)\s*%|(\d+(?:\.\d+)?)\s*%")


def extract_material_magnitude(text, event_type):
    """指示書15番：同じevent_typeでも規模を考慮する。金額（億円）か%のどちらか大きい方を
    採用する簡易ヒューリスティック（既知の制約：業種・時価総額に対する相対規模は未考慮）。"""
    if not text:
        return None
    amounts = [float(m.group(1)) for m in _MATERIAL_AMOUNT_TO_OKU_RE.finditer(text)]
    pcts = [float(m.group(1) or m.group(2)) for m in _MATERIAL_PCT_RE.finditer(text)]
    if amounts:
        return max(amounts)
    if pcts:
        return max(pcts)
    return None


_GUIDANCE_REVISION_RE = re.compile(r"(売上高|営業利益|純利益|EPS)[^\d]{0,6}(\d+(?:\.\d+)?)\s*%")


def extract_guidance_revision_details(text):
    """指示書16番：revenue/operating_profit/eps revision%を抽出する（見つかった項目だけ）。"""
    if not text:
        return {}
    label_map = {"売上高": "revenue_revision_pct", "営業利益": "operating_profit_revision_pct", "EPS": "eps_revision_pct"}
    out = {}
    for m in _GUIDANCE_REVISION_RE.finditer(text):
        key = label_map.get(m.group(1))
        if key:
            out[key] = float(m.group(2))
    return out


_BUYBACK_SHARES_PCT_RE = re.compile(r"発行済株式.{0,10}?(\d+(?:\.\d+)?)\s*%")


def extract_buyback_details(text):
    """指示書17番：buyback_amount（億円）・buyback_pct_shares（発行済株式比率%）を抽出する。
    buyback_pct_market_capは時価総額データが必要なため今回未実装（既知の制約）。"""
    if not text:
        return {}
    out = {}
    amounts = [float(m.group(1)) for m in _MATERIAL_AMOUNT_TO_OKU_RE.finditer(text)]
    if amounts:
        out["buyback_amount_oku_yen"] = max(amounts)
    m = _BUYBACK_SHARES_PCT_RE.search(text)
    if m:
        out["buyback_pct_shares"] = float(m.group(1))
    return out


_TOB_OFFER_PRICE_RE = re.compile(r"(?:TOB価格|買付価格|公開買付価格)[^\d]{0,4}(\d+(?:\.\d+)?)\s*円")


def extract_tob_details(text, pre_event_price=None):
    """指示書18番：offer_price・pre_event_price・premium_pctを保存する。pre_event_priceは
    呼び出し側（イベント検知時点の株価スナップショット）から渡す想定。"""
    if not text:
        return {}
    out = {}
    m = _TOB_OFFER_PRICE_RE.search(text)
    if m:
        offer_price = float(m.group(1))
        out["offer_price"] = offer_price
        if pre_event_price:
            out["pre_event_price"] = pre_event_price
            out["premium_pct"] = round((offer_price - pre_event_price) / pre_event_price * 100, 2)
    return out


_CAPITAL_RAISE_DILUTION_RE = re.compile(r"希薄化率?[^\d]{0,4}(\d+(?:\.\d+)?)\s*%")
_CAPITAL_RAISE_CONVERSION_PRICE_RE = re.compile(r"転換価額[^\d]{0,4}(\d+(?:\.\d+)?)\s*円")


def extract_capital_raise_details(text):
    """指示書19番：dilution_pct・issue_amount（億円）・conversion_priceを抽出する。"""
    if not text:
        return {}
    out = {}
    m = _CAPITAL_RAISE_DILUTION_RE.search(text)
    if m:
        out["dilution_pct"] = float(m.group(1))
    amounts = [float(m.group(1)) for m in _MATERIAL_AMOUNT_TO_OKU_RE.finditer(text)]
    if amounts:
        out["issue_amount_oku_yen"] = max(amounts)
    m2 = _CAPITAL_RAISE_CONVERSION_PRICE_RE.search(text)
    if m2:
        out["conversion_price"] = float(m2.group(1))
    return out


EVENT_TYPE_DETAIL_EXTRACTORS = {
    "GUIDANCE_REVISION": extract_guidance_revision_details,
    "BUYBACK": extract_buyback_details,
    "CAPITAL_RAISE": extract_capital_raise_details,
    "CB_BOND": extract_capital_raise_details,
}


def extract_event_type_details(event_type, text, pre_event_price=None):
    """指示書16・17・18・19番の統合ディスパッチ。TOB_MAだけpre_event_priceを取る特殊系。"""
    if event_type == "TOB_MA":
        return extract_tob_details(text, pre_event_price=pre_event_price)
    extractor = EVENT_TYPE_DETAIL_EXTRACTORS.get(event_type)
    return extractor(text) if extractor else {}


# ---- 指示書20・21・22番：prediction resolution tracking ----

_RESOLUTION_DATE_RE = re.compile(r"(\d{1,2})/(\d{1,2})\s*(?:に|まで)?(?:解決|resolve|締切|期限)")


def extract_resolution_date(text, posted_at):
    """指示書20番：Polymarket投稿からresolution_dateを抽出する（見つからなければNone、
    無理に推測しない——書式が定まらないことが多いため保守的に実装、既知の制約）。"""
    if not text:
        return None
    m = _RESOLUTION_DATE_RE.search(text)
    if not m:
        return None
    month, day = int(m.group(1)), int(m.group(2))
    year = posted_at.year if hasattr(posted_at, "year") else datetime.datetime.now(datetime.timezone.utc).year
    try:
        d = datetime.date(year, month, day)
    except ValueError:
        return None
    return d.isoformat()


def track_prediction_resolution(database_url, event_id, topic, probability):
    """指示書21・22番：probability_at_first_seen/peak_probability/final_probabilityを
    更新する（upsert_prediction_resolutionが単調増加のpeak管理を担当）。Brier score等の
    calibration計算はPhase8では保存中心にとどめる（指示書22番「保存中心でもよい」）。"""
    if investment_db is None or not database_url or probability is None:
        return None
    existing = None
    try:
        pending = investment_db.list_pending_prediction_resolutions(database_url, limit=200)
        existing = next((p for p in pending if p.get("event_id") == event_id), None)
    except Exception:
        pass
    fields = {"topic": topic, "peak_probability": probability / 100 if probability > 1 else probability}
    if existing is None:
        fields["probability_at_first_seen"] = probability / 100 if probability > 1 else probability
    return investment_db.upsert_prediction_resolution(database_url, event_id, fields)


def track_prediction_resolution_safe(database_url, event_id, topic, probability):
    try:
        return track_prediction_resolution(database_url, event_id, topic, probability)
    except Exception as e:
        print("  Market Intelligence: prediction resolution追跡で例外（無視して続行）", e)
        return None


# ============================================================
# Market Intelligence Phase9（2026-09-11新規）：Event Quality Calibration /
# Decision Support Bridge。Phase7の underlying_event、Phase8の event_market_reaction・
# event_type_performance・社会的合意（consensus）を組み合わせ「材料は強いか→実際に市場が
# 反応しているか→既に織り込まれていないか→今のポジションから見て入る価値があるか」を
# decision_support_state（STRONG_SUPPORT/SUPPORTIVE/NEUTRAL/CAUTION/AVOID/AVOID_CHASE）として
# 判定する補助レイヤー。既存のBUY/WAIT/SELL・entry_score（ENTRY TOP5）・thesis score・
# AUTO_RS・AUTO_SECTOR・損切り・ポジションサイジングは一切直接変更しない
# （指示書21・43番、常に「隣に並べるだけ」）。
# 「良い会社」「良い材料」「株価が動いた」「今から入って良い位置」は全て別物という原則
# （指示書45番）をコード化する——特に「材料も反応も強いが、既に伸び切っている」場合は
# AVOID_CHASEを優先する。
# ============================================================

# 指示書7番：初期重み付け。後から実データで較正できるよう1箇所に集約する
# （コード内に散在させない）。material_quality/reaction_quality/freshness/historical_edge/
# source_confidenceの重みの合計を分母に正規化し、extension_penaltyはスコアからの減点として
# 別枠で引く。
DECISION_SUPPORT_WEIGHTS = {
    "material_quality": 0.30,
    "reaction_quality": 0.30,
    "freshness": 0.15,
    "historical_edge": 0.15,
    "source_confidence": 0.10,
    "extension_penalty": 0.20,
}

# 指示書6・32番：event_type_performanceのsample_count閾値。5未満はhistorical_edgeをほぼ
# 無視、5〜9はPROVISIONAL（重み弱める）、10以上でCALIBRATED（フルスコア）。
EVENT_TYPE_HISTORICAL_MIN_SAMPLE_WEAK = 5
EVENT_TYPE_HISTORICAL_MIN_SAMPLE_FULL = 10


def compute_material_quality_score(event, event_type_performance=None):
    """指示書2番：0〜100。event_type・公式確認度（confidence_level）・source独立性
    （independent_source_count）・impact_score（既存Phase7の事前重要度）・
    material_magnitude（規模）・event_type別過去実績から算出する。event_direction（後述）
    とは完全に独立——弱気材料でも「材料としての強さ・明確さ」自体は高くなり得る
    （指示書15番、material_quality=90かつevent_direction=NEGATIVEも成立する）。"""
    if not event:
        return 0.0
    score = 0.0
    score += {"OFFICIAL_CONFIRMED": 35, "MULTI_SOURCE_CONFIRMED": 25, "SINGLE_RELIABLE_SOURCE": 15,
              "SOCIAL_ONLY": 6, "UNVERIFIED": 0}.get(event.get("confidence_level"), 0)
    independent = event.get("independent_source_count") or 0
    score += min(independent * 4, 12)
    impact = event.get("impact_score")
    if impact is not None:
        score += min(max(impact, 0), 100) * 0.25
    magnitude = event.get("material_magnitude")
    if magnitude is not None:
        score += min(abs(magnitude) * 3, 18)
    perf = (event_type_performance or {}).get(event.get("event_type"))
    if perf and (perf.get("sample_count") or 0) >= EVENT_TYPE_HISTORICAL_MIN_SAMPLE_WEAK:
        positive_rate = perf.get("positive_rate")
        if positive_rate is not None:
            score += (positive_rate - 0.5) * 20  # 実績が良いevent_typeほど加点、悪ければ減点
    return round(max(0.0, min(score, 100.0)), 1)


def compute_reaction_quality_score(returns_by_window, reaction_pattern=None, breadth=None, volume_ratio=None):
    """指示書3番：0〜100。5M/30M/1H/CLOSEの相対リターン・breadth・volume・persistenceから
    算出する。「dead-cat pop」（5M+8%→CLOSE+0.5%でFADE）はreaction_qualityを下げる
    （指示書3番の明示例）——直近windowの値を最重視しつつ、途中で崩れていないか
    （最小値がプラス圏か）とpersistenceパターンで補正する。"""
    if not returns_by_window:
        return 0.0
    order = ["5M", "30M", "1H", "CLOSE"]
    vals = [returns_by_window[w] for w in order if returns_by_window.get(w) is not None]
    if not vals:
        return 0.0
    score = min(max(vals[-1], 0) * 6, 40)
    if len(vals) >= 2:
        score += min(max(min(vals), 0) * 4, 15)
    if breadth is not None:
        score += breadth * 15
    if volume_ratio is not None and volume_ratio >= 1:
        score += min((volume_ratio - 1) * 10, 10)
    pattern_bonus = {"PERSISTENT": 20, "DELAYED": 12, "FADE": -15, "REVERSAL": -20, "NO_REACTION": -10}
    score += pattern_bonus.get(reaction_pattern, 0)
    return round(max(0.0, min(score, 100.0)), 1)


def compute_extension_score(current_price=None, event_baseline_price=None, vwap=None, ma5=None,
                              gap_pct=None, atr=None):
    """指示書4番：0〜100、高いほど過熱（＝追いかけ危険）。event baseline・VWAP・5分MA・
    gap%・ATR倍率のうち使えるものだけを組み合わせる（既知の制約：全て揃わなくても算出する
    簡易加点式）。判定材料が1つも無ければNone（0点＝過熱なし、と混同しない）。"""
    score, used = 0.0, False
    if current_price is not None and event_baseline_price:
        score += min(max((current_price - event_baseline_price) / event_baseline_price * 100, 0) * 5, 50)
        used = True
    if current_price is not None and vwap:
        score += min(max((current_price - vwap) / vwap * 100, 0) * 4, 25)
        used = True
    if current_price is not None and ma5:
        score += min(max((current_price - ma5) / ma5 * 100, 0) * 3, 15)
        used = True
    if gap_pct is not None:
        score += min(max(gap_pct, 0) * 2, 10)
        used = True
    if atr and current_price is not None and event_baseline_price:
        score += min(abs(current_price - event_baseline_price) / atr * 5, 10)
        used = True
    if not used:
        return None
    return round(min(score, 100.0), 1)


def compute_freshness_score(minutes_since_event, event_timing=None):
    """指示書5番：<15分=100,15-30分=90,30-60分=75,1-3h=55,close後=40,翌日以降=25。
    event_type別の細かい調整は今回省略（既知の制約、historical_edgeやpersistence_classで
    別途カバーする方針）。"""
    if minutes_since_event is None:
        return None
    if minutes_since_event < 15:
        return 100.0
    if minutes_since_event < 30:
        return 90.0
    if minutes_since_event < 60:
        return 75.0
    if minutes_since_event < 180:
        return 55.0
    if minutes_since_event < 1440:
        return 40.0
    return 25.0


def compute_historical_edge_score(event_type_performance_entry):
    """指示書6・32番：0〜100とquality（NO_DATA/INSUFFICIENT_SAMPLE/PROVISIONAL/CALIBRATED）を
    タプルで返す。sample_count<5はhistorical_edgeをほぼ無視（0扱い）、5〜9はPROVISIONAL
    （0.6倍に減衰）、10以上でCALIBRATED（フルスコア）。"""
    if not event_type_performance_entry:
        return 0.0, "NO_DATA"
    sample = event_type_performance_entry.get("sample_count") or 0
    positive_rate = event_type_performance_entry.get("positive_rate")
    if sample < EVENT_TYPE_HISTORICAL_MIN_SAMPLE_WEAK or positive_rate is None:
        return 0.0, "INSUFFICIENT_SAMPLE"
    raw = max(0.0, min(positive_rate, 1.0)) * 100
    if sample < EVENT_TYPE_HISTORICAL_MIN_SAMPLE_FULL:
        return round(raw * 0.6, 1), "PROVISIONAL"
    return round(raw, 1), "CALIBRATED"


def compute_source_confidence_score(confidence_level):
    """指示書7番：source confidence（既存confidence_levelの再利用）を0〜100へ写像する。"""
    return {"OFFICIAL_CONFIRMED": 100.0, "MULTI_SOURCE_CONFIRMED": 75.0, "SINGLE_RELIABLE_SOURCE": 50.0,
            "SOCIAL_ONLY": 25.0, "UNVERIFIED": 0.0}.get(confidence_level, 0.0)


def compute_decision_support_score(material_quality_score, reaction_quality_score, freshness_score,
                                     historical_edge_score, extension_score, source_confidence_score,
                                     weights=None):
    """指示書7番：material_quality 30%・reaction_quality 30%・freshness 15%・
    historical_edge 15%・source_confidence 10%を加重平均で正規化し、extensionは
    extension_penalty(20%)分をスコアから減点する。重みはDECISION_SUPPORT_WEIGHTSの1箇所に
    集約——コード内に散在させない（指示書7番の要求通り）。"""
    w = weights or DECISION_SUPPORT_WEIGHTS
    mq = material_quality_score or 0
    rq = reaction_quality_score or 0
    fr = freshness_score if freshness_score is not None else 50.0  # データ無しは中立値
    he = historical_edge_score or 0
    sc = source_confidence_score or 0
    ext = extension_score if extension_score is not None else 0.0
    positive_weight_total = (w["material_quality"] + w["reaction_quality"] + w["freshness"]
                              + w["historical_edge"] + w["source_confidence"])
    positive = (mq * w["material_quality"] + rq * w["reaction_quality"] + fr * w["freshness"]
                + he * w["historical_edge"] + sc * w["source_confidence"])
    normalized_positive = positive / positive_weight_total if positive_weight_total else 0.0
    penalty = ext * w["extension_penalty"]
    return round(max(0.0, min(normalized_positive - penalty, 100.0)), 1)


# 指示書8番：スコアだけからの素の分類。AVOID_CHASEは呼び出し側でoverrideする
# （extension_score・現在の伸び幅からdetect_avoid_chaseが判定し、成立すればスコアに
# 関わらずAVOID_CHASEに置き換える）。
DECISION_SUPPORT_STATE_THRESHOLDS = [(80, "STRONG_SUPPORT"), (65, "SUPPORTIVE"), (45, "NEUTRAL"),
                                       (30, "CAUTION"), (0, "AVOID")]


def classify_decision_support_state(score):
    """指示書8番：80-100=STRONG_SUPPORT,65-79=SUPPORTIVE,45-64=NEUTRAL,30-44=CAUTION,
    0-29=AVOID。"""
    if score is None:
        return "NEUTRAL"
    for threshold, state in DECISION_SUPPORT_STATE_THRESHOLDS:
        if score >= threshold:
            return state
    return "AVOID"


AVOID_CHASE_EXTENSION_THRESHOLD = 80.0
AVOID_CHASE_RETURN_THRESHOLD_PCT = 8.0
AVOID_CHASE_VWAP_DEVIATION_THRESHOLD_PCT = 6.0


def detect_avoid_chase(extension_score, current_return_from_event_pct=None, vwap_deviation_pct=None):
    """指示書9番：extension_score>=80かつcurrent_return>=+8%、またはVWAP乖離>=閾値。
    「売買禁止」ではなく「追いかけ注意」の補助フラグ（指示書9番の注記通り）。"""
    if extension_score is None:
        return False
    if extension_score >= AVOID_CHASE_EXTENSION_THRESHOLD and current_return_from_event_pct is not None \
            and current_return_from_event_pct >= AVOID_CHASE_RETURN_THRESHOLD_PCT:
        return True
    if vwap_deviation_pct is not None and vwap_deviation_pct >= AVOID_CHASE_VWAP_DEVIATION_THRESHOLD_PCT:
        return True
    return False


def detect_pullback_candidate(material_quality_score, reaction_quality_score, avoid_chase):
    """指示書10番：強い材料＋強い反応＋過熱（avoid_chase）の組み合わせでは「今は追わず
    押し目待ち」を明示する。avoid_chaseが立っていなければpullback_candidateも立てない
    （過熱していないのに押し目を語る必要はないため）。"""
    if not avoid_chase:
        return False
    return (material_quality_score or 0) >= 65 and (reaction_quality_score or 0) >= 60


def compute_preferred_pullback_zone(vwap=None, ma5=None, recent_breakout_price=None, event_baseline_price=None):
    """指示書11番：VWAP・5分20MA・直近ブレイク値・event baselineから候補レンジ
    （preferred_pullback_zone）を作る。未来の株価を断定しない——disclaimerを必ず含める
    （指示書11番「将来の株価を断定的に主張しない」）。"""
    candidates = [v for v in (vwap, ma5, recent_breakout_price, event_baseline_price) if v is not None]
    if not candidates:
        return None
    return {
        "low": round(min(candidates), 2), "high": round(max(candidates), 2),
        "basis": {"vwap": vwap, "ma5": ma5, "recent_breakout_price": recent_breakout_price,
                  "event_baseline_price": event_baseline_price},
        "disclaimer": "将来の株価を保証するものではなく、過去の参照ラインから見た押し目候補ゾーンの目安です。",
    }


FAILED_REACTION_MATERIAL_THRESHOLD = 70.0
FAILED_REACTION_QUALITY_THRESHOLD = 35.0


def detect_failed_reaction(material_quality_score, reaction_quality_score):
    """指示書12番：材料は強いのに株価が反応しない＝弱さとして扱う重要な警告
    （「良い材料なのに上がらない」＝弱さ）。"""
    if material_quality_score is None or reaction_quality_score is None:
        return False
    return material_quality_score >= FAILED_REACTION_MATERIAL_THRESHOLD \
        and reaction_quality_score <= FAILED_REACTION_QUALITY_THRESHOLD


SELL_THE_NEWS_GAP_THRESHOLD_PCT = 3.0


def detect_sell_the_news(gap_pct, reaction_pattern):
    """指示書13番：好材料でgap upした後にFADEした場合の候補フラグ。"""
    if gap_pct is None or reaction_pattern != "FADE":
        return False
    return gap_pct >= SELL_THE_NEWS_GAP_THRESHOLD_PCT


# 指示書14・15・16番：event_type別の既定direction（テキストに手がかりが無い場合の保守的な
# フォールバック）。material_quality_scoreとは完全に独立した軸——弱気材料でもmaterial_qualityは
# 高くなり得る（指示書15番）。
EVENT_TYPE_DEFAULT_DIRECTION = {
    "BUYBACK": "POSITIVE", "DIVIDEND": "POSITIVE", "TOB_MA": "POSITIVE", "CONTRACT": "POSITIVE",
    "PRODUCT": "POSITIVE",
    "CAPITAL_RAISE": "NEGATIVE", "CB_BOND": "NEGATIVE", "REGULATION": "NEGATIVE",
    "GUIDANCE_REVISION": "MIXED", "CORPORATE_NEWS": "MIXED",
    "EARNINGS": "NEUTRAL", "GOVERNMENT_POLICY": "NEUTRAL", "ECONOMIC_INDICATOR": "NEUTRAL",
    "CENTRAL_BANK": "NEUTRAL", "GEOPOLITICS": "NEUTRAL", "MARKET_MOVE": "NEUTRAL",
    "PREDICTION_MARKET": "NEUTRAL", "OTHER": "NEUTRAL",
}
_EVENT_DIRECTION_POSITIVE_KEYWORDS = ["上方修正", "増配", "自社株買い", "受注", "黒字転換", "最高益"]
_EVENT_DIRECTION_NEGATIVE_KEYWORDS = ["下方修正", "減配", "公募増資", "第三者割当", "行政処分",
                                        "業務改善命令", "赤字", "希薄化"]


def classify_event_direction(event_type, text=None):
    """指示書14・15・16番：material_quality_scoreとは独立にPOSITIVE/NEGATIVE/MIXED/NEUTRALと
    信頼度(0-1)を返す。material_quality_score=90でevent_direction=NEGATIVEも成立する
    （非常に明確な悪材料、指示書15番の例）。同時に複数方向のキーワードが出た場合はMIXED
    （指示書16番、上方修正＋増資の同時発表等）。"""
    has_pos = bool(text) and any(kw in text for kw in _EVENT_DIRECTION_POSITIVE_KEYWORDS)
    has_neg = bool(text) and any(kw in text for kw in _EVENT_DIRECTION_NEGATIVE_KEYWORDS)
    if has_pos and has_neg:
        return "MIXED", 0.5
    if has_pos:
        return "POSITIVE", 0.85
    if has_neg:
        return "NEGATIVE", 0.85
    default = EVENT_TYPE_DEFAULT_DIRECTION.get(event_type, "NEUTRAL")
    return default, (0.5 if default != "NEUTRAL" else 0.3)


def detect_event_conflict(event_directions):
    """指示書17番：同一ticker内で同時にPOSITIVEとNEGATIVEのeventがある場合にTrue。
    event_directionsは対象tickerの直近active event群のevent_direction文字列のリスト。
    単一材料だけで判断しない（指示書17番）。"""
    directions = {d for d in (event_directions or []) if d}
    return "POSITIVE" in directions and "NEGATIVE" in directions


# 指示書20番：単純な時間減衰ではなく材料の性質から持続期間クラスを推定する
# （大型上方修正・新中期経営計画・大型受注・政策変更は長持ちする、との指示書の例示）。
PERSISTENCE_CLASS_BY_EVENT_TYPE = {
    "GUIDANCE_REVISION": "SWING", "TOB_MA": "STRUCTURAL", "GOVERNMENT_POLICY": "STRUCTURAL",
    "CONTRACT": "SWING", "BUYBACK": "SWING", "CAPITAL_RAISE": "SWING", "CB_BOND": "SHORT_TERM",
    "DIVIDEND": "SHORT_TERM", "EARNINGS": "SHORT_TERM", "REGULATION": "SWING",
    "ECONOMIC_INDICATOR": "INTRADAY", "CENTRAL_BANK": "SWING", "GEOPOLITICS": "SWING",
    "PRODUCT": "SHORT_TERM", "CORPORATE_NEWS": "SHORT_TERM", "MARKET_MOVE": "INTRADAY",
    "PREDICTION_MARKET": "SHORT_TERM", "OTHER": "SHORT_TERM",
}
_PERSISTENCE_CLASS_ORDER = ["INTRADAY", "SHORT_TERM", "SWING", "STRUCTURAL"]
_PERSISTENCE_MAGNITUDE_UPGRADE_THRESHOLD = 20.0  # 大型修正・大型受注等は1段階格上げ


def classify_persistence_class(event_type, material_magnitude=None):
    """指示書20番：INTRADAY/SHORT_TERM/SWING/STRUCTURAL。event_type別の既定クラスに加え、
    material_magnitudeが大きい場合は1段階格上げする（大型修正ほど長持ちする、という指示書の
    例示に沿う簡易ヒューリスティック）。"""
    base = PERSISTENCE_CLASS_BY_EVENT_TYPE.get(event_type, "SHORT_TERM")
    if material_magnitude is not None and abs(material_magnitude) >= _PERSISTENCE_MAGNITUDE_UPGRADE_THRESHOLD:
        idx = min(_PERSISTENCE_CLASS_ORDER.index(base) + 1, len(_PERSISTENCE_CLASS_ORDER) - 1)
        return _PERSISTENCE_CLASS_ORDER[idx]
    return base


# 指示書19番：同日=1.0,1日=0.8,2-3日=0.6,4-7日=0.4,7日超=0.2（days_since_event<=閾値の順で判定）。
RECENCY_WEIGHT_BY_DAYS = [(0, 1.0), (1, 0.8), (3, 0.6), (7, 0.4)]
RECENCY_WEIGHT_FALLBACK = 0.2
# 指示書20番：persistence_classがSWING/STRUCTURALの材料は減衰を緩める（乗数、上限1.0）。
PERSISTENCE_RECENCY_MULTIPLIER = {"INTRADAY": 0.6, "SHORT_TERM": 1.0, "SWING": 1.4, "STRUCTURAL": 2.0}


def compute_recency_weight(days_since_event, persistence_class=None):
    """指示書19・20番：古いeventの影響を時間減衰させる。event_typeの持続性
    （persistence_class）で減衰カーブを調整する（指示書20番、SWING/STRUCTURALは減衰を緩める）。"""
    if days_since_event is None:
        return RECENCY_WEIGHT_FALLBACK
    base = RECENCY_WEIGHT_FALLBACK
    for threshold, weight in RECENCY_WEIGHT_BY_DAYS:
        if days_since_event <= threshold:
            base = weight
            break
    multiplier = PERSISTENCE_RECENCY_MULTIPLIER.get(persistence_class, 1.0)
    return round(min(base * multiplier, 1.0), 3)


def detect_contradiction_flags(material_quality_score=None, reaction_quality_score=None,
                                  price_move_pct=None, source_consensus_direction=None,
                                  price_direction=None):
    """指示書35番：GOOD_MATERIAL_BAD_REACTION・BAD_MATERIAL_STRONG_PRICE・
    SOURCE_CONSENSUS_PRICE_DIVERGENCEを検出する。単純な閾値ベース（指示書全体の方針＝
    AI不使用のルールベース、Phase5〜8と同じ思想）。"""
    flags = []
    if material_quality_score is not None and reaction_quality_score is not None:
        if material_quality_score >= 70 and reaction_quality_score <= 30:
            flags.append("GOOD_MATERIAL_BAD_REACTION")
        if material_quality_score <= 30 and price_move_pct is not None and price_move_pct >= 5:
            flags.append("BAD_MATERIAL_STRONG_PRICE")
    if source_consensus_direction and price_direction and source_consensus_direction != "NEUTRAL" \
            and price_direction != "NEUTRAL" and source_consensus_direction != price_direction:
        flags.append("SOURCE_CONSENSUS_PRICE_DIVERGENCE")
    return flags


def generate_event_decision_support(database_url, event_id, ticker, market_context=None,
                                      event_type_performance=None):
    """指示書1・27番：1event×1tickerのdecision_supportを計算しDBへ1行追加する
    （履歴として積む——UPDATEしない、指示書28・29番の遷移追跡のため）。
    market_contextは呼び出し側が用意する現在の価格文脈（current_price/vwap/ma5/gap_pct/atr/
    event_baseline_price/current_return_from_event_pct/vwap_deviation_pct/
    recent_breakout_price/volume_ratio/breadth/sector_strength_at_event/
    source_consensus_direction/market_state）。用意できないキーはNoneのまま渡してよい
    （各スコア関数がNoneに対応する）。
    指示書31番（no hindsight、REQUIRED）：available_data_atは常に「今」であり、事後の
    市場反応を遡ってこの評価を良く見せることはしない。"""
    if investment_db is None or not database_url:
        return None
    event = investment_db.get_underlying_event(database_url, event_id)
    if not event:
        return None
    market_context = market_context or {}
    event_type_performance = event_type_performance or {}
    now_utc = datetime.datetime.now(datetime.timezone.utc)

    material_quality = compute_material_quality_score(event, event_type_performance)

    reactions = investment_db.list_event_market_reactions_for_event(database_url, event_id)
    evaluated = [r for r in reactions if r.get("evaluation_status") == "EVALUATED"
                 and r.get("ticker") == ticker and r.get("target_type") == "STOCK"]
    returns_by_window = {r["reaction_window"]: r.get("stock_return_pct") for r in evaluated}
    pattern = classify_reaction_pattern(returns_by_window) if returns_by_window else None
    breadths = [r.get("breadth") for r in evaluated if r.get("breadth") is not None]
    volume_ratios = [r.get("volume_ratio") for r in evaluated if r.get("volume_ratio") is not None]
    reaction_quality = compute_reaction_quality_score(
        returns_by_window, reaction_pattern=pattern,
        breadth=(max(breadths) if breadths else market_context.get("breadth")),
        volume_ratio=(max(volume_ratios) if volume_ratios else market_context.get("volume_ratio")))

    extension = compute_extension_score(
        current_price=market_context.get("current_price"), event_baseline_price=market_context.get("event_baseline_price"),
        vwap=market_context.get("vwap"), ma5=market_context.get("ma5"), gap_pct=market_context.get("gap_pct"),
        atr=market_context.get("atr"))
    if extension is None and event.get("extended_move"):
        extension = 85.0  # 指示書26番：Phase8のEXTENDED_MOVEフラグを補完的に利用する

    market_relevant_at = None
    minutes_since_event = None
    try:
        market_relevant_at = datetime.datetime.fromisoformat(
            str(resolve_event_market_relevant_at(event)).replace("Z", "+00:00"))
        if market_relevant_at.tzinfo is None:
            market_relevant_at = market_relevant_at.replace(tzinfo=datetime.timezone.utc)
        minutes_since_event = (now_utc - market_relevant_at).total_seconds() / 60
    except Exception:
        market_relevant_at = None
    timing = classify_event_timing(market_relevant_at) if market_relevant_at else None
    freshness = compute_freshness_score(minutes_since_event, event_timing=timing)

    perf_entry = event_type_performance.get(event.get("event_type"))
    historical_edge, historical_edge_quality = compute_historical_edge_score(perf_entry)

    source_confidence = compute_source_confidence_score(event.get("confidence_level"))

    score = compute_decision_support_score(material_quality, reaction_quality, freshness,
                                             historical_edge, extension, source_confidence)
    avoid_chase = detect_avoid_chase(extension, market_context.get("current_return_from_event_pct"),
                                       market_context.get("vwap_deviation_pct"))
    state = classify_decision_support_state(score)
    if avoid_chase:
        state = "AVOID_CHASE"  # 指示書8・9番：スコアに関わらずoverride

    pullback_candidate = detect_pullback_candidate(material_quality, reaction_quality, avoid_chase)
    pullback_zone = compute_preferred_pullback_zone(
        vwap=market_context.get("vwap"), ma5=market_context.get("ma5"),
        recent_breakout_price=market_context.get("recent_breakout_price"),
        event_baseline_price=market_context.get("event_baseline_price")) if pullback_candidate else None

    failed_reaction = detect_failed_reaction(material_quality, reaction_quality)
    sell_the_news = detect_sell_the_news(market_context.get("gap_pct"), pattern)

    direction, direction_confidence = classify_event_direction(event.get("event_type"), event.get("title"))

    persistence_class = classify_persistence_class(event.get("event_type"), event.get("material_magnitude"))

    market_regime = None
    try:
        market_state = market_context.get("market_state")
        if market_state is None and "market_state" not in market_context:
            market_state = capture_market_state_snapshot()
        regimes = classify_market_regime(market_state) if market_state else []
        market_regime = ",".join(regimes) if regimes else None
    except Exception as e:
        print("  Market Intelligence: decision support market_regime取得で例外（無視して続行）", e)
        market_regime = None

    current_return = market_context.get("current_return_from_event_pct")
    price_direction = "POSITIVE" if (current_return or 0) > 0 else ("NEGATIVE" if (current_return or 0) < 0 else "NEUTRAL")
    contradiction_flags = detect_contradiction_flags(
        material_quality_score=material_quality, reaction_quality_score=reaction_quality,
        price_move_pct=current_return, source_consensus_direction=market_context.get("source_consensus_direction"),
        price_direction=price_direction if current_return is not None else None)

    reasons, warnings = [], []
    if material_quality >= 70:
        reasons.append("材料の確度・重要度が高い")
    if reaction_quality >= 60:
        reasons.append("市場が実際に反応している")
    if historical_edge_quality == "PROVISIONAL":
        reasons.append("過去実績サンプルが少なめ（参考程度）")
    if pullback_candidate:
        reasons.append("押し目待ちの候補（pullback_candidate）")
    if avoid_chase:
        warnings.append("すでに値幅が伸びており高値掴みに注意（AVOID_CHASE）")
    if failed_reaction:
        warnings.append("材料は強いが株価が反応していない（FAILED_REACTION）")
    if sell_the_news:
        warnings.append("好材料での上昇後に失速（SELL_THE_NEWS候補）")
    for flag in contradiction_flags:
        warnings.append(f"矛盾フラグ：{flag}")

    fields = {
        "event_id": event_id, "ticker": ticker, "available_data_at": now_utc.isoformat(),
        "material_quality_score": material_quality, "reaction_quality_score": reaction_quality,
        "extension_score": extension, "freshness_score": freshness, "historical_edge_score": historical_edge,
        "source_confidence_score": source_confidence, "decision_support_score": score,
        "decision_support_state": state, "event_direction": direction, "event_direction_confidence": direction_confidence,
        "persistence_class": persistence_class, "avoid_chase": avoid_chase, "pullback_candidate": pullback_candidate,
        "preferred_pullback_zone_json": pullback_zone, "failed_reaction": failed_reaction, "sell_the_news": sell_the_news,
        "event_conflict": False,  # event_conflictはticker横断判定（build_ticker_intelligence_summary）専任
        "contradiction_flags_json": contradiction_flags, "market_regime": market_regime,
        "sector_strength_at_event": market_context.get("sector_strength_at_event"),
        "reasons_json": reasons, "warnings_json": warnings,
    }
    # Market Intelligence Phase10新規（指示書12・13・29番）：state遷移を記録する。
    # 新規行を作る前の「直前の最新state」と比較し、変化があればevent_decision_transitionsへ
    # 1行残す（transition理由はヒューリスティックな推定、既知の制約）。
    try:
        previous = investment_db.get_latest_event_decision_support(database_url, event_id, ticker)
        if previous and previous.get("decision_support_state") != state:
            investment_db.create_event_decision_transition(database_url, {
                "event_id": event_id, "ticker": ticker, "from_state": previous.get("decision_support_state"),
                "to_state": state, "price": market_context.get("current_price"),
                "reason": classify_transition_reason(previous, fields),
            })
    except Exception as e:
        print("  Market Intelligence: decision support transition記録で例外（無視して続行）", e)
    return investment_db.create_event_decision_support(database_url, fields)


def generate_event_decision_support_safe(database_url, event_id, ticker, market_context=None,
                                            event_type_performance=None):
    try:
        return generate_event_decision_support(database_url, event_id, ticker, market_context, event_type_performance)
    except Exception as e:
        print("  Market Intelligence: decision support生成で例外（無視して続行）", e)
        return None


def build_ticker_intelligence_summary(database_url, ticker, lookback_days=7, _preloaded_rows=None):
    """指示書18番：{"ticker":..,"active_events":N,"net_event_direction":..,
    "best_event_support_score":..,"event_conflict":bool,"avoid_chase":bool,
    "pullback_candidate":bool}を返す。event毎の最新decision_support行（直近lookback_days）を
    集約する。
    2026-09-15追加（Market Data Phase 2、DB N+1解消）：_preloaded_rowsを渡すと
    investment_db.list_event_decision_support_for_ticker()への問い合わせを省略し、渡された
    行リスト（同関数と同じ形式・同じ集約基準で事前にバッチ取得済みのもの）をそのまま使う。
    ENTRY TOP5のバッチ経路専用のオプション引数で、省略時は従来通り動作する。"""
    empty = {"ticker": ticker, "active_events": 0, "net_event_direction": "NEUTRAL",
              "best_event_support_score": None, "event_conflict": False, "avoid_chase": False,
              "pullback_candidate": False}
    if investment_db is None or not database_url:
        return empty
    if _preloaded_rows is not None:
        rows = _preloaded_rows
    else:
        since_iso = (datetime.datetime.now(datetime.timezone.utc) - datetime.timedelta(days=lookback_days)).isoformat()
        rows = investment_db.list_event_decision_support_for_ticker(database_url, ticker, since_iso)
    if not rows:
        return empty
    directions = [r.get("event_direction") for r in rows if r.get("event_direction")]
    conflict = detect_event_conflict(directions)
    if conflict:
        net_direction = "MIXED"
    elif "POSITIVE" in directions:
        net_direction = "POSITIVE"
    elif "NEGATIVE" in directions:
        net_direction = "NEGATIVE"
    else:
        net_direction = "NEUTRAL"
    scores = [r.get("decision_support_score") for r in rows if r.get("decision_support_score") is not None]
    return {
        "ticker": ticker, "active_events": len(rows), "net_event_direction": net_direction,
        "best_event_support_score": max(scores) if scores else None, "event_conflict": conflict,
        "avoid_chase": any(r.get("avoid_chase") for r in rows),
        "pullback_candidate": any(r.get("pullback_candidate") for r in rows),
    }


def build_entry_top5_event_support_label(database_url, ticker, _preloaded_rows=None):
    """指示書21・38番：ENTRY TOP5の追加専用表示——entry_score自体は変更しない。
    "STRONG"/"NEUTRAL"/"CAUTION"/"AVOID_CHASE"のいずれか、対象event無しならNoneを返す。
    2026-09-15追加（Market Data Phase 2、DB N+1解消）：_preloaded_rowsは
    build_ticker_intelligence_summary()へそのまま引き継ぐだけ（ENTRY TOP5のバッチ経路専用）。"""
    summary = build_ticker_intelligence_summary(database_url, ticker, _preloaded_rows=_preloaded_rows)
    if not summary.get("active_events"):
        return None
    if summary.get("avoid_chase"):
        return "AVOID_CHASE"
    score = summary.get("best_event_support_score")
    if score is None:
        return "NEUTRAL"
    if score >= 65:
        return "STRONG"
    if score >= 45:
        return "NEUTRAL"
    return "CAUTION"


def build_watchlist_event_tags(database_url, ticker):
    """指示書22・37番：監視銘柄カード用の軽量タグ（EVENT+/EVENT⚠/PULLBACK）。UIを重くしない
    ため最大3種類のタグのみ。"""
    summary = build_ticker_intelligence_summary(database_url, ticker)
    if not summary.get("active_events"):
        return []
    tags = []
    if summary.get("avoid_chase"):
        tags.append("EVENT⚠")
    elif (summary.get("best_event_support_score") or 0) >= 65:
        tags.append("EVENT+")
    if summary.get("pullback_candidate"):
        tags.append("PULLBACK")
    return tags


def build_event_decision_support_payload(database_url, event_id):
    """指示書23番：ChatGPT相談payload向け。複数ticker対象の場合はdecision_support_scoreが
    最良のものを採用する。フォーマット例：{"material_quality_score":84,
    "reaction_quality_score":77,"extension_score":82,"decision_support_state":"AVOID_CHASE",
    "pullback_candidate":true,"reasons":[...]}。"""
    if investment_db is None or not database_url:
        return None
    rows = investment_db.list_event_decision_support_history(database_url, event_id, limit=1000) or []
    latest_by_ticker = {}
    for r in rows:  # historyはevaluated_at ASCなので、後に出てきた行ほど新しい
        latest_by_ticker[r.get("ticker")] = r
    if not latest_by_ticker:
        return None
    best = max(latest_by_ticker.values(), key=lambda r: r.get("decision_support_score") or 0)
    return {
        "material_quality_score": best.get("material_quality_score"),
        "reaction_quality_score": best.get("reaction_quality_score"),
        "extension_score": best.get("extension_score"),
        "decision_support_state": best.get("decision_support_state"),
        "pullback_candidate": bool(best.get("pullback_candidate")),
        "failed_reaction": bool(best.get("failed_reaction")),  # UI「重要」タブのフィルタ用（指示書39番）
        "reasons": best.get("reasons_json") or [],
    }


def build_intraday_event_decision_digest(database_url, lookback_hours=6):
    """指示書24・26番：INTRADAY_REPORT（寄り30分・前場終了・後場30分・大引け）に追加する
    「イベント支援・反応失敗・追いかけ注意・押し目候補」一覧。既存の判断は上書きしない、
    追加専用セクション。"""
    empty = {"supported": [], "failed_reaction": [], "avoid_chase": [], "pullback_candidate": []}
    if investment_db is None or not database_url:
        return empty
    since_iso = (datetime.datetime.now(datetime.timezone.utc) - datetime.timedelta(hours=lookback_hours)).isoformat()
    rows = investment_db.list_recent_event_decision_support(database_url, since_iso, limit=200)

    def _brief(r):
        return {"ticker": r.get("ticker"), "event_id": r.get("event_id"),
                "decision_support_state": r.get("decision_support_state"),
                "decision_support_score": r.get("decision_support_score")}
    return {
        "supported": [_brief(r) for r in rows if r.get("decision_support_state") in ("STRONG_SUPPORT", "SUPPORTIVE")][:10],
        "failed_reaction": [_brief(r) for r in rows if r.get("failed_reaction")][:10],
        "avoid_chase": [_brief(r) for r in rows if r.get("avoid_chase")][:10],
        "pullback_candidate": [_brief(r) for r in rows if r.get("pullback_candidate")][:10],
    }


def build_intraday_event_decision_digest_safe(database_url, lookback_hours=6):
    try:
        return build_intraday_event_decision_digest(database_url, lookback_hours)
    except Exception as e:
        print("  Market Intelligence: intraday event decision digest生成で例外（無視して続行）", e)
        return {"supported": [], "failed_reaction": [], "avoid_chase": [], "pullback_candidate": []}


def build_morning_overnight_event_digest(database_url, lookback_hours=18):
    """指示書25番：前日引け〜当日朝までのeventからovernight catalyst・event_direction・
    event_type別過去実績を要約する。ギャップアップ（GU）は買いサインではない、との注記を
    必ず含める（指示書25番「GU≠buy」）。"""
    gu_note = "ギャップアップは買いサインではありません（追いかけ注意、指示書25番）。"
    if investment_db is None or not database_url:
        return {"overnight_events": [], "note": gu_note}
    since_iso = (datetime.datetime.now(datetime.timezone.utc) - datetime.timedelta(hours=lookback_hours)).isoformat()
    events = investment_db.list_active_underlying_events(database_url, since_iso=since_iso, limit=30)
    perf_since_iso = (datetime.datetime.now(datetime.timezone.utc) - datetime.timedelta(days=90)).isoformat()
    perf = aggregate_event_type_performance(
        investment_db.list_evaluated_event_market_reactions_since(database_url, perf_since_iso))
    out = []
    for ev in events:
        timing = None
        try:
            market_relevant_at = datetime.datetime.fromisoformat(
                str(resolve_event_market_relevant_at(ev)).replace("Z", "+00:00"))
            if market_relevant_at.tzinfo is None:
                market_relevant_at = market_relevant_at.replace(tzinfo=datetime.timezone.utc)
            timing = classify_event_timing(market_relevant_at)
        except Exception:
            timing = None
        if timing not in ("OVERNIGHT", "AFTER_CLOSE", "PRE_MARKET"):
            continue
        direction, confidence = classify_event_direction(ev.get("event_type"), ev.get("title"))
        out.append({
            "event_id": ev.get("id"), "event_type": ev.get("event_type"), "title": ev.get("title"),
            "tickers": ev.get("direct_tickers_json") or [], "event_direction": direction,
            "event_direction_confidence": confidence, "historical_edge": perf.get(ev.get("event_type")),
        })
    return {"overnight_events": out, "note": gu_note}


def build_morning_overnight_event_digest_safe(database_url, lookback_hours=18):
    try:
        return build_morning_overnight_event_digest(database_url, lookback_hours)
    except Exception as e:
        print("  Market Intelligence: 朝overnight event digest生成で例外（無視して続行）", e)
        return {"overnight_events": [], "note": "ギャップアップは買いサインではありません（追いかけ注意）。"}


# ============================================================
# Market Intelligence Phase10（2026-09-11新規）：Real-Time Calibration / Decision Support
# Replay / Trade Review Integration。Phase9までのevent_decision_supportを実際の売買判断
# （ENTRY/ADD/HOLD/EXIT/STOP）の前後でsnapshot保存し、「結果」と「判断の質」を分離して
# 評価する。最重要原則（指示書44番）：「結果が良かった」と「判断が良かった」は別物——
# decision_quality・timing_quality・rule_compliance・outcomeを必ず分離する。
# 既存のBUY/WAIT/SELL・ENTRY TOP5のentry_score・AUTO_RS・AUTO_SECTOR・損切り・
# ポジションサイジングは一切直接変更しない（指示書42番）。
# ============================================================

def classify_transition_reason(previous_row, new_fields):
    """指示書13番：state遷移の理由をヒューリスティックに推定する（AI不使用のルールベース、
    他のPhaseと同じ方針）。複数該当すれば全て列挙する。"""
    reasons = []
    prev_ext = previous_row.get("extension_score")
    new_ext = new_fields.get("extension_score")
    if prev_ext is not None and new_ext is not None and prev_ext - new_ext >= 15:
        reasons.append("extension normalized")
    prev_reaction = previous_row.get("reaction_quality_score") or 0
    new_reaction = new_fields.get("reaction_quality_score") or 0
    if new_reaction - prev_reaction >= 15:
        reasons.append("reaction persisted/improved")
    prev_source = previous_row.get("source_confidence_score") or 0
    new_source = new_fields.get("source_confidence_score") or 0
    if new_source > prev_source:
        reasons.append("new official confirmation")
    prev_regime = previous_row.get("market_regime") or ""
    new_regime = new_fields.get("market_regime") or ""
    if "RISK_ON" in new_regime and "RISK_ON" not in prev_regime:
        reasons.append("market regime improved")
    if not reasons:
        reasons.append("re-evaluation")
    return "; ".join(reasons)


def capture_trade_decision_context(database_url, user_id, trade_id, ticker, action, price=None,
                                     entry_score=None, market_context=None):
    """指示書1・2・3・4・5番：売買判断（ENTRY/ADD/HOLD/EXIT/STOP）時点のdecision_support
    snapshotを保存する。immutable（一切UPDATEしない、呼ぶ度に新しい行を積む）。
    available_data_at/captured_atは常に「今」——過去に遡って良く見せない（no hindsight、
    指示書2番）。"""
    if investment_db is None or not database_url:
        return None
    market_context = market_context or {}
    summary = build_ticker_intelligence_summary(database_url, ticker)
    since_iso = (datetime.datetime.now(datetime.timezone.utc) - datetime.timedelta(days=7)).isoformat()
    rows = investment_db.list_event_decision_support_for_ticker(database_url, ticker, since_iso)
    best = max(rows, key=lambda r: r.get("decision_support_score") or 0, default=None)
    now_utc = datetime.datetime.now(datetime.timezone.utc)
    fields = {
        "trade_id": str(trade_id), "ticker": ticker, "action": action, "price": price,
        "entry_score": entry_score,
        "event_support_state": (best or {}).get("decision_support_state"),
        "material_quality_score": (best or {}).get("material_quality_score"),
        "reaction_quality_score": (best or {}).get("reaction_quality_score"),
        "extension_score": (best or {}).get("extension_score"),
        "decision_support_score": (best or {}).get("decision_support_score"),
        "pullback_candidate": summary.get("pullback_candidate", False),
        "avoid_chase": summary.get("avoid_chase", False),
        "active_event_ids_json": [r.get("event_id") for r in rows],
        "market_regime_json": market_context.get("market_regime") or [],
        "sector_strength_json": market_context.get("sector_strength") or {},
        "available_data_at": now_utc.isoformat(),
    }
    return investment_db.create_trade_decision_context(database_url, user_id, fields)


def capture_trade_decision_context_safe(database_url, user_id, trade_id, ticker, action, price=None,
                                           entry_score=None, market_context=None):
    try:
        return capture_trade_decision_context(database_url, user_id, trade_id, ticker, action, price,
                                                entry_score, market_context)
    except Exception as e:
        print("  Market Intelligence: trade decision context保存で例外（無視して続行）", e)
        return None


# 指示書7番：GOOD/BAD_DECISION × GOOD/BAD_RESULT。「勝った＝正しい判断」「負けた＝悪い判断」
# としない（指示書44番、最重要原則）。
def evaluate_decision_was_good(entry_context, rule_compliant=True):
    """判断が良かったかどうかは、ENTRY時点で見えていた情報だけで判定する（no hindsight）。
    avoid_chaseで入った・event_support_stateがCAUTION/AVOID/AVOID_CHASEだった・ルール違反が
    あった、のいずれかがあれば「悪い判断」とみなす。"""
    if not entry_context:
        return None
    if not rule_compliant:
        return False
    if entry_context.get("avoid_chase"):
        return False
    if entry_context.get("event_support_state") in ("AVOID", "AVOID_CHASE", "CAUTION"):
        return False
    return True


def classify_decision_quality(decision_was_good, outcome_was_good):
    """指示書7番：GOOD_DECISION_GOOD_RESULT/GOOD_DECISION_BAD_RESULT/
    BAD_DECISION_GOOD_RESULT/BAD_DECISION_BAD_RESULT。"""
    if decision_was_good is None or outcome_was_good is None:
        return None
    if decision_was_good and outcome_was_good:
        return "GOOD_DECISION_GOOD_RESULT"
    if decision_was_good and not outcome_was_good:
        return "GOOD_DECISION_BAD_RESULT"
    if not decision_was_good and outcome_was_good:
        return "BAD_DECISION_GOOD_RESULT"
    return "BAD_DECISION_BAD_RESULT"


def classify_entry_timing_quality(entry_context):
    """指示書8番：EARLY_GOOD/GOOD_ENTRY/LATE_ENTRY/CHASE_ENTRY。extension_scoreを軸にする
    （Phase9のextension_scoreをそのまま再利用、指示書8番の指定通り）。"""
    if not entry_context:
        return None
    if entry_context.get("avoid_chase"):
        return "CHASE_ENTRY"
    ext = entry_context.get("extension_score")
    if ext is None:
        return "GOOD_ENTRY"
    if ext <= 20:
        return "EARLY_GOOD"
    if ext <= 50:
        return "GOOD_ENTRY"
    if ext <= 80:
        return "LATE_ENTRY"
    return "CHASE_ENTRY"


def classify_exit_timing_quality(exit_context, pnl_pct=None):
    """指示書8番：PREMATURE_EXIT/GOOD_EXIT/LATE_EXIT。exit時点のevent_support_stateと
    結果損益を組み合わせる。"""
    if not exit_context:
        return None
    state = exit_context.get("event_support_state")
    if state in ("AVOID_CHASE", "AVOID") and (pnl_pct or 0) > 0:
        return "GOOD_EXIT"  # 過熱・弱気化する前に利確できた
    if state in ("STRONG_SUPPORT", "SUPPORTIVE") and (pnl_pct or 0) > 0:
        return "PREMATURE_EXIT"  # まだ支持的な状態なのに降りた（machine視点の参考情報）
    if (pnl_pct or 0) < 0:
        return "LATE_EXIT"
    return "GOOD_EXIT"


def classify_timing_quality(entry_context, exit_context=None, pnl_pct=None):
    """指示書8番：entry側のtiming（CHASE_ENTRY/LATE_ENTRY等）を優先し、entry側に問題が
    無ければexit側の判定を採用する。"""
    entry_timing = classify_entry_timing_quality(entry_context)
    if entry_timing in ("CHASE_ENTRY", "LATE_ENTRY"):
        return entry_timing
    if exit_context:
        exit_timing = classify_exit_timing_quality(exit_context, pnl_pct)
        if exit_timing:
            return exit_timing
    return entry_timing


def compute_mfe_mae_pct(entry_price, high_since_entry=None, low_since_entry=None):
    """指示書6番：max_favorable_excursion_pct・max_adverse_excursion_pct。"""
    if not entry_price:
        return None, None
    mfe = round((high_since_entry - entry_price) / entry_price * 100, 2) if high_since_entry is not None else None
    mae = round((low_since_entry - entry_price) / entry_price * 100, 2) if low_since_entry is not None else None
    return mfe, mae


EVENT_SUPPORT_ACCURACY_FALSE_POSITIVE_STATES = ("STRONG_SUPPORT", "SUPPORTIVE")
EVENT_SUPPORT_ACCURACY_FALSE_NEGATIVE_STATES = ("CAUTION", "AVOID", "AVOID_CHASE")
EVENT_SUPPORT_ACCURACY_MISSED_UPSIDE_THRESHOLD_PCT = 10.0


def classify_event_support_accuracy(entry_context, pnl_pct):
    """指示書21・22番：false positive（STRONG_SUPPORT/SUPPORTIVEだったのに下落）・
    false negative（CAUTION/AVOID/AVOID_CHASEだったのにさらに大きく上昇）を判定する。"""
    if not entry_context or pnl_pct is None:
        return None
    state = entry_context.get("event_support_state")
    if state is None:
        return None
    if state in EVENT_SUPPORT_ACCURACY_FALSE_POSITIVE_STATES and pnl_pct < 0:
        return "FALSE_POSITIVE"
    if state in EVENT_SUPPORT_ACCURACY_FALSE_NEGATIVE_STATES and pnl_pct >= EVENT_SUPPORT_ACCURACY_MISSED_UPSIDE_THRESHOLD_PCT:
        return "FALSE_NEGATIVE"
    return "ACCURATE"


def classify_rule_compliance(rule_triggered, entry_or_exit_event_support_state):
    """指示書23・24番：既存ルール（NO_OVERNIGHT・-8%強制売却等）とevent_decision_contextを
    同時に評価する。ルールが発動しevent supportが強気だった場合はRULE_OVERRIDES_EVENT
    （ルール優先が正しい挙動——ルールを軽視しない）。"""
    if rule_triggered and entry_or_exit_event_support_state in ("STRONG_SUPPORT", "SUPPORTIVE"):
        return "RULE_OVERRIDES_EVENT"
    if rule_triggered:
        return "RULE_COMPLIANT_EXIT"
    return "COMPLIANT"


WAIT_MISSED_BREAKOUT_THRESHOLD_PCT = 15.0


def classify_wait_outcome(subsequent_return_pct, pullback_then_supportive=False):
    """指示書30・31番：CORRECT_WAIT/GOOD_PULLBACK/MISSED_BREAKOUT/NO_EDGE。"""
    if pullback_then_supportive:
        return "GOOD_PULLBACK"
    if subsequent_return_pct is None:
        return "NO_EDGE"
    if subsequent_return_pct <= 0:
        return "CORRECT_WAIT"
    if subsequent_return_pct >= WAIT_MISSED_BREAKOUT_THRESHOLD_PCT:
        return "MISSED_BREAKOUT"
    return "NO_EDGE"


def compute_opportunity_cost_pct(subsequent_return_pct, wait_outcome):
    """指示書32番：MISSED_BREAKOUTのみopportunity_cost_pctを記録する（損失とは別扱い、
    daily scoreへの影響は小さくする方針——ここでは値の算出のみ行い、重み付けは呼び出し側）。"""
    if wait_outcome == "MISSED_BREAKOUT" and subsequent_return_pct is not None:
        return round(subsequent_return_pct, 2)
    return None


def compute_avoided_loss_pct(subsequent_return_pct, was_avoid_chase):
    """指示書33番：AVOID_CHASEで見送りその後急落した場合、避けた損失を記録する
    （「取らなかった利益」だけでなく「避けた損失」も評価する）。"""
    if was_avoid_chase and subsequent_return_pct is not None and subsequent_return_pct < 0:
        return round(abs(subsequent_return_pct), 2)
    return None


def evaluate_trade_outcome(database_url, user_id, trade_id, exit_price=None, high_since_entry=None,
                             low_since_entry=None, rule_triggered=False):
    """指示書6〜9・21〜24番の統合オーケストレーション。trade_decision_contextの
    ENTRY/ADD（最初）とEXIT/STOP（最後）を突き合わせ、decision_quality・timing_quality・
    rule_compliance・event_support_accuracyを算出しtrade_outcome_evaluationsへ保存する。"""
    if investment_db is None or not database_url:
        return None
    contexts = investment_db.list_trade_decision_contexts_for_trade(database_url, str(trade_id))
    if not contexts:
        return None
    entry_context = next((c for c in contexts if c.get("action") in ("ENTRY", "ADD")), contexts[0])
    exit_context = next((c for c in reversed(contexts) if c.get("action") in ("EXIT", "STOP")), None)
    entry_price = entry_context.get("price")
    resolved_exit_price = exit_price if exit_price is not None else (exit_context or {}).get("price")
    pnl_pct = None
    if entry_price and resolved_exit_price:
        pnl_pct = round((resolved_exit_price - entry_price) / entry_price * 100, 2)
    mfe, mae = compute_mfe_mae_pct(entry_price, high_since_entry, low_since_entry)
    rule_compliance = classify_rule_compliance(
        rule_triggered, (exit_context or entry_context).get("event_support_state"))
    decision_was_good = evaluate_decision_was_good(entry_context, rule_compliant=(rule_compliance != "RULE_OVERRIDES_EVENT" or not rule_triggered))
    outcome_was_good = (pnl_pct or 0) > 0 if pnl_pct is not None else None
    decision_quality = classify_decision_quality(decision_was_good, outcome_was_good)
    timing_quality = classify_timing_quality(entry_context, exit_context, pnl_pct)
    event_support_accuracy = classify_event_support_accuracy(entry_context, pnl_pct)
    fields = {
        "ticker": entry_context.get("ticker"), "entry_context_id": entry_context.get("id"),
        "exit_context_id": (exit_context or {}).get("id"), "pnl_pct": pnl_pct,
        "max_favorable_excursion_pct": mfe, "max_adverse_excursion_pct": mae,
        "decision_quality": decision_quality, "timing_quality": timing_quality,
        "rule_compliance": rule_compliance, "event_support_accuracy": event_support_accuracy,
        "review_notes_json": [],
    }
    return investment_db.upsert_trade_outcome_evaluation(database_url, user_id, str(trade_id), fields)


def evaluate_trade_outcome_safe(database_url, user_id, trade_id, exit_price=None, high_since_entry=None,
                                   low_since_entry=None, rule_triggered=False):
    try:
        return evaluate_trade_outcome(database_url, user_id, trade_id, exit_price, high_since_entry,
                                        low_since_entry, rule_triggered)
    except Exception as e:
        print("  Market Intelligence: trade outcome評価で例外（無視して続行）", e)
        return None


def get_intraday_snapshot_at(as_of_iso, price_series=None):
    """Market Intelligence Phase11新規（指示書12・13番）：as_of時点までのbarだけを使って
    price/vwap/ma5m20/atr/day_high_so_far/day_low_so_farを再構築する。price_seriesは
    呼び出し側が用意する[{"timestamp":iso,"high":..,"low":..,"close":..,"volume":..}, ...]
    （順不同可）。as_of**より後**のbarは必ず除外する——day_high_so_far/day_low_so_farに
    未来の高値・安値を混ぜないのがこの関数の唯一の責務（指示書13番）。"""
    empty = {"price": None, "vwap": None, "ma5m20": None, "atr": None,
              "day_high_so_far": None, "day_low_so_far": None, "quality": "NO_DATA"}
    if not price_series:
        return empty
    bars = sorted((b for b in price_series if b.get("timestamp") and str(b["timestamp"]) <= as_of_iso),
                  key=lambda b: b["timestamp"])
    if not bars:
        return empty
    price = bars[-1]["close"]
    total_vol = sum(b.get("volume") or 0 for b in bars)
    vwap = (sum(b["close"] * (b.get("volume") or 0) for b in bars) / total_vol) if total_vol > 0 \
        else (sum(b["close"] for b in bars) / len(bars))
    recent20 = bars[-20:]
    ma5m20 = sum(b["close"] for b in recent20) / len(recent20)
    trs = []
    for i in range(1, len(bars)):
        h, l, prev_close = bars[i]["high"], bars[i]["low"], bars[i - 1]["close"]
        trs.append(max(h - l, abs(h - prev_close), abs(l - prev_close)))
    atr = (sum(trs[-14:]) / len(trs[-14:])) if trs else None
    day_high = max(b["high"] for b in bars)
    day_low = min(b["low"] for b in bars)
    quality = "EXACT" if len(bars) >= 5 else "ESTIMATED"
    return {"price": round(price, 2), "vwap": round(vwap, 2), "ma5m20": round(ma5m20, 2),
            "atr": round(atr, 2) if atr is not None else None, "day_high_so_far": round(day_high, 2),
            "day_low_so_far": round(day_low, 2), "quality": quality}


def replay_decision_support_at(database_url, event_id, ticker, as_of_iso, event_type_performance=None,
                                  price_series=None, event_baseline_price=None):
    """指示書14・15・28番：過去のある時点(as_of)で「何が見えていたか」だけを使って
    decision_supportを再現する。as_of以降に得られたevidence・reactionは一切使わない
    （未来データ禁止、指示書14番）。Phase11新規（指示書12番）：price_series・
    event_baseline_priceが渡された場合はget_intraday_snapshot_atでextension_scoreも
    再構築する（未指定なら従来通りNone、既知の制約は維持）。"""
    empty = {"as_of": as_of_iso, "decision_support_state": None, "decision_support_score": None,
              "note": "この時点のevidence不足のため再現できません。"}
    if investment_db is None or not database_url:
        return empty
    event = investment_db.get_underlying_event(database_url, event_id)
    if not event:
        return empty
    try:
        as_of = datetime.datetime.fromisoformat(str(as_of_iso).replace("Z", "+00:00"))
        if as_of.tzinfo is None:
            as_of = as_of.replace(tzinfo=datetime.timezone.utc)
    except Exception:
        return empty
    evidence = investment_db.list_underlying_event_evidence(database_url, event_id)
    evidence_at_time = [e for e in evidence if e.get("posted_at") and str(e["posted_at"]) <= as_of_iso]
    independent_count = compute_independent_source_count(evidence_at_time) if evidence_at_time else \
        (event.get("independent_source_count") or 0)
    confidence_level = classify_event_confidence_level(event.get("primary_source_type"), independent_count) \
        if evidence_at_time else event.get("confidence_level")
    effective_event = dict(event)
    effective_event["independent_source_count"] = independent_count
    effective_event["confidence_level"] = confidence_level
    material_quality = compute_material_quality_score(effective_event, event_type_performance)

    reactions = investment_db.list_event_market_reactions_for_event(database_url, event_id)
    evaluated = [r for r in reactions if r.get("evaluation_status") == "EVALUATED" and r.get("ticker") == ticker
                 and r.get("target_type") == "STOCK" and r.get("evaluated_at") and str(r["evaluated_at"]) <= as_of_iso]
    returns_by_window = {r["reaction_window"]: r.get("stock_return_pct") for r in evaluated}
    pattern = classify_reaction_pattern(returns_by_window) if returns_by_window else None
    reaction_quality = compute_reaction_quality_score(returns_by_window, reaction_pattern=pattern) if returns_by_window else 0.0

    try:
        market_relevant_at = datetime.datetime.fromisoformat(
            str(resolve_event_market_relevant_at(event)).replace("Z", "+00:00"))
        if market_relevant_at.tzinfo is None:
            market_relevant_at = market_relevant_at.replace(tzinfo=datetime.timezone.utc)
        minutes_since_event = (as_of - market_relevant_at).total_seconds() / 60
    except Exception:
        minutes_since_event = None
    freshness = compute_freshness_score(minutes_since_event) if minutes_since_event is not None and minutes_since_event >= 0 else None

    perf_entry = (event_type_performance or {}).get(event.get("event_type"))
    historical_edge, _quality = compute_historical_edge_score(perf_entry)
    source_confidence = compute_source_confidence_score(confidence_level)

    # Phase11新規（指示書12・13番）：price_series・event_baseline_priceが与えられた場合のみ
    # extension_scoreを再構築する（未来データを含まないget_intraday_snapshot_atを経由）。
    extension = None
    intraday_snapshot = None
    if price_series and event_baseline_price:
        intraday_snapshot = get_intraday_snapshot_at(as_of_iso, price_series)
        if intraday_snapshot.get("price") is not None:
            extension = compute_extension_score(
                current_price=intraday_snapshot["price"], event_baseline_price=event_baseline_price,
                vwap=intraday_snapshot.get("vwap"), ma5=intraday_snapshot.get("ma5m20"),
                atr=intraday_snapshot.get("atr"))

    score = compute_decision_support_score(material_quality, reaction_quality, freshness, historical_edge,
                                             extension, source_confidence)
    state = classify_decision_support_state(score)
    note = "replay: as_of時点で観測可能だった情報のみ使用。" + (
        "extension_scoreはas_of時点までのintraday dataから再構築しています。"
        if extension is not None else
        "extension_scoreは過去の価格系列が渡されなかったため再現していません（既知の制約）。")
    return {
        "as_of": as_of_iso, "material_quality_score": material_quality, "reaction_quality_score": reaction_quality,
        "freshness_score": freshness, "historical_edge_score": historical_edge, "extension_score": extension,
        "decision_support_score": score, "decision_support_state": state, "note": note,
    }


def replay_decision_support_series(database_url, event_id, ticker, as_of_list, event_type_performance=None,
                                      price_series=None, event_baseline_price=None):
    """指示書14・36番：複数時点をまとめてreplayし、タイムライン表示用の配列を返す。"""
    return [replay_decision_support_at(database_url, event_id, ticker, as_of, event_type_performance,
                                          price_series=price_series, event_baseline_price=event_baseline_price)
            for as_of in (as_of_list or [])]


# ---- 指示書16〜20・25・26・37番：calibration（実データに基づく重み較正の準備） ----

CALIBRATION_MIN_SAMPLE = 30
CALIBRATION_REFERENCE_SAMPLE = 50


def _simple_pearson_corr(pairs):
    """外部統計ライブラリを使わない単純なピアソン相関係数（他のPhaseと同じ方針）。"""
    pairs = [(x, y) for x, y in pairs if x is not None and y is not None]
    n = len(pairs)
    if n < 2:
        return 0.0
    mx = sum(p[0] for p in pairs) / n
    my = sum(p[1] for p in pairs) / n
    cov = sum((p[0] - mx) * (p[1] - my) for p in pairs)
    vx = sum((p[0] - mx) ** 2 for p in pairs)
    vy = sum((p[1] - my) ** 2 for p in pairs)
    if vx <= 0 or vy <= 0:
        return 0.0
    return cov / ((vx ** 0.5) * (vy ** 0.5))


def suggest_calibrated_weights(samples, current_weights=None):
    """指示書17番：現在の重みと、実績相関に基づく緩やかな提案重みを比較する。自動適用は
    絶対に行わない（呼び出し側もこの戻り値をそのまま保存・自動反映してはならない、
    指示書17番REQUIRED）。"""
    current = current_weights or {"material_quality": DECISION_SUPPORT_WEIGHTS["material_quality"],
                                    "reaction_quality": DECISION_SUPPORT_WEIGHTS["reaction_quality"]}
    material_corr = _simple_pearson_corr([(s.get("material_quality_score"), s.get("pnl_pct")) for s in samples])
    reaction_corr = _simple_pearson_corr([(s.get("reaction_quality_score"), s.get("pnl_pct")) for s in samples])
    correlations = {"material_quality": max(material_corr, 0), "reaction_quality": max(reaction_corr, 0)}
    corr_total = sum(correlations.values()) or 1e-9
    total_weight = sum(current.values())
    suggested = {}
    for key in current:
        corr_share = correlations[key] / corr_total
        # 現在の重みと相関ベース比率の平均でなだらかに寄せる（急激な変更をしない）。
        suggested[key] = (current[key] + total_weight * corr_share) / 2
    suggested_total = sum(suggested.values()) or 1e-9
    factor = total_weight / suggested_total
    suggested = {k: round(v * factor, 3) for k, v in suggested.items()}
    return {"current": {k: round(v, 3) for k, v in current.items()}, "suggested": suggested}


def compute_decision_support_calibration(samples, current_weights=None):
    """指示書16・17・18番：sample_count<30は較正禁止（INSUFFICIENT_SAMPLE）、50以上で
    REFERENCE（参考値として十分）、30〜49はPROVISIONAL。samplesは各要素が
    material_quality_score/reaction_quality_score/decision_support_state/pnl_pctを持つdict
    のリスト（trade_outcome_evaluations×entry_contextの結合、呼び出し側で用意する）。"""
    n = len(samples)
    if n < CALIBRATION_MIN_SAMPLE:
        return {"sample_count": n, "status": "INSUFFICIENT_SAMPLE", "hit_rate_by_state": {},
                "avg_return_by_state": {}, "suggested_weights": None,
                "note": f"サンプル{n}件（{CALIBRATION_MIN_SAMPLE}件未満）のため較正は行いません。"}
    status = "REFERENCE" if n >= CALIBRATION_REFERENCE_SAMPLE else "PROVISIONAL"
    by_state = {}
    for s in samples:
        by_state.setdefault(s.get("decision_support_state"), []).append(s)
    hit_rate_by_state, avg_return_by_state = {}, {}
    for state, items in by_state.items():
        pnls = [i["pnl_pct"] for i in items if i.get("pnl_pct") is not None]
        if pnls:
            hit_rate_by_state[state] = round(sum(1 for p in pnls if p > 0) / len(pnls), 3)
            avg_return_by_state[state] = round(sum(pnls) / len(pnls), 2)
    return {
        "sample_count": n, "status": status, "hit_rate_by_state": hit_rate_by_state,
        "avg_return_by_state": avg_return_by_state,
        "suggested_weights": suggest_calibrated_weights(samples, current_weights),
        "note": "自動適用は行いません。参考値としてのみ利用してください（指示書17・18番）。",
    }


def compute_calibration_by_market_regime(samples, current_weights=None):
    """指示書19番：RISK_ON/RISK_OFF/HIGH_VOL等、regime別に較正データを分析可能にする
    （Phase5のmarket_regime文字列をそのまま再利用）。"""
    by_regime = {}
    for s in samples:
        regimes = (s.get("market_regime") or "UNKNOWN").split(",") if s.get("market_regime") else ["UNKNOWN"]
        for regime in regimes:
            by_regime.setdefault(regime or "UNKNOWN", []).append(s)
    return {regime: compute_decision_support_calibration(items, current_weights) for regime, items in by_regime.items()}


def compute_calibration_by_event_type(samples, current_weights=None):
    """指示書20番：BUYBACK/GUIDANCE_REVISION/TOB_MA/CAPITAL_RAISE等、event_type別に
    最適な判断基準が異なることを検証可能にする。"""
    by_type = {}
    for s in samples:
        by_type.setdefault(s.get("event_type"), []).append(s)
    return {et: compute_decision_support_calibration(items, current_weights) for et, items in by_type.items()}


def find_decision_support_false_positives(samples, pnl_threshold=0.0):
    """指示書21番：STRONG_SUPPORT/SUPPORTIVEだったのにその後下落したケースを抽出する。"""
    return [s for s in samples if s.get("decision_support_state") in ("STRONG_SUPPORT", "SUPPORTIVE")
            and (s.get("pnl_pct") or 0) < pnl_threshold]


def find_decision_support_false_negatives(samples, pnl_threshold=EVENT_SUPPORT_ACCURACY_MISSED_UPSIDE_THRESHOLD_PCT):
    """指示書22番：CAUTION/AVOID/AVOID_CHASEだったのにさらに大きく上昇したケースを抽出する
    （systemが慎重すぎた可能性の確認）。"""
    return [s for s in samples if s.get("decision_support_state") in ("CAUTION", "AVOID", "AVOID_CHASE")
            and (s.get("pnl_pct") or 0) >= pnl_threshold]


def build_daily_decision_review(database_url, user_id, review_date):
    """指示書25・26番：既存の日次振り返り（daily_reviews、スコア計算は無変更）へ追加する
    補助セクション。良かった判断・悪かった判断・追いかけた取引・押し目を待てた取引等を
    分類するだけで、既存score_totalの計算式には一切触れない。"""
    empty = {"good_decisions": 0, "bad_decisions": 0, "chase_entries": 0, "correct_waits": 0,
              "good_pullbacks": 0, "missed_breakouts": 0, "avoided_losses_pct_total": 0.0, "items": []}
    if investment_db is None or not database_url:
        return empty
    jst = datetime.timezone(datetime.timedelta(hours=9))
    day_start = datetime.datetime.strptime(review_date, "%Y-%m-%d").replace(tzinfo=jst)
    since_iso = day_start.astimezone(datetime.timezone.utc).isoformat()
    until_iso = (day_start + datetime.timedelta(days=1)).astimezone(datetime.timezone.utc).isoformat()
    evaluations = investment_db.list_trade_outcome_evaluations(database_url, user_id, since_iso=since_iso)
    evaluations = [e for e in evaluations if str(e.get("created_at")) < until_iso]
    out = dict(empty)
    out["items"] = []
    for e in evaluations:
        if e.get("decision_quality") in ("GOOD_DECISION_GOOD_RESULT", "GOOD_DECISION_BAD_RESULT"):
            out["good_decisions"] += 1
        elif e.get("decision_quality") in ("BAD_DECISION_GOOD_RESULT", "BAD_DECISION_BAD_RESULT"):
            out["bad_decisions"] += 1
        if e.get("timing_quality") == "CHASE_ENTRY":
            out["chase_entries"] += 1
        if e.get("wait_outcome") == "CORRECT_WAIT":
            out["correct_waits"] += 1
        if e.get("wait_outcome") == "GOOD_PULLBACK":
            out["good_pullbacks"] += 1
        if e.get("wait_outcome") == "MISSED_BREAKOUT":
            out["missed_breakouts"] += 1
        if e.get("avoided_loss_pct"):
            out["avoided_losses_pct_total"] += e["avoided_loss_pct"]
        out["items"].append({"ticker": e.get("ticker"), "trade_id": e.get("trade_id"),
                               "decision_quality": e.get("decision_quality"), "timing_quality": e.get("timing_quality"),
                               "rule_compliance": e.get("rule_compliance"), "pnl_pct": e.get("pnl_pct")})
    out["avoided_losses_pct_total"] = round(out["avoided_losses_pct_total"], 2)
    return out


def build_daily_decision_review_safe(database_url, user_id, review_date):
    try:
        return build_daily_decision_review(database_url, user_id, review_date)
    except Exception as e:
        print("  Market Intelligence: 日次decision review生成で例外（無視して続行）", e)
        return {"good_decisions": 0, "bad_decisions": 0, "chase_entries": 0, "correct_waits": 0,
                 "good_pullbacks": 0, "missed_breakouts": 0, "avoided_losses_pct_total": 0.0, "items": []}


def build_calibration_report(database_url, user_id):
    """指示書16〜20・37・40番：calibration分析のAPIレスポンス。専用テーブルは作らず、
    既存データ（trade_decision_context×trade_outcome_evaluations）から動的生成する
    （指示書16番「既存データから動的生成」で明示的に許容されている方針）。"""
    empty = {"overall": {"sample_count": 0, "status": "INSUFFICIENT_SAMPLE"}, "by_market_regime": {},
              "by_event_type": {}, "false_positives": [], "false_negatives": []}
    if investment_db is None or not database_url:
        return empty
    evaluations = investment_db.list_trade_outcome_evaluations(database_url, user_id, limit=1000)
    samples = []
    for e in evaluations:
        entry_ctx = investment_db.get_trade_decision_context(database_url, e.get("entry_context_id")) \
            if e.get("entry_context_id") else None
        if not entry_ctx:
            continue
        event_type = None
        active_ids = entry_ctx.get("active_event_ids_json") or []
        if active_ids:
            ev = investment_db.get_underlying_event(database_url, active_ids[0])
            event_type = ev.get("event_type") if ev else None
        regimes = entry_ctx.get("market_regime_json") or []
        samples.append({
            "material_quality_score": entry_ctx.get("material_quality_score"),
            "reaction_quality_score": entry_ctx.get("reaction_quality_score"),
            "decision_support_state": entry_ctx.get("event_support_state"),
            "pnl_pct": e.get("pnl_pct"), "market_regime": ",".join(regimes) if regimes else None,
            "event_type": event_type,
        })
    return {
        "overall": compute_decision_support_calibration(samples),
        "by_market_regime": compute_calibration_by_market_regime(samples),
        "by_event_type": compute_calibration_by_event_type(samples),
        "false_positives": find_decision_support_false_positives(samples),
        "false_negatives": find_decision_support_false_negatives(samples),
    }


def build_calibration_report_safe(database_url, user_id):
    try:
        return build_calibration_report(database_url, user_id)
    except Exception as e:
        print("  Market Intelligence: calibration report生成で例外（無視して続行）", e)
        return {"overall": {"sample_count": 0, "status": "INSUFFICIENT_SAMPLE"}, "by_market_regime": {},
                 "by_event_type": {}, "false_positives": [], "false_negatives": []}


def get_trade_decision_diagnostics(database_url, user_id):
    """指示書39番：decision_contexts_today・evaluated_trades・chase_entries・
    avoid_chase_successes・wait_outcomes_generated・calibration_sample_count。"""
    if investment_db is None or not database_url:
        return {"decision_contexts_today": 0, "evaluated_trades": 0, "chase_entries": 0,
                "avoid_chase_successes": 0, "wait_outcomes_generated": 0, "calibration_sample_count": 0}
    today_start_iso = datetime.datetime.now(_JST).replace(hour=0, minute=0, second=0, microsecond=0) \
        .astimezone(datetime.timezone.utc).isoformat()
    all_time_iso = "2000-01-01T00:00:00+00:00"
    evaluations = investment_db.list_trade_outcome_evaluations(database_url, user_id, since_iso=all_time_iso)
    chase_entries = sum(1 for e in evaluations if e.get("timing_quality") == "CHASE_ENTRY")
    avoid_chase_successes = sum(1 for e in evaluations if e.get("avoided_loss_pct"))
    wait_outcomes_generated = sum(1 for e in evaluations if e.get("wait_outcome"))
    return {
        "decision_contexts_today": investment_db.count_trade_decision_contexts_since(database_url, user_id, today_start_iso),
        "evaluated_trades": len(evaluations),
        "chase_entries": chase_entries,
        "avoid_chase_successes": avoid_chase_successes,
        "wait_outcomes_generated": wait_outcomes_generated,
        "calibration_sample_count": len([e for e in evaluations if e.get("pnl_pct") is not None]),
    }


# ============================================================
# Market Intelligence Phase11（2026-09-11新規）：Candidate Outcome Engine / Historical
# Replay Accuracy / Live Validation。Phase10までに作った判断が「本当に役に立ったか」を
# 測ることを優先する（指示書48番、最重要原則）——ENTRYした結果だけでなく、WAITした結果・
# AVOIDした結果・買わなかったTOP5候補まで必ず評価する。新しい売買判断ロジックは追加しない
# （指示書冒頭）。
# ============================================================

MARKET_INTELLIGENCE_VALIDATION_MODE = os.environ.get("MARKET_INTELLIGENCE_VALIDATION_MODE", "false").lower() == "true"
DECISION_SUPPORT_CONFIG_VERSION = "DS_V1"  # 指示書25番：将来重み変更後、古いデータと混ぜない


def build_candidate_dedupe_key(code, candidate_type, candidate_at_iso, candidate_state=None):
    """指示書3・4番：1日・銘柄・候補タイプ・状態ごとにdedupeする。状態が変われば
    （例：09:10 WAIT→10:05 SUPPORTIVE）別dedupe_keyとなり新規snapshotとして保存される。"""
    day = str(candidate_at_iso)[:10]
    return f"{code}:{candidate_type}:{day}:{candidate_state or 'NONE'}"


CANDIDATE_OUTCOME_SUCCESS_THRESHOLD_PCT = 2.0
CANDIDATE_OUTCOME_FAILED_THRESHOLD_PCT = -2.0
CANDIDATE_CHASE_TRAP_EXTENSION_THRESHOLD = 80.0
CANDIDATE_AVOIDED_LOSS_THRESHOLD_PCT = -5.0


def classify_candidate_outcome(candidate_type, subsequent_close_pct=None, mfe_pct=None, mae_pct=None,
                                  extension_score=None, pullback_then_supportive=False):
    """指示書5〜9番：SUCCESS/FAILED/CORRECT_WAIT/GOOD_PULLBACK/MISSED_BREAKOUT/AVOIDED_LOSS/
    CHASE_TRAP/NO_EDGE。candidate_typeごとに評価軸を切り替え、単純な終値だけで判定しない
    （MFE/MAEも考慮する、指示書6番）。"""
    if candidate_type == "WAIT":
        return classify_wait_outcome(subsequent_close_pct, pullback_then_supportive=pullback_then_supportive)
    if candidate_type == "AVOID_CHASE":
        if subsequent_close_pct is not None and subsequent_close_pct <= CANDIDATE_AVOIDED_LOSS_THRESHOLD_PCT:
            return "AVOIDED_LOSS"  # 指示書8番：追いかけなかったことで損失を避けられた
        if subsequent_close_pct is not None and subsequent_close_pct >= WAIT_MISSED_BREAKOUT_THRESHOLD_PCT:
            return "MISSED_BREAKOUT"  # 指示書8番：「判断ミス」と即断せず機会損失として記録するのみ
        return "NO_EDGE"
    # ENTRY/DAYTRADE/PULLBACKはこちらの軸で評価する。
    if extension_score is not None and extension_score >= CANDIDATE_CHASE_TRAP_EXTENSION_THRESHOLD \
            and mfe_pct is not None and mfe_pct > 0 and subsequent_close_pct is not None and subsequent_close_pct <= 0:
        return "CHASE_TRAP"  # 指示書9番：候補時点で過熱＋直後上昇→その後baseline以下
    if subsequent_close_pct is None:
        return "NO_EDGE"
    if subsequent_close_pct >= CANDIDATE_OUTCOME_SUCCESS_THRESHOLD_PCT:
        return "SUCCESS"
    if subsequent_close_pct <= CANDIDATE_OUTCOME_FAILED_THRESHOLD_PCT:
        return "FAILED"
    return "NO_EDGE"


def compute_candidate_mfe_mae(candidate_price, high_since_candidate=None, low_since_candidate=None,
                                 data_quality_hint="ESTIMATED"):
    """指示書11番：candidate時点からのhigh/lowベースでMFE/MAEを算出する（終値ベースではなく
    intraday high/lowベース）。データ粒度不足の場合はevaluation_quality=ESTIMATEDとする。"""
    mfe, mae = compute_mfe_mae_pct(candidate_price, high_since_candidate, low_since_candidate)
    quality = "EXACT" if (data_quality_hint == "EXACT" and high_since_candidate is not None
                            and low_since_candidate is not None) else "ESTIMATED"
    return mfe, mae, quality


def compute_replay_drift(actual_history, replay_series):
    """指示書15・16番：保存済みhistory（実際のstate遷移、evaluated_at昇順を想定しない）と
    replayの結果を突き合わせ、不一致をreplay_driftとして検出する。各replay時点について、
    その時点以前で最も新しい実測値と比較する（当然、as_of以降の実測値と比べない＝
    未来データでreplayを採点しない）。"""
    matches, drifts = 0, []
    for r in (replay_series or []):
        state = r.get("decision_support_state")
        as_of = r.get("as_of")
        if not state or not as_of:
            continue
        candidates = [a for a in (actual_history or []) if a.get("evaluated_at") and str(a["evaluated_at"]) <= str(as_of)]
        if not candidates:
            continue
        nearest = max(candidates, key=lambda a: a["evaluated_at"])
        if nearest.get("decision_support_state") == state:
            matches += 1
        else:
            drifts.append({"as_of": as_of, "actual": nearest.get("decision_support_state"), "replay": state})
    total = matches + len(drifts)
    return {"replay_samples": total, "replay_match_rate": round(matches / total, 3) if total else None,
             "replay_drift_count": len(drifts), "drifts": drifts}


CANDIDATE_SUCCESS_OUTCOME_STATUSES = ("SUCCESS", "CORRECT_WAIT", "GOOD_PULLBACK", "AVOIDED_LOSS")


def aggregate_candidate_performance(snapshots):
    """指示書17番：candidate_type別のcount/success_rate/avg_30m_return/avg_mfe/avg_mae。"""
    by_type = {}
    for s in snapshots or []:
        by_type.setdefault(s.get("candidate_type") or "ENTRY", []).append(s)
    out = {}
    for ct, items in by_type.items():
        n = len(items)
        entry = {"count": n}
        successes = sum(1 for i in items if i.get("outcome_status") in CANDIDATE_SUCCESS_OUTCOME_STATUSES)
        evaluated = [i for i in items if i.get("outcome_status")]
        if evaluated:
            entry["success_rate"] = round(successes / len(evaluated), 3)
        returns30 = [i["subsequent_30m_pct"] for i in items if i.get("subsequent_30m_pct") is not None]
        if returns30:
            entry["avg_30m_return"] = round(sum(returns30) / len(returns30), 2)
        mfes = [i["mfe_pct"] for i in items if i.get("mfe_pct") is not None]
        if mfes:
            entry["avg_mfe"] = round(sum(mfes) / len(mfes), 2)
        maes = [i["mae_pct"] for i in items if i.get("mae_pct") is not None]
        if maes:
            entry["avg_mae"] = round(sum(maes) / len(maes), 2)
        out[ct] = entry
    return out


def aggregate_candidate_performance_by_rank(snapshots):
    """指示書18番：ENTRY TOP5のrank別実績（entry_score自体は変更しない、集計のみ）。"""
    by_rank = {}
    for s in snapshots or []:
        if (s.get("candidate_type") or "ENTRY") != "ENTRY" or s.get("candidate_rank") is None:
            continue
        by_rank.setdefault(int(s["candidate_rank"]), []).append(s)
    out = {}
    for rank, items in by_rank.items():
        returns30 = [i["subsequent_30m_pct"] for i in items if i.get("subsequent_30m_pct") is not None]
        out[f"TOP{rank}"] = {"count": len(items),
                                "avg_30m_return": round(sum(returns30) / len(returns30), 2) if returns30 else None}
    return out


def aggregate_candidate_performance_by_event_support(snapshots):
    """指示書19番：STRONG/SUPPORTIVE/NEUTRAL/CAUTION/AVOID_CHASEごとのsubsequent return・
    MFE・MAE・win rateを集計する。"""
    by_state = {}
    for s in snapshots or []:
        by_state.setdefault(s.get("candidate_state") or s.get("event_support"), []).append(s)
    out = {}
    for state, items in by_state.items():
        if not state:
            continue
        returns = [i["subsequent_close_pct"] for i in items if i.get("subsequent_close_pct") is not None]
        mfes = [i["mfe_pct"] for i in items if i.get("mfe_pct") is not None]
        maes = [i["mae_pct"] for i in items if i.get("mae_pct") is not None]
        out[state] = {
            "count": len(items),
            "win_rate": round(sum(1 for r in returns if r > 0) / len(returns), 3) if returns else None,
            "avg_return": round(sum(returns) / len(returns), 2) if returns else None,
            "avg_mfe": round(sum(mfes) / len(mfes), 2) if mfes else None,
            "avg_mae": round(sum(maes) / len(maes), 2) if maes else None,
        }
    return out


def aggregate_candidate_performance_by_wait_reason(snapshots):
    """指示書20番：WAIT理由（EXTENDED/LOW_VOLUME/MARKET_WEAK/SECTOR_WEAK/
    ENTRY_CONDITION_NOT_MET/EVENT_UNCONFIRMED等）別に、どの理由が有効だったかを評価する。"""
    by_reason = {}
    for s in snapshots or []:
        if (s.get("candidate_type") or "") != "WAIT" or not s.get("wait_reason"):
            continue
        by_reason.setdefault(s["wait_reason"], []).append(s)
    out = {}
    for reason, items in by_reason.items():
        correct = sum(1 for i in items if i.get("outcome_status") in ("CORRECT_WAIT", "GOOD_PULLBACK"))
        evaluated = [i for i in items if i.get("outcome_status")]
        out[reason] = {"count": len(items),
                         "correct_rate": round(correct / len(evaluated), 3) if evaluated else None}
    return out


def evaluate_rule_linked_wait(subsequent_return_pct):
    """指示書21番：FOMC前・決算前等ルールに基づくWAITは「取り逃した」と即断せず、
    risk_avoided（下落した場合）とopportunity_missed（上昇した場合）を両方の枠で記録する。"""
    if subsequent_return_pct is None:
        return {"risk_avoided_pct": None, "opportunity_missed_pct": None}
    if subsequent_return_pct < 0:
        return {"risk_avoided_pct": round(abs(subsequent_return_pct), 2), "opportunity_missed_pct": None}
    return {"risk_avoided_pct": None, "opportunity_missed_pct": round(subsequent_return_pct, 2)}


def compute_data_quality_score(evaluation_quality=None, confidence_level=None, has_vwap=True,
                                  source_only_social=False):
    """指示書27番：0〜100。intraday実測＋公式ソース＋完全なbenchmarkなら高、推定値・VWAP欠損・
    social-onlyなら低。"""
    score = 50.0
    if evaluation_quality == "EXACT":
        score += 30
    elif evaluation_quality == "ESTIMATED":
        score += 10
    if confidence_level == "OFFICIAL_CONFIRMED":
        score += 20
    elif confidence_level in ("MULTI_SOURCE_CONFIRMED", "SINGLE_RELIABLE_SOURCE"):
        score += 8
    elif confidence_level == "SOCIAL_ONLY":
        score -= 20
    if not has_vwap:
        score -= 15
    if source_only_social:
        score -= 10
    return round(max(0.0, min(score, 100.0)), 1)


CALIBRATION_DATA_QUALITY_MIN = 60.0


def filter_calibration_samples_by_quality(samples, min_quality=CALIBRATION_DATA_QUALITY_MIN):
    """指示書27・28番：data_quality_score<60は重み較正の対象から除外する（参考統計には
    残してよいので、この関数はcompute_decision_support_calibrationの入力を絞る用途のみ）。
    data_quality_score未設定（None）の既存データは後方互換のため除外しない。"""
    return [s for s in (samples or [])
            if s.get("data_quality_score") is None or s.get("data_quality_score") >= min_quality]


def compute_sample_integrity(snapshots):
    """指示書29番：raw_snapshot_count（保存された全snapshot数）とindependent_candidate_count
    （同一銘柄・同一日・同一候補タイプを1件と数えた数）を分ける——同じ銘柄の同じイベントで
    5回snapshotされたものを独立5サンプルと数えない。"""
    raw = len(snapshots or [])
    independent_keys = {(s.get("code"), s.get("candidate_type"), str(s.get("candidate_at"))[:10])
                          for s in (snapshots or [])}
    return {"raw_snapshot_count": raw, "independent_candidate_count": len(independent_keys)}


def compute_candidate_coverage_rate(eligible_count, saved_count):
    """指示書30・31番：survivorship bias防止。生成された候補のうち何%が実際にsnapshot保存
    されたかを示す——低coverageなら結果を過信しない、との警告に使う指標。"""
    if not eligible_count:
        return None
    return round(min(saved_count, eligible_count) / eligible_count, 3)


def capture_entry_candidate_snapshot(database_url, user_id, code, candidate_type, price=None, entry_score=None,
                                        event_support=None, candidate_state=None, candidate_rank=None,
                                        extension_score=None, wait_reason=None, data_quality_score=None,
                                        was_taken=False):
    """指示書1・3・4・29・30番：ENTRY TOP5・WAIT・PULLBACK・AVOID_CHASE候補（買わなかった
    ものも含め原則すべて）のsnapshotを保存する。dedupe_keyにより1日・銘柄・候補タイプ・
    状態単位で重複を防ぐ。"""
    if investment_db is None or not database_url:
        return None
    now_iso = datetime.datetime.now(datetime.timezone.utc).isoformat()
    dedupe_key = build_candidate_dedupe_key(code, candidate_type, now_iso, candidate_state)
    fields = {
        "code": code, "entry_score": entry_score, "event_support": event_support,
        "price_at_candidate": price, "was_taken": was_taken, "candidate_type": candidate_type,
        "candidate_state": candidate_state, "candidate_rank": candidate_rank, "extension_score": extension_score,
        "wait_reason": wait_reason, "data_quality_score": data_quality_score, "dedupe_key": dedupe_key,
        "config_version": DECISION_SUPPORT_CONFIG_VERSION,
    }
    return investment_db.create_entry_candidate_snapshot(database_url, user_id, fields)


def capture_entry_candidate_snapshot_safe(database_url, user_id, code, candidate_type, **kwargs):
    try:
        return capture_entry_candidate_snapshot(database_url, user_id, code, candidate_type, **kwargs)
    except Exception as e:
        print("  Market Intelligence: candidate snapshot保存で例外（無視して続行）", code, e)
        return None


def run_due_candidate_outcomes(database_url, user_id, limit=50):
    """指示書10・11番：due（candidate_at<=now-30分）かつoutcome_status未確定のsnapshotのみ
    処理する独立scheduler向け関数。5分周期を想定（呼び出し側でtime.sleepする）。"""
    result = {"evaluated": 0, "no_data": 0}
    if investment_db is None or not database_url:
        return result
    now_utc = datetime.datetime.now(datetime.timezone.utc)
    cutoff = (now_utc - datetime.timedelta(minutes=30)).isoformat()
    due = investment_db.list_due_entry_candidate_snapshots_for_backfill(database_url, cutoff, limit=limit)
    for snap in due:
        try:
            candidate_price = snap.get("price_at_candidate")
            if not candidate_price:
                investment_db.save_entry_candidate_snapshot_result(
                    database_url, snap["id"], outcome_status="NO_EDGE",
                    outcome_evaluated_at=now_utc.isoformat(), evaluation_quality="NO_DATA")
                result["no_data"] += 1
                continue
            quotes = get_stock_quotes([{"code": snap["code"], "market": "JP"}])
            quote = quotes.get(snap["code"]) if quotes else None
            if not quote or quote.get("t") is None:
                result["no_data"] += 1
                continue
            current_price = quote["t"]
            candidate_at = datetime.datetime.fromisoformat(str(snap["candidate_at"]).replace("Z", "+00:00"))
            if candidate_at.tzinfo is None:
                candidate_at = candidate_at.replace(tzinfo=datetime.timezone.utc)
            elapsed_minutes = (now_utc - candidate_at).total_seconds() / 60
            subsequent_pct = round((current_price - candidate_price) / candidate_price * 100, 2)
            fields = {}
            if elapsed_minutes >= 30 and snap.get("subsequent_30m_pct") is None:
                fields["subsequent_30m_pct"] = subsequent_pct
            if elapsed_minutes >= 60 and snap.get("subsequent_1h_pct") is None:
                fields["subsequent_1h_pct"] = subsequent_pct
            timing = classify_event_timing(now_utc)
            if timing in ("AFTER_CLOSE", "OVERNIGHT", "NON_TRADING_DAY") and snap.get("subsequent_close_pct") is None:
                fields["subsequent_close_pct"] = subsequent_pct
                has_hl = quote.get("high") is not None and quote.get("low") is not None
                mfe, mae, quality = compute_candidate_mfe_mae(
                    candidate_price, quote.get("high"), quote.get("low"),
                    data_quality_hint="EXACT" if has_hl else "ESTIMATED")
                fields["mfe_pct"], fields["mae_pct"], fields["evaluation_quality"] = mfe, mae, quality
                fields["outcome_status"] = classify_candidate_outcome(
                    snap.get("candidate_type") or "ENTRY", subsequent_close_pct=subsequent_pct, mfe_pct=mfe,
                    mae_pct=mae, extension_score=snap.get("extension_score"))
                fields["outcome_evaluated_at"] = now_utc.isoformat()
                fields["data_quality_score"] = compute_data_quality_score(evaluation_quality=quality)
            if fields:
                investment_db.save_entry_candidate_snapshot_result(database_url, snap["id"], **fields)
                result["evaluated"] += 1
        except Exception as e:
            print("  Market Intelligence: candidate outcome評価で例外（無視して続行）", snap.get("code"), e)
    return result


def run_due_candidate_outcomes_safe(database_url, user_id, limit=50):
    try:
        return run_due_candidate_outcomes(database_url, user_id, limit)
    except Exception as e:
        print("  Market Intelligence: candidate outcome scheduler処理で例外（無視して続行）", e)
        return {"evaluated": 0, "no_data": 0}


def _candidate_outcome_scheduler_loop():
    """指示書10番：既存scheduler（にこそくポーリング・event reaction評価等）と競合しない
    独立処理。due（30分以上経過・未評価）のcandidateだけを5分間隔で処理する。"""
    while True:
        _mark_scheduler_tick("candidate_outcome")
        try:
            if investment_db is not None and DATABASE_URL:
                user_id = _morning_check_scheduler_users()[0]
                result = run_due_candidate_outcomes(DATABASE_URL, user_id, limit=50)
                if result["evaluated"] or result["no_data"]:
                    print(f"  [Market Intelligence] candidate outcome evaluated={result['evaluated']}件 "
                          f"no_data={result['no_data']}件")
                _mark_scheduler_success("candidate_outcome", processed_count=result["evaluated"] + result["no_data"])
            else:
                _mark_scheduler_success("candidate_outcome")
        except Exception as e:
            print("  [Market Intelligence] candidate outcome schedulerループで例外", e)
            _mark_scheduler_error("candidate_outcome", e)
        time.sleep(300)


def backfill_candidate_outcomes(database_url, user_id, limit=100, dry_run=True):
    """指示書32番：POST /api/market-intelligence/backfill-candidate-outcomes向け。dry_run=True
    なら対象件数のみ返し実際の更新は行わない（他Phaseのbackfillと同じ方針）。"""
    if investment_db is None or not database_url:
        return {"dry_run": dry_run, "target_count": 0, "result": None}
    cutoff = datetime.datetime.now(datetime.timezone.utc).isoformat()
    due = investment_db.list_due_entry_candidate_snapshots_for_backfill(database_url, cutoff, limit=limit)
    if dry_run:
        return {"dry_run": True, "target_count": len(due), "result": None}
    result = run_due_candidate_outcomes(database_url, user_id, limit=limit)
    return {"dry_run": False, "target_count": len(due), "result": result}


