TRADE_EXPERIENCE_PATTERN_TAGS = (
    "OVERSOLD_REVERSAL", "SHORT_MA_RECLAIM", "ROUND_NUMBER_RECLAIM", "VOLUME_EXPANSION",
    "AFTERNOON_MOMENTUM", "AFTERNOON_REVERSAL", "WAIT_TO_ENTRY", "MOMENTUM_STOCK",
    "FULL_EXIT_PROFIT_TAKING", "FALLING_KNIFE",
)

# 指示書17番：学習対象外（誤発注・約定事故等）はlearning_weightを下げる。ACTIVEルールを
# 直接は変更しないため、ここでは「統計に強く効かせない」ための重みだけを扱う。
TRADE_EXPERIENCE_LOW_WEIGHT_KEYWORDS = ("誤発注", "約定事故", "特殊材料直後", "ストップ高", "ストップ安",
                                          "板が極端に薄い", "システム障害", "再現性なし")


def classify_trade_result(gross_pnl):
    """WIN/LOSS/BREAKEVEN。"""
    if gross_pnl is None:
        return None
    if gross_pnl > 0:
        return "WIN"
    if gross_pnl < 0:
        return "LOSS"
    return "BREAKEVEN"


def compute_trade_gross_pnl(entry_price, exit_price, quantity, side="BUY"):
    """指示書19番：(2760-2600)*200=32000の検算対象。"""
    if entry_price is None or exit_price is None or quantity is None:
        return None
    diff = (exit_price - entry_price) if side == "BUY" else (entry_price - exit_price)
    return round(diff * quantity, 2)


def compute_trade_gross_pnl_pct(entry_price, exit_price, side="BUY"):
    """指示書19番：約6.1538%の検算対象。"""
    if not entry_price or exit_price is None:
        return None
    diff_pct = ((exit_price - entry_price) / entry_price * 100) if side == "BUY" \
        else ((entry_price - exit_price) / entry_price * 100)
    return round(diff_pct, 4)


def compute_holding_minutes(entry_time_iso, exit_time_iso):
    if not entry_time_iso or not exit_time_iso:
        return None
    try:
        et = datetime.datetime.fromisoformat(str(entry_time_iso).replace("Z", "+00:00"))
        xt = datetime.datetime.fromisoformat(str(exit_time_iso).replace("Z", "+00:00"))
        return max(0, round((xt - et).total_seconds() / 60))
    except Exception:
        return None


def classify_trade_experience_learning_weight(notes):
    """指示書17番：誤発注・約定事故等のキーワードが含まれる場合は学習重みを大きく下げる
    （0を使わないのは「参考には残す」ため、指示書のlearning_weight 0.0〜1.0のレンジ内）。"""
    if not notes:
        return 1.0
    if any(kw in notes for kw in TRADE_EXPERIENCE_LOW_WEIGHT_KEYWORDS):
        return 0.1
    return 1.0


def build_trade_experience_features(trade):
    """指示書4番：build_trade_experience_features(trade)。既存フィールドから軽量な特徴量を
    抽出するだけで、新しい市場データ取得は行わない。"""
    trade = trade or {}
    tags = set(trade.get("pattern_tags_json") or [])
    rsi_entry = trade.get("rsi_at_entry")
    entry_setup = {
        "oversold": (rsi_entry is not None and rsi_entry <= 35) or "OVERSOLD_REVERSAL" in tags,
        "rsi_recovery": "OVERSOLD_REVERSAL" in tags,
        "short_ma_reclaim": "SHORT_MA_RECLAIM" in tags,
        "round_number_reclaim": "ROUND_NUMBER_RECLAIM" in tags,
        "volume_expansion": "VOLUME_EXPANSION" in tags or (trade.get("volume_ratio") or 0) >= 1.5,
        "relative_strength_improving": (trade.get("relative_strength") or 0) > 0,
    }
    session, minutes_to_close = None, None
    entry_time = trade.get("entry_time")
    if entry_time:
        try:
            et = datetime.datetime.fromisoformat(str(entry_time).replace("Z", "+00:00")).astimezone(_JST)
            hhmm = et.hour * 60 + et.minute
            session = "MORNING" if hhmm < 11 * 60 + 30 else ("LUNCH" if hhmm < 12 * 60 + 30 else "AFTERNOON")
            minutes_to_close = max(0, (15 * 60 + 30) - hhmm)
        except Exception:
            pass
    timing = {"session": session, "minutes_to_close": minutes_to_close}
    risk = {
        "high_volatility": (trade.get("volatility_score") or 0) >= 60 or "MOMENTUM_STOCK" in tags,
        "momentum_stock": "MOMENTUM_STOCK" in tags,
        "falling_knife_entry": "FALLING_KNIFE" in tags,
    }
    execution = {
        "wait_before_entry": "WAIT_TO_ENTRY" in tags or bool(trade.get("wait_reason_json")),
        "entered_after_confirmation": bool(trade.get("pre_entry_state")) and "WAIT" not in str(trade.get("pre_entry_state") or ""),
        "full_exit": "FULL_EXIT_PROFIT_TAKING" in tags,
    }
    return {"entry_setup": entry_setup, "timing": timing, "risk": risk, "execution": execution}


def _trade_experience_similarity(current_tags, other_tags, current_features, other_features):
    """指示書5番：pattern_tags／RSI・MA回復／出来高／時間帯／地合いで類似度を計算する
    （AI不使用、タグのJaccard類似度＋特徴量一致率の加重平均という単純なルールベース）。"""
    a_tags, b_tags = set(current_tags or []), set(other_tags or [])
    tag_sim = (len(a_tags & b_tags) / len(a_tags | b_tags)) if (a_tags or b_tags) else 0.0
    feat_matches, feat_total = 0, 0
    for group in ("entry_setup", "risk", "execution"):
        ag, bg = (current_features or {}).get(group) or {}, (other_features or {}).get(group) or {}
        for k in set(ag) | set(bg):
            feat_total += 1
            if ag.get(k) == bg.get(k):
                feat_matches += 1
    feat_sim = (feat_matches / feat_total) if feat_total else 0.0
    return round(tag_sim * 0.6 + feat_sim * 0.4, 3)


TRADE_EXPERIENCE_MIN_LEARNING_WEIGHT = 0.3  # 指示書17番：低重み（誤発注等）は類似検索・統計から除外


def find_similar_trade_experiences(database_url, user_id, symbol=None, current_tags=None,
                                      current_features=None, limit=20, min_similarity=0.3,
                                      _preloaded_experiences=None):
    """指示書5番：単純な銘柄一致だけでなく、pattern_tags/RSI/MA回復/出来高/時間帯/地合いで
    類似度を計算する。symbol一致は類似度1.0として最優先で拾う（指示書「find_similar_trade_
    experiences(symbol=...)」の呼び出し例に対応）。
    2026-09-15追加（Market Data Phase 2、DB N+1解消）：_preloaded_experiencesを渡すと
    investment_db.list_trade_experiences()への問い合わせを省略し、渡されたリストをそのまま
    走査対象にする（experiences自体はsymbolに依存しないクエリのため、同一user_idなら1回の
    取得を全銘柄で使い回せる）。ENTRY TOP5のバッチ経路専用のオプション引数で、省略時は
    従来通り動作する。"""
    empty = {"similar_count": 0, "wins": 0, "losses": 0, "win_rate": None, "avg_return_pct": None,
              "median_return_pct": None, "avg_mfe_pct": None, "avg_mae_pct": None, "max_similarity": 0.0,
              "recent_10_win_rate": None, "examples": []}
    if investment_db is None or not database_url:
        return empty
    all_exps = _preloaded_experiences if _preloaded_experiences is not None else investment_db.list_trade_experiences(database_url, user_id, limit=1000)
    scored = []
    for t in all_exps:
        if (t.get("learning_weight") if t.get("learning_weight") is not None else 1.0) < TRADE_EXPERIENCE_MIN_LEARNING_WEIGHT:
            continue
        sim = 1.0 if (symbol and t.get("symbol") == symbol) else 0.0
        if current_tags is not None or current_features is not None:
            t_feat = build_trade_experience_features(t)
            sim = max(sim, _trade_experience_similarity(current_tags, t.get("pattern_tags_json"), current_features, t_feat))
        if sim >= min_similarity:
            scored.append((sim, t))
    scored.sort(key=lambda x: -x[0])
    top = scored[:limit]
    if not top:
        return empty
    wins = sum(1 for _, t in top if t.get("result_class") == "WIN")
    losses = sum(1 for _, t in top if t.get("result_class") == "LOSS")
    returns = [t["gross_pnl_pct"] for _, t in top if t.get("gross_pnl_pct") is not None]
    mfes = [t["max_favorable_excursion_pct"] for _, t in top if t.get("max_favorable_excursion_pct") is not None]
    maes = [t["max_adverse_excursion_pct"] for _, t in top if t.get("max_adverse_excursion_pct") is not None]
    n = len(top)
    recent10 = sorted(top, key=lambda x: x[1].get("trade_date") or "", reverse=True)[:10]
    recent10_wins = sum(1 for _, t in recent10 if t.get("result_class") == "WIN")
    return {
        "similar_count": n, "wins": wins, "losses": losses,
        "win_rate": round(wins / n, 3) if n else None,
        "avg_return_pct": round(sum(returns) / len(returns), 2) if returns else None,
        "median_return_pct": round(sorted(returns)[len(returns) // 2], 2) if returns else None,
        "avg_mfe_pct": round(sum(mfes) / len(mfes), 2) if mfes else None,
        "avg_mae_pct": round(sum(maes) / len(maes), 2) if maes else None,
        "max_similarity": top[0][0], "recent_10_win_rate": round(recent10_wins / len(recent10), 3) if recent10 else None,
        "examples": [t for _, t in top[:5]],
    }


def classify_pattern_confidence(sample_count):
    """指示書6番：LOW(<5)/MEDIUM(5〜14)/HIGH(15+)。サンプル数が少ない段階では強い根拠として
    扱わない、との指示に対応するラベル。"""
    if sample_count < 5:
        return "LOW"
    if sample_count <= 14:
        return "MEDIUM"
    return "HIGH"


def compute_pattern_statistics(experiences):
    """指示書6番：pattern_statistics。パターンごとのsample_count/win_rate/avg_pnl_pct/
    median_pnl_pct/avg_mfe/avg_mae/avg_holding_minutes/latest_10_win_rate/confidence_levelを
    集計する。"""
    by_pattern = {}
    for t in experiences or []:
        if (t.get("learning_weight") if t.get("learning_weight") is not None else 1.0) < TRADE_EXPERIENCE_MIN_LEARNING_WEIGHT:
            continue
        for tag in (t.get("pattern_tags_json") or []):
            by_pattern.setdefault(tag, []).append(t)
    out = {}
    for tag, items in by_pattern.items():
        n = len(items)
        wins = sum(1 for t in items if t.get("result_class") == "WIN")
        losses = sum(1 for t in items if t.get("result_class") == "LOSS")
        pnls = [t["gross_pnl_pct"] for t in items if t.get("gross_pnl_pct") is not None]
        mfes = [t["max_favorable_excursion_pct"] for t in items if t.get("max_favorable_excursion_pct") is not None]
        maes = [t["max_adverse_excursion_pct"] for t in items if t.get("max_adverse_excursion_pct") is not None]
        holds = [t["holding_minutes"] for t in items if t.get("holding_minutes") is not None]
        recent10 = sorted(items, key=lambda t: t.get("trade_date") or "", reverse=True)[:10]
        recent10_wins = sum(1 for t in recent10 if t.get("result_class") == "WIN")
        out[tag] = {
            "sample_count": n, "win_count": wins, "loss_count": losses,
            "win_rate": round(wins / n, 3) if n else None,
            "avg_pnl_pct": round(sum(pnls) / len(pnls), 2) if pnls else None,
            "median_pnl_pct": round(sorted(pnls)[len(pnls) // 2], 2) if pnls else None,
            "avg_mfe": round(sum(mfes) / len(mfes), 2) if mfes else None,
            "avg_mae": round(sum(maes) / len(maes), 2) if maes else None,
            "avg_holding_minutes": round(sum(holds) / len(holds), 1) if holds else None,
            "latest_10_win_rate": round(recent10_wins / len(recent10), 3) if recent10 else None,
            "confidence_level": classify_pattern_confidence(n),
        }
    return out


def compute_experience_score(similar_result):
    """指示書7番：EXPERIENCE_SCORE 0〜10点。sample_count<5なら最大+2まで（過大評価防止）。
    既存のENTRY_SCORE本体には一切加点しない、完全に別枠の補助スコア。"""
    if not similar_result:
        return 0.0
    n = similar_result.get("similar_count") or 0
    win_rate = similar_result.get("win_rate") or 0
    avg_return = similar_result.get("avg_return_pct")
    max_sim = similar_result.get("max_similarity") or 0
    recent10_win_rate = similar_result.get("recent_10_win_rate")
    examples = similar_result.get("examples") or []
    score = 0.0
    if n >= 10 and win_rate >= 0.70:
        score += 3
    if avg_return is not None and avg_return >= 2.0:
        score += 2
    if any("WAIT_TO_ENTRY" in (e.get("pattern_tags_json") or []) and e.get("result_class") == "WIN" for e in examples):
        score += 2
    if max_sim >= 0.80:
        score += 2
    if recent10_win_rate is not None and recent10_win_rate >= win_rate:
        score += 1
    cap = 2.0 if n < 5 else 10.0
    return round(min(score, cap), 1)


def evaluate_trade_experience(trade):
    """指示書15番：entry_timing(0-25)/risk_control(0-20)/exit_execution(0-20)/
    rule_compliance(0-20)/repeatability(0-15)＝合計100点。恣意的な固定点数を付けず、
    採点根拠（score_breakdown）をそのまま返す＝呼び出し側がJSON保存できる。"""
    trade = trade or {}
    tags = set(trade.get("pattern_tags_json") or [])
    breakdown = {}

    entry_timing = 0
    if "WAIT_TO_ENTRY" in tags:
        entry_timing += 10  # 飛びつかず確認待ちができた
    if "SHORT_MA_RECLAIM" in tags or "ROUND_NUMBER_RECLAIM" in tags:
        entry_timing += 8  # 節目・短期MA奪回を確認してからENTRY
    if "OVERSOLD_REVERSAL" in tags:
        entry_timing += 7  # 売られすぎからの反転を確認
    breakdown["entry_timing_score"] = min(entry_timing, 25)

    risk_control = 10
    mae = trade.get("max_adverse_excursion_pct")
    if mae is not None:
        risk_control += 10 if mae > -3 else (5 if mae > -6 else 0)
    breakdown["risk_control_score"] = min(risk_control, 20)

    exit_execution = 0
    if "FULL_EXIT_PROFIT_TAKING" in tags:
        exit_execution += 10
    if trade.get("result_class") == "WIN":
        exit_execution += 10
    breakdown["exit_execution_score"] = min(exit_execution, 20)

    rc = trade.get("rule_compliance_score")
    breakdown["rule_compliance_score"] = min(20, round(rc / 5)) if rc is not None else 14

    repeatability = 8
    if len(tags) >= 4:
        repeatability += 4
    if "MOMENTUM_STOCK" in tags:
        repeatability += 3
    breakdown["repeatability_score"] = min(repeatability, 15)

    total = sum(breakdown.values())
    breakdown["total"] = total
    return total, breakdown


# ============================================================
# トレード学習・損切り分析強化（2026-09-15新規）。既存trade_experiencesのスキーマ・
# sync_trade_experiences_for_date()の枠組みは一切変更せず、当日約定の生の5分足
# （_fetch_intraday_bars、既存のポジション画面チャートと同じ取得関数を再利用）から
# エントリー/エグジット時点の市場コンテキストを再構築し、損切り理由14タグの自動分類を追加する
# だけの拡張。指示書7番「不明な情報を推測で埋めない。取得できない項目はunknownとする」に
# 厳密に従い、算出できない項目はNoneのまま返す（ダミー値・平均値での穴埋めはしない）。
# ============================================================

LOSS_REASON_TAGS = (
    "CHASE_ENTRY", "LATE_ENTRY", "FALSE_BREAKOUT", "VWAP_LOSS", "VOLUME_FADE",
    "SECTOR_WEAKNESS", "MARKET_REVERSAL", "ENTRY_BEFORE_CONFIRMATION", "POOR_RISK_REWARD",
    "EVENT_RISK", "RULE_VIOLATION", "STOP_TOO_TIGHT", "THESIS_WRONG", "GOOD_ENTRY_BAD_OUTCOME",
)


def reconstruct_trade_market_context(code, market, trade_date, entry_time_iso, exit_time_iso):
    """指示書1・7番：損切りトレードを「エントリー判断教材」として保存するための市場コンテキスト
    再構築。当日5分足からエントリー/エグジット時点のVWAP位置・当日高安位置・出来高推移・
    RSI/MA・MFE/MAE・エグジット後の値動きを算出する。未来データを混ぜない
    （エントリー時点の指標はエントリーバーまでのデータだけで計算＝後知恵禁止）。
    取得失敗・データ不足時は該当フィールドをNoneのまま返す（指示書7番、推測しない）。"""
    empty = {
        "vwap_at_entry": None, "above_vwap_at_entry": None, "vwap_at_exit": None,
        "day_open": None, "day_high_so_far_at_entry": None, "day_low_so_far_at_entry": None,
        "day_high": None, "day_low": None,
        "distance_from_low_pct": None, "distance_from_high_pct": None,
        "rsi_at_entry": None, "rsi_at_exit": None,
        "short_ma": None, "mid_ma": None, "long_ma": None,
        "volume_ratio": None, "volume_trend_after_entry": None,
        "trend_5m_before_entry": None, "entry_setup_type": None,
        "broke_prior_high_then_failed": None,
        "max_favorable_excursion_pct": None, "max_adverse_excursion_pct": None,
        "post_exit_max_price": None, "post_exit_min_price": None, "post_exit_direction": None,
        "data_quality": "NO_DATA",
    }
    if yf is None or not code:
        return empty
    symbol = f"{code}.T" if (market or "JP") == "JP" else code
    try:
        bars = _fetch_intraday_bars(symbol, interval="5m", period="5d")
    except Exception as e:
        print("  トレード学習：5分足再構築失敗", code, e)
        return empty
    if not bars:
        return empty
    try:
        day_bars = [b for b in bars if datetime.datetime.fromtimestamp(b["time"], tz=datetime.timezone.utc)
                    .astimezone(_JST).strftime("%Y-%m-%d") == str(trade_date)]
    except Exception:
        day_bars = []
    if len(day_bars) < 2:
        return empty

    def _parse(iso):
        if not iso:
            return None
        try:
            return datetime.datetime.fromisoformat(str(iso).replace("Z", "+00:00"))
        except Exception:
            return None

    entry_dt, exit_dt = _parse(entry_time_iso), _parse(exit_time_iso)
    entry_idx = 0
    if entry_dt:
        for i, b in enumerate(day_bars):
            if b["time"] <= entry_dt.timestamp():
                entry_idx = i
            else:
                break
    exit_idx = len(day_bars) - 1
    if exit_dt:
        for i, b in enumerate(day_bars):
            if b["time"] <= exit_dt.timestamp():
                exit_idx = i
    exit_idx = max(exit_idx, entry_idx)

    pre_entry = day_bars[:entry_idx + 1]
    closes_pre, vols_pre = [b["close"] for b in pre_entry], [b["volume"] for b in pre_entry]
    vwap_entry = _vwap(closes_pre, vols_pre)
    up_to_exit = day_bars[:exit_idx + 1]
    vwap_exit = _vwap([b["close"] for b in up_to_exit], [b["volume"] for b in up_to_exit])

    day_open = day_bars[0]["open"]
    day_high_so_far = max(b["high"] for b in pre_entry)
    day_low_so_far = min(b["low"] for b in pre_entry)
    entry_price = day_bars[entry_idx]["close"]

    result = dict(empty)
    result["data_quality"] = "RECONSTRUCTED_5M"
    result["day_open"] = round(day_open, 2)
    result["day_high_so_far_at_entry"] = round(day_high_so_far, 2)
    result["day_low_so_far_at_entry"] = round(day_low_so_far, 2)
    result["day_high"] = round(max(b["high"] for b in day_bars), 2)
    result["day_low"] = round(min(b["low"] for b in day_bars), 2)
    if vwap_entry is not None:
        result["vwap_at_entry"] = round(vwap_entry, 2)
        result["above_vwap_at_entry"] = entry_price >= vwap_entry
    if vwap_exit is not None:
        result["vwap_at_exit"] = round(vwap_exit, 2)
    if day_low_so_far:
        result["distance_from_low_pct"] = round((entry_price - day_low_so_far) / day_low_so_far * 100, 2)
    if day_high_so_far:
        result["distance_from_high_pct"] = round((entry_price - day_high_so_far) / day_high_so_far * 100, 2)
    # 既存の_rsi()/_sma()（日足RSI・MA判定と同じ実装、行2242・2260）をそのまま再利用——
    # 過去日5分足専用の別実装は作らない。
    result["rsi_at_entry"] = _rsi(closes_pre) if len(closes_pre) >= 15 else None
    result["rsi_at_exit"] = _rsi([b["close"] for b in up_to_exit]) if len(up_to_exit) >= 15 else None
    sma5, sma15, sma25 = _sma(closes_pre, 5), _sma(closes_pre, 15), _sma(closes_pre, 25)
    result["short_ma"] = round(sma5, 2) if sma5 is not None else None
    result["mid_ma"] = round(sma15, 2) if sma15 is not None else None
    result["long_ma"] = round(sma25, 2) if sma25 is not None else None
    if len(pre_entry) >= 6:
        recent3, prior3 = vols_pre[-3:], vols_pre[-6:-3]
        avg_recent = sum(recent3) / 3
        avg_prior = (sum(prior3) / 3) if prior3 else None
        if avg_prior:
            result["volume_ratio"] = round(avg_recent / avg_prior, 2)
    post_entry_bars = day_bars[entry_idx:exit_idx + 1]
    if len(post_entry_bars) >= 4:
        half = len(post_entry_bars) // 2
        first_half_vol = sum(b["volume"] for b in post_entry_bars[:half]) or 0
        second_half_vol = sum(b["volume"] for b in post_entry_bars[half:]) or 0
        if first_half_vol:
            result["volume_trend_after_entry"] = ("FADING" if second_half_vol < first_half_vol * 0.7
                                                    else ("RISING" if second_half_vol > first_half_vol * 1.3 else "FLAT"))
    if len(closes_pre) >= 4:
        last4 = closes_pre[-4:]
        result["trend_5m_before_entry"] = "UP" if last4[-1] > last4[0] else ("DOWN" if last4[-1] < last4[0] else "FLAT")

    # エントリー形態の3分類（指示書1番「上昇直後の飛び乗りか、押し目か、ブレイクか」）。
    broke_prior_high = entry_idx > 0 and entry_price >= day_high_so_far * 0.999
    if broke_prior_high:
        result["entry_setup_type"] = "BREAKOUT"
    elif result["distance_from_low_pct"] is not None and result["distance_from_low_pct"] <= 2.0 \
            and result.get("trend_5m_before_entry") != "DOWN":
        result["entry_setup_type"] = "PULLBACK"
    elif result.get("trend_5m_before_entry") == "UP" and (result["distance_from_low_pct"] or 0) >= 5.0:
        result["entry_setup_type"] = "CHASE"
    else:
        result["entry_setup_type"] = "OTHER"

    if broke_prior_high:
        post_min = min(b["low"] for b in day_bars[entry_idx:exit_idx + 1])
        result["broke_prior_high_then_failed"] = post_min < day_high_so_far

    window = day_bars[entry_idx:exit_idx + 1]
    if window:
        mfe, mae = compute_mfe_mae_pct(entry_price, max(b["high"] for b in window), min(b["low"] for b in window))
        result["max_favorable_excursion_pct"] = mfe
        result["max_adverse_excursion_pct"] = mae

    # エグジット後の値動き（同日のみ。翌日以降は未収集、既知の制約——推測しない）。
    post_exit = day_bars[exit_idx + 1:]
    if post_exit:
        post_max = round(max(b["high"] for b in post_exit), 2)
        post_min = round(min(b["low"] for b in post_exit), 2)
        result["post_exit_max_price"] = post_max
        result["post_exit_min_price"] = post_min
        exit_price_bar = day_bars[exit_idx]["close"]
        if post_min < exit_price_bar * 0.998:
            result["post_exit_direction"] = "FURTHER_DOWN"
        elif post_max > exit_price_bar * 1.002:
            result["post_exit_direction"] = "RECOVERED"
        else:
            result["post_exit_direction"] = "FLAT"
    return result


def classify_loss_reasons(gross_pnl_pct, ctx, exit_price=None, sector_state_at_entry=None,
                           market_mode_at_entry=None, market_mode_at_exit=None,
                           event_risk_at_entry=None, rule_compliance_score=None):
    """指示書2番：損切りトレードに複数タグを付与する。「結果論だけで悪いエントリーと判定
    しない」（指示書2番の重要事項）に従い、判定材料が無いタグは付けない（POOR_RISK_REWARD・
    THESIS_WRONGは、想定リスクリワードや投資仮説を記録する仕組みが現状無いため、常に
    自動判定しない——憶測でタグ付けしない）。GOOD_ENTRY_BAD_OUTCOMEは他のネガティブタグと
    排他にせず、悪材料タグが実質無い場合にのみ独立して付与する（「正しいエントリーだったが
    偶然損切りになったケース」を分離するため）。"""
    tags = []
    ctx = ctx or {}
    rsi_entry = ctx.get("rsi_at_entry")
    if ctx.get("entry_setup_type") == "CHASE" or (rsi_entry is not None and rsi_entry >= 70):
        tags.append("CHASE_ENTRY")  # 当日値幅での急伸追随、またはRSI70以上の過熱局面での飛び乗り
    if ctx.get("entry_setup_type") == "OTHER" and ctx.get("trend_5m_before_entry") == "UP" \
            and ctx.get("distance_from_high_pct") is not None and ctx["distance_from_high_pct"] < -3:
        tags.append("LATE_ENTRY")
    if ctx.get("broke_prior_high_then_failed"):
        tags.append("FALSE_BREAKOUT")
    if ctx.get("vwap_at_exit") is not None and exit_price is not None and ctx.get("above_vwap_at_entry") \
            and exit_price < ctx["vwap_at_exit"]:
        tags.append("VWAP_LOSS")
    if ctx.get("volume_trend_after_entry") == "FADING":
        tags.append("VOLUME_FADE")
    if sector_state_at_entry in ("WEAKENING", "LAGGING", "RISK_OFF"):
        tags.append("SECTOR_WEAKNESS")
    if market_mode_at_entry and market_mode_at_exit and market_mode_at_entry != market_mode_at_exit \
            and "RISK_OFF" in str(market_mode_at_exit).upper():
        tags.append("MARKET_REVERSAL")
    # 下落継続中（反転未確認）に飛び込んだ場合。押し目待ち・反転確認を待たずに入ったケース
    # （RSI売られすぎでの「まだ下げ止まっていない」逆張りエントリーを含む）。
    if ctx.get("trend_5m_before_entry") == "DOWN" and not ctx.get("above_vwap_at_entry"):
        tags.append("ENTRY_BEFORE_CONFIRMATION")
    elif ctx.get("entry_setup_type") in ("CHASE", "OTHER") and ctx.get("trend_5m_before_entry") == "UP":
        tags.append("ENTRY_BEFORE_CONFIRMATION")
    mae = ctx.get("max_adverse_excursion_pct")
    if mae is not None and gross_pnl_pct is not None and abs(mae) < 2.0 and gross_pnl_pct <= mae + 0.3:
        tags.append("STOP_TOO_TIGHT")
    if event_risk_at_entry and str(event_risk_at_entry).upper() not in ("", "NONE", "LOW"):
        tags.append("EVENT_RISK")
    if rule_compliance_score is not None and rule_compliance_score < 60:
        tags.append("RULE_VIOLATION")
    negative_tags = [t for t in tags if t != "RULE_VIOLATION"]
    good_entry_bad_outcome = (
        ctx.get("entry_setup_type") in ("PULLBACK", "BREAKOUT")
        and not negative_tags
        and (rule_compliance_score is None or rule_compliance_score >= 80)
    )
    if good_entry_bad_outcome:
        tags.append("GOOD_ENTRY_BAD_OUTCOME")
    return tags


def classify_entry_avoidability(loss_tags, data_quality):
    """指示書6番：AVOIDABLE/PARTIALLY_AVOIDABLE/NOT_AVOIDABLE/UNKNOWNの4段階。
    「負けたから悪いENTRY」を禁止する（指示書7番）——判定材料はclassify_loss_reasons()が
    既に算出した客観的な市場シグナルのタグ数のみで、損益の符号は一切見ない。
    データ不足（reconstruct_trade_market_context()がNO_DATAを返した場合）は無理に判定しない。"""
    if not data_quality or data_quality == "NO_DATA":
        return "UNKNOWN"
    if "GOOD_ENTRY_BAD_OUTCOME" in (loss_tags or []):
        return "NOT_AVOIDABLE"
    warning_tags = [t for t in (loss_tags or []) if t != "GOOD_ENTRY_BAD_OUTCOME"]
    if len(warning_tags) >= 2:
        return "AVOIDABLE"
    if len(warning_tags) == 1:
        return "PARTIALLY_AVOIDABLE"
    return "UNKNOWN"  # 悪材料タグ0件だがGOOD_ENTRY_BAD_OUTCOMEの条件（PULLBACK/BREAKOUT等）も
                       # 満たさない＝判断材料が不十分（無理にNOT_AVOIDABLEにしない）


# 指示書9番「ENTRYを止めるだけでなく、待てば入れる条件を出す」：各損切り理由タグに対応する
# 「何が変わればENTRYを解禁してよいか」を機械的に紐付ける固定辞書（AI不使用、他のAUTO系
# エンジンと同じ方針）。判定不能なタグ（EVENT_RISK等、市況要因）には解禁条件を出さない。
LOSS_TAG_UNBLOCK_CONDITIONS = {
    "CHASE_ENTRY": "5分足RSIが70未満へ低下（過熱解消）",
    "LATE_ENTRY": "押し目（直近安値からの調整）を確認してからのエントリーに切り替える",
    "FALSE_BREAKOUT": "直近高値を出来高を伴って明確に上抜け、その後も高値を維持",
    "VWAP_LOSS": "5分足VWAPを再突破し、その後も維持",
    "VOLUME_FADE": "出来高が再び増加（直近3本平均が減少前の水準を回復）",
    "SECTOR_WEAKNESS": "セクター全体の相対強弱が改善",
    "MARKET_REVERSAL": "地合い（日経平均）が反転・落ち着きを確認",
    "ENTRY_BEFORE_CONFIRMATION": "下落が止まり、短期MA・VWAPを回復する反転確認後にエントリー",
    "STOP_TOO_TIGHT": "初期損切り幅をATR等のボラティリティに応じて広げる",
    "RULE_VIOLATION": "該当ルールを満たしてからエントリー",
}


def build_entry_unblock_conditions(loss_tags):
    """指示書9番：LOSS PATTERN MATCH表示の下に「ENTRY解禁条件」を添える。既知の損切り理由
    タグにのみ条件を返す（判定不能なものは無理に条件を作らない）。"""
    return [LOSS_TAG_UNBLOCK_CONDITIONS[t] for t in (loss_tags or []) if t in LOSS_TAG_UNBLOCK_CONDITIONS]


def build_entry_snapshot(code, entry_price, entry_time_iso, market_ctx, market_mode_today=None,
                          sector_state_at_entry=None, nikkei_chg=None, database_url=None, user_id=None):
    """指示書5番：ENTRY時点のスナップショットを固定スキーマで保存する。後から現在値を使って
    再評価しない（後知恵禁止）。取得できない値はNoneのまま（指示書：unknown/null、推測しない）。
    entry_score/entry_state/loss_pattern_similarity/event_riskは、この売買がアプリのENTRY TOP5
    →WAIT/ENTRY判断イベントを経由していた場合のみtrade_decision_eventsから拾う（手動記録のみの
    トレードでは常にNone、無理に埋めない——指示書「未来の情報をENTRY評価に混ぜない」）。"""
    ctx = market_ctx or {}
    distance_from_vwap_pct = None
    if ctx.get("vwap_at_entry") and entry_price is not None:
        distance_from_vwap_pct = round((entry_price - ctx["vwap_at_entry"]) / ctx["vwap_at_entry"] * 100, 2)
    nikkei_trend = None
    if nikkei_chg is not None:
        nikkei_trend = "UP" if nikkei_chg > 0 else ("DOWN" if nikkei_chg < 0 else "FLAT")

    entry_score = entry_state = loss_pattern_similarity = event_risk = None
    if investment_db is not None and database_url:
        try:
            events = investment_db.list_trade_decision_events(database_url, user_id, symbol=code, limit=50)
            entry_dt = None
            try:
                entry_dt = datetime.datetime.fromisoformat(str(entry_time_iso).replace("Z", "+00:00")) if entry_time_iso else None
            except Exception:
                entry_dt = None
            candidate = None
            for e in events:
                if e.get("decision_type") != "ENTRY":
                    continue
                if entry_dt is None:
                    candidate = e
                    break
                try:
                    et = datetime.datetime.fromisoformat(str(e.get("event_time")).replace("Z", "+00:00"))
                    if abs((et - entry_dt).total_seconds()) <= 3600:
                        candidate = e
                        break
                except Exception:
                    continue
            if candidate:
                snap = candidate.get("technical_snapshot_json") or {}
                entry_score = snap.get("entry_score")
                entry_state = snap.get("entry_state")
                event_risk = snap.get("event_risk")
                loss_pattern_similarity = (snap.get("entryRisk") or {}).get("loss_pattern_similarity")
        except Exception as e:
            print("  build_entry_snapshot: trade_decision_events照合で例外（無視して続行）", code, e)

    return {
        "price": entry_price, "time": entry_time_iso,
        "vwap": ctx.get("vwap_at_entry"), "distance_from_vwap_pct": distance_from_vwap_pct,
        "rsi_5m": ctx.get("rsi_at_entry"), "ma5": ctx.get("short_ma"), "ma25": ctx.get("long_ma"),
        "volume_ratio": ctx.get("volume_ratio"),
        "day_high": ctx.get("day_high_so_far_at_entry"), "distance_from_day_high_pct": ctx.get("distance_from_high_pct"),
        "market_regime": market_mode_today, "sector_strength": sector_state_at_entry, "nikkei_trend": nikkei_trend,
        "entry_score": entry_score, "entry_state": entry_state,
        "loss_pattern_similarity": loss_pattern_similarity, "event_risk": event_risk,
    }


def compute_entry_risk_assessment(similar_result):
    """指示書3番：GOOD_ENTRY_SIMILARITY / LOSS_PATTERN_SIMILARITY / ENTRY_RISK_SCOREを算出する。
    既存find_similar_trade_experiences()が返すsimilar_result（symbol一致＋タグ/特徴量類似度）を
    そのまま使う解釈レイヤーであり、類似度計算そのものは変更しない。サンプル不足時は
    過大評価しない（compute_experience_score/compute_behavior_scoreと同じ信頼度キャップの思想）。"""
    empty = {"good_entry_similarity": None, "loss_pattern_similarity": None, "entry_risk_score": None,
             "risk_level": "UNKNOWN", "explanation": None, "confidence": "LOW"}
    if not similar_result or not similar_result.get("similar_count"):
        return empty
    n = similar_result["similar_count"]
    win_rate = similar_result.get("win_rate") or 0.0
    loss_rate = 1.0 - win_rate
    max_sim = similar_result.get("max_similarity") or 0.0
    confidence = classify_pattern_confidence(n)
    conf_factor = {"HIGH": 1.0, "MEDIUM": 0.6, "LOW": 0.25}[confidence]
    good_entry_similarity = round(win_rate * max_sim, 3)
    loss_pattern_similarity = round(loss_rate * max_sim, 3)
    entry_risk_score = round(min(100.0, loss_pattern_similarity * 100 * conf_factor), 1)
    if entry_risk_score >= 50 and confidence != "LOW":
        risk_level = "HIGH"
    elif entry_risk_score >= 25:
        risk_level = "MEDIUM"
    else:
        risk_level = "LOW"
    losses = similar_result.get("losses") or 0
    explanation = (f"過去の類似セットアップ{n}件中、{losses}件が損切り"
                   f"（勝率{round(win_rate * 100)}%、信頼度{confidence}）")
    return {"good_entry_similarity": good_entry_similarity, "loss_pattern_similarity": loss_pattern_similarity,
            "entry_risk_score": entry_risk_score, "risk_level": risk_level, "explanation": explanation,
            "confidence": confidence, "similar_count": n, "losses": losses, "win_rate": similar_result.get("win_rate")}


# 指示書9番：sample_count/win_rateがこの水準を超えたパターンのみ「候補」として提示する
# （自動でACTIVEにはしない、指示書冒頭「重要」）。
RULE_CANDIDATE_MIN_SAMPLE = 15
RULE_CANDIDATE_MIN_WIN_RATE = 0.65
TRADE_EXPERIENCE_PATTERN_RULE_TEXT = {
    "WAIT_TO_ENTRY": "RSI30以下等の下落銘柄は、短期MA＋節目価格の奪回確認後にENTRYする（先回りしない）",
    "OVERSOLD_REVERSAL": "売られすぎ（RSI低水準）だけでENTRYせず、反転確認を待つ",
    "SHORT_MA_RECLAIM": "短期移動平均の奪回を確認してからENTRYする",
    "VOLUME_EXPANSION": "出来高増加を伴わないブレイクは見送る",
    "AFTERNOON_MOMENTUM": "午後のモメンタム急騰は全戻しリスクを踏まえ早めの利確を優先する",
    "MOMENTUM_STOCK": "モメンタム株は高ボラティリティのため利益率優先で利確する",
}


def propose_rule_candidates_from_pattern_stats(pattern_stats):
    """指示書9番：経験データから「実績上有効そう」な候補だけを提示する。ACTIVEルールへは
    自動で変更しない（呼び出し側がpromote_trade_experience_rule_candidate()を明示的に呼んだ
    場合のみTESTINGへ昇格、指示書9番REQUIRED）。"""
    proposals = []
    for tag, stats in (pattern_stats or {}).items():
        if stats.get("sample_count", 0) >= RULE_CANDIDATE_MIN_SAMPLE and (stats.get("win_rate") or 0) >= RULE_CANDIDATE_MIN_WIN_RATE:
            proposals.append({
                "pattern": tag,
                "rule_text": TRADE_EXPERIENCE_PATTERN_RULE_TEXT.get(tag, f"{tag}パターンは実績上有効そう（要ユーザー確認）"),
                "sample_count": stats["sample_count"], "win_rate": stats["win_rate"],
                "avg_pnl_pct": stats.get("avg_pnl_pct"), "confidence_level": stats["confidence_level"],
            })
    return proposals


def compute_momentum_stock_stats(experiences):
    """指示書11番：MOMENTUM_STOCKタグのトレードだけの別集計。ENTRY後5/15/30分の値動き・
    翌日GD率・持ち越し成績は現状データを収集していないため未算出（既知の制約、noteに明記）。"""
    momentum = [t for t in (experiences or []) if "MOMENTUM_STOCK" in (t.get("pattern_tags_json") or [])]
    if not momentum:
        return {"sample_count": 0, "avg_mfe_pct": None, "avg_mae_pct": None,
                 "afternoon_full_exit_count": 0, "note": "MOMENTUM_STOCKタグのサンプルがまだありません。"}
    mfes = [t["max_favorable_excursion_pct"] for t in momentum if t.get("max_favorable_excursion_pct") is not None]
    maes = [t["max_adverse_excursion_pct"] for t in momentum if t.get("max_adverse_excursion_pct") is not None]
    afternoon_full_exit = sum(1 for t in momentum if "AFTERNOON" in "".join(t.get("pattern_tags_json") or [])
                                and "FULL_EXIT_PROFIT_TAKING" in (t.get("pattern_tags_json") or []))
    return {
        "sample_count": len(momentum),
        "avg_mfe_pct": round(sum(mfes) / len(mfes), 2) if mfes else None,
        "avg_mae_pct": round(sum(maes) / len(maes), 2) if maes else None,
        "afternoon_full_exit_count": afternoon_full_exit,
        "note": "ENTRY後5/15/30分足の値動き・翌日GD率・持ち越し成績は未収集のため未算出（既知の制約）。",
    }


def build_daily_trade_learning_summary(experiences_for_day):
    """指示書12番：Best Trade/Worst Trade/Best WAIT/Rule Violation/New Pattern Candidateを
    自動生成する（既存daily_reviewsのスコア計算には一切触れない、追加専用集計）。"""
    empty = {"best_trade": None, "worst_trade": None, "best_wait": None, "rule_violations": [],
              "learning_notes": []}
    if not experiences_for_day:
        return empty
    ranked = sorted(experiences_for_day, key=lambda t: t.get("gross_pnl_pct") if t.get("gross_pnl_pct") is not None else 0,
                      reverse=True)
    best, worst = ranked[0], (ranked[-1] if len(ranked) > 1 else None)
    best_wait = next((t for t in experiences_for_day if t.get("wait_reason_json")), None)
    violations = [t for t in experiences_for_day
                   if t.get("rule_compliance_score") is not None and t["rule_compliance_score"] < 60]
    learning_notes = []
    for t in experiences_for_day:
        if t.get("pre_entry_state") and "WAIT" in str(t["pre_entry_state"]) and t.get("result_class") == "WIN":
            learning_notes.append(f"「売られすぎ」だけではENTRYせず、反転条件確認後に入る方が再現性が高い可能性（{t.get('symbol')}）")
    return {
        "best_trade": {"symbol": best.get("symbol"), "stock_name": best.get("stock_name"),
                         "gross_pnl_pct": best.get("gross_pnl_pct"), "gross_pnl": best.get("gross_pnl")} if best else None,
        "worst_trade": {"symbol": worst.get("symbol"), "stock_name": worst.get("stock_name"),
                          "gross_pnl_pct": worst.get("gross_pnl_pct")} if worst else None,
        "best_wait": {"symbol": best_wait.get("symbol"), "reasons": best_wait.get("wait_reason_json")} if best_wait else None,
        "rule_violations": [{"symbol": t.get("symbol"), "rule_compliance_score": t.get("rule_compliance_score")}
                              for t in violations],
        "learning_notes": learning_notes,
    }


def build_trade_experience_summary_for_symbol(database_url, user_id, symbol, current_tags=None, current_features=None,
                                                 _preloaded_experiences=None):
    """指示書7・8番：トレード分析／ENTRY TOP5の両方から呼ぶ共通の「経験値」要約。
    similar_result＋EXPERIENCE_SCOREをまとめて返す。
    2026-09-15追加（Market Data Phase 2、DB N+1解消）：_preloaded_experiencesは
    find_similar_trade_experiences()へそのまま引き継ぐだけ（ENTRY TOP5のバッチ経路専用）。"""
    similar = find_similar_trade_experiences(database_url, user_id, symbol=symbol, current_tags=current_tags,
                                                current_features=current_features, _preloaded_experiences=_preloaded_experiences)
    score = compute_experience_score(similar)
    entry_risk = compute_entry_risk_assessment(similar)
    return {"experience_score": score, "similar": similar, "entryRisk": entry_risk}


def build_trade_experience_payload(trade):
    """指示書13番：ChatGPT/Claude Code共有JSON向け。後知恵禁止（指示書16番）——entry_reasonには
    decision_snapshot_json（ENTRY時点で分かっていたことだけ）を使い、EXIT後に判明した情報
    （post_trade_analysis_json）は混ぜない。"""
    if not trade:
        return None
    return {
        "symbol": trade.get("symbol"), "stock_name": trade.get("stock_name"), "trade_date": str(trade.get("trade_date")),
        "entry_price": trade.get("entry_price"), "exit_price": trade.get("exit_price"), "quantity": trade.get("quantity"),
        "gross_pnl": trade.get("gross_pnl"), "gross_pnl_pct": trade.get("gross_pnl_pct"),
        "pre_entry_decision": (trade.get("decision_snapshot_json") or {}).get("pre_entry_decision"),
        "entry_pattern": trade.get("pattern_tags_json") or [],
        "exit_pattern": trade.get("exit_reason_json") or [],
        "result": trade.get("result_class"),
        "learning_summary": (trade.get("post_trade_analysis_json") or {}).get("learning_summary"),
    }


def get_trade_experience_diagnostics(database_url, user_id):
    """指示書：件数の可視化（記録タブ・診断向け）。"""
    if investment_db is None or not database_url:
        return {"total_experiences": 0, "rule_candidates_pending": 0, "patterns_tracked": 0}
    exps = investment_db.list_trade_experiences(database_url, user_id, limit=1000)
    stats = compute_pattern_statistics(exps)
    candidates = investment_db.list_trade_experience_rule_candidates(database_url, user_id)
    return {"total_experiences": len(exps), "rule_candidates_pending": len(candidates), "patterns_tracked": len(stats)}


def build_loss_learning_report(database_url, user_id, since_date=None, limit=1000):
    """運用ルール（2026-09-15、ユーザー明示指示）：ENTRY判定改善のため損切りトレードを定期的に
    集計するレポート。既存compute_pattern_statistics()（タグ別win_rate/avg_pnl_pct/
    confidence_level、行12084付近）をそのまま再利用し、二重の集計ロジックは作らない。
    目的は勝率最大化ではなく「期待値の高いENTRYを残し、期待値の低いENTRYを減らす」こと
    （ユーザー明示）——win_rateだけでなくavg_pnl_pctも必ず併記し、confidence_level
    （サンプル<5=LOW/5〜14=MEDIUM/15+=HIGH）で過信を防ぐ。since_date省略時は全期間。
    このレポート自体はENTRYスコアやWAIT/CAUTION判定に直接介入しない（既存
    compute_entry_risk_assessment()の信頼度ゲートが個別candidateへの反映を担う——
    このレポートは人間・Claude Codeが定期的に眺めて傾向を把握するための集計専用）。"""
    empty = {
        "period": {"since": since_date, "totalTrades": 0},
        "lossCount": 0, "winCount": 0,
        "avoidableLossCount": 0, "notAvoidableLossCount": 0, "unknownAvoidabilityCount": 0,
        "goodEntryBadOutcomeCount": 0, "exitWasGoodEntryWasBadCount": 0,
        "lossTagFrequency": [], "lossTagPerformance": [], "winningPatternPerformance": [],
    }
    if investment_db is None or not database_url:
        return empty
    exps = investment_db.list_trade_experiences(database_url, user_id, limit=limit)
    entered = [e for e in exps if e.get("side") != "WAIT"]
    if since_date:
        entered = [e for e in entered if str(e.get("trade_date") or "") >= since_date]
    losses = [e for e in entered if e.get("result_class") == "LOSS"]
    wins = [e for e in entered if e.get("result_class") == "WIN"]

    # 2026-09-16更新（4段階評価に統一）：post_trade_analysis_json.entry_avoidability
    # （AVOIDABLE/PARTIALLY_AVOIDABLE/NOT_AVOIDABLE/UNKNOWN）を集計する。旧booleanフィールド
    # （avoidable_at_entry）しか無い古い行（2026-09-15時点で生成済みの3件）は無理に4段階へ
    # 変換せず、UNKNOWN扱いにする（推測で埋めない）。
    avoidability_counts = {"AVOIDABLE": 0, "PARTIALLY_AVOIDABLE": 0, "NOT_AVOIDABLE": 0, "UNKNOWN": 0}
    for e in losses:
        pta = e.get("post_trade_analysis_json") or {}
        av = pta.get("entry_avoidability")
        if av in avoidability_counts:
            avoidability_counts[av] += 1
        elif pta.get("avoidable_at_entry") is True:
            avoidability_counts["AVOIDABLE"] += 1
        elif pta.get("avoidable_at_entry") is False:
            avoidability_counts["NOT_AVOIDABLE"] += 1
        else:
            avoidability_counts["UNKNOWN"] += 1
    avoidable = avoidability_counts["AVOIDABLE"]
    partially_avoidable = avoidability_counts["PARTIALLY_AVOIDABLE"]
    not_avoidable = avoidability_counts["NOT_AVOIDABLE"]
    unknown_avoidability = avoidability_counts["UNKNOWN"]
    good_entry_bad_outcome = sum(1 for e in losses if "GOOD_ENTRY_BAD_OUTCOME" in (e.get("pattern_tags_json") or []))

    # 指示書「損切り自体は正しかったケース」：exit_execution_scoreが高い（損切り実行自体は
    # 適切）のにentry_timing_scoreが低い（エントリー判断に問題があった）ケースを機械的に抽出
    # （build_trade_breakdown_for_dayのexitWasGoodButEntryWasBadと同じ判定基準、全期間版）。
    exit_good_entry_bad = 0
    for e in losses:
        bd = e.get("score_breakdown_json") or {}
        if (bd.get("exit_execution_score") or 0) >= 15 and (bd.get("entry_timing_score") or 0) < 10:
            exit_good_entry_bad += 1

    tag_counter = {}
    for e in losses:
        for tag in (e.get("exit_reason_json") or []):
            tag_counter[tag] = tag_counter.get(tag, 0) + 1
    loss_tag_frequency = sorted(({"tag": t, "count": c} for t, c in tag_counter.items()),
                                 key=lambda x: -x["count"])

    pattern_stats = compute_pattern_statistics(entered)  # 既存関数の再利用（二重集計を避ける）
    loss_tag_performance = sorted(
        [{"tag": tag, **pattern_stats[tag]} for tag in LOSS_REASON_TAGS if tag in pattern_stats],
        key=lambda x: -(x.get("sample_count") or 0))
    # 「成功パターンとの比較」：ENTRY setup系タグ（損切り理由タグとは別軸）の成績を並記する。
    winning_setup_tags = ("WAIT_TO_ENTRY", "OVERSOLD_REVERSAL", "SHORT_MA_RECLAIM", "ROUND_NUMBER_RECLAIM",
                           "VOLUME_EXPANSION", "SETUP_PULLBACK", "SETUP_BREAKOUT")
    winning_pattern_performance = sorted(
        [{"tag": tag, **pattern_stats[tag]} for tag in winning_setup_tags if tag in pattern_stats],
        key=lambda x: -(x.get("sample_count") or 0))

    return {
        "period": {"since": since_date, "totalTrades": len(entered)},
        "lossCount": len(losses), "winCount": len(wins),
        "avoidableLossCount": avoidable, "partiallyAvoidableLossCount": partially_avoidable,
        "notAvoidableLossCount": not_avoidable, "unknownAvoidabilityCount": unknown_avoidability,
        "goodEntryBadOutcomeCount": good_entry_bad_outcome,
        "exitWasGoodEntryWasBadCount": exit_good_entry_bad,
        "lossTagFrequency": loss_tag_frequency,
        "lossTagPerformance": loss_tag_performance,
        "winningPatternPerformance": winning_pattern_performance,
    }


# ============================================================
# 「今日の振り返り」独立タブ化 + 15:30自動評価 + トレード経験/銘柄クセ学習（2026-09-12新規）。
# 既存daily_reviewsのscore_total計算・既存Trade Experience Learning（Task E）のCRUD/評価関数は
# 一切変更せず、その上に積む形の追加専用ロジックのみ（指示書冒頭「必ずAIが勝手にACTIVEルールを
# 変更しない」「経験・クセはまず補助情報」を踏襲）。
# ============================================================

BEHAVIOR_TIME_BUCKETS = ("09:00-09:30", "09:30-10:30", "10:30-11:30", "12:30-13:30", "13:30-14:30", "14:30-15:30")
_BEHAVIOR_TIME_BUCKET_RANGES = (
    ("09:00-09:30", 9 * 60, 9 * 60 + 30), ("09:30-10:30", 9 * 60 + 30, 10 * 60 + 30),
    ("10:30-11:30", 10 * 60 + 30, 11 * 60 + 30), ("12:30-13:30", 12 * 60 + 30, 13 * 60 + 30),
    ("13:30-14:30", 13 * 60 + 30, 14 * 60 + 30), ("14:30-15:30", 14 * 60 + 30, 15 * 60 + 30),
)


def classify_behavior_time_bucket(entry_time_iso):
    """指示書16番：JST基準で6つの時間帯へ分類する（09:00-09:30〜14:30-15:30）。範囲外
    （寄り前・引け後・昼休み等）や日時が読めない場合はNone。"""
    if not entry_time_iso:
        return None
    try:
        t = datetime.datetime.fromisoformat(str(entry_time_iso).replace("Z", "+00:00")).astimezone(_JST)
    except Exception:
        return None
    hhmm = t.hour * 60 + t.minute
    for label, start, end in _BEHAVIOR_TIME_BUCKET_RANGES:
        if start <= hhmm < end:
            return label
    return None


def compute_trade_result_score(gross_pnl_pct):
    """指示書6・7番：「結果」だけを機械的に0-100へ写像する（判断品質＝execution_score/
    decision_quality_scoreとは完全に独立の軸）。-10%以下→0点、+10%以上→100点の単純な
    線形写像（恣意的な固定点は使わない）。判定不能時は中立の50点。"""
    if gross_pnl_pct is None:
        return 50.0
    clamped = max(-10.0, min(10.0, gross_pnl_pct))
    return round((clamped + 10.0) / 20.0 * 100, 1)


def evaluate_wait_decision(entry_score_at_wait):
    """指示書13番：「買わなかった判断」の妥当性を、WAIT時点で分かっていた情報（entry_score）
    だけで評価する。事後の値動き（急落した／急騰した）は結果の記録にのみ使い、判断の当否
    そのものには使わない（後知恵禁止、指示書22番と同じ思想）。entry_score_at_wait<55
    （ENTRY_READY昇格閾値未満）でのWAITは、その後の結果に関わらず判断として妥当
    （GOOD_WAIT）。>=55（本来ENTRY_READY相当だったのに見送った）は個別確認が必要という
    意味でNEUTRAL_WAITに留め、単純にBAD認定はしない（指示書「単純にBAD WAITにしない」）。
    戻り値：(result_class, reason_text)。"""
    if entry_score_at_wait is None:
        return "NEUTRAL_WAIT", "判断時点のスコアが不明なため評価不能"
    if entry_score_at_wait < 55:
        return "GOOD_WAIT", "判断時点でENTRY条件未達（entry_score<55）のため、その後の値動きに関わらず妥当な判断"
    return "NEUTRAL_WAIT", "判断時点でentry_score>=55（ENTRY READY相当）だったが見送り——個別確認が必要"


def sync_trade_experiences_for_date(database_url, user_id, review_date):
    """15:30自動評価（指示書12・13・21・26・29番）：当日の実トレード（勝ち/負け/同値/損切り/
    利確、全部——勝ちトレードだけの登録は禁止）をtrade_experiencesへ冪等にupsertし、WAITのみで
    終わった判断もGOOD_WAIT等として記録する。sync_key
    （'trade:<trade_history.id>' / 'wait:<symbol>:<trade_date>:<event_time>'）で重複登録を
    防ぐ——同じ日に再実行しても増えない（指示書29番）。
    戻り値：{"trades_synced": N, "waits_synced": N, "experience_ids": [...]}。"""
    result = {"trades_synced": 0, "waits_synced": 0, "experience_ids": []}
    if investment_db is None or not database_url:
        return result
    # Choruco Style連携（2026-09-12新規、指示書38番）：market_mode/event_riskの連続的な
    # 時系列履歴はまだ保存していないため（既知の制約）、15:30同期時点で1回だけ計算した値を
    # その日の全トレードへ共通で使う——「エントリー時点の厳密なモード」ではなく「その日の
    # 引け後に見た代表値」であることに注意（将来、時系列スナップショットを追加すれば
    # 個別トレードごとの正確な値に置き換えられる設計にしてある）。
    market_mode_today, event_risk_today = None, None
    try:
        mode_result = compute_choruco_market_mode(database_url, user_id)
        market_mode_today = mode_result.get("mode")
        event_risk_today = mode_result.get("event_risk_level")
    except Exception as e:
        print("  daily-review: choruco market mode取得で例外（無視して続行）", e)
    # ENTRY時点スナップショット用（指示書5番、2026-09-16新規）：run_momentum_stage1()は
    # プロセス内で共有キャッシュ済みのため、ここで1回呼んでも新規の全市場スキャンにはならない。
    nikkei_chg_today = None
    try:
        nikkei_chg_today = run_momentum_stage1().get("nikkeiChangePct")
    except Exception as e:
        print("  daily-review: nikkei変化率取得で例外（無視して続行）", e)
    history = investment_db.list_trade_history(database_url, user_id, limit=500)
    exits_today = [t for t in history if str(t.get("closed_at") or "")[:10] == review_date]
    for t in exits_today:
        sync_key = f"trade:{t.get('id')}"
        gross_pnl = t.get("gross_pnl") if t.get("gross_pnl") is not None else t.get("pnl")
        entry_price, exit_price, qty = t.get("entry_price"), t.get("exit_price"), t.get("shares")
        gross_pnl_pct = compute_trade_gross_pnl_pct(entry_price, exit_price) if entry_price else None
        result_class = classify_trade_result(gross_pnl)
        # Cross-Market Link Phase 2新規（指示書14番）：同期時点のprimary driver情報を付与する
        # （market_mode同様、「エントリー時点の厳密な値」ではなく「15:30同期時点の代表値」、
        # 既知の制約）。半導体・AI関連銘柄以外はbuild_cross_market_link()がゲートしNoneに近い
        # 値を返す。
        primary_driver = driver_corr = driver_lag = driver_state = cross_score = None
        try:
            cm = build_cross_market_link(t.get("code"))
            if cm.get("primary_driver"):
                primary_driver = cm.get("primary_driver")
                driver_corr = cm.get("correlation")
                driver_lag = cm.get("best_lag_minutes")
                primary_driver_change = next((d.get("recent_change_pct") for d in (cm.get("drivers") or [])
                                                if d.get("label") == primary_driver), None)
                driver_state = "UP" if (primary_driver_change or 0) > 0 else ("DOWN" if (primary_driver_change or 0) < 0 else None)
                cross_score = cm.get("cross_market_score")
        except Exception as e:
            print("  daily-review: cross-market取得で例外（無視して続行）", t.get("code"), e)

        # Sector Rotation Engine新規（指示書36番）：同期時点のsector state・flow scoreを付与
        # する（既知の制約：market_mode/primary_driver同様「エントリー時点の厳密な値」ではなく
        # 「15:30同期時点の代表値」）。
        sector_at_entry = sector_state = sector_flow_score = rotation_context = None
        try:
            themes = get_stock_themes(t.get("code"))
            if themes:
                rotation_snapshot = build_sector_rotation_snapshot(database_url, user_id)
                sector_at_entry = themes[0]
                info = rotation_snapshot.get("sectors", {}).get(sector_at_entry) or {}
                sector_state = info.get("state")
                sector_flow_score = compute_sector_flow_score_for_entry(sector_state)
                rotation_context = {"rotation_pairs": rotation_snapshot.get("rotation_pairs", [])}
        except Exception as e:
            print("  daily-review: sector rotation取得で例外（無視して続行）", t.get("code"), e)

        entry_time_iso, exit_time_iso = t.get("acquired_at"), t.get("closed_at")
        holding_minutes = None
        if entry_time_iso and exit_time_iso:
            try:
                et = datetime.datetime.fromisoformat(str(entry_time_iso).replace("Z", "+00:00"))
                xt = datetime.datetime.fromisoformat(str(exit_time_iso).replace("Z", "+00:00"))
                holding_minutes = max(0, round((xt - et).total_seconds() / 60))
            except Exception:
                pass

        # トレード学習・損切り分析強化（2026-09-15新規、指示書1・2・7番）：当日5分足から
        # エントリー/エグジット時点の市場コンテキストを再構築し（reconstruct_trade_market_context）、
        # 損切りトレードには理由タグを自動分類する（classify_loss_reasons）。取得できない値は
        # 推測せずNoneのまま保存する（指示書7番「不明な情報を推測で埋めない」）。
        market_ctx = reconstruct_trade_market_context(t.get("code"), t.get("market", "JP"), review_date,
                                                        entry_time_iso, exit_time_iso)
        loss_tags = []
        if result_class == "LOSS":
            loss_tags = classify_loss_reasons(gross_pnl_pct, market_ctx, exit_price=exit_price,
                                               sector_state_at_entry=sector_state,
                                               market_mode_at_entry=market_mode_today,
                                               market_mode_at_exit=market_mode_today,
                                               event_risk_at_entry=event_risk_today)
        entry_setup_tags = []
        if market_ctx.get("entry_setup_type"):
            entry_setup_tags.append(f"SETUP_{market_ctx['entry_setup_type']}")
        if market_ctx.get("rsi_at_entry") is not None and market_ctx["rsi_at_entry"] <= 35:
            entry_setup_tags.append("OVERSOLD_REVERSAL")
        if market_ctx.get("short_ma") is not None and entry_price is not None and entry_price >= market_ctx["short_ma"]:
            entry_setup_tags.append("SHORT_MA_RECLAIM")
        if market_ctx.get("volume_ratio") is not None and market_ctx["volume_ratio"] >= 1.5:
            entry_setup_tags.append("VOLUME_EXPANSION")
        pattern_tags = entry_setup_tags + loss_tags

        # 指示書6番：AVOIDABLE/PARTIALLY_AVOIDABLE/NOT_AVOIDABLE/UNKNOWNの4段階（損益の符号は
        # 一切見ない、指示書7番「負けたから悪いENTRY」の禁止を厳守）。
        entry_avoidability = classify_entry_avoidability(loss_tags, market_ctx.get("data_quality")) \
            if result_class == "LOSS" else None
        # 指示書9番：ENTRYを止めるだけでなく「待てば入れる条件」を添える。
        entry_unblock_conditions = build_entry_unblock_conditions(loss_tags) if result_class == "LOSS" else []
        # 指示書5番：ENTRY時点スナップショット（全トレード対象、勝敗を問わない）。後から現在値を
        # 使って再評価しない固定スキーマ。
        entry_snapshot = build_entry_snapshot(t.get("code"), entry_price, entry_time_iso, market_ctx,
                                               market_mode_today=market_mode_today, sector_state_at_entry=sector_state,
                                               nikkei_chg=nikkei_chg_today, database_url=database_url, user_id=user_id)

        fields = {
            "trade_date": review_date, "symbol": t.get("code"), "stock_name": t.get("name"),
            "side": "BUY", "trade_style": t.get("trade_style"),
            "quantity": qty, "entry_price": entry_price, "exit_price": exit_price,
            "entry_time": entry_time_iso, "exit_time": exit_time_iso, "holding_minutes": holding_minutes,
            "gross_pnl": gross_pnl, "gross_pnl_pct": gross_pnl_pct,
            "result_class": result_class,
            "trade_result_score": compute_trade_result_score(gross_pnl_pct),
            "market_mode_at_entry": market_mode_today, "market_mode_at_exit": market_mode_today,
            "event_risk_at_entry": event_risk_today,
            "primary_driver": primary_driver, "driver_corr_at_entry": driver_corr,
            "driver_lag_at_entry": driver_lag, "driver_state_at_entry": driver_state,
            "driver_state_at_exit": driver_state, "cross_market_score_at_entry": cross_score,
            "sector_at_entry": sector_at_entry, "sector_state_at_entry": sector_state,
            "sector_flow_score_at_entry": sector_flow_score, "sector_state_at_exit": sector_state,
            "sector_flow_score_at_exit": sector_flow_score, "rotation_context_json": rotation_context,
            "rsi_at_entry": market_ctx.get("rsi_at_entry"), "rsi_at_exit": market_ctx.get("rsi_at_exit"),
            "short_ma": market_ctx.get("short_ma"), "mid_ma": market_ctx.get("mid_ma"),
            "long_ma": market_ctx.get("long_ma"), "volume_ratio": market_ctx.get("volume_ratio"),
            "intraday_high": market_ctx.get("day_high"), "intraday_low": market_ctx.get("day_low"),
            "distance_from_low_pct": market_ctx.get("distance_from_low_pct"),
            "distance_from_high_pct": market_ctx.get("distance_from_high_pct"),
            "max_favorable_excursion_pct": market_ctx.get("max_favorable_excursion_pct"),
            "max_adverse_excursion_pct": market_ctx.get("max_adverse_excursion_pct"),
            "post_exit_max_price": market_ctx.get("post_exit_max_price"),
            "post_exit_min_price": market_ctx.get("post_exit_min_price"),
            "pattern_tags_json": pattern_tags or None, "exit_reason_json": loss_tags or None,
            "decision_snapshot_json": {
                "entry_snapshot": entry_snapshot,  # 指示書5番：ENTRY時点固定スキーマ
                "day_open": market_ctx.get("day_open"), "vwap_at_entry": market_ctx.get("vwap_at_entry"),
                "above_vwap_at_entry": market_ctx.get("above_vwap_at_entry"),
                "distance_from_low_pct": market_ctx.get("distance_from_low_pct"),
                "distance_from_high_pct": market_ctx.get("distance_from_high_pct"),
                "trend_5m_before_entry": market_ctx.get("trend_5m_before_entry"),
                "entry_setup_type": market_ctx.get("entry_setup_type"),
                "data_quality": market_ctx.get("data_quality"),
            },
            "post_trade_analysis_json": ({
                "loss_reason_tags": loss_tags, "vwap_at_exit": market_ctx.get("vwap_at_exit"),
                "volume_trend_after_entry": market_ctx.get("volume_trend_after_entry"),
                "broke_prior_high_then_failed": market_ctx.get("broke_prior_high_then_failed"),
                "post_exit_direction": market_ctx.get("post_exit_direction"),
                "entry_avoidability": entry_avoidability,  # 指示書6番：4段階評価
                "entry_unblock_conditions": entry_unblock_conditions,  # 指示書9番
                "data_quality": market_ctx.get("data_quality"),
            } if result_class == "LOSS" else None),
            "notes": "15:30自動評価による自動登録（sync_trade_experiences_for_date）。",
        }
        try:
            saved = investment_db.upsert_trade_experience_by_sync_key(database_url, user_id, sync_key, fields)
        except Exception as e:
            print("  daily-review: trade experience同期で例外（無視して続行）", t.get("code"), e)
            saved = None
        if saved:
            result["trades_synced"] += 1
            result["experience_ids"].append(saved.get("id"))
            # 指示書5番：損した／利益が出た、だけで判断品質を決めない——entry_timing/risk_control/
            # exit_execution/rule_compliance/repeatabilityの5軸をトレードごとに自動採点する
            # （evaluate_trade_experience()は既存関数、これまで手動APIからしか呼ばれていなかった
            # ものを15:30自動評価にも接続するだけ）。
            try:
                merged = {**saved, **fields}
                _total, breakdown = evaluate_trade_experience(merged)
                investment_db.update_trade_experience(database_url, user_id, saved["id"],
                                                       {"execution_score": breakdown["total"],
                                                        "score_breakdown_json": breakdown})
            except Exception as e:
                print("  daily-review: trade experience自動採点で例外（無視して続行）", t.get("code"), e)

    # WAITのみで終わった判断（当日ENTRYに至らなかったWAIT決断イベント）もGOOD_WAIT等として記録する
    try:
        events = investment_db.list_trade_decision_events(database_url, user_id, limit=2000)
    except Exception as e:
        print("  daily-review: trade decision events取得で例外（無視して続行）", e)
        events = []
    today_events = [e for e in events if str(e.get("event_time") or "")[:10] == review_date]
    entered_symbols = {e.get("symbol") for e in today_events if e.get("decision_type") == "ENTRY"}
    for e in today_events:
        if e.get("decision_type") != "WAIT" or e.get("symbol") in entered_symbols:
            continue
        snapshot = e.get("technical_snapshot_json") or {}
        result_class, reason = evaluate_wait_decision(snapshot.get("entry_score"))
        sync_key = f"wait:{e.get('symbol')}:{review_date}:{e.get('event_time')}"
        fields = {
            "trade_date": review_date, "symbol": e.get("symbol"), "side": "WAIT",
            "pre_entry_state": "WAIT_ONLY", "wait_reason_json": e.get("reason_json"),
            "result_class": result_class,
            "post_trade_analysis_json": {"wait_evaluation": reason},
            "notes": "15:30自動評価によるWAIT判断の自動登録（sync_trade_experiences_for_date）。",
        }
        try:
            saved = investment_db.upsert_trade_experience_by_sync_key(database_url, user_id, sync_key, fields)
        except Exception as ex:
            print("  daily-review: WAIT experience同期で例外（無視して続行）", e.get("symbol"), ex)
            saved = None
        if saved:
            result["waits_synced"] += 1
            result["experience_ids"].append(saved.get("id"))
    return result


def compute_behavior_score(setup_stats_for_current_setup):
    """指示書19・20番：BEHAVIOR_SCORE 0〜10の補助スコア。既存ENTRY SCOREは一切書き換えない。
    サンプル<5は強い判断材料として使わない＝上限キャップ（Trade Experience Learningの
    compute_experience_score()と同じ設計方針）。"""
    if not setup_stats_for_current_setup:
        return 0.0
    count = setup_stats_for_current_setup.get("sample_count") or setup_stats_for_current_setup.get("count") or 0
    win_rate = setup_stats_for_current_setup.get("win_rate")
    if not count or win_rate is None:
        return 0.0
    raw = win_rate * 10.0
    if count < 5:
        raw = min(raw, 2.0)
    elif count < 15:
        raw = min(raw, 7.0)
    return round(min(10.0, raw), 1)


def aggregate_stock_behavior_stats(experiences):
    """指示書14・15・16・17番：symbol単位のtrade_experiencesリストから統計値を算出する純粋
    関数（文章ではなく統計値から作る）。サンプル不足時も嘘の値は作らずNoneのまま返す。
    パターン別（SETUP別）統計は既存compute_pattern_statistics()をそのまま再利用する
    （二重の集計ロジックを作らない）。"""
    n = len(experiences or [])
    empty = {"sample_count": 0, "confidence_level": "LOW", "preferred_setup_json": {},
              "time_bucket_stats_json": {}, "best_entry_time_bucket": None, "worst_entry_time_bucket": None,
              "avg_mfe_pct": None, "avg_mae_pct": None, "danger_patterns_json": []}
    if n == 0:
        return empty

    setup_stats = compute_pattern_statistics(experiences)  # 既存関数の再利用（指示書17番）

    bucket_stats = {}
    for e in experiences:
        b = classify_behavior_time_bucket(e.get("entry_time"))
        if not b:
            continue
        st = bucket_stats.setdefault(b, {"count": 0, "wins": 0})
        st["count"] += 1
        if e.get("result_class") == "WIN":
            st["wins"] += 1
    for st in bucket_stats.values():
        st["win_rate"] = round(st["wins"] / st["count"], 3) if st["count"] else None
    # 信頼できる比較には最低限のサンプル（MEDIUM相当=5件）を要求する（指示書20番の思想を時間帯にも適用）
    comparable = {b: st for b, st in bucket_stats.items() if st["count"] >= 5 and st["win_rate"] is not None}
    best_bucket = max(comparable, key=lambda b: comparable[b]["win_rate"]) if comparable else None
    worst_bucket = min(comparable, key=lambda b: comparable[b]["win_rate"]) if comparable else None

    mfes = [e["max_favorable_excursion_pct"] for e in experiences if e.get("max_favorable_excursion_pct") is not None]
    maes = [e["max_adverse_excursion_pct"] for e in experiences if e.get("max_adverse_excursion_pct") is not None]
    danger_patterns = [tag for tag, st in setup_stats.items()
                        if st.get("sample_count", 0) >= 5
                        and (st.get("win_rate") if st.get("win_rate") is not None else 1.0) < 0.4]

    return {
        "sample_count": n, "confidence_level": classify_pattern_confidence(n),
        "preferred_setup_json": setup_stats, "time_bucket_stats_json": bucket_stats,
        "best_entry_time_bucket": best_bucket, "worst_entry_time_bucket": worst_bucket,
        "avg_mfe_pct": round(sum(mfes) / len(mfes), 2) if mfes else None,
        "avg_mae_pct": round(sum(maes) / len(maes), 2) if maes else None,
        "danger_patterns_json": danger_patterns,
    }


def update_stock_behavior_profile(database_url, user_id, symbol):
    """指示書21番：取引結果からstock_behavior_profileを再集計・保存する。当日Trade Experience
    ↓ stock_behavior_profile再集計、の循環の1ステップ。既存プロフィールのstock_nameは
    trade_experiencesの最新レコードから補う。"""
    if investment_db is None or not database_url:
        return None
    experiences = investment_db.list_trade_experiences(database_url, user_id, symbol=symbol, limit=1000)
    # WAIT専用行（side='WAIT'）はENTRY/EXITが無いため統計対象から除く——押し目/ブレイク等の
    # SETUP別集計・時間帯集計は「実際にENTRYした」経験のみを対象にする（指示書14〜17番の
    # 「銘柄のクセ」はエントリー後の値動きの話であり、見送り判断とは別軸のため）。
    entered = [e for e in experiences if e.get("side") != "WAIT"]
    stats = aggregate_stock_behavior_stats(entered)
    stock_name = next((e.get("stock_name") for e in experiences if e.get("stock_name")), None)
    fields = {**stats, "stock_name": stock_name}
    # Cross-Market Link Phase 2新規（指示書15番）：「8035はKOSPIが平均8分先行」のように表示
    # できるよう、蓄積済みtrade_experiencesからprimary_driver・平均相関・平均lag・信頼度
    # （予測が当たった割合）を集計する。半導体・AI関連銘柄以外はprimary_driverが常にNoneの
    # ためこのブロックは実質何もしない。
    driver_rows = [e for e in entered if e.get("primary_driver")]
    if driver_rows:
        from collections import Counter
        most_common_driver = Counter(e["primary_driver"] for e in driver_rows).most_common(1)[0][0]
        same_driver_rows = [e for e in driver_rows if e["primary_driver"] == most_common_driver]
        corrs = [e["driver_corr_at_entry"] for e in same_driver_rows if e.get("driver_corr_at_entry") is not None]
        lags = [e["driver_lag_at_entry"] for e in same_driver_rows if e.get("driver_lag_at_entry") is not None]
        validities = [_cross_market_prediction_was_valid(e) for e in same_driver_rows]
        validities = [v for v in validities if v is not None]
        fields["primary_driver"] = most_common_driver
        fields["primary_driver_corr"] = round(sum(corrs) / len(corrs), 2) if corrs else None
        fields["primary_driver_lag"] = round(sum(lags) / len(lags)) if lags else None
        fields["cross_market_reliability"] = round(sum(1 for v in validities if v) / len(validities), 2) if validities else None
    return investment_db.upsert_stock_behavior_profile(database_url, user_id, symbol, fields)


def build_learning_accumulation_summary(database_url, user_id, review_date=None):
    """指示書25・27番：GET /api/trade-learning/summary。「今日の学習」蓄積状況
    （新規Trade Experience件数・更新された銘柄プロフィール数・新しいPattern Candidate・
    未承認のRule Candidate件数）を返す。review_date未指定時は当日。"""
    review_date = review_date or datetime.date.today().isoformat()
    empty = {"new_trade_experiences": 0, "updated_stock_profiles": 0, "new_pattern_candidates": 0,
              "rule_candidates_pending": 0}
    if investment_db is None or not database_url:
        return empty
    day_experiences = investment_db.list_trade_experiences(database_url, user_id, trade_date=review_date)
    symbols_today = {e.get("symbol") for e in day_experiences if e.get("symbol") and e.get("side") != "WAIT"}
    all_experiences = investment_db.list_trade_experiences(database_url, user_id, limit=1000)
    pattern_stats = compute_pattern_statistics(all_experiences)
    new_candidates = propose_rule_candidates_from_pattern_stats(pattern_stats)
    rule_candidates_pending = investment_db.list_trade_experience_rule_candidates(database_url, user_id)
    return {
        "new_trade_experiences": len(day_experiences),
        "updated_stock_profiles": len(symbols_today),
        "new_pattern_candidates": len(new_candidates),
        "rule_candidates_pending": len(rule_candidates_pending),
    }


def build_stock_behavior_summary(database_url, user_id, symbol, current_setup_tags=None):
    """トレード分析カードのコンパクト表示（指示書18・32番）向け。symbolのプロフィールを
    取得し、現在Setup（current_setup_tags、ENTRY TOP5/トレード分析が既に算出済みの
    pattern_tags相当）に対応するBEHAVIOR_SCOREも一緒に返す。プロフィールが無ければ
    sample_count=0のまま返す（作り物のクセを表示しない）。"""
    empty = {"profile": None, "behavior_score": 0.0}
    if investment_db is None or not database_url:
        return empty
    profile = investment_db.get_stock_behavior_profile(database_url, user_id, symbol)
    if not profile:
        return empty
    setup_json = profile.get("preferred_setup_json") or {}
    behavior_score = 0.0
    if current_setup_tags:
        for tag in current_setup_tags:
            if tag in setup_json:
                behavior_score = max(behavior_score, compute_behavior_score(setup_json[tag]))
    return {"profile": profile, "behavior_score": behavior_score}


def generate_daily_review_with_learning(database_url, user_id, review_date, user_feedback=None, finalize=True):
    """15:30自動評価パイプライン全体（指示書4・28番）：
      当日レビュー生成 → trade experience確定 → stock behavior更新 → pattern statistics更新 →
      rule candidate判定 → daily review保存 → （呼び出し側で）通知
    既存generate_daily_review()のscore_total計算・既存Trade Experience Learning（Task E）の
    評価関数には一切触れず、その上に積む追加専用の後続ステップ。finalize=Trueの場合のみ
    daily_reviews.is_finalizedを立てる（15:30スケジューラのリトライ中はfinalize=Falseで
    様子見にできる）。
    戻り値：{"review":..., "sync":..., "behaviorUpdated":[...], "patternCandidatesTracked":N,
             "ruleCandidatesProposed":[...]}。"""
    if investment_db is None or not database_url:
        return None
    # 2026-09-14修正（不具合対応）：土日・祝日・年末年始は「地合い情報が未記録」ではなく
    # 「市場休場日のため評価対象外」として扱うため、JP祝日カレンダー込みの正確な判定
    # （is_jp_trading_day）をここから渡す（investment_db側は祝日カレンダーを持たないため
    # 土日だけの簡易フォールバックしかできない）。
    try:
        is_business_day = is_jp_trading_day(datetime.date.fromisoformat(review_date))
    except (ValueError, TypeError):
        is_business_day = True
    review = investment_db.generate_daily_review(database_url, user_id, review_date, user_feedback=user_feedback,
                                                   is_business_day=is_business_day)

    sync_result = sync_trade_experiences_for_date(database_url, user_id, review_date)

    day_experiences = investment_db.list_trade_experiences(database_url, user_id, trade_date=review_date)
    symbols_today = sorted({e.get("symbol") for e in day_experiences if e.get("symbol") and e.get("side") != "WAIT"})
    behavior_updated = []
    for sym in symbols_today:
        try:
            profile = update_stock_behavior_profile(database_url, user_id, sym)
            if profile:
                behavior_updated.append({"symbol": sym, "sample_count": profile.get("sample_count"),
                                            "confidence_level": profile.get("confidence_level")})
        except Exception as e:
            print("  daily-review: stock behavior更新で例外（無視して続行）", sym, e)

    all_experiences = investment_db.list_trade_experiences(database_url, user_id, limit=1000)
    pattern_stats = compute_pattern_statistics(all_experiences)
    rule_candidates_proposed = propose_rule_candidates_from_pattern_stats(pattern_stats)

    # 判断品質と結果を分けて日次集計する（指示書6・7番）。今日の実トレード（WAIT以外）の
    # execution_score平均を「判断品質」、trade_result_score平均を「結果」として保存する——
    # 既存score_total（process quality寄りの既存5軸合計）は無変更のまま。
    today_trades = [e for e in day_experiences if e.get("side") != "WAIT"]
    exec_scores = [e["execution_score"] for e in today_trades if e.get("execution_score") is not None]
    result_scores = [e["trade_result_score"] for e in today_trades if e.get("trade_result_score") is not None]
    decision_quality_score = round(sum(exec_scores) / len(exec_scores), 1) if exec_scores else None
    trade_result_score = round(sum(result_scores) / len(result_scores), 1) if result_scores else None
    if review and (decision_quality_score is not None or trade_result_score is not None):
        try:
            investment_db.update_daily_review_learning_scores(database_url, user_id, review_date,
                                                                  decision_quality_score, trade_result_score)
        except Exception as e:
            print("  daily-review: decision_quality/trade_result保存で例外（無視して続行）", e)

    # Choruco Style / ちょる子式評価（2026-09-12新規、指示書39・40番）。既存score_total等の
    # 5軸評価とは別軸で100点満点、daily_reviews.choruco_score/choruco_breakdown_jsonへ保存する。
    choruco_result = None
    try:
        market_mode_today = compute_choruco_market_mode(database_url, user_id).get("mode")
        choruco_result = evaluate_choruco_daily_performance(market_mode_today, today_trades)
        if review:
            investment_db.update_daily_review_choruco_score(database_url, user_id, review_date,
                                                                choruco_result["total"], choruco_result)
    except Exception as e:
        print("  daily-review: choruco評価保存で例外（無視して続行）", e)

    if finalize:
        try:
            finalized_review = investment_db.mark_daily_review_finalized(database_url, user_id, review_date)
            if finalized_review:
                review = finalized_review  # 呼び出し元へ返す値をis_finalized/decision_quality等込みの最新状態にする
        except Exception as e:
            print("  daily-review: finalizeマークで例外（無視して続行）", e)

    return {
        "review": review, "sync": sync_result, "behaviorUpdated": behavior_updated,
        "patternCandidatesTracked": len(pattern_stats), "ruleCandidatesProposed": rule_candidates_proposed,
        "choruco": choruco_result, "tradeBreakdown": build_trade_breakdown_for_day(today_trades),
    }


def build_trade_breakdown_for_day(day_trades):
    """指示書5番：日次振り返りを損切り中心に強化——「損した＝悪い判断」にせず、トレードごとに
    ①entry_timing_score（エントリー判断）②exit_execution_score・risk_control_score（損切り判断）
    ③rule_compliance_score（ルール遵守）④trade_result_score（結果）を分離して表示できるよう、
    既存daily_reviewsの日次集計スコア（score_total等、無変更）とは別に、トレード単位の内訳を
    一覧として組み立てる（execution_score/score_breakdown_jsonはsync_trade_experiences_for_date
    内で既に自動採点済み、ここでは整形するだけ。DB永続化はしない——呼び出し側が都度
    trade_experiencesから読み直して再構成する設計）。day_trades：side!='WAIT'の
    trade_experiences行リスト（generate_daily_review_with_learning・GET /api/daily-reviewの
    両方から同じ関数を使う、二重実装を避ける）。"""
    trade_breakdown = []
    for e in (day_trades or []):
        bd = e.get("score_breakdown_json") or {}
        trade_breakdown.append({
            "symbol": e.get("symbol"), "stockName": e.get("stock_name"), "resultClass": e.get("result_class"),
            "grossPnlPct": e.get("gross_pnl_pct"),
            "entryTimingScore": bd.get("entry_timing_score"),
            "exitExecutionScore": bd.get("exit_execution_score"),
            "riskControlScore": bd.get("risk_control_score"),
            "ruleComplianceScore": bd.get("rule_compliance_score"),
            "tradeResultScore": e.get("trade_result_score"),
            # 損切りGOOD／問題はENTRY、を機械的に読み取れるよう明示する（指示書5番）。
            "exitWasGoodButEntryWasBad": (
                (bd.get("exit_execution_score") or 0) >= 15 and (bd.get("entry_timing_score") or 0) < 10
                if e.get("result_class") == "LOSS" else None
            ),
            "lossReasonTags": e.get("exit_reason_json") or [],
            "entryAvoidability": (e.get("post_trade_analysis_json") or {}).get("entry_avoidability"),
            "entryUnblockConditions": (e.get("post_trade_analysis_json") or {}).get("entry_unblock_conditions") or [],
        })
    return trade_breakdown


def plan_unconfirmed_position_cleanup(database_url, user_id, code, market):
    """未約定ポジション削除連動（2026-09-16新規、指示書1・2・3・13番）：portfolio行を削除する
    "前"に呼ぶ判定専用関数（DB書き込みは一切しない）。list_portfolio()はまだ削除されていない
    行を必要とするため、必ず投稿delete_portfolio_item()より前に呼ぶこと（実際の再生成は
    apply_unconfirmed_position_cleanup()が削除"後"に行う——generate_daily_review_with_learning()
    はlist_portfolio()の「今この瞬間」の状態を読むため、削除前に再生成すると削除される行が
    まだ残ったまま再計算されてしまうバグを直接テストで発見した経緯がある。必ずこの2関数を
    delete_portfolio_item()を挟んでこの順で呼ぶこと）。
    「実際に売買したトレードは絶対に消さない」を最優先に、以下の条件を"すべて"満たす場合だけ
    shouldRegenerate=Trueを返す：
      ①削除される建玉のacquired_at時点の日付に、既にdaily_reviewsが生成済み
      ②その銘柄について、その日付をacquired_at〜closed_atの範囲に含むtrade_history行が
        1件も無い（＝約定を伴う確定売買が既存データ上に存在しない）
    trade_history側にすでに行がある「実際に売買して損切り・利確した」ケースは②で除外される
    ため、既存のtrade_history/trade_experiencesを一切変更・削除しない（再生成はdaily_reviews
    の再計算のみ、既存portfolio/trade_history/trade_experiencesスキーマは無変更＝二重schemaを
    作らない、指示書の方針通り）。"""
    plan = {"shouldRegenerate": False, "reviewDate": None, "wasFinalized": False, "reason": None}
    if investment_db is None or not database_url or not code:
        plan["reason"] = "no_db"
        return plan
    try:
        positions = investment_db.list_portfolio(database_url, user_id)
    except Exception as e:
        print("  plan_unconfirmed_position_cleanup: portfolio取得で例外", code, e)
        plan["reason"] = f"portfolio_fetch_failed: {e}"
        return plan
    pos = next((p for p in positions if p.get("code") == code and (p.get("market") or "JP") == (market or "JP")), None)
    if not pos:
        plan["reason"] = "position_not_found"
        return plan
    acquired_date = investment_db._to_jst_date_str(pos.get("acquired_at") or pos.get("created_at"))
    if not acquired_date:
        plan["reason"] = "no_acquired_date"
        return plan
    try:
        existing_review = investment_db.get_daily_review(database_url, user_id, acquired_date)
    except Exception as e:
        print("  plan_unconfirmed_position_cleanup: daily_review取得で例外", code, e)
        plan["reason"] = f"review_fetch_failed: {e}"
        return plan
    if not existing_review:
        plan["reason"] = "no_existing_review"
        return plan
    try:
        history = investment_db.list_trade_history(database_url, user_id, limit=1000)
    except Exception as e:
        print("  plan_unconfirmed_position_cleanup: trade_history取得で例外", code, e)
        plan["reason"] = f"history_fetch_failed: {e}"
        return plan
    confirmed = any(
        t.get("code") == code
        and investment_db._to_jst_date_str(t.get("acquired_at")) and investment_db._to_jst_date_str(t.get("acquired_at")) <= acquired_date
        and (investment_db._to_jst_date_str(t.get("closed_at")) or "9999-12-31") >= acquired_date
        for t in history
    )
    if confirmed:
        plan["reason"] = "confirmed_trade_exists"
        return plan
    plan["shouldRegenerate"] = True
    plan["reviewDate"] = acquired_date
    plan["wasFinalized"] = bool(existing_review.get("is_finalized"))
    plan["reason"] = "unconfirmed_position_pending_delete"
    return plan


def apply_unconfirmed_position_cleanup(database_url, user_id, plan):
    """未約定ポジション削除連動：delete_portfolio_item()の"後"に呼ぶ。plan_unconfirmed_
    position_cleanup()の判定に従い、shouldRegenerate=Trueの場合のみdaily_reviewsを
    再生成する（削除後なので、対象銘柄は再生成時のlist_portfolio()にもう含まれない）。"""
    if not plan or not plan.get("shouldRegenerate"):
        return {"triggered": False, "reviewDate": (plan or {}).get("reviewDate"), "reason": (plan or {}).get("reason")}
    review_date = plan["reviewDate"]
    try:
        generate_daily_review_with_learning(database_url, user_id, review_date, finalize=plan.get("wasFinalized", False))
        print(f"  [PositionCleanup] 未約定ポジション削除連動：acquired_date={review_date} のdaily_reviewを再生成しました")
        return {"triggered": True, "reviewDate": review_date, "reason": "unconfirmed_position_removed"}
    except Exception as e:
        print("  apply_unconfirmed_position_cleanup: 再生成で例外", review_date, e)
        return {"triggered": False, "reviewDate": review_date, "reason": f"regenerate_failed: {e}"}


# 15:30自動評価スケジューラ（指示書4・5・11・28・29・30番）。既存_morning_check_scheduler_loop
# と全く同じ設計（60秒間隔でJST時刻をチェック、平日のみ、プロセス内fired集合＋DBのUNIQUE
# 制約の二重防御）を踏襲する。15:30ちょうどには終値等が未確定な場合があるため、15:30〜15:35の
# 間は30秒間隔で細かくリトライし、15:35時点でその時点のデータのまま確定（finalize）する。
DAILY_REVIEW_SCHEDULE_HHMM = "15:30"
DAILY_REVIEW_RETRY_DEADLINE_HHMM = "15:35"


def _daily_review_scheduler_users():
    """定時生成の対象ユーザー一覧（_morning_check_scheduler_users()と同じ考え方）。"""
    if USERS:
        return list(USERS.keys())
    return ["matsuura"]


def _daily_review_data_looks_complete(database_url, user_id):
    """当日終値・高値/安値・出来高が確定しているかの簡易判定（指示書4番）。厳密な「取引所
    公式の確定値フラグ」は無いため、既存の共有Stage1（run_momentum_stage1）が当日データを
    保持しているかで代用する——全滅（scanFailed）の場合のみ「未確定/取得失敗」として扱い、
    それ以外は「取得できている」とみなして確定させる（既知の制約、無限リトライはしない）。"""
    try:
        stage1 = run_momentum_stage1()
        return not stage1.get("scanFailed")
    except Exception:
        return False


def _daily_review_notify_ready(user_id, review_date, result):
    """完了通知（指示書8番）のためのプロセス内キュー。フロントは/api/daily-review/latestを
    ポーリングして generated_at の変化を検知するため、ここではログ出力のみでよい
    （新規のWebSocket/push基盤は追加しない、既存のポーリング中心の設計に合わせる）。"""
    review = (result or {}).get("review") or {}
    print(f"  [DailyReview] {user_id} {review_date} 確定完了。投資スコア{review.get('score_total')}点"
          f"（trades_synced={result.get('sync', {}).get('trades_synced')}・"
          f"waits_synced={result.get('sync', {}).get('waits_synced')}・"
          f"behaviorUpdated={len(result.get('behaviorUpdated', []))}銘柄）")


def _daily_review_scheduler_loop():
    """毎営業日15:30の引け後に当日評価を必ず自動実行するデーモンスレッド（指示書4番）。
    15:30〜15:35の間、30秒間隔でデータ完成を確認しながらリトライし（指示書「30秒～60秒間隔で
    再取得、最大15:35までリトライ」）、15:35時点でその時点のデータのまま確定保存する。
    silent failure禁止（指示書11番）——生成に失敗してもログへ明示し、次のポーリングで再試行、
    最終的にis_finalizedが立たなければフロント側の手動[再実行]（既存POST /api/daily-review/
    generate）で救済できる。冪等性はsync_key・(user_id,review_date)のUNIQUE制約が最終防衛線。"""
    finalized_today = set()  # {(review_date, user_id)}
    JST = datetime.timezone(datetime.timedelta(hours=9))
    while True:
        try:
            now_jst = datetime.datetime.now(JST)
            hhmm = now_jst.strftime("%H:%M")
            if _is_jp_market_business_day(now_jst) and DAILY_REVIEW_SCHEDULE_HHMM <= hhmm <= DAILY_REVIEW_RETRY_DEADLINE_HHMM:
                review_date = now_jst.date().isoformat()
                for user_id in _daily_review_scheduler_users():
                    key = (review_date, user_id)
                    if key in finalized_today:
                        continue
                    data_complete = _daily_review_data_looks_complete(DATABASE_URL, user_id)
                    at_deadline = hhmm >= DAILY_REVIEW_RETRY_DEADLINE_HHMM
                    if not data_complete and not at_deadline:
                        continue  # まだ未確定・締切前 → 次の30秒ポーリングで再試行
                    try:
                        result = generate_daily_review_with_learning(DATABASE_URL, user_id, review_date, finalize=True)
                        finalized_today.add(key)
                        _daily_review_notify_ready(user_id, review_date, result)
                    except Exception as e:
                        print(f"  [DailyReview] {user_id} {review_date} 15:30自動評価に失敗（次回ポーリングで再試行）", e)
                if len(finalized_today) > 200:
                    finalized_today = {k for k in finalized_today if k[0] == now_jst.date().isoformat()}
        except Exception as e:
            print("  [DailyReview] スケジューラループで例外", e)
        time.sleep(30)


# ============================================================
# Choruco Style / ちょる子式（2026-09-12新規）。既存ENTRY SCORE・Rule Engine・
# Trade Experience Learning・15:30 Daily Reviewには一切変更を加えず、その上に積む補助判断
# レイヤーとして追加する。AIが勝手にACTIVEルールを書き換えることはない（既存
# upsert_trade_rule_from_text/_evaluate_rule_promotionは経由しない）。既存ルールとの矛盾が
# ある場合は既存ルールを優先——本レイヤーの各関数は「表示・提案」のみを行い、既存の
# entry_score/entry_state/ACTIVEルールの判定結果そのものを書き換えることはない。
# ============================================================

# ---- MARKET MODE（指示書1〜5番） ----
CHORUCO_MODE_ATTACK_THRESHOLD = 75
CHORUCO_MODE_NORMAL_THRESHOLD = 45
CHORUCO_MODE_SCORE_WEIGHTS = {
    "us_market": 20, "japan_breadth": 20, "sector_rotation": 15, "volatility": 15,
    "rates_fx": 10, "entry_quality": 10, "event_risk": 10,
}


def build_choruco_market_mode(us_market_score, japan_breadth_score, sector_rotation_score,
                                volatility_score, rates_fx_score, entry_quality_score, event_risk_score,
                                force_defense_reasons=None):
    """指示書3・4番：CHORUCO_MODE（ATTACK/NORMAL/DEFENSE）を100点満点の加重合計から決める
    純粋関数（各サブスコアは0-100、呼び出し側で正規化済みの値を渡す）。
    配点：US market/futures20・Japan breadth20・sector rotation15・volatility15・rates/FX10・
    entry candidate quality10・event risk10＝100。
    force_defense_reasonsが非空なら、指示書5番によりスコアに関係なくDEFENSEにする。"""
    subscores = {"us_market": us_market_score, "japan_breadth": japan_breadth_score,
                 "sector_rotation": sector_rotation_score, "volatility": volatility_score,
                 "rates_fx": rates_fx_score, "entry_quality": entry_quality_score,
                 "event_risk": event_risk_score}
    total = sum((subscores[k] or 0) * w / 100 for k, w in CHORUCO_MODE_SCORE_WEIGHTS.items())
    total = round(max(0.0, min(100.0, total)), 1)
    force_defense = bool(force_defense_reasons)
    if force_defense:
        mode = "DEFENSE"
    elif total >= CHORUCO_MODE_ATTACK_THRESHOLD:
        mode = "ATTACK"
    elif total >= CHORUCO_MODE_NORMAL_THRESHOLD:
        mode = "NORMAL"
    else:
        mode = "DEFENSE"
    dist_from_boundary = min(abs(total - CHORUCO_MODE_NORMAL_THRESHOLD), abs(total - CHORUCO_MODE_ATTACK_THRESHOLD))
    confidence = "HIGH" if (force_defense or dist_from_boundary >= 15) else ("MEDIUM" if dist_from_boundary >= 5 else "LOW")
    # 指示書3番のpositive_factors/negative_factors：各軸が中央値(50)より高いか低いかで
    # 機械的にラベル化する（恣意的な固定文言リストを作らない、閾値50は「平均的な地合い」の目安）。
    axis_labels = {"us_market": "US market/futures", "japan_breadth": "Japan market breadth",
                    "sector_rotation": "sector rotation", "volatility": "volatility (inverse)",
                    "rates_fx": "rates/FX stability", "entry_quality": "entry candidate quality",
                    "event_risk": "event safety"}
    positive_factors = [axis_labels[k] for k, v in subscores.items() if (v or 0) >= 60]
    negative_factors = [axis_labels[k] for k, v in subscores.items() if (v or 0) < 40]
    event_penalty = round(max(0, 10 - (subscores.get("event_risk") or 10) / 10), 1)
    risk_penalty = round(max(0, 10 - (subscores.get("entry_quality") or 10) / 10), 1)
    return {
        "mode": mode, "score": total, "confidence": confidence,
        "positive_factors": positive_factors, "negative_factors": negative_factors,
        "event_penalty": event_penalty, "risk_penalty": risk_penalty,
        "force_defense": force_defense, "force_defense_reasons": list(force_defense_reasons or []),
        "subscores": subscores,
        "updated_at": datetime.datetime.now(datetime.timezone.utc).isoformat(),
    }


def detect_choruco_force_defense(vix_value=None, vix_prev=None, nikkei_futures_chg=None, sox_chg=None,
                                    kospi_chg=None, usdjpy_chg=None, crude_chg=None, event_risk_level=None,
                                    failed_break_ratio=None):
    """指示書5番：強制DEFENSE条件。該当した理由のリストを返す（空＝該当なし）。
    スコアに関係なくDEFENSEへ強制する材料——恣意的な閾値だが、いずれも「急変」を検知する
    ための単純な変化率しきい値であり、将来調整しやすいよう定数化はせず素直な数値のまま
    書く（他のCHORUCO定数と異なり、この関数だけの局所的な閾値のため）。"""
    reasons = []
    if event_risk_level == "EXTREME":
        reasons.append("重要イベントが極めて近い（EXTREME）")
    if vix_value is not None and vix_prev and vix_value >= vix_prev * 1.15:
        reasons.append("VIX急騰")
    if nikkei_futures_chg is not None and nikkei_futures_chg <= -2.0:
        reasons.append("日経先物急落")
    if sox_chg is not None and sox_chg <= -3.0:
        reasons.append("SOX急落")
    if kospi_chg is not None and kospi_chg <= -3.0:
        reasons.append("KOSPI急落（サーキットブレーカー級）")
    if usdjpy_chg is not None and abs(usdjpy_chg) >= 2.0:
        reasons.append("USDJPY急変")
    if crude_chg is not None and crude_chg >= 5.0:
        reasons.append("原油急騰")
    if failed_break_ratio is not None and failed_break_ratio >= 0.5:
        reasons.append("市場全体でFAILED BREAK急増")
    return reasons


def _choruco_scale_centered(value, center, spread, invert=False):
    """変化率等の実測値を0-100スコアへ変換する共通ヘルパー。centerを50点とし、spread
    （プラス/マイナス片側の幅）でクランプする。invert=Trueは値が大きいほど悪い指標
    （VIX等）用。"""
    if value is None:
        return 50.0
    z = (value - center) / spread if spread else 0
    score = 50 + z * 50
    if invert:
        score = 100 - score
    return round(max(0.0, min(100.0, score)), 1)


CHORUCO_MARKET_MODE_CACHE_TTL = 20  # 指示書61番「market_mode:10〜30秒」


def compute_choruco_market_mode_cached(database_url, user_id):
    """compute_choruco_market_mode()をCHORUCO_MARKET_MODE_CACHE_TTL秒でラップする。
    FAST UPDATE（10秒間隔・銘柄ごと）から呼ばれても、実際の指数取得・ENTRY候補再計算は
    このTTLごとに1回で済む（指示書59番「重い計算は禁止」）。"""
    key = f"choruco_mode:{user_id}"
    entry = _cache_get(key)
    if _cache_fresh(entry, CHORUCO_MARKET_MODE_CACHE_TTL):
        return entry["value"]
    value = compute_choruco_market_mode(database_url, user_id)
    _cache_set(key, value)
    return value


def compute_choruco_market_mode(database_url, user_id):
    """CHORUCO_MODEのI/Oラッパー。既存の_fetch_index_snapshot（indexキャッシュ、TTL45秒＝
    指示書61番「market_mode:10〜30秒」相当を既存キャッシュで代用、新規の重い取得経路は
    追加しない）・_score_entry_candidates（ENTRY READY/RISK等のカウントは.debugを再利用）・
    upcoming_event_signalsをそのまま使う。"""
    empty = {"mode": "NORMAL", "score": 50.0, "confidence": "LOW", "positive_factors": [],
              "negative_factors": [], "event_penalty": 0, "risk_penalty": 0, "force_defense": False,
              "force_defense_reasons": [], "subscores": {}, "updated_at": None}
    idx = _fetch_index_snapshot(["nikkei", "topix_etf", "growth250_etf", "nikkei_fut", "nasdaq", "sox",
                                    "kospi", "vix", "us10y", "usdjpy", "wti"])

    def chg(key):
        return (idx.get(key) or {}).get("changePct")

    us_market_score = round((_choruco_scale_centered(chg("nasdaq"), 0, 1.5) +
                              _choruco_scale_centered(chg("sox"), 0, 2.5)) / 2, 1)
    japan_breadth_score = round((_choruco_scale_centered(chg("nikkei"), 0, 1.0) +
                                  _choruco_scale_centered(chg("topix_etf"), 0, 1.0) +
                                  _choruco_scale_centered(chg("growth250_etf"), 0, 1.5) +
                                  _choruco_scale_centered(chg("nikkei_fut"), 0, 1.0)) / 4, 1)
    volatility_score = _choruco_scale_centered(idx.get("vix", {}).get("value"), 18, 8, invert=True)
    rates_fx_score = round((_choruco_scale_centered(chg("us10y"), 0, 3.0, invert=True) +
                             _choruco_scale_centered(chg("usdjpy"), 0, 1.0)) / 2, 1)

    entry_quality_score, event_risk_score = 50.0, 50.0
    try:
        sector_flow = compute_choruco_sector_flow(database_url, user_id)
        sectors = sector_flow.get("sectors", [])
        n_sectors = len(sectors) or 1
        strong = sum(1 for s in sectors if s["flow"] == "STRONG")
        weak = sum(1 for s in sectors if s["flow"] == "WEAKENING")
        sector_rotation_score = round(50 + (strong - weak) / n_sectors * 50, 1)
    except Exception as e:
        print("  choruco: sector flow取得で例外（無視して続行）", e)
        sector_rotation_score = 50.0
    # 指示書59・61番「重い計算は禁止」：_score_entry_candidates()（Stage2・5分足スナップショットを
    # 監視銘柄全件に対して取得する重い処理、TOP5表示ロジック修正で判明した通り数百銘柄規模だと
    # 数分かかることがある）は呼ばない。市場モードは既に取得済みのStage1（共有キャッシュ）
    # だけから安く近似する——「対象市場全体でプラス圏＆対市場優位な銘柄の比率」を
    # entry candidate qualityの代理指標とし、「大幅安（-3%以下）の比率」をfailed_break_ratioの
    # 代理指標とする。
    failed_break_ratio = None
    try:
        stage1 = run_momentum_stage1()
        stage1_rows = list(stage1.get("rows", {}).values())
        watchlist_codes = {w.get("code") for w in
                            (investment_db.list_watchlist(database_url, user_id, market="JP")
                             if (investment_db is not None and database_url) else [])}
        relevant_rows = [r for r in stage1_rows if r.get("code") in watchlist_codes] if watchlist_codes else stage1_rows
        n = len(relevant_rows)
        if n:
            strong_candidates = sum(1 for r in relevant_rows
                                      if (r.get("changePct") or 0) > 0 and (r.get("marketRS") or 0) > 0)
            failed_break_count = sum(1 for r in relevant_rows if (r.get("changePct") or 0) <= -3)
            entry_quality_score = round(min(100.0, strong_candidates / n * 300), 1)
            failed_break_ratio = failed_break_count / n
    except Exception as e:
        print("  choruco: entry candidate quality簡易算出で例外（無視して続行）", e)

    event_risk_level = "LOW"
    try:
        events_info = investment_db.upcoming_event_signals(database_url, user_id) if (investment_db and database_url) else {"events": []}
        events_with_hours = [{"importance": e.get("importance"),
                                "hours_to_event": e.get("business_days_until", 0) * 24}
                               for e in events_info.get("events", [])]
        event_risk_level = compute_event_risk_for_events(events_with_hours)
        event_risk_score = {"LOW": 90.0, "MEDIUM": 65.0, "HIGH": 35.0, "EXTREME": 5.0}[event_risk_level]
    except Exception as e:
        print("  choruco: event risk取得で例外（無視して続行）", e)

    force_reasons = detect_choruco_force_defense(
        vix_value=idx.get("vix", {}).get("value"), nikkei_futures_chg=chg("nikkei_fut"),
        sox_chg=chg("sox"), kospi_chg=chg("kospi"), usdjpy_chg=chg("usdjpy"), crude_chg=chg("wti"),
        event_risk_level=event_risk_level, failed_break_ratio=failed_break_ratio)

    result = build_choruco_market_mode(us_market_score, japan_breadth_score, sector_rotation_score,
                                          volatility_score, rates_fx_score, entry_quality_score, event_risk_score,
                                          force_defense_reasons=force_reasons)
    result["event_risk_level"] = event_risk_level
    return result


# ---- EVENT RISK（指示書6〜8番） ----
CHORUCO_EVENT_RISK_LOT_MULTIPLIER = {"LOW": 1.00, "MEDIUM": 0.75, "HIGH": 0.50, "EXTREME": 0.25}
CHORUCO_CRITICAL_EVENT_KEYWORDS = ("FOMC", "日銀", "BOJ", "CPI", "雇用統計", "NFP", "ECB", "PCE")


def classify_event_risk_level(hours_to_event, importance=None, title=None):
    """指示書6・7番：EVENT_RISK_LEVEL（LOW/MEDIUM/HIGH/EXTREME）。>48h LOW / 24-48h MEDIUM /
    6-24h HIGH / <6h EXTREMEが基本。FOMC/CPI/雇用統計等の重要イベント（重み付け、指示書7番
    「ただしイベント種類により重み付け」）はcritical判定または件名一致で1段階厳しくする。"""
    if hours_to_event is None:
        return "LOW"
    if hours_to_event > 48:
        base = "LOW"
    elif hours_to_event > 24:
        base = "MEDIUM"
    elif hours_to_event > 6:
        base = "HIGH"
    else:
        base = "EXTREME"
    is_critical = (importance or "").lower() == "critical" or \
        any(kw in (title or "") for kw in CHORUCO_CRITICAL_EVENT_KEYWORDS)
    if is_critical:
        order = ["LOW", "MEDIUM", "HIGH", "EXTREME"]
        base = order[min(order.index(base) + 1, len(order) - 1)]
    return base


def compute_event_risk_for_events(events_with_hours):
    """複数イベントのうち最も厳しいレベルを採用する。"""
    order = {"LOW": 0, "MEDIUM": 1, "HIGH": 2, "EXTREME": 3}
    levels = [classify_event_risk_level(e.get("hours_to_event"), e.get("importance"), e.get("title"))
              for e in (events_with_hours or [])]
    if not levels:
        return "LOW"
    return max(levels, key=lambda l: order[l])


def event_risk_lot_multiplier(event_risk_level):
    """指示書8番：イベント前ロット縮小。LOW1.00/MEDIUM0.75/HIGH0.50/EXTREME0.25。"""
    return CHORUCO_EVENT_RISK_LOT_MULTIPLIER.get(event_risk_level, 1.0)


# ---- SECTOR FLOW（指示書27〜28番） ----

def classify_sector_flow_label(vs_market):
    """指示書27番：CHORUCO_SECTOR_FLOW。セクター対市場（vsMarket、既存_compute_sector_stats
    と同じ定義）からSTRONG/NEUTRAL/WEAKENINGを機械的にラベル化する。"""
    if vs_market is None:
        return "NEUTRAL"
    if vs_market >= 1.0:
        return "STRONG"
    if vs_market <= -1.0:
        return "WEAKENING"
    return "NEUTRAL"


def compute_choruco_sector_flow(database_url, user_id):
    """指示書27番：CHORUCO_SECTOR_FLOW。既存_compute_sector_stats()（AUTO_SECTOR_LEADERの
    セクター集計と共有、run_momentum_stage1のキャッシュに従属）をそのまま再利用する
    （新規の全市場再集計はしない）。"""
    stage1 = run_momentum_stage1()
    nikkei_chg = stage1.get("nikkeiChangePct")
    stats = _compute_sector_stats(stage1, nikkei_chg)
    sectors = []
    for sector, avg in stats["avg"].items():
        vs_market = stats["vsMarket"].get(sector)
        sectors.append({"sector": sector, "avgChangePct": round(avg, 2),
                          "vsMarket": round(vs_market, 2) if vs_market is not None else None,
                          "rank": stats["rank"].get(sector), "flow": classify_sector_flow_label(vs_market)})
    sectors.sort(key=lambda s: s["rank"] or 999)
    return {"sectors": sectors, "updated_at": datetime.datetime.now(datetime.timezone.utc).isoformat()}


# ---- CHORUCO FIT（指示書53・54番） ----
CHORUCO_FIT_MODE_POINTS = {"ATTACK": 3, "NORMAL": 2, "DEFENSE": 1}
CHORUCO_FIT_SECTOR_POINTS = {"STRONG": 2, "NEUTRAL": 1, "WEAKENING": 0}
CHORUCO_FIT_EVENT_POINTS = {"LOW": 2, "MEDIUM": 1, "HIGH": 0.5, "EXTREME": 0}


def compute_choruco_fit(market_mode, sector_flow_label, event_risk_level, story_score=None, price_action_ok=True):
    """指示書53・54番：CHORUCO FIT 0-10。market_mode fit3+sector flow fit2+event safety2+
    story quality2+price action1＝10。既存ENTRY SCOREには一切影響しない補助スコア。"""
    mode_fit = CHORUCO_FIT_MODE_POINTS.get(market_mode, 1)
    sector_fit = CHORUCO_FIT_SECTOR_POINTS.get(sector_flow_label, 1)
    event_fit = CHORUCO_FIT_EVENT_POINTS.get(event_risk_level, 1)
    story_fit = 2 if (story_score or 0) >= 60 else (1 if (story_score or 0) >= 40 else 0)
    price_fit = 1 if price_action_ok else 0
    return round(mode_fit + sector_fit + event_fit + story_fit + price_fit, 1)


def compute_choruco_stock_view(database_url, user_id, symbol, sector=None):
    """GET /api/choruco/stock/{symbol}向けの統合ビュー。市場モード・セクターフロー・
    イベントリスク・ストーリー・CHORUCO FIT・推奨ロット倍率をまとめて返す。"""
    market_mode_result = compute_choruco_market_mode_cached(database_url, user_id)
    sector_flow = compute_choruco_sector_flow(database_url, user_id)
    sector_label = next((s["flow"] for s in sector_flow.get("sectors", []) if s["sector"] == sector), "NEUTRAL") \
        if sector else "NEUTRAL"
    event_risk_level = market_mode_result.get("event_risk_level", "LOW")
    if investment_db is not None and database_url:
        try:
            events_info = investment_db.upcoming_event_signals(database_url, user_id, code=symbol, sector=sector)
            events_with_hours = [{"importance": e.get("importance"), "hours_to_event": e.get("business_days_until", 0) * 24,
                                    "title": e.get("title")} for e in events_info.get("events", [])]
            event_risk_level = compute_event_risk_for_events(events_with_hours)
        except Exception as e:
            print("  choruco: 銘柄別イベントリスク取得で例外（無視して続行）", symbol, e)
    story = None
    if investment_db is not None and database_url:
        try:
            story = investment_db.get_latest_choruco_story(database_url, user_id, symbol)
        except Exception as e:
            print("  choruco: story取得で例外（無視して続行）", symbol, e)
    story_score = (story or {}).get("story_score")
    choruco_fit = compute_choruco_fit(market_mode_result["mode"], sector_label, event_risk_level, story_score)
    multiplier = compute_choruco_position_multiplier(market_mode_result["mode"], event_risk_level)
    return {
        "symbol": symbol, "market_mode": market_mode_result["mode"],
        "market_mode_score": market_mode_result["score"], "sector_flow": sector_label,
        "event_risk_level": event_risk_level, "story": story, "choruco_fit": choruco_fit,
        "position_multiplier": multiplier,
    }


# ---- POSITION SIZE MULTIPLIER（指示書9〜12番） ----
CHORUCO_MODE_BASE_MULTIPLIER = {"ATTACK": 1.00, "NORMAL": 0.70, "DEFENSE": 0.50}  # 指示書9・11番の例（DEFENSE x0.5=100株、NORMAL x0.7）に合わせる
CHORUCO_STOCK_RISK_MULTIPLIERS = {
    "MOMENTUM_STOCK": 0.5, "HIGH_VOLATILITY": 0.6, "LOW_LIQUIDITY": 0.5,
    "EVENT_BEFORE_EARNINGS": 0.5, "CHASE_RISK": 0.25, "FAILED_BREAK": 0.0,
}


def compute_choruco_position_multiplier(market_mode, event_risk_level, stock_risk_tags=None):
    """指示書9・10番：最終ロット倍率＝base(mode)×event_risk×個別リスク。複数の個別リスクが
    該当する場合は最も厳しい（最小）倍率を採用する（単純な掛け算の複合による過度な
    ペナルティを避ける——例えばMOMENTUM_STOCK(0.5)とHIGH_VOLATILITY(0.6)が両方該当しても
    0.5×0.6=0.3ではなくmin=0.5を採用）。既存ENTRY SCOREには一切影響しない。"""
    base = CHORUCO_MODE_BASE_MULTIPLIER.get(market_mode, 0.5)
    event_mult = event_risk_lot_multiplier(event_risk_level)
    applicable = [CHORUCO_STOCK_RISK_MULTIPLIERS[t] for t in (stock_risk_tags or []) if t in CHORUCO_STOCK_RISK_MULTIPLIERS]
    stock_mult = min(applicable) if applicable else 1.0
    return round(max(0.0, min(1.0, base * event_mult * stock_mult)), 3)


def round_position_size_to_lot(calculated_shares, lot_size=100):
    """指示書12番：SBI 100株単位対応。切り捨てで単元株に丸める（160→100、240→200）。"""
    if calculated_shares is None or calculated_shares <= 0:
        return 0
    return int(calculated_shares // lot_size) * lot_size


def compute_choruco_final_position_size(base_position_size, market_mode, event_risk_level,
                                            stock_risk_tags=None, lot_size=100):
    """指示書11番：最終ロット計算。指示書8番「EXTREME: 0.25 or NO ENTRY」は、より安全側の
    解釈として「DEFENSEモード×EXTREMEイベント」の組み合わせのみNO ENTRY（0株）に倒し、
    それ以外のEXTREME（ATTACK/NORMAL下でのEXTREME接近）は0.25倍数として計算する
    （どちらの解釈も指示書の記述と矛盾しないため、より保守的な方を選択）。
    戻り値：(final_shares, multiplier)。"""
    multiplier = compute_choruco_position_multiplier(market_mode, event_risk_level, stock_risk_tags)
    if event_risk_level == "EXTREME" and market_mode == "DEFENSE":
        return 0, multiplier
    raw = (base_position_size or 0) * multiplier
    return round_position_size_to_lot(raw, lot_size), multiplier


def derive_choruco_stock_risk_tags(entry_state=None, volume_type=None, days_to_earnings=None,
                                      liquidity_low=False, volatility_score=None):
    """既存の軽量スナップショット（compute_light_trade_analysis_snapshot等）が既に持っている
    値だけからCHORUCO_STOCK_RISK_MULTIPLIER用のタグを導出する（新規の重い判定は追加しない）。"""
    tags = []
    if volume_type == "CLIMAX_UP":
        tags.append("MOMENTUM_STOCK")
    if entry_state == "CHASE_RISK":
        tags.append("CHASE_RISK")
    if volatility_score is not None and volatility_score >= 70:
        tags.append("HIGH_VOLATILITY")
    if liquidity_low:
        tags.append("LOW_LIQUIDITY")
    if days_to_earnings is not None and 0 <= days_to_earnings <= 2:
        tags.append("EVENT_BEFORE_EARNINGS")
    return tags


# ---- STORY ENGINE（指示書13〜17番） ----
CHORUCO_STORY_SCORE_WEIGHTS = {
    "market_alignment": 15, "sector_alignment": 15, "technical_setup": 20, "volume_confirmation": 15,
    "relative_strength": 15, "event_safety": 10, "risk_reward": 10,
}


def compute_story_score(components):
    """指示書14番：STORY SCORE 0-100（componentsは各軸0-100、欠損キーは0点扱い）。"""
    total = sum((components or {}).get(k, 0) * w / 100 for k, w in CHORUCO_STORY_SCORE_WEIGHTS.items())
    return round(max(0.0, min(100.0, total)), 1)


def detect_story_break(story, current_snapshot):
    """指示書15番：ストーリー崩れの軽量検知（FAST UPDATE、5〜10秒間隔から呼ばれる想定、
    重い計算はしない）。storyは{"support":..,"market_mode_at_entry":..}等（TRADE_STORY、
    指示書13番）、current_snapshotはFAST UPDATEスナップショット
    （price/vwap/short_ma/entry_state/market_mode等）。戻り値：崩れ理由のリスト（空＝崩れなし）。"""
    story = story or {}
    snap = current_snapshot or {}
    reasons = []
    price = snap.get("price")
    support = story.get("support")
    if support is not None and price is not None and price < support:
        reasons.append("support割れ")
    if snap.get("vwap") is not None and price is not None and price < snap["vwap"]:
        reasons.append("VWAP割れ")
    if snap.get("short_ma") is not None and price is not None and price < snap["short_ma"]:
        reasons.append("短期MA割れ")
    if snap.get("entry_state") == "CHASE_RISK":
        reasons.append("breakout失敗（高値掴みリスク化）")
    if snap.get("entry_state") in ("WEAK", "INVALID"):
        reasons.append("RS急低下・根拠崩れ")
    if snap.get("market_mode") == "DEFENSE" and story.get("market_mode_at_entry") != "DEFENSE":
        reasons.append("地合いDEFENSE化")
    # Cross-Market Link Phase 2新規（指示書9番）：ENTRY時点のprimary driverが急落し、かつ
    # ENTRY時点と同じ相関方向が続いている場合に崩れ条件へ追加する（既存のstory崩れ判定は
    # 無変更、追加条件のみ）。
    primary_driver = story.get("primary_driver")
    driver_corr = story.get("driver_corr")
    cm = snap.get("cross_market") or {}
    if primary_driver and cm.get("primary_driver") == primary_driver:
        driver_change = cm.get("driver_recent_change_pct")
        direction = cm.get("direction") or ("POSITIVE" if (driver_corr or 0) >= 0 else "NEGATIVE")
        if driver_change is not None:
            adverse = (direction == "POSITIVE" and driver_change <= -CROSS_MARKET_LEADING_ALERT_MIN_DRIVER_CHANGE) or \
                      (direction == "NEGATIVE" and driver_change >= CROSS_MARKET_LEADING_ALERT_MIN_DRIVER_CHANGE)
            if adverse:
                reasons.append(f"{primary_driver}急変（連動崩れ）")
    # Sector Rotation Engine新規（指示書24番）：ENTRY時点のsector_stateがLEADING/IMPROVING
    # だったのに、現在WEAKENING/LAGGINGへ悪化していれば崩れ条件へ追加する（既存の判定は無変更、
    # 追加条件のみ）。
    sector_state_at_entry = story.get("sector_state_at_entry")
    current_sector_state = (snap.get("sector_rotation") or {}).get("state")
    if sector_state_at_entry in ("LEADING", "IMPROVING") and current_sector_state in ("WEAKENING", "LAGGING"):
        reasons.append(f"セクター弱化（{sector_state_at_entry}→{current_sector_state}）")
    # Yaaman Style新規（指示書33番）：ENTRY時点のtheme_stageがEXPANDING（またはEARLY）
    # だったのに、現在EXHAUSTINGへ悪化していれば崩れ条件へ追加する（既存の判定は無変更、
    # 追加条件のみ）。
    theme_stage_at_entry = story.get("theme_stage")
    current_theme_stage = (snap.get("theme") or {}).get("stage")
    if theme_stage_at_entry in ("EARLY", "EXPANDING") and current_theme_stage == "EXHAUSTING":
        reasons.append(f"テーマ失速（{theme_stage_at_entry}→EXHAUSTING）")
    return reasons


def classify_story_status(score, break_reasons=None):
    """指示書16番：ACTIVE/WEAKENING/BROKEN。break_reasonsが1件でもあれば、スコアが高くても
    即BROKEN扱いにする（指示書15番の崩れ条件は「明確な条件崩れ」であり、スコアの緩やかな
    低下とは別に即時反映すべきため）。"""
    if break_reasons:
        return "BROKEN"
    if score is None:
        return "WEAKENING"
    if score >= 60:
        return "ACTIVE"
    if score >= 40:
        return "WEAKENING"
    return "BROKEN"


# ---- PRICE ACTION OVERRIDE / GOOD_NEWS_WEAK_PRICE（指示書29〜31番） ----

def detect_good_news_weak_price(catalyst_sentiment, relative_strength, volume_type):
    """指示書29・31番：材料出尽くし・「良い材料なのに上がらない」検知。ポジティブ材料＋
    相対的弱さ＋売り出来高の3条件が揃った場合のみ検知する（単独では判定しない、
    指示書「これは重要な弱気シグナル」）。"""
    if catalyst_sentiment != "positive":
        return False
    if relative_strength is None or relative_strength >= 0:
        return False
    if volume_type not in ("NEGATIVE_VOLUME", "CLIMAX_DOWN"):
        return False
    return True


def apply_price_action_override(fundamental_signal, price_action_signal):
    """指示書30番：PRICE_ACTION_OVERRIDE。ファンダ/材料がPOSITIVEでもprice actionがWEAKなら
    WAITへ強制する。"""
    if fundamental_signal == "POSITIVE" and price_action_signal == "WEAK":
        return "WAIT"
    return fundamental_signal


# ---- パーフェクトオーダー / 押し目判定（指示書32〜34番） ----

def classify_perfect_order(ma5, ma25, ma75, ma5_prev=None, ma25_prev=None, ma75_prev=None):
    """指示書32番：5>25>75かつ傾きが正（比較対象が渡された場合のみ傾き判定）。
    ENTRY理由単独にはしない——この関数はラベルを返すだけで、呼び出し側のentry_scoreには
    一切加点しない（指示書「ただしENTRY理由単独にはしない」）。"""
    if ma5 is None or ma25 is None or ma75 is None:
        return False
    if not (ma5 > ma25 > ma75):
        return False
    if ma5_prev is not None and ma25_prev is not None and ma75_prev is not None:
        return ma5 > ma5_prev and ma25 > ma25_prev and ma75 > ma75_prev
    return True


def classify_pullback_candidate(perfect_order, price, ma5, ma25, support=None, volume_ok=None, sector_strong=None):
    """指示書33番：パーフェクトオーダー中、5日線/25日線接近＋support＋出来高＋セクター強さの
    押し目候補判定。"""
    if not perfect_order or ma25 is None or ma5 is None:
        return False
    near_ma = abs(ma5 - ma25) / ma25 < 0.02 if ma25 else False
    support_ok = support is None or (price is not None and price >= support)
    return bool(near_ma and support_ok and volume_ok is not False and sector_strong is not False)


# ---- Daily Review連携（指示書39〜44番） ----
CHORUCO_DAILY_SCORE_MAX = {"market_mode_adaptation": 30, "event_awareness": 20, "position_sizing": 20,
                             "story_discipline": 20, "defense_execution": 10}


def evaluate_choruco_daily_performance(market_mode_today, trades_today, missed_opportunity=False):
    """指示書39〜44番：ちょる子式スコア（100点満点）。「取引しなかった」を単純に失敗扱い
    しない（指示書41・42番GOOD_DEFENSE：DEFENSE日にノートレードは満点）。ATTACK日の
    ノートレードは指示書43番により減点は弱め（MISSED_OPPORTUNITY候補）。DEFENSE日の
    高値追いエントリーは指示書44番RULE_VIOLATION_HIGH相当で大きく減点する。"""
    trades_today = trades_today or []
    breakdown, notes = {}, []

    if market_mode_today == "DEFENSE":
        chase_count = sum(1 for t in trades_today if "CHASE_RISK" in (t.get("pattern_tags_json") or []))
        if not trades_today:
            breakdown["market_mode_adaptation"] = 30
            notes.append("GOOD_DEFENSE：DEFENSE日にノートレード（適切な守備、高評価）")
        elif chase_count:
            breakdown["market_mode_adaptation"] = max(0, 30 - chase_count * 15)
            notes.append(f"RULE_VIOLATION_HIGH候補：DEFENSE日に高値追いエントリー{chase_count}件")
        else:
            breakdown["market_mode_adaptation"] = 30
    elif market_mode_today == "ATTACK":
        if not trades_today:
            breakdown["market_mode_adaptation"] = 20 if missed_opportunity else 30
            if missed_opportunity:
                notes.append("MISSED_OPPORTUNITY候補：ATTACK日にノートレード（減点は弱め）")
        else:
            breakdown["market_mode_adaptation"] = 30
    else:
        breakdown["market_mode_adaptation"] = 25

    high_risk_entries = sum(1 for t in trades_today if t.get("event_risk_at_entry") in ("HIGH", "EXTREME"))
    breakdown["event_awareness"] = max(0, 20 - high_risk_entries * 10)
    if high_risk_entries:
        notes.append(f"イベントリスクHIGH/EXTREME下でのエントリー{high_risk_entries}件")

    deviations = [abs((t.get("position_multiplier") or 1.0) - (t.get("recommended_multiplier") or 1.0))
                  for t in trades_today if t.get("position_multiplier") is not None]
    breakdown["position_sizing"] = max(0, round(20 - (sum(deviations) / len(deviations)) * 40, 1)) if deviations else 20

    broken_trades = [t for t in trades_today if t.get("story_break_status") == "BROKEN"]
    delayed = sum(1 for t in broken_trades if (t.get("post_trade_analysis_json") or {}).get("exit_delay_after_break") == "DELAYED")
    breakdown["story_discipline"] = max(0, 20 - delayed * 10) if broken_trades else 20

    if market_mode_today == "DEFENSE":
        overnight_count = sum(1 for t in trades_today if t.get("trade_style") == "SWING")
        breakdown["defense_execution"] = max(0, 10 - overnight_count * 5)
    else:
        breakdown["defense_execution"] = 10

    total = round(sum(breakdown.values()), 1)
    return {"total": total, "breakdown": breakdown, "notes": notes}


# ---- 学習機能（指示書46〜49番） ----

def aggregate_choruco_mode_performance(experiences):
    """指示書46番：market_mode別成績（ATTACK/NORMAL/DEFENSE）。件数・勝率・平均損益。"""
    out = {}
    for mode in ("ATTACK", "NORMAL", "DEFENSE"):
        group = [e for e in (experiences or []) if e.get("market_mode_at_entry") == mode]
        n = len(group)
        if not n:
            out[mode] = {"trades": 0, "win_rate": None, "avg_pnl_pct": None}
            continue
        wins = sum(1 for e in group if e.get("result_class") == "WIN")
        pnls = [e["gross_pnl_pct"] for e in group if e.get("gross_pnl_pct") is not None]
        out[mode] = {"trades": n, "win_rate": round(wins / n, 3),
                       "avg_pnl_pct": round(sum(pnls) / len(pnls), 2) if pnls else None}
    return out


CHORUCO_LOT_MULTIPLIER_BUCKETS = (0.25, 0.5, 0.75, 1.0)


def aggregate_choruco_lot_multiplier_performance(experiences):
    """指示書47番：ロット倍率別成績（0.25x/0.5x/0.75x/1.0xの最も近いバケットに丸める）。"""
    buckets = {b: [] for b in CHORUCO_LOT_MULTIPLIER_BUCKETS}
    for e in (experiences or []):
        m = e.get("position_multiplier")
        if m is None:
            continue
        nearest = min(CHORUCO_LOT_MULTIPLIER_BUCKETS, key=lambda b: abs(b - m))
        buckets[nearest].append(e)
    out = {}
    for b, group in buckets.items():
        n = len(group)
        if not n:
            out[str(b)] = {"trades": 0, "win_rate": None, "avg_pnl_pct": None, "avg_mae_pct": None, "avg_mfe_pct": None}
            continue
        wins = sum(1 for e in group if e.get("result_class") == "WIN")
        pnls = [e["gross_pnl_pct"] for e in group if e.get("gross_pnl_pct") is not None]
        maes = [e["max_adverse_excursion_pct"] for e in group if e.get("max_adverse_excursion_pct") is not None]
        mfes = [e["max_favorable_excursion_pct"] for e in group if e.get("max_favorable_excursion_pct") is not None]
        out[str(b)] = {"trades": n, "win_rate": round(wins / n, 3),
                         "avg_pnl_pct": round(sum(pnls) / len(pnls), 2) if pnls else None,
                         "avg_mae_pct": round(sum(maes) / len(maes), 2) if maes else None,
                         "avg_mfe_pct": round(sum(mfes) / len(mfes), 2) if mfes else None}
    return out


def aggregate_choruco_story_score_performance(experiences):
    """指示書48番：STORY別成績（story_score_at_entryを80+/70-79/60-69/<60で集計）。"""
    def bucket_of(score):
        if score is None:
            return None
        if score >= 80:
            return "80+"
        if score >= 70:
            return "70-79"
        if score >= 60:
            return "60-69"
        return "<60"
    buckets = {"80+": [], "70-79": [], "60-69": [], "<60": []}
    for e in (experiences or []):
        b = bucket_of(e.get("story_score_at_entry"))
        if b:
            buckets[b].append(e)
    out = {}
    for b, group in buckets.items():
        n = len(group)
        wins = sum(1 for e in group if e.get("result_class") == "WIN")
        out[b] = {"trades": n, "win_rate": round(wins / n, 3) if n else None}
    return out


def aggregate_choruco_story_break_response(experiences):
    """指示書49番：STORY BREAK後の行動評価（即EXIT/遅延EXIT/HOLDの成績比較）。"""
    out = {"immediate_exit": {"trades": 0, "avg_pnl_pct": None},
            "delayed_exit": {"trades": 0, "avg_pnl_pct": None},
            "held": {"trades": 0, "avg_pnl_pct": None}}
    key_map = {"IMMEDIATE": "immediate_exit", "DELAYED": "delayed_exit", "HELD": "held"}
    for e in (experiences or []):
        if e.get("story_break_status") != "BROKEN":
            continue
        response = (e.get("post_trade_analysis_json") or {}).get("story_break_response")
        bucket = key_map.get(response)
        if not bucket:
            continue
        out[bucket]["trades"] += 1
    for bucket_key, group_key in key_map.items():
        group = [e for e in (experiences or [])
                 if e.get("story_break_status") == "BROKEN"
                 and (e.get("post_trade_analysis_json") or {}).get("story_break_response") == bucket_key]
        pnls = [e["gross_pnl_pct"] for e in group if e.get("gross_pnl_pct") is not None]
        out[group_key]["avg_pnl_pct"] = round(sum(pnls) / len(pnls), 2) if pnls else None
    return out


# ============================================================
# Cross-Market Link Phase 2（2026-09-12新規）。既存Choruco Style（Market Mode/Event Risk/
# Story Engine）・既存ENTRY SCORE・Rule Engineには一切変更を加えず、その上に積む補助レイヤー。
# 対象はまず半導体・AI関連銘柄のみ（指示書1・18番、全56銘柄×全driverの総当たりは行わない）。
# 【重要な既知の制約】NASDAQ/SOX/NVIDIA/Micronは米国市場が日本のザラ場時間中は休場のため、
# 「同時刻の5分足」を厳密に突き合わせることはできない（日本株が動いている間、米国株は
# 前セッションの終値のまま静止している）。本エンジンはyfinanceが返す各シンボル直近の5本足
# 系列同士を単純にインデックス対応させて相関を計算する——KOSPI・USDJPY・日経先物は取引時間帯が
# 重なるため実際の同時性がある一方、NASDAQ/SOX/NVIDIA/Micronは「直近に確定した値動きの
# 方向性」程度の参考値に留まる（真の同時相関ではない）。UI文言は「連動」「先行傾向」に限定し、
# 「原因」等の因果関係を示唆する表現は使わない（指示書17番）。
# ============================================================

